export const y3v4Chapters: Record<number, string> = {
    "1": "<div style=\"text-align:center;margin:2em 0;\"><img alt=\"Color Illustration 1\" width=\"600\" height=\"849\" src=\"/assets/y3v4_color0.webp\"></div>\n<div style=\"text-align:center;margin:2em 0;\"><img alt=\"Color Illustration 2\" width=\"600\" height=\"849\" src=\"/assets/y3v4_color1.webp\"></div>\n<div style=\"text-align:center;margin:2em 0;\"><img alt=\"Color Illustration 3\" width=\"600\" height=\"849\" src=\"/assets/y3v4_color2.webp\"></div>\n<div style=\"text-align:center;margin:2em 0;\"><img alt=\"Color Illustration 4\" width=\"600\" height=\"849\" src=\"/assets/y3v4_color3.webp\"></div>",
    "2": "<div><p>I always had a feeling that someday it would come to this, that sooner or later, I wouldn’t be able to keep up with this school’s system.</p></div>\n<div><p>I sucked at studying.</p></div>\n<div><p>I wasn’t exactly good at working with other people either.</p></div>\n<div><p>The only thing I could say I was good at… was fighting.</p></div>\n<div><p>That’s why somewhere deep down, I had already sensed it, that when the time came, I’d be the one discarded.</p></div>\n<div><p>Ryūen, obviously, and even Shiina and Katsuragi, were indispensable to the class.</p></div>\n<div><p>But unlike them, I’d always been standing on the edge of the cliff.</p></div>\n<div><p>That was why I thought I’d be fine even if I got expelled.</p></div>\n<div><p>That was what I’d believed all this time.</p></div>\n<div><p>That I had no regrets left behind.</p></div>\n<div><p>At least, that was what I thought…</p></div>\n<div><p>But now, as I stared at Ayanokōji’s back, I realized there was still one thing left undone.</p></div>\n<div><p>If I was getting expelled anyway, then before I disappeared, I wanted to land at least one solid punch on Ayanokōji, no matter what.<span></span></p></div>\n<div><p>Staring at his infuriating back, I steeled my resolve.</p></div>\n<div><p><em>A surprise attack?</em></p></div>\n<div><p><em>Feints before the real hit?</em></p></div>\n<div><p>Yeah, I already knew none of that crap would work on this guy.</p></div>\n<div><p>So I’d do it properly.</p></div>\n<div><p>Straight on. Fair and square.</p></div>\n<div><p>I stepped forward with force and closed the distance between us.</p></div>\n<div><p>Ayanokōji turned around.</p></div>\n<div><p>That same unreadable expression on his face.</p></div>\n<div><p>I grabbed him by the collar and drew back my fist.</p></div>\n<div><p>“I’ll accept the expulsion,” I spat. “So let me hit you once before I go.”</p></div>\n<div><p>It was a completely absurd demand.</p></div>\n<div><p>A hopeless shot.</p></div>\n<div><p>I’d fully expected him to refuse, tell me he had no reason to indulge me, and the second he did, I was ready to swing anyway.<span></span></p></div>\n<div><p>But the response I got was the last thing I expected.</p></div>\n<div><p>“I’m the one who decided to have you expelled, after all,” Ayanokōji said evenly. “I suppose I can grant you at least that much.”</p></div>\n<div><p>Hearing that, the corner of my mouth curled upward ever so slightly.</p></div>\n<div><p>“You’ve got some nerve,” I muttered, tightening my grip. “Fine, then. Don’t expect me to hold back.”</p></div>\n<div><p>I won’t hold back.</p></div>\n<div><p>If he thought he could underestimate a woman's strength, he was dead wrong.</p></div>\n<div><p>I was going to knock out one or two of his teeth for sure.</p></div>\n<div><p>Then, putting every last ounce of strength into it, I unleashed the most dead-serious, super-ultra straight punch of my entire life.<span></span></p></div>",
    "3": "<div><p>Mashima-sensei’s voice rang across the shoreline with quiet finality.</p></div>\n<div><p>“Effective immediately, we will now commence the Uninhabited Island Special Exam.”</p></div>\n<div><p>The students, already exhausted from the survival game, were still struggling to process what they had just heard. Yet Mashima-sensei showed no intention of waiting for anyone to catch up. As though brushing aside the confusion spreading through the crowd, he continued his explanation without hesitation.</p></div>\n<div><p>Just when everyone thought the island exam was finally over, another special exam was suddenly set into motion.</p></div>\n<div><p><em>So the Survival Game conducted earlier was merely the prelude, and this was the second phase?</em></p></div>\n<div><p>Of course, there was always the possibility that this next phase was only the midpoint of an even larger ordeal waiting beyond it. But considering the condition some students were already in, pushing them through three consecutive stages would be unrealistic.</p></div>\n<div><p>Either way, it was a harsh situation.</p></div>\n<div><p>Meanwhile, the sun was already beginning to sink toward the horizon. It was close to five in the evening.</p></div>\n<div><p>The third-years had weathered countless special exams by now and developed a tolerance for the school’s unpredictability. Even so, they couldn’t hide their confusion. This was different from anything they’d faced before.</p></div>\n<div><p>“Damn, they’re seriously going to start another special exam right now?” Hashimoto muttered beside me with a strained half-laugh. “Yamamura and Shiraishi are already hanging by a thread.”</p></div>\n<div><p>His tone carried a trace of sympathy, but the school showed no sign of reconsidering.</p></div>\n<div><p>“The special exam commencing now,” Mashima-sensei continued, “will consist of ten groups, each containing sixteen students. Every group will be assigned one adult supervisor who will provide instructions as necessary. You are expected to obey your supervisor at all times. As you are already aware, due to the number of students expelled thus far, some groups will inevitably begin with fewer members than others. However, adjustments have been made to ensure that disparities in group size will not create any advantages or disadvantages.”</p></div>\n<div><p>Sixteen students per group.</p></div>\n<div><p>If that was the base structure, then this was unlikely to be a straightforward class-versus-class exam.</p></div>\n<div><p>As though confirming that very suspicion, Mashima-sensei’s next words peeled back another layer of the situation.</p></div>\n<div><p>“The bottled drinks you were instructed to take upon disembarking may have struck some of you as unusual. Those bottles are the key to determining your groups.”</p></div>\n<div><p>At once, students began glancing down at the plastic bottles in their hands.</p></div>\n<div><p>“There are five different label colors,” he explained. “Red, blue, green, yellow, and purple. Enough had been prepared for each class, with adjustments and guidance carried out to ensure everyone received one.”</p></div>\n<div><p>I lowered my gaze to the mineral water bottle I’d been carrying since leaving the ship, it bore a blue label.</p></div>\n<div><p>Hashimoto, standing beside me, held purple.</p></div>\n<div><p>At the very least, it confirmed one thing: the two of us wouldn’t end up in the same group.</p></div>\n<div><p>However, there were only five colors. That alone wasn’t enough to divide everyone into ten separate groups.</p></div>\n<div><p>Which meant there had to be another layer hidden somewhere in the selection process.</p></div>\n<div><p>Removing the label would only create litter. On an island like this, a stray gust of wind could easily carry it straight into the ocean. The school wouldn’t use something so careless.</p></div>\n<div><p>If they wanted a cleaner, simpler way to add another randomizer, there was an obvious answer.</p></div>\n<div><p>The cap.</p></div>\n<div><p>Without a word, I twisted the bottle open, removed the cap, and checked the underside.</p></div>\n<div><p>A second later, Hashimoto noticed what I was doing and quietly checked his own as well.</p></div>\n<div><p>“There’s nothing on my cap,” I said quietly. “What about yours?”</p></div>\n<div><p>“Mine’s marked,” Hashimoto replied immediately. “One black line.”</p></div>\n<div><p>Right on cue, Mashima-sensei resumed speaking over the microphone.</p></div>\n<div><p>“I would like everyone to remove the caps from your bottles and examine the underside carefully.”</p></div>\n<div><p>Around us, the sound of twisting plastic caps spread through the crowd in uneven bursts.</p></div>\n<div><p>“There are two types of caps prepared for this exam,” he continued. “Plain caps with no markings, and caps marked with a single black line. Students carrying red labels with unmarked caps will belong to Group 1, and students carrying red labels with marked caps will belong to Group 2. That will determine your assigned groups.”</p></div>\n<div><p>He proceeded through the remaining combinations without pause.</p></div>\n<div><p>Blue labels corresponded to Groups 3 and 4. Green to 5 and 6. Yellow to 7 and 8. And purple to 9 and 10.</p></div>\n<div><p>It was also explained that Group 10 alone would begin with fewer than sixteen members.</p></div>\n<div><p>Hashimoto glanced at his purple label again.</p></div>\n<div><p>“So I got stuck in the smaller Group 10, huh? And you’re Group 3…” He slowly scanned the students surrounding us. “Still, there’s no way in hell to tell who ended up where from here.”</p></div>\n<div><p>Even if someone managed to identify the color of another student’s bottle label from a distance, spotting the tiny black line hidden beneath a bottle cap was another matter entirely. Until everyone physically gathered with their assigned groups, nobody could know for certain who their teammates would be.</p></div>\n<div><p>Which was probably intentional.</p></div>\n<div><p>If group assignments had been too easy to identify, students might’ve attempted to exchange bottles beforehand. The school had clearly accounted for that possibility from the start.</p></div>\n<div><p>Still, the identities of our future teammates were something we would inevitably learn soon enough. Speculating now was pointless. More important was understanding the rules of the exam itself.</p></div>\n<div><p>In fact, Mashima-sensei and the others were already proceeding to the next stage without wasting time.</p></div>\n<div><p>“Now then, I will explain the details of this special exam. To assist your understanding, documents summarizing the rules and structure will now be distributed. Read through them carefully.”</p></div>\n<div><p>After a brief pause, teachers moved through the students, handing out the materials one by one.</p></div>\n<div><p>The multi-page document was bundled together with detailed maps of the island. Small card rings had been fastened through the corners, likely to prevent them from being blown away by the wind.</p></div>\n<div><p>As the documents reached my hands, Mashima-sensei resumed speaking.</p></div>\n<div><p>“You will divide into your assigned groups and undertake various challenges throughout the island. Based on your results, you will earn rewards known as ‘tokens.’ Collecting these tokens will form the core objective of the exam. In addition, one student from each class has already been selected by their homeroom teacher to serve as class leader. Although the results of the Survival Game Special Exam have caused provisional changes in class rankings, those standings will remain unofficial until the end of the month. Therefore, for the purposes of this exam, the current class designations will remain unchanged.</p></div>\n<div><p>He paused briefly before reading out the names.</p></div>\n<div><p>“For Class A: Horikita Suzune. For Class B: Ryūen Kakeru. For Class C: Ayanokōji Kiyotaka. And for Class D: Ichinose Honami. These students will serve as the leaders for their respective classes.”</p></div>\n<div><p>As his voice echoed across the shore, I lowered my gaze to the documents in my hands.</p></div>\n<div><hr></div>\n<div><p><strong><em>‘Token Collection Special Exam’</em></strong></p></div>\n<div><p>• <strong>Overview</strong></p></div>\n<div><p>During the course of the four-day, three-night examination, students are required to travel across the island while undertaking various challenges, collect tokens, and ultimately reach the designated goal.</p></div>\n<div><p>• <strong>Group Goal Rewards</strong></p></div>\n<div><p>Token multipliers and Private Point rewards will be distributed according to the order in which groups reach the goal.</p></div>\n<div><p>• <em>Note:</em></p></div>\n<div><p><em>A group’s finishing rank is determined the moment a majority of its members successfully reach the goal.</em></p></div>\n<div><p>• <strong>Group Rank</strong></p></div>\n<div><p>1st Place: 100% Token Multiplier &amp; 100,000 Private Point Reward</p></div>\n<div><p>2nd Place: 95% Token Multiplier &amp;  80,000 Private Point Reward</p></div>\n<div><p>3rd Place: 90% Token Multiplier &amp;  50,000 Private Point Reward</p></div>\n<div><p>4th Place: 85% Token Multiplier &amp;  30,000 Private Point Reward</p></div>\n<div><p>5th Place: 80% Token Multiplier &amp;  20,000 Private Point Reward</p></div>\n<div><p>6th Place or Lower: 75% Token Multiplier &amp;  10,000 Private Point Reward</p></div>\n<div><p>Disqualified Group: 70% Token Multiplier &amp;  No additional reward</p></div>\n<div><p>• <strong>Rewards and Penalties Based on Token Holdings</strong></p></div>\n<div><p>The groups containing each class leader will determine their class’s outcome based on the total number of tokens accumulated.</p></div>\n<div><p>• <strong>Token Holding Rank Result</strong></p></div>\n<div><p>1st Place: Class Points +100</p></div>\n<div><p>2nd Place: Class Points +50</p></div>\n<div><p>3rd Place: Class Points +20</p></div>\n<div><p>4th–9th Place: No Change</p></div>\n<div><p>Last Place: Class Points -50</p></div>\n<div><hr></div>\n<div><p>What mattered most was not simply collecting tokens, but balancing two objectives simultaneously: gathering as many as possible while also reaching the goal quickly enough to preserve a high multiplier.</p></div>\n<div><p>Neither alone would be enough.</p></div>\n<div><p>Mashima-sensei broke the brief silence, resuming his explanation.</p></div>\n<div><p>“As for the private point rewards granted upon reaching the goal, if a group finishes in first place, every student within that group will individually receive 100,000 private points. The second reward, the token multiplier, is tied both to your group’s ranking by token possession and to the individual rewards I will explain shortly. If a group finishes in third place, the total number of tokens used in calculations will be reduced to 90%. Groups ranked 6th or lower will receive only 75%.” He paused briefly before adding, “Any fractional values produced after the multiplier is applied will be rounded upward.”</p></div>\n<div><p>In other words, even if a group accumulated 1,000 tokens through relentless effort over four exhausting days, a poor finishing rank would steadily erode the value of everything they had gathered.</p></div>\n<div><p>The exact conditions for what constituted “reaching the goal” remained unclear for now, but one thing was already obvious. Finishing near the top was non-negotiable.</p></div>\n<div><p>“Up to this point, the rules may have sounded favorable to the students, however, this special exam also contains several major penalties. And… some of them are unavoidable.”</p></div>\n<div><p>I lowered my eyes to the next page of the booklet. The penalties he referred to had already been printed there in orderly text.</p></div>\n<div><hr></div>\n<div><p><strong><em>Penalty List</em></strong></p></div>\n<div><p>• <strong>Lowest Token Holder Expulsion</strong></p></div>\n<div><p>At the conclusion of the exam, the single student across the entire year with the fewest tokens will be expelled.</p></div>\n<div><p>If multiple students are tied for the lowest number of tokens, the student with the lowest Overall Ability Assessment (OAA) score as of June 1st will be selected. If still tied, earlier monthly OAA records will be referenced in order.</p></div>\n<div><p>• <strong>Reaching Zero Tokens</strong></p></div>\n<div><p>If a student’s token count ever reaches zero during the exam, that student will be expelled immediately.</p></div>\n<div><p>However, if the student possesses a Protection Point, they will instead withdraw from the exam and wait aboard the ship.</p></div>\n<div><p>This penalty applies only to the <em>first</em> student whose token count reaches zero.</p></div>\n<div><p>• <strong>Failure to Reach the Goal</strong></p></div>\n<div><p>For every student who fails to reach the goal by the end of the exam, their class will lose 5 Class Points.</p></div>\n<div><p>In addition, regardless of the group’s finishing rank, any student who fails to reach the goal will have their token multiplier reduced to 70%.</p></div>\n<div><p>• <strong>Delayed Goal Completion Penalty</strong></p></div>\n<div><p>Once a majority of a group has reached the goal and the group’s ranking is finalized, every student who still has not reached the goal will continue costing their class 1 Class Point every 30 minutes until they arrive.</p></div>\n<div><p>• <strong>Leaving the Supervisor’s Area</strong><span></span></p></div>\n<div><p>For every hour a student remains outside the area where their assigned supervisor is stationed, that student will lose 1 token.</p></div>\n<div><p>Returning to the designated area resets the timer.</p></div>\n<div><hr></div>\n<div><p>The penalties laid out before us were severe.</p></div>\n<div><p>Unlike ordinary punishments for breaking rules, these weren’t pitfalls students could simply avoid through caution or obedience. Some could potentially be managed, but others were built into the structure of the exam itself, unavoidable by design.</p></div>\n<div><p>Compared to the Survival Game Special Exam, this was a clear step deeper into dangerous territory.</p></div>\n<div><p>“So this is finally the real deal, huh?” Hashimoto muttered beside me under his breath.</p></div>\n<div><p>“It seems so,” I replied quietly.</p></div>\n<div><p>Considering Horikita had most likely shouldered the penalty from the Survival Game Exam, the only student confirmed to still possess a Protection Point was Kōenji. Other classes might still have some in reserve, but intentionally reducing your own tokens to zero just to burn that single expulsion slot would only benefit rival classes more than your allies. No one would willingly make that sacrifice.</p></div>\n<div><p>With the safety net already stripped away following their recent defeat, Class A’s position in particular had become especially unforgiving.</p></div>\n<div><p>Mashima-sensei gave the students a moment to absorb the weight of the penalties before resuming his explanation.</p></div>\n<div><p>“Next, I will explain the details regarding tokens themselves… as well as the individual rewards.”</p></div>\n<div><hr></div>\n<div><p>• <strong>Token Classifications (Front-side and Back-side)</strong></p></div>\n<div><p>Tokens are divided into two distinct classifications: Front-side and Back-side.</p></div>\n<div><p>Tokens earned through verified individual achievements are classified as Front-side. Tokens acquired through all other methods are classified as Back-side.</p></div>\n<div><p>Victory rewards based on token possession will account for the aggregate total, regardless of whether they are Front-side or Back-side.</p></div>\n<div><p>Individual rewards will strictly account for Front-side tokens only.</p></div>\n<div><p>• <strong>Token Transfer Protocols</strong></p></div>\n<div><p>Tokens are fully transferable between students. To initiate a transfer, a specific interface operation must be performed, followed by physical contact between both parties' wristwatches.</p></div>\n<div><p>There are no restrictions on the quantity of tokens transferred, the frequency of transfers, or the intended recipient.</p></div>\n<div><p>Any token utilized in a transfer will permanently convert into a Back-side token and cannot be reverted back to Front-side.</p></div>\n<div><p>A student's token count becomes finalized the exact moment they reach the goal. Beyond this point, any further transfers involving that student are prohibited.</p></div>\n<div><p>• <strong>Token Expenditure</strong></p></div>\n<div><p>Expending 1 Token permits 5 minutes of communication with any student of your choice.</p></div>\n<div><p>Expending 1 Token permits a location check to view the current coordinates of any student of your choice.</p></div>\n<div><hr></div>\n<div><p>The ability to freely transfer tokens at any time seemed likely to play a major role in avoiding certain penalties.</p></div>\n<div><p>A student close to reaching zero could be rescued by allies before expulsion triggered. Likewise, someone at risk of falling to the bottom of the rankings could potentially be saved by pooling resources.</p></div>\n<div><p>At the same time, there was an obvious tradeoff.</p></div>\n<div><p>The moment a token was transferred, it lost its front-side status and became a back-side token permanently, making them ineligible for pursuing individual rewards.</p></div>\n<div><hr></div>\n<div><p><strong><em>Individual Rewards</em></strong></p></div>\n<div><p>• <strong>Special Reward:</strong> The class of the student who accumulates the highest number of Front-side tokens will be awarded 100 Class Points. Additionally, that student will receive 500,000 Private Points. <em>(In the event of a tie for the top position, the rewards will be divided equally among the qualifying students).</em></p></div>\n<div><p>• <strong>General Reward (All Students):</strong> Every student will receive 1,000 Private Points multiplied by their total number of Front-side tokens in possession.</p></div>\n<div><hr></div>\n<div><p>The section regarding the Special Reward was impossible to ignore.</p></div>\n<div><p>100 Class Points.</p></div>\n<div><p>That alone was significant enough to rival the rewards of an entire special exam victory. But there was an important catch. If multiple students tied for the highest number of front-side tokens, the reward would simply be divided among them.</p></div>\n<div><p>In any case, gathering even a single additional token as an individual carried clear advantages for every student involved.</p></div>\n<div><p>By now, the entire structure of the exam had finally come into view, and a measured tension began settling over the crowd.</p></div>\n<div><p>If a group cooperated efficiently, gathered large numbers of tokens, and secured a top finish, then naturally every member of that group stood to gain a huge amount of Private Points. That was the straightforward benefit.</p></div>\n<div><p>But the problem was what happened inside the group itself.</p></div>\n<div><p>If a student from a rival class happened to accumulate an overwhelming number of front-side tokens while working alongside you, they could seize the Special Award for their class instead. And that would effectively create a massive class point gap in favor of a rival class.</p></div>\n<div><p>After that, the explanation shifted toward the new functions added to the wristwatches.</p></div>\n<div><p>“By entering the six-digit passcode assigned to your device,” Mashima-sensei explained, “you may confirm your current token count as well as transfer tokens to others. We will now have everyone operate the system as part of the explanation.”</p></div>\n<div><p>He paused briefly.</p></div>\n<div><p>“However, there is one important precaution. Every student has been provided with at least two tokens at the start of the exam, but the number distributed differs from student to student. Your starting token count is therefore valuable information. I strongly recommend you avoid revealing it to others.”</p></div>\n<div><p>So the starting conditions weren’t equal after all.</p></div>\n<div><p>The wristwatch displays themselves were designed with privacy in mind. Unless someone deliberately stood directly behind another person, or pressed in unnaturally close from the side, stealing a glance at the screen was nearly impossible.</p></div>\n<div><p>Even so, the students took no chances, shielding the screens with their bodies, they cautiously entered passcodes to confirm the initial token counts.</p></div>\n<div><p>I too entered my passcode and the screen lit up.</p></div>\n<div><p><em>11 Tokens: Front-Side</em></p></div>\n<div><p>At first glance, it seemed relatively high.</p></div>\n<div><p>But there was no baseline yet beyond “two or more.” Without additional comparisons, there was no reliable way to judge where the number actually stood.</p></div>\n<div><p>In addition, a send button and receive button for transfers were displayed simultaneously. It seemed token transfers required both parties to activate the appropriate commands before physically touching their wristwatches together.</p></div>\n<div><p>Without speaking, I extended my arm slightly toward Hashimoto, showing him my screen.</p></div>\n<div><p>His eyes widened slightly in surprise as he compared it to his own before turning his watch toward me in return.</p></div>\n<div><p><em>9 Tokens</em></p></div>\n<div><p>Close to mine, but slightly lower.</p></div>\n<div><p>It was hard to believe the distribution was based directly on OAA scores or academic performance. More likely, they were related to the previous exam, not necessarily contribution itself, but survival duration.</p></div>\n<div><p>Yamamura and Shiraishi had endured until the very end of the Survival Game, exhausting themselves more thoroughly than anyone else.</p></div>\n<div><p>Meanwhile, students eliminated early had probably recovered completely by now, entering this exam in a far better condition.</p></div>\n<div><p>Seen that way, the uneven token distribution made sense. A form of insurance. A balancing measure intended to offset the physical disparity between students.</p></div>\n<div><p>Still, it wasn’t something to celebrate unconditionally.</p></div>\n<div><p>Even if others could eventually make educated guesses regarding who had started with a larger number of tokens, concealing that information whenever possible was still the smarter choice.</p></div>\n<div><p>“And finally,” Mashima-sensei continued, “although everyone is currently present, some students may unexpectedly fall ill during the course of the exam. In such cases, the procedures involved are extremely delicate. Be certain to carefully review the relevant section in your documents.”</p></div>\n<div><p>At those words, I lowered my gaze toward the final page.</p></div>\n<div><hr></div>\n<div><p>• <strong>Conditions That Make Continuing the Exam Impossible</strong></p></div>\n<div><p>If a student suffers a sudden illness or serious injury severe enough to prevent them from continuing, they may, in principle, report the situation verbally to a supervisor and request a judgment on whether they are allowed to proceed.</p></div>\n<div><p>If no supervisor is nearby and direct contact is impossible, the student may instead use the emergency request function on their wristwatch.</p></div>\n<div><p>However, the moment a student is officially declared retired from the exam, their token count becomes finalized.</p></div>\n<div><p>As a relief measure, any student may transfer tokens to a retired participant regardless of distance.</p></div>\n<div><p>In addition, a group containing a retired student may still receive an official ranking, but only if every remaining member of that group successfully reaches the goal.</p></div>\n<div><p>Feigning illness, or intentionally concealing a serious injury or medical condition in order to continue participating, is strictly prohibited.</p></div>\n<div><p>If a student is uncertain whether their condition qualifies, they are instructed to consult the school for judgment.</p></div>\n<div><p>If a violation is discovered, an expulsion penalty will be imposed.</p></div>\n<div><hr></div>\n<div><p>In an island exam like this, health issues and injuries were practically inevitable.</p></div>\n<div><p>Because the exam was fundamentally built around maintaining group numbers, the school likely had zero tolerance for students concealing their true condition.</p></div>\n<div><p>If being grouped together with students from other classes puts you at a disadvantage, then naturally people would want to hide any signs of poor health.</p></div>\n<div><p>This rule existed specifically to prevent that from happening.</p></div>\n<div><p>And since faking illness would not work either, it effectively prevented someone like Kōenji from casually abandoning the exam whenever he pleased.</p></div>\n<div><p>“Man, these rules are brutal,” Hashimoto muttered. “So even if you get sick and retire, they still won’t show any mercy, huh?”</p></div>\n<div><p>The relief measures certainly existed. But if a student lacking either ability or social value retired early, there was a very real possibility their class would simply abandon them.</p></div>\n<div><p>On the other hand, someone like Ichinose would almost certainly be saved without hesitation. Her classmates would willingly gather tokens from across the island just to keep her safe.</p></div>\n<div><p>In any case, token possession itself remained hidden behind layers of secrecy. Whether they were front-side or back-side, no third party had any reliable way to verify the total unless the owner chose to reveal it. The entire system was effectively a black box.</p></div>\n<div><p>Let alone knowing the token counts outside the group, even grasping the token counts within the group won't be straightforward.</p></div>\n<div><p>Additionally, it seems students could spend tokens to contact one another, but every use would naturally reduce the maximum number of tokens they could finish the exam with. Unless it was an emergency, unnecessary communication had to be avoided.</p></div>\n<div><p>After that, the explanation shifted to supplies: food, tents, and other necessities.</p></div>\n<div><p>Students would each be given a designated backpack and permitted to pack whatever items they wanted from the prepared stock.</p></div>\n<div><p>However, no explanation was given regarding what would happen if supplies ran short during the three nights on the island. Because of that, it was probably wiser to carry extra provisions even if it meant adding more weight.</p></div>\n<div><p>That naturally made girls with less muscle mass more likely to be at a disadvantage.<span></span></p></div>\n<div><p>Still, it was hard to believe the school hadn’t already considered that issue. There was a good chance some kind of support measure existed behind the scenes.</p></div>\n<div><p>“Now then, after a 10-minute break, you will assemble according to your assigned groups. That concludes the explanation.”</p></div>\n<div><p>With that, the briefing finally came to an end.</p></div>\n<div><p>I turned toward Hashimoto.</p></div>\n<div><p>“I need you to pass a message along to the others in class,” I said.</p></div>\n<div><p>Hashimoto looked over at me.</p></div>\n<div><p>“Sure thing, just say the word.”</p></div>\n<div><p>“The first thing I want you to tell them is this: whether they share their token counts with classmates is their own decision. But right now, they should think very carefully before doing it.”</p></div>\n<div><p>“…Carefully about sharing?” Hashimoto tilted his head slightly. “I mean, personally I’m all for keeping secrets, but wouldn’t sharing help avoid risks?”</p></div>\n<div><p>“It would, if you could be absolutely certain every single person was prepared to go down together for the sake of the class.”</p></div>\n<div><p>I paused.</p></div>\n<div><p>“But classmates are still, ultimately, other people. If it comes down to choosing between themselves and someone else, the answer becomes obvious.”</p></div>\n<div><p>Especially in my class, more than half the students were highly capable and deeply confident in their own abilities.</p></div>\n<div><p>And because they carried such a strong determination to graduate from Class A, careless information sharing carried risks of its own.</p></div>\n<div><p>The students assigned to each mixed group were now being forced to make a difficult choice:</p></div>\n<div><p><em>Would they constantly share information about their token counts with their classmates… or keep everything hidden?</em></p></div>\n<div><p>If a class managed token information thoroughly, then students running low could be supported collectively, reducing the risk of expulsions across the board. There was a clear advantage to that approach.</p></div>\n<div><p>Of course, doing so would make it nearly impossible for any individual to monopolize tokens and chase the massive personal rewards tied to them.</p></div>\n<div><p>Still, if the alternative was sacrificing classmates, plenty of students would consider that a fair trade.</p></div>\n<div><p>The problem was that even perfect cooperation didn’t guarantee safety.</p></div>\n<div><p>Suppose three or four students worked together and distributed tokens evenly among themselves. If that balance still resulted in someone ending up at the bottom overall, then expulsion remained unavoidable.</p></div>\n<div><p>In the end, the deciding factor would become OAA rankings.</p></div>\n<div><p>And if the group tried compensating for that by funneling extra tokens toward the student with the lowest OAA, then naturally the student with the second-lowest OAA would become the next person in danger.</p></div>\n<div><p>No matter how carefully people joined hands, trust and moral hazard would always exist side by side.</p></div>\n<div><p>It started with whether people could genuinely accept the policy established from the beginning. Even within a single group, resentment and distrust could easily grow through complaints like, “He’s holding more than he claims,” or “She’s not helping nearly as much as expected.” On top of that, there was no telling where information might leak.</p></div>\n<div><p>Students who accumulated large numbers of tokens would eventually attract attention beyond their own groups as well. The more successful someone became, the more they would inevitably be treated as a potential savior by people desperate for help.</p></div>\n<div><p>On the other hand, refusing to share token counts entirely was also a perfectly reasonable option.</p></div>\n<div><p>But complete secrecy created its own dangers.</p></div>\n<div><p>If nobody shared anything, then classmates approaching the expulsion threshold could not be rescued in time during emergencies.</p></div>\n<div><p>Worse, students willing to lie and manipulate others into offering assistance would gain a clear advantage. Paranoia inside the class would deepen further, slowly poisoning internal trust eventually causing losses.</p></div>\n<div><p>In the end, the most rational students would probably settle somewhere in the middle. They would avoid revealing exact numbers, respond vaguely like “I don’t really have room to spare,” and only contribute the bare minimum whenever a classmate truly faced immediate danger.</p></div>\n<div><p>“So basically,” Hashimoto said, “don’t trust your classmates too much.”</p></div>\n<div><p>“That’s right.”</p></div>\n<div><p>The fact that Hashimoto understood immediately probably meant he’d already been thinking along similar lines himself.</p></div>\n<div><p>After that, I gave him a few more requests to pass along.</p></div>\n<div><p>He accepted every one of them without complaint, nodding firmly each time.</p></div>\n<div><p>“Leave it to me for now.”</p></div>\n<div><p>Hashimoto answered with easy confidence, then immediately broke into a run across the sand.</p></div>\n<div><p>Almost as if trading places with him, Shiraishi and Nishikawa began walking toward me at an unhurried pace.</p></div>\n<div><p>“Just now, the loyal dog Hachikō, or rather, the loyal dog Hashimoto Masayoshi, seemed to run energetically across the sandy beach. He looked like a child unable to contain his joy at being asked to run an errand.”</p></div>\n<div><p>And alongside them was the usual oddball Morishita.</p></div>\n<div><p>“You look more energetic than expected, Ayanokōji Kiyotaka,” she said as she walked up. “Weren't you starting to feel a mixture of heart-pounding anticipation and anxiety from wanting to see me so badly?\"</p></div>\n<div><p>“Not even remotely,” I replied. “More importantly, considering you retired on the second day, you seem pretty energetic yourself.”</p></div>\n<div><p>“Quite, quite,” Morishita declared proudly without the slightest shame. “Life aboard the ship was unexpectedly wonderful. I spent private points like running water, eating delicious food, drinking, and playing around. Honestly, I would’ve liked to continue that elegant lifestyle for a while longer.”</p></div>\n<div><p>She spoke without the slightest attempt to hide a single thing.</p></div>\n<div><p>“That certainly sounds like a meaningful use of your time,” I said dryly. “Did anything unusual happen aboard the ship?”</p></div>\n<div><p>Expecting little of value from Morishita, I directed the question toward Nishikawa instead, since she had also been eliminated early.</p></div>\n<div><p>“The third-years who retired were basically given free time until the Survival Game Special Exam ended,” Nishikawa explained. “But it sounded like the first-years and second-years were doing separate special exams of their own. Though I haven’t heard anything about the results, so I don’t really know the details. Sorry.”</p></div>\n<div><p>So rather than getting an early summer vacation, it seemed they had been placed in a similar environment.</p></div>\n<div><p>“The first-years must have it rough too,” Shiraishi murmured. “They’re probably struggling with the contrast compared to the luxury cruise ship.”</p></div>\n<div><p>She sounded genuinely concerned, but Morishita immediately went “tsk, tsk” and wagged a finger.</p></div>\n<div><p>“You’re still far too naïve, Shiraishi Asuka. A real softie. Our juniors, especially the first-years, should absolutely suffer on the island just like we did. We’ve been struggling ever since our own first year, and yet they get pampered? Very cheeky.”</p></div>\n<div><p>Coming from someone who’d barely suffered at all this year, Morishita’s venom carried remarkably little self-awareness.</p></div>\n<div><p>“I happened to run into Yamamura Miki earlier,” she continued. “And wow, she absolutely reeked of sweat and dirt.”</p></div>\n<div><p>“Don’t say things like that, even as a joke,” I replied. “Yamamura staying until the end helped the class a lot. Same goes for Shiraishi here.”</p></div>\n<div><p>I looked toward Shiraishi.</p></div>\n<div><p>“How’s your condition?”</p></div>\n<div><p>“To be honest,” she answered with a faint smile, “it’s a little difficult. But I can’t afford to complain. Our class managed to take second place, and we’ve finally closed the distance with the classes above us.”</p></div>\n<div><p>In the Survival Game Special Exam, Ichinose’s class had finished first, Ryūen’s class third, while Horikita’s class had fallen to last place. As a result, the gap in Class Points between the upper and lower classes had narrowed significantly.</p></div>\n<div><p>Although our class had temporarily dropped into provisional Class D after the reshuffling, the difference between us and Ryūen’s class was still minimal.</p></div>\n<div><p>Depending on the outcome of the special exam about to begin, every class still had a realistic chance of ending up anywhere between A and D.</p></div>\n<div><p>“We actually came over because we wanted to compare our initial token counts.”</p></div>\n<div><p>Saying that, Shiraishi swiftly operated her wristwatch and turned the display toward me.</p></div>\n<div><p>The tokens displayed there were 12. Nishikawa, who showed hers in tandem, had 2, a massive difference.</p></div>\n<div><p>“What about Morishita?”</p></div>\n<div><p>“Fufu, I am a believer in secrecy.”</p></div>\n<div><p>“Earlier, I was allowed to confirm Morishita-san’s token count,” Shiraishi said calmly. “She had five.”</p></div>\n<div><p>It seemed the believer in secrecy had thoroughly shared her information.</p></div>\n<div><p>“Well, for someone operating at my level, five tokens is more than sufficient. Though in the unlikely event of an emergency, I fully intend to exploit Ayanokōji Kiyotaka, so please earn plenty on my behalf.”<span></span></p></div>\n<div><p>At the moment, Shiraishi held the highest confirmed count with twelve. I had eleven. Nishikawa had two, and Morishita five, huh.</p></div>\n<div><p>“Hashimoto had nine,” I said. “It’s probably safe to assume the longer someone remained active in the Survival Game Special Exam, the larger the advantage they received in starting tokens.”</p></div>\n<div><p>Class rankings, movements during the exam, roles, and contribution levels may also have had an effect.</p></div>\n<div><p>At the very least, those kinds of factors were clearly connected to the initial token distribution.</p></div>\n<div><p>How meaningful that initial token handicap would prove to be might become one of the major keys to the entire test.</p></div>\n<div><p>Shiraishi considered that silently before speaking again.</p></div>\n<div><p>“Since everyone begins with at least two tokens, would it be reasonable to assume the penalty involving the first student reduced to zero tokens is unlikely to happen easily?”</p></div>\n<div><p>“Not necessarily,” I replied. “As long as unrestricted token transfers exist, the system is constantly providing students with ways to adjust their situation.”</p></div>\n<div><p>I looked back toward Shiraishi.</p></div>\n<div><p>“If the very first task carried the possibility of losing multiple tokens, then students would need to receive additional tokens from others before even attempting it.”</p></div>\n<div><p>It was an intentionally extreme scenario.</p></div>\n<div><p>Realistically, the exam probably wouldn’t escalate that far that quickly. But with Morishita casually nodding along beside us, it wasn’t a bad lie to leave hanging in the air.</p></div>\n<div><p>A little tension would do her good.</p></div>\n<div><p>“Are you sure it's okay not to go and support everyone in the class?” Shiraishi asked quietly.</p></div>\n<div><p>“I’ve already asked Hashimoto to relay several things,” I replied. “Besides, no matter how thoroughly we organize things, nobody is truly safe from the zero-token expulsion penalty until they’ve secured a stable number of tokens for themselves. Since the groups have been separated, this is something they’ll have to overcome on their own.”</p></div>\n<div><p>There were limits to how much protection could be offered from the outside.</p></div>\n<div><p>If someone allowed their tokens to fall to zero so easily, then receiving an expulsion notice would simply be the consequence of that failure.</p></div>\n<div><p>There was another possible approach, of course.</p></div>\n<div><p>The class could gather from the start, pool its surplus tokens, and redistribute them to students like Nishikawa, who possessed only the minimum amount.</p></div>\n<div><p>On paper, that would strengthen the weakest members of the class. But even that strategy came with drawbacks.</p></div>\n<div><p>Protecting weaker students too aggressively would lower the overall ceiling of the class’s earning potential. The more tokens were redistributed defensively, the harder it became for stronger students to maximize gains elsewhere.</p></div>\n<div><p>And in an exam structured entirely around token acquisition, lowering the class’s offensive potential too much could become fatal in its own way.</p></div>\n<div><p>If the class intended to win, then students ultimately needed to gather tokens through their own ability.</p></div>\n<div><p>This was not an exam where every single person could be protected with absolute certainty. A certain amount of risk had to be accepted.</p></div>\n<div><p>“By the way,” Nishikawa asked, “what group did you end up in, Ayanokōji-kun? I’m in Group One. Honestly, I was hoping I’d end up with Asuka if possible, though~\"</p></div>\n<div><p>It seemed Shiraishi had been assigned to Group Two instead, so that wish had not been granted.</p></div>\n<div><p>“So you wish to know my group?” Morishita folded her arms with unnecessary pride, “truly, what a secretly perverted man you are! It’s Group Three. Three.”</p></div>\n<div><p>“I don’t remember asking in the slightest…” I muttered. “Wait. Don’t tell me we’re actually in the same group…”</p></div>\n<div><p>“Eh!? Seriously!? We’re together!?”<span></span></p></div>\n<div><p>Morishita abruptly covered her mouth with both hands in exaggerated shock.</p></div>\n<div><p>Though notably, her eyes remained completely unchanged.</p></div>\n<div><p>“This is going to be an exhausting special exam…”</p></div>\n<div><p>Just imagining how loud things were likely to become over the next few days was enough to leave me slightly depressed already.<span></span></p></div>\n<div><h2>Part 1</h2></div>\n<div><p>With the explanations finally concluded, Morishita and I made our way to our group's designated gathering spot.</p></div>\n<div><p>Since Group 3’s standby area happened to be right nearby, we ended up being the first ones to arrive.</p></div>\n<div><p>“Allow me to make one thing clear in advance,” Morishita said, turning to me with the composed severity of someone delivering an official warning. “During the exam, please refrain from acting overly familiar with me. If there were even the slightest misunderstanding that you were my boyfriend, it would seriously ruin my future school life.”</p></div>\n<div><p>“You don’t have to worry about that.”</p></div>\n<div><p>“I wonder about that,” she replied without missing a beat. “They say that even when a man denies it, his lower half remains quite energetic. Though I admit, I don't fully understand the biological mechanisms behind it.”<span></span></p></div>\n<div><p>“You really have a knack for speaking confidently about things you know nothing about.”</p></div>\n<div><p>“Flattery won't raise my affection rating for you, you know.”</p></div>\n<div><p><em>Isn't anyone else going to show up?</em></p></div>\n<div><p>Just as I was silently hoping for a distraction, the sound of footsteps shifting through the sand reached my ears.</p></div>\n<div><p>“Let’s do our best, Ayanokōji.” The voice belonged to Yoshida Kenta, who had come up from behind.</p></div>\n<div><p>Sanada followed shortly after, and with their arrival, the Class C members assigned to our group had gathered. Looking over them, they were the academically inclined sort, students who might not stand out in any dramatic way, but who could be counted on to handle most situations steadily and without unnecessary trouble.</p></div>\n<div><p>“Ugh, Morishita, seriously?” Yoshida groaned.</p></div>\n<div><p>“It seems you simply cannot hide your joy, Kobayashi Kenta.”</p></div>\n<div><p>“It's Yoshida,” he corrected at once. “<em>Yoshida.</em>”</p></div>\n<div><p>“...Ugh. Ayanokōji. Don't tell me I'm stuck with you.” The voice that cut in from the side was thick with undisguised disgust. It belonged to another participant: Class B’s Ibuki Mio.<span></span></p></div>\n<div><p>Almost at the same moment, another figure began moving toward us: Katsuragi Kōhei, his expression stiff and guarded.<span></span></p></div>\n<div><p>“To think I'd be placed in the same group as you,” he said, stopping nearby. “It looks like this is going to be a tough battle.”</p></div>\n<div><p>“I could say the same,” I replied.</p></div>\n<div><p>Katsuragi wasn’t the type to be easily swayed by emotion. If he ended up on the opposing side in a special exam like this, he wouldn’t make things easy for anyone.</p></div>\n<div><p>That said, because this exam also required mutual cooperation within the same group, he could just as easily be considered a highly dependable ally, making it difficult to definitively weigh his presence.</p></div>\n<div><p>The rest of the Class B students had yet to make an appearance. Before they did, however, a student from Class A approached.</p></div>\n<div><p>“Oh, I'm with you, Ibuki-san!” Kushida’s voice came brightly from behind her. “I look forward to working together.”</p></div>\n<div><p>She stepped close to Ibuki and, with a gentle little pat, placed a hand on her shoulder. Her smile was flawless, almost angelic.</p></div>\n<div><p>To anyone watching from the outside, it would have looked like nothing more than a girl warmly greeting a friend. Whether that was truly the case, however, was another matter.</p></div>\n<div><p>“Ugh, Kushida... This is the absolute worst.”</p></div>\n<div><p>Ibuki looked just as thoroughly disgusted with her as she had been with me, but Kushida, naturally, didn't allow a single facial muscle to twitch.</p></div>\n<div><p>In the meantime, students from the other classes continued to arrive one after another.</p></div>\n<div><p>When, at last, all sixteen participants had gathered, I looked over the group once more and took a moment to mentally review the lineup.</p></div>\n<div><hr></div>\n<div><p><strong>Group 3 Participants</strong></p></div>\n<div><p>Class D: Sumida Makoto, Moriyama Susumu, Minamikata Kozue, Amikura Mako.<span></span></p></div>\n<div><p>Class C: Ayanokōji Kiyotaka, Yoshida Kenta, Sanada Kōsei, Morishita Ai.</p></div>\n<div><p>Class B: Sonoda Masashi, Katsuragi Kōhei, Ibuki Mio, Morofuji Rika.</p></div>\n<div><p>Class A: Ike Kanji, Kushida Kikyō, Shinohara Satsuki, Wang Mei-Yu.<span></span></p></div>\n<div><hr></div>\n<div><p>There were a few loudmouths in the mix, but my initial impression was that this was a solid, well-balanced group.<span></span></p></div>\n<div><p>I immediately began constructing the logic needed to secure a win, and more importantly, how to avoid a loss.<span></span></p></div>\n<div><p>The important factors were the number of tokens, the multipliers, and avoiding penalties. There were still unknowns, such as the goals system that affected those multipliers, but one thing was already certain: these sixteen people were both allies and enemies. By analyzing their individual abilities and relationships, I began narrowing down the optimal way to maneuver from here.</p></div>\n<div><p>As I ran through these calculations, I noticed the four Class A students watching me closely.</p></div>\n<div><p>As their former classmate, I figured I should probably offer them a standard, polite greeting. Though, knowing Ike and the others, there was a fair chance they would just hurl abuse at me the second I opened my mouth.</p></div>\n<div><p>While I was idly considering that possibility, Ike Kanji and Shinohara Satsuki exchanged a glance. Then after a brief, hushed conversation, they took the initiative and approached me, both wearing visibly nervous expressions.</p></div>\n<div><p>They were walking extremely close to one another, close enough that their shoulders nearly lined up. From that alone, it was easy to see that their relationship was still going well.</p></div>\n<div><p>Statistically, the probability of a couple ending up in the same group was just under eight percent. It wasn't a particularly surprising outcome in itself, but the two of them likely interpreted it as some stroke of baseless romantic destiny.<span></span></p></div>\n<div><p>Behind them, Kushida and Mii-chan were watching me as well. Kushida, smile firmly in place, gave me a small, casual wave. Mii-chan, meanwhile, looked somewhat nervous, but still lowered her head in a polite bow.<span></span></p></div>\n<div><p>“I never imagined I'd end up in the same group as you, Ayanokōji.”</p></div>\n<div><p>Ike was the first to speak. His tone was surprisingly composed. Even as I considered how best to match his demeanor, he kept going.</p></div>\n<div><p>“When I first saw your face, I thought about giving you a piece of my mind. But since we're stuck in the same group, we might as well try to get along. I'll lend a hand where I can.”</p></div>\n<div><p>“I feel the same way as Kanji,” Shinohara added. “It doesn't seem like this exam is just a straightforward battle, and I think I properly understand just how capable you actually are, Ayanokōji-kun. I'll cooperate however I can, so I look forward to working with you.”</p></div>\n<div><p>It was an unexpectedly amicable greeting from my former classmates. Given the circumstances, they should have harbored overwhelmingly negative feelings toward me. Yet, their smiles were genuine, lacking any trace of deception, and they seemed to be treating me as normally as possible.<span></span></p></div>\n<div><p>In this exam, we were simultaneously allies and enemies. That was precisely why they wanted to keep the peace and approach the situation cordially. Maneuvering to avoid making unnecessary enemies was the tactically correct decision, but I was genuinely surprised to see such sound judgment coming from these two. It felt as though I was witnessing a genuine sign of growth.</p></div>\n<div><p>Considering they were addressing the very person who had betrayed their class, their soft expressions and mild demeanor were practically impeccable. Ike and Shinohara had likely mustered a great deal of courage just to initiate this contact.</p></div>\n<div><p>I let my gaze slip away from the two of them.</p></div>\n<div><p>Then, without stopping, I passed by and moved toward Kushida and Mii-chan, who had been standing just behind them, quietly watching how things were unfolding.</p></div>\n<div><p>”I'm sure there are plenty of difficulties that come with working alongside a traitor,” I said, directing my first words to Mii-chan. “But I look forward to working with you until the exam concludes.”</p></div>\n<div><p>“Eh?” She blinked, visibly caught off guard. “Ah, y-yes. The pleasure is mine...”</p></div>\n<div><p>Though she was flustered, her reply was polite, almost overly so. After receiving it, I shifted my eyes to Kushida, who stood beside her.</p></div>\n<div><p>“It would be a great help if I could rely on you as an ally, too.”</p></div>\n<div><p>“That’s what I should be saying,” Kushida answered with a gentle smile. “I only hope someone like me can be useful.”</p></div>\n<div><p>Her voice was soft, her expression perfectly composed. Only her eyes gave the faintest glimpse of something closer to her true feelings.</p></div>\n<div><p>“I rate your communication skills particularly highly, Kushida,” I said. “With students from all four classes mixed together, managing the group won’t be easy.”</p></div>\n<div><p>“Of course, I'll do everything in my power to help. It would be wonderful if everyone in the group could achieve a good result, wouldn't it?” Ever mindful of the prying eyes around us, Kushida delivered a flawlessly safe response.</p></div>\n<div><p>“That will be sufficient.”</p></div>\n<div><p>With those brief greetings out of the way, I turned my back on them and began walking over to where the Class C students were gathered.</p></div>\n<div><p>“Hey, wait, hold on a second?”</p></div>\n<div><p>“Um, Ayanokōji-kun...?”</p></div>\n<div><p>Ike and Shinohara called after me, their voices carrying the same bewilderment their faces showed. Neither of them seemed to understand what had just happened. They had approached me, offered a greeting, extended something close to goodwill, and I had walked past them as though it had never reached me.</p></div>\n<div><p>I gave them only the briefest glance.</p></div>\n<div><p>Then I continued on.</p></div>\n<div><p>Perhaps realizing just how unnatural this behavior was, Ike raised his voice.<span></span></p></div>\n<div><p>“Wait a minute, you're just gonna ignore us?!”</p></div>\n<div><p>The irritation in him finally began to show. He had been the one to take the first step, forcing down whatever resentment still lingered inside him and choosing to speak to me before Kushida or Mii-chan did.</p></div>\n<div><p>“That's honestly really messed up,” Shinohara said, her tone losing some of its earlier composure. “I mean, seriously… Did we do something to you?”</p></div>\n<div><p>“No, nothing,” I answered. “I simply judged that you weren't worth greeting.”<span></span></p></div>\n<div><p>“Excuse me?!”</p></div>\n<div><p>Showered with such unexpectedly merciless words, their expressions predictably, and rather amusingly, twisted with fresh anger.<span></span></p></div>\n<div><p>Even Kushida likely couldn't have imagined I would say something so harshly blunt.</p></div>\n<div><p>But their reaction was a perfectly natural one. Anyone would be furious if they choked down their negative feelings to politely greet someone, only to receive an unreserved insult in return.</p></div>\n<div><p>“Well then,” I said, already turning away. “I’ll see you later.”</p></div>\n<div><p>Even as I took my leave, I aimed those parting words entirely at Kushida and Mii-chan, completely ignoring the other two.</p></div>\n<div><p>“Ayanokōji!” Ike shouted after me, his restraint finally breaking. “What the hell is your problem?! That attitude is way out of line!”<span></span></p></div>\n<div><p>Though he finally let his suppressed emotions explode, Ike didn't attempt to chase after me.</p></div>\n<div><p>Ignoring his shouting, I resumed my walk toward the area where Yoshida and the others had gathered. Along the way, I noticed a girl standing between us, frozen as though the commotion had caught her attention and then left her unsure of what to do. She was looking directly at me as our eyes met.</p></div>\n<div><p>“...A-Ah, s-sorry! I'm sorry...!” Morofuji stammered, shrinking back almost at once. “F-For being in the way...”<span></span></p></div>\n<div><p>Her apology came out in broken fragments. Before I could say anything, she hurriedly moved aside and fled, her behavior suspiciously restless.</p></div>\n<div><p>There had been no particular reason for her to apologize. Yet the look on her face had gone beyond ordinary wariness. She seemed frightened, unnaturally so.</p></div>\n<div><p>Morofuji had once been among the students involved in the bullying of Karuizawa. Perhaps what happened back then still lingered in her memory and influenced the way she saw me now.</p></div>\n<div><p>As I watched her flee back toward the Class B students, Yoshida approached from the other side and called out to me.</p></div>\n<div><p>“Did something happen with Morofuji?”</p></div>\n<div><p>“No,” I replied. “Nothing in particular.”</p></div>\n<div><p>“I see. More importantly…” Yoshida glanced past me. “Are you sure that’s okay? Ike and Shinohara have been glaring at you this whole time.”</p></div>\n<div><p>He must have overheard parts of our exchange, judging by his concerned tone.</p></div>\n<div><p>“Don't worry about it. I never intended to play nice with my former classmates to begin with,” I replied. “More importantly, now that you’ve seen the members, what's your assessment of our group's lineup?”<span></span></p></div>\n<div><p>“Hm? Oh, well,” Yoshida looked over the gathered group. “I’d say we got off pretty easy. Katsuragi is going to be a pain since he knows us well, but the rest of Class B's members are pretty minor players. Class A is a mixed bag: a weird, mismatched combination of top-tier and bottom-tier students. As for Class D, they're well-balanced, and they seem capable enough, but they aren't exactly intimidating, you know?”</p></div>\n<div><p>Having visualized the upcoming battles, Yoshida offered this straightforward evaluation.</p></div>\n<div><p>“This setup should make things pretty easy for you to maneuver too, right?” he asked.</p></div>\n<div><p>“If we’re only talking about Group Three, then that assessment is correct.” I looked over the assembled students once more. “However, when it comes to the key leaders, figures like Ryūen, Horikita, and Ichinose, it would have been best to have them all placed in the same group as me. Especially Ryūen.”</p></div>\n<div><p>“...<em>Ryūen?” </em>Yoshida’s face twisted at the thought, as if he had just bitten into something bitter. “I'd absolutely hate being stuck in the same group as him.”</p></div>\n<div><p>From a short distance away, Sanada, who had been listening to us, slowly approached.</p></div>\n<div><p>“The more troublesome the opponent, the more useful it is to keep them close. In this special exam, that makes them easier to control. That’s what you’re thinking, isn’t it, Ayanokōji-kun?”</p></div>\n<div><p>“Exactly. Regardless of who I’m up against, my commitment to doing whatever it takes to protect the class and secure a win remains unchanged. But given the structure of this exam, it’s going to be impossible to manage everything happening out of my sight.”</p></div>\n<div><p>Sanada nodded, picking up the exam materials and flipping to the page detailing the penalties.</p></div>\n<div><p>“To a certain extent, I can maneuver things to ensure our classmates don't finish dead last in token counts, or prevent anyone from failing to reach the goal,” I said. “However, the penalty stating that the first student whose tokens drop to zero will face immediate expulsion, that is something I have absolutely no control over.”</p></div>\n<div><p>Yoshida seemed to understand what I meant. His mouth bent into a hard, uneasy line, and after a moment he nodded.</p></div>\n<div><p>“Yeah, you've got a point... If the guys grouped with Ryūen fall for one of his underhanded tricks and hit zero tokens, they'd be instantly expelled on the spot. When you put it like that, it's actually pretty terrifying.”</p></div>\n<div><p>“Of all the penalties outlined in the rules, I feel that's the only one I can't actively counter,” I added.</p></div>\n<div><p>In reality, under a specific set of conditions, there was a chance that an entirely different penalty could bare its fangs and prove even more devastating. However, there was no point in bringing that up right now, so I let the thought pass.<span></span></p></div>\n<div><p>“Isn't it pointless to worry too much about it?” Sanada interjected. “I imagine the school has designed the tasks so that tokens won’t drop to zero that easily.”</p></div>\n<div><p>“Sanada's right,” Yoshida agreed. “As long as someone doesn't do something incredibly stupid and walk right into a trap, they'll be fine. Besides, even if we do worry about it, there's no way to prevent it, right?”</p></div>\n<div><p>“For now, let's prioritize figuring out how our own group is going to maneuver,” Sanada said.</p></div>\n<div><p>I gave a single nod in agreement.</p></div>\n<div><p>From here on out, my process would be the same as always. I needed to gather all the scattered building blocks of practical strategies before me and begin sorting through them based on what was efficient and what wasn’t.</p></div>\n<div><p>I had already eliminated many unnecessary possibilities from consideration, but I still lacked the information necessary to map out the hidden motives of the class leaders: Horikita, Ichinose, and Ryūen.<span></span></p></div>\n<div><p>More time was needed before I could fully analyze the finer details of the rules.</p></div>\n<div><p>In the meantime, with our faculty supervisor still nowhere to be seen, I let my gaze drift around the area.</p></div>\n<div><p>Naturally, the entirety of the third-year student body, along with numerous adult staff members, were hurriedly gathering nearby.</p></div>\n<div><p>That said, I wasn't scanning the crowd to figure out the composition of all ten groups, nor was I trying to map out who belonged where. While I could roughly identify some of it just by observing the crowd here, without any way to guarantee complete accuracy, there was little value in trying to memorize it all.</p></div>\n<div><p>My true objective was simpler than that.</p></div>\n<div><p>I was looking for one particular person.<span></span></p></div>\n<div><p>And sure enough, I eventually spotted Hiyori in the distance, chatting happily while surrounded by her classmates. If she had been closer, I might have been able to call out to her, but the physical distance made that completely impossible.</p></div>\n<div><p>It seemed I really was fated to have no meaningful interaction with her during this Uninhabited Island Exam.</p></div>\n<div><p>But there was no need to rush.</p></div>\n<div><p>Once we returned to the cruise ship, there would inevitably be time to talk.</p></div>\n<div><p>“...”</p></div>\n<div><p>Suddenly, a strange sense of dissonance crept into my thoughts.</p></div>\n<div><p>That’s right. There was no need to rush.<span></span></p></div>\n<div><p>And thinking I was ‘fated to have no connection’ with her was logically incorrect, too.</p></div>\n<div><p>It was true that we hadn't spoken for a few days, not since we first boarded the cruise ship. But a few days wasn't nearly long enough to warrant such a dramatic conclusion. In fact, looking back, there had been plenty of times where we had gone much longer without interacting at all.</p></div>\n<div><p><em>So why was I suddenly overwhelmed by the sensation that it had been an eternity since we last spoke?</em></p></div>\n<div><p>No...</p></div>\n<div><p><em>Was the very fact that I was questioning the reason already proof that I had entered unfamiliar territory?</em></p></div>\n<div><p><em>Was this the effect of realizing I might have feelings for Hiyori, the change it had brought about in my heart?</em><span></span></p></div>\n<div><p>Given the current lack of concrete exam details, Hiyori, who belonged to a different class and a completely different group, was nothing but static noise. Her existence factored nowhere into the strategic framework I was currently constructing.</p></div>\n<div><p>And still, my eyes followed her.</p></div>\n<div><p>Unconsciously, they traced the distant outline of her profile.</p></div>\n<div><p>Even after I realized what I was doing, nothing changed.</p></div>\n<div><p>The action was pointless. The time spent on it served no practical purpose. Even so, somewhere within that uselessness, there was a faint stirring of exhilaration.</p></div>\n<div><p>If this feeling really was romantic affection, then had Karuizawa once looked at me in the same way? Had she felt something similar when her eyes followed me?</p></div>\n<div><p>Romance was a textbook I had failed to comprehend on my first read-through. But by reviewing the material, I was gradually beginning to notice all the subtle details I had missed the first time around.<span></span></p></div>\n<div><p><em>What sort of emotion was born when speaking to the person one liked?</em></p></div>\n<div><p><em>What arose when touching them?</em></p></div>\n<div><p>My curiosity wasn't limited to purely positive feelings, either.</p></div>\n<div><p><em>What sort of emotions would be born within me if I were to be hated by that same person, or if I were to lose them entirely?</em><span></span></p></div>\n<div><p>I wanted to experience both ends of it: the warmth of affection, and the coldness of rejection. Love and hate alike.</p></div>\n<div><p>Yet perhaps it was foolish to wish for both at the same time.</p></div>\n<div><p>Perhaps it was important not to be greedy. Perhaps one should not try to learn everything from a single romance.</p></div>\n<div><p>If attaining both was impossible, then experiencing either one would suffice...<span></span></p></div>\n<div><p>“What's wrong, Ayanokōji? Something bothering you?”</p></div>\n<div><p>Yoshida, who had been speaking with Sanada only moments before, turned his attention toward me.</p></div>\n<div><p>“No, not particularly,” I replied. “Why do you ask?”</p></div>\n<div><p>“Well, it’s not exactly why……” He glanced in the direction I had been looking, then back at me. “You were staring off into the distance. I thought maybe you’d noticed something we should be worried about.”</p></div>\n<div><p>“We just finished the Survival Game Special Exam, after all,” I replied smoothly. “I suppose I'm just a little worn out. But considering Shiraishi and Yamamura are still giving it their all, I can't exactly be the first one to throw in the towel.”<span></span></p></div>\n<div><p>Taking a brief pause, I decided to steer the conversation and add a bit more context.</p></div>\n<div><p>“Right now, we don't have the full picture. We don't know the exact number of tasks, nor how many tokens we'll actually be able to acquire. Whatever happens, please do not leak any information regarding your token counts to anyone outside.”</p></div>\n<div><p>“Not even to our allies, right? I heard that from Hashimoto,” Yoshida said.</p></div>\n<div><p>“Right. And for now, I’d also like to avoid unnecessary conflict with the other classes. If we’re going to aim for first place in this group, like you’re hoping, then cooperation with students from the other classes will be unavoidable.”<span></span></p></div>\n<div><p>“I suppose that's true,” Sanada chimed in. “But I wonder how the other side feels about that. I'm sure they want the Private Points, but they probably don't want our class to win, either. They might end up slacking off on purpose.”</p></div>\n<div><p>“Even if they do, the leaders of the other three classes are facing the exact same dilemma. The underlying motive of not wanting to hand another class a victory will always be a factor.”</p></div>\n<div><p>Sanada and Yoshida exchanged a brief glance, quickly understanding the logic behind my words.</p></div>\n<div><p>“I get what you're saying,” Yoshida said. “Anyway, just give us the word whenever you need us.”</p></div>\n<div><p>I gave a single nod, letting my demeanor convey my gratitude.</p></div>\n<div><p>Satisfied with my convenient excuse, Yoshida gave me a light pat on the back.</p></div>\n<div><p>“Don't hesitate to reach out if you need a hand.”</p></div>\n<div><p>“Yeah, I will.”</p></div>\n<div><p>With that response, I finally tore my lingering gaze away from Hiyori.</p></div>\n<div><p>For the time being, all I needed to focus on was getting through this Special Exam. Everything beyond that could wait.<span></span></p></div>\n<div><h2>Part 2</h2></div>\n<div><p>Right around the time Ayanokōji was making his first contact with Group 3, Horikita, assigned elsewhere to Group 8, was experiencing a face-to-face encounter of her own.</p></div>\n<div><p>A gentle sea breeze playfully tossed the long, pink hair of the student standing before her. A warm smile graced the girl's lips as she spoke.</p></div>\n<div><p>“I look forward to working with you, Horikita-san.”</p></div>\n<div><p>“I knew there was a decent chance that class leaders might end up in the same group, but to think I'd be paired with you of all people, Ichinose-san.”</p></div>\n<div><p>Inwardly, Horikita breathed a sigh of relief. Out of the three rival leaders, Ichinose was by far the easiest to manage. It wasn't a question of her being a weak opponent, but rather a certainty: <em>having Ichinose Honami as an ally would bring an immense sense of stability to their group.</em></p></div>\n<div><p>This special exam certainly contained the element of competition between classes. However, it also placed heavy importance on the results achieved by each group as a whole. In that regard, Ichinose’s presence was almost guaranteed to steer them in a positive direction.</p></div>\n<div><p>“If this were a purely class-based competition, it might have been a bit troublesome,” Ichinose said. “But looking at the rules, cooperating as a group clearly leads to mutual benefit, so it's a rather good setup. If you and I pool our strengths, Horikita-san, we might just be able to guide our group to a safe and steady victory.”</p></div>\n<div><p>It seemed Ichinose had been harboring the exact same thoughts.</p></div>\n<div><p>Yet, looking at the girl standing before her, Horikita sensed a quiet, powerful intensity that hadn't been there before. As an enemy, this newfound strength would be a nightmare to deal with. But as an ally? It made her incredibly reliable.</p></div>\n<div><p>“True enough,” Horikita replied. “As leaders, our group is expected to secure a win. Under normal circumstances, we'd be probing each other for ulterior motives, but instead, we will cooperate and aim for the highest rank possible... I take it we're in agreement on that?”</p></div>\n<div><p>Whether they chose to cooperate or oppose would determine everything. It was possible to send tokens to other groups, deliberately weakening their own side in order to prevent another class from profiting. Depending on the policy they adopted, the total number of tokens their group could secure would change dramatically.</p></div>\n<div><p>“Of course,” Ichinose replied brightly. “If our group takes first place, we'll each be rewarded with one hundred Class Points. It's the ideal outcome for both of us. And it won't just be me, if necessary, I'll firmly request the full cooperation of everyone in Class D. Does that work for you?”</p></div>\n<div><p>“I'll gladly accept your offer,” Horikita said smoothly. “On our end, I also intend to unite my classmates under a policy of securely maximizing our group's total tokens. Though, naturally, that will heavily depend on the moves made by Class B and Class C, whose hands we've yet to see.”</p></div>\n<div><p>Students from the other classes began to appear one by one, but there was no sign of Ayanokōji or Ryūen among them.</p></div>\n<div><p>Hypothetically, if all four class leaders had ended up in the same group, cooperating to maximize their total token yield would have been a simple affair. However, such an arrangement offered little benefit to anyone aside from the front-running Class A.</p></div>\n<div><p>A precious Special Exam like this was a rare opportunity to widen the gap between classes; but if every leader simply worked together in the same group, that precious chance would be dulled from the outset.</p></div>\n<div><p>“It seems coming to a mutual understanding and aiming for first place will go smoother than expected,” Horikita noted. “However, there is one critical issue that both you and I must treat with the utmost importance.”</p></div>\n<div><p>“How to handle the expulsions... right?”</p></div>\n<div><p>Their eyes met, and Horikita gave a firm nod.</p></div>\n<div><p>It had already been established that this Special Exam would result in expulsions. Worse still, one of those was a mandatory penalty that <em>someone </em>absolutely had to shoulder. The only ways to prevent a student from being sent home were if the target conveniently held a Protection Point, or if someone paid the exorbitant fee of 20 million Private Points.</p></div>\n<div><p>“Horikita-san,” Ichinose said, her tone resolute. “I absolutely will not allow a single one of my classmates to be expelled. If securing first place in total tokens requires sacrificing a peer, then I will choose to save my ally without a second thought.”</p></div>\n<div><p>The unspoken message from Ichinose was clearly hanging in the air: <em>If you have a problem with that, speak up now.</em></p></div>\n<div><p>Taking the declaration in stride, Horikita drew a quiet breath before responding. “I agree. I have no intention of sacrificing my classmates either.”</p></div>\n<div><p>“Then I suppose that makes us allies who can join hands and face the same direction, right?”</p></div>\n<div><p>“...Assuming you're willing to trust me, that is.”</p></div>\n<div><p>Horikita was well aware that she hadn't garnered nearly as much goodwill and trust as Ichinose had. She knew her standing. Right now, she was the one who needed to prove she was worthy of being trusted.</p></div>\n<div><p>“Then it looks like we won't have any problems!”</p></div>\n<div><p>Breaking into a bright, unwavering smile, Ichinose extended her hand.</p></div>\n<div><img alt=\"Chapter Image\" width=\"600\" height=\"800\" src=\"https://cdn.sanity.io/images/m1xj6lbt/production/09779d2ff988ea23846805b0c78a8ec1dbeaa1e6-2000x2808.webp\"><span><span></span></span></div>\n<div><p>Seeing her unhesitating demeanor, Horikita couldn't help but let out an inward sigh of admiration.</p></div>\n<div><p>Over the past two years, Ichinose had weathered countless storms through the sheer power of trust, a track record that spoke volumes. Horikita had felt it indirectly on several occasions, but standing beside her in the same group brought that strength into incredibly sharp, reassuring focus. Under normal circumstances, one should never easily trust a rival. Yet, Horikita found her mind effortlessly jumping to the conclusion that Ichinose was safe to believe in.</p></div>\n<div><p>Of course, that trust was not absolute. The possibility of betrayal, however remote, could never truly be erased.</p></div>\n<div><p>But the mere fact that Ichinose could subconsciously instill such an unwavering mindset in someone: making them feel that <em>if I am betrayed by Ichinose, then so be it, </em>was a profoundly impressive feat in itself.</p></div>\n<div><p>“Before I take your hand, there is one more thing…”</p></div>\n<div><p>Staring down at Ichinose's slender, elegant fingers, Horikita pressed further, delving into the crux of the matter.</p></div>\n<div><p>“Sacrifices are practically unavoidable in this exam. However, we are agreeing that neither of our classes will produce any expulsions, and we will maneuver with everything we have to ensure that. Maintaining this policy means, by process of elimination, cornering someone from either Ryūen-kun's or Ayanokōji-kun's class for expulsion instead. Are you prepared for that?”</p></div>\n<div><p>At the sharp question, Ichinose closed her eyes for a moment, letting out a soft, breathy laugh.</p></div>\n<div><p>“It's true that the old me probably wouldn't have agreed so easily,” she admitted. “But I don't hesitate anymore. You can rest assured, Horikita-san, I have no intention of holding back against rival classes if it means protecting my friends.”</p></div>\n<div><p>Horikita met that open, unwavering gaze head-on.</p></div>\n<div><p>“I see. It seems you've grown far more than I realized while I wasn't looking, Ichinose-san.”</p></div>\n<div><p>Horikita had always recognized her as a formidable opponent. Yet, somewhere deep down, she had still been underestimating the student known as Ichinose Honami.</p></div>\n<div><p>Being a genuinely good person usually meant harboring inherent weaknesses beneath the surface. Protecting an entire class was no easy feat; Horikita and Hirata had both tried countless times, only to fall short of that ideal. Yet, despite her bitter struggles, Ichinose had continued to protect her classmates to this very day, refusing to lose a single one.<span></span></p></div>\n<div><p>“I feel the exact same way about you, Horikita-san,” Ichinose replied softly. “You're much more formidable now than when we first enrolled.”</p></div>\n<div><p>“I wonder about that. Personally, I feel it's only become harder to maneuver now that I have more things to protect…” Horikita trailed off before continuing. “But more importantly, there is something that's been bothering me since we heard the explanation for this Special Exam. Ensuring our allies' tokens don't drop to zero will require a certain element of luck. What are your thoughts on that?”</p></div>\n<div><p>“Have you noticed the correlation between the number of starting tokens and the Survival Game Special Exam?”</p></div>\n<div><p>“Yes,” Horikita answered. “Students who remained in the previous exam for a longer time seem to have received more tokens. Of course, I haven’t confirmed it with every classmate, so I can’t say for certain…”</p></div>\n<div><p>She added, after a moment, that this was based only on what she had heard from several students whose elimination times had differed.</p></div>\n<div><p>“That is my assessment as well,” Ichinose said. “In other words, you could say we have a slight advantage over Ayanokōji-kun's and Ryūen-kun's classes, since both suffered a high number of early eliminations.”</p></div>\n<div><p>“Your class even had students who remained until the very end. If that conclusion can be drawn from the highest number of tokens among them, then you’re probably right. However, simply having a high total token pool as a class doesn't necessarily mean things will proceed to our advantage.”</p></div>\n<div><p>Ultimately, because the students had been distributed randomly, a high class total would only create variance between the different groups, or at best, provide an edge in individual battles.</p></div>\n<div><p>“But holding a large number of tokens as a class does mean a massive difference in how often we can transmit information over the radios,” Ichinose countered. “If you and I cooperate to meticulously manage our tokens, Horikita-san, we can constantly keep track of any students whose counts drop dangerously low. Excluding Group 10, which doesn’t have full sixteen members, we’d have eight people in each group who could transfer tokens and cover for one another.”</p></div>\n<div><p>“I see... You're suggesting that everyone outside of our Group 8, which will strictly aim for first place, maneuvers solely to prevent casualties? Transferred tokens are flipped Back-side, meaning they lose their value for individual rewards. But from our group's perspective, it also means the rival groups we need to defeat will naturally fall behind.”</p></div>\n<div><p>Under normal circumstances, coordinating two separate classes with such a unified strategy was no simple task. First and foremost, it required forcing the students assigned to the other nine groups to completely abandon any hope of acquiring the Special Reward. While the monolithically united Ichinose Class might accept such terms, convincing every single one of Horikita's classmates to swallow that pill would be practically impossible.</p></div>\n<div><p>“It's an interesting idea,” Horikita said, “but it means forcing students in other groups who might be perfectly capable of pulling off a massive upset to sacrifice their chances. If anything, wouldn't the groups completely free of Ryūen-kun and Ayanokōji-kun's influence be the ones harboring the best chance for a surprise victory?”</p></div>\n<div><p>This exchange perfectly highlighted their fundamental difference in approach. Ichinose wanted to fight with a heavily defensive focus, prioritizing collective survival, while Horikita wanted to maintain a certain degree of offensive awareness, seeking out opportunities to win.</p></div>\n<div><p>Even with their agreement to cooperate, Horikita couldn't shake the strong premonition that this Special Exam was going to be fraught with difficulties.</p></div>\n<div><p>“You're right,” Ichinose agreed softly. “I'm sure we won't always see eye to eye. But this Special Exam lasts for four days and three nights. Let's discuss things thoroughly and decide our course as we go, Horikita-san.”</p></div>\n<div><p>“True. We still don't know what the specific tasks entail or how the tokens will flow in practice. There's no point in rushing things.”</p></div>\n<div><p>“Alright then. I’ll go speak to everyone in the group.”</p></div>\n<div><p>With a polite bow, Ichinose excused herself and stepped away.</p></div>\n<div><p>Standing alone at a slight distance, Horikita watched as Ichinose cheerfully exchanged greetings with students from other classes.</p></div>\n<div><p>“I know there's no need to rush, but…” she murmured to herself.</p></div>\n<div><p>Her mind drifted back to a troubling exchange she’d had with Sudō immediately following the Survival Game Special Exam.</p></div>\n<div><p><em>“There might be a traitor in our class.”</em></p></div>\n<div><p>He had told her how, during Class A's battle, the opposing students had completely bypassed him, despite the massive physical threat he posed on the battlefield, to aggressively target Satō, their VIP.</p></div>\n<div><p>If Horikita had been the enemy commander, she would have undoubtedly prioritized taking Sudō off the board first. If the opposition had instead focused all their fire on Satō... and if someone had been pulling the strings from the shadows to orchestrate that...</p></div>\n<div><p><em>“Is someone in our class really leaking information...?”</em></p></div>\n<div><p>Her gaze drifted, eventually landing on Ayanokōji's figure in the distance. Gathered with him were four students from Class A: Wang, Shinohara, Ike, and Kushida.</p></div>\n<div><p>Before the first semester had even come to an end, the four classes had already settled in a tense state of equilibrium.</p></div>\n<div><p>If all of their internal affairs were truly leaking out, then the strategies or information Horikita relayed to her classmates would inevitably find their way to Ayanokōji.</p></div>\n<div><p>Should that come to pass, they would be forced into a grueling, uphill battle in this Special Exam as well.</p></div>\n<div><p>And so, like a quiet, stubborn ember, that dark anxiety continued to smolder within her chest.</p></div>\n<div><h2>Part 3</h2></div>\n<div><p>Before the exhaustion from the Survival Game Special Exam could even fade, a new Special Exam was already upon them. As Mashima outlined the rules, Ryūen was already turning over several strategies in his mind.</p></div>\n<div><p>Ever since enrolling at this school, he had tackled every obstacle with absolute, unshakable confidence in his own judgment. Yet lately, no matter the time or situation, the phantom image of Ayanokōji seemed to constantly flicker at the back of his mind.</p></div>\n<div><p>Orthodox tactics, unconventional schemes, or even outright lawlessness that shattered the rules themselves, Ayanokōji would see right through all of it and still come out on top.</p></div>\n<div><p>Ryūen caught himself preemptively conceding defeat for a future that had yet to even unfold.</p></div>\n<div><p>If this were a mere battle of wits, he would have countless ways to counterattack. But Ayanokōji also possessed monstrous physical prowess. The memory of their shootout with paint guns flashed behind his eyes, prompting Ryūen to let out a quiet, sharp click of his tongue.</p></div>\n<div><p>“Is something the matter, Ryūen-shi? Did something displease you?”</p></div>\n<div><p>Having been placed in the same group, Kaneda seemed to have noticed that small sound. He called out to Ryūen, his gaze shifting toward the other members who were starting to gather.</p></div>\n<div><p>“I was just thinkin' about that bastard Ayanokōji. Don't sweat it.”</p></div>\n<div><p>“...So it has to do with Ayanokōji-shi. I see.”</p></div>\n<div><p>If Ayanokōji were left to his own devices, his group would easily secure first place in total tokens. Between that and the Special Reward for individual performance, Class C stood to gain a massive haul of up to 200 Class Points. On top of that, the influx of Private Points would grant them an even more dangerous degree of freedom.</p></div>\n<div><p>The comfortable advantage Ryūen's class had maintained up until now had completely vapourised during the first half of the uninhabited island exam. Even if official class demotions wouldn't take effect until the following month, they had already bled enough Class Points to provisionally plummet from Class B down to Class C. Worse yet, the gap between them and Ayanokōji's last-place class was now razor-thin.</p></div>\n<div><p>Simply put, it was a battle they absolutely could not afford to lose. Then again... the exact same thing could have been said about the last Special Exam.</p></div>\n<div><p><em>Just how is he supposed to outmaneuver Ayanokōji?</em></p></div>\n<div><p>Ayanokōji would undoubtedly rake in a massive haul of Front-side tokens. The real question was whether Ryūen could actually surpass that total. If outscoring him directly proved impossible, then beating him in the group rankings to secure the token multiplier was an absolute must. It was the bare minimum requirement for Ryūen to secure a victory.</p></div>\n<div><p>Then there was the expulsion penalty, triggered the moment a student's token count hit zero.</p></div>\n<div><p>No matter how monstrous Ayanokōji might be, he couldn't protect all his classmates twenty-four hours a day. If Ryūen could seize total control of their group, eliminating a single student from Class C would be entirely within his grasp.</p></div>\n<div><p>Letting his gaze drift across the area, Ryūen spotted Ayanokōji a short distance away. Yoshida was standing right beside him, chattering about something, but the boy didn't even register in Ryūen's field of vision.</p></div>\n<div><p>Ayanokōji was staring off in another direction, his eyes characteristically listless.</p></div>\n<div><p><em>“What the hell is that bastard staring at—”</em><span></span></p></div>\n<div><p>Just because Ayanokōji’s thoughts and emotions were hidden behind an impenetrable wall didn't mean Ryūen was going to give up trying to read him. To find a breakthrough, he had no choice but to strike like a serpent, sinking his fangs into even the most trivial of clues.</p></div>\n<div><p>And so, Ryūen traced the line of Ayanokōji's gaze.</p></div>\n<div><p>Normally, pinpointing exactly what someone was looking at from a distance was nearly impossible, especially with so many students clustered tightly together.</p></div>\n<div><p>Yet, Ryūen realized it instantly.</p></div>\n<div><p>Standing at the very end of Ayanokōji's unblinking gaze was the figure of Shiina Hiyori.<span></span></p></div>\n<div><p>“Ryūen-kun, it looks like we're in the same group.”</p></div>\n<div><p>A voice shattered his concentration just as he was trying to dissect Ayanokōji's thoughts.</p></div>\n<div><p>“What the hell do you want?”</p></div>\n<div><p>Whipping his sharp glare toward the intruder, Ryūen found Hirata Yōsuke standing right in front of him.</p></div>\n<div><p>“I'd like to make a request right off the bat,” Hirata said. “I don't want anyone in this group to be expelled.”</p></div>\n<div><p>“Hah, you've got a damn sharp nose,” Ryūen scoffed. “But that's one wish I ain't granting, Hirata. This is the perfect chance to kick someone out of your precious Class A, after all. Don't go thinkin' you're the only one sitting safe and sound.”</p></div>\n<div><p>“If you want to target me, I don't intend to stop you,” Hirata replied evenly. “But if you plan on expelling any other student from Class A... or from Class C, for that matter, then I'll have to make you listen.”</p></div>\n<div><p>Hirata had accurately read the atmosphere. He knew from Ryūen's gaze alone that Class A wasn't even on his radar; Ryūen was actively scouting for prey in Class C. That was exactly why Hirata's statement carried such a pointed implication.</p></div>\n<div><p>“I ain't got any reason to take orders on who I target,” Ryūen sneered. “Or what? You got something to offer in exchange for me lettin' the small fry off the hook?”</p></div>\n<div><p>“Well, I suppose I could become proactive about cooperating across class lines. You're a class leader, Ryūen-kun, which means a victory for our group is also a victory for Class B.”</p></div>\n<div><p>“I can't think of a single damn reason why a Class A guy like you would lend me a hand.”</p></div>\n<div><p>“It's simple, really. We can avoid producing any pointless expulsions. To me, that is the greatest merit.”</p></div>\n<div><p>“Seems like you've got the same pain-in-the-ass personality as Ichinose.”</p></div>\n<div><p>“I don't mind what you think of me. I just want to settle things peacefully.”</p></div>\n<div><p>Rather than jumping to a hasty conclusion, Ryūen paused to weigh the credibility of Hirata's words and demeanor, carefully considering which path would best serve his goals.</p></div>\n<div><p>Even if he did drain someone's tokens to zero and force an expulsion from Class C, it would amount to little more than petty harassment directed at Ayanokōji. It wouldn't directly impact his own class's standing or net them any points. Furthermore, one could argue that any student careless enough to let their tokens hit zero was just dead weight anyway. Going out of his way to eliminate them, especially at the cost of making an enemy out of Hirata, held very little strategic value.</p></div>\n<div><p>On the other hand, if Hirata's offer to cooperate was genuine, it would be a distinct advantage.</p></div>\n<div><p>Gazing at the other students gathering for their group, Hirata continued.</p></div>\n<div><p>“Given the severe penalties in this Special Exam, I know it wouldn't be impossible for you to set a trap and expel someone from Class C, Ryūen-kun. However, the only reason you're keeping the option to target a lower-ranked class open is to inflict damage on Ayanokōji-kun. But even if you could freely pick off one of the four people in our group... or rather, one person from Class C, it wouldn't actually affect him. You wouldn't be scoring a real point against him, would you?”</p></div>\n<div><p>It was a simple truth. If Ayanokōji were in the same group and Ryūen managed to crush his strategy in a direct confrontation before expelling a Class C student, it would undoubtedly be a massive victory. But under the current rules, there were inevitable blind spots where they couldn't observe one another. Scoring a cheap hit while the demon was away was nothing to brag about.</p></div>\n<div><p>“If anything, it might just prove that you're a small fry,” Hirata added.<span></span></p></div>\n<div><p>“Don't make me laugh.” Opting to put his final decision on hold, Ryūen threw the threat back at him. “You want to protect this makeshift group so badly you'd go out of your way to provoke me? Then you're gonna have to show it with your actions first.”</p></div>\n<div><p>He calculated that if Hirata could actually operate as an ally rather than an enemy in this Special Exam, his utility value would be immense.</p></div>\n<div><p>As if anticipating this demand from the very beginning, Hirata gave a single, firm nod.</p></div>\n<div><p>“I know.”</p></div>\n<div><p>From the corner of his eye, Ryūen caught sight of Hirata’s rigid expression— so unlike the image he had held of him until now that, for the first time, he sensed within him a faint trace of murderous intent.<span></span></p></div>",
    "4": "<div><p>It was already past five in the evening.</p></div>\n<div><p>Even with the late midsummer sunset, there was no denying that dusk was beginning to settle over the island.</p></div>\n<div><p>Yet, far from recovering from the fatigue of the Survival Game, some students stepped directly into another special exam, still carrying all of their accumulated exhaustion.</p></div>\n<div><p>As the time to begin the exam drew near, the supervisors finally made their appearance.</p></div>\n<div><p>“My name is Urushibara,” one of the adults announced calmly as he stepped forward. “I will be serving as the supervisor for Group 3. I look forward to working with all of you.”</p></div>\n<div><p>He was a man I had never seen before. After introducing himself, he immediately began checking attendance with efficient professionalism.</p></div>\n<div><p>Out of the ten groups, four had apparently been assigned third-year homeroom teachers as supervisors.</p></div>\n<div><p>Urushibara belonged to the remaining six.</p></div>\n<div><p>Once he confirmed that everyone was present, he continued without delay.</p></div>\n<div><p>“In this special exam, you will challenge a variety of tasks in order to acquire tokens. These tasks are divided into three separate categories, so please listen carefully while I explain. The three categories are: <em>Individual, Group, </em>and <em>Team.</em></p></div>\n<div><p>“<em>Individual </em>category is the simplest to understand. These are assignments issued to students on a one-on-one basis. You may compete individually against someone from your own group, or against a student from another group.</p></div>\n<div><p>“Next is the <em>Group </em>category. These involve all sixteen members currently assembled here working together to complete tasks issued by the school, or competing directly against entire other groups.</p></div>\n<div><p>“And finally, <em>Team. </em>This category further divides the group according to class affiliation. In other words, students from the same class within the group will form smaller units. Since these tasks contain more specialized rules, detailed explanations will be given at the time those assignments are actually conducted.”</p></div>\n<div><p>After confirming everyone was following along without issue, the supervisor, Urushibara continued.</p></div>\n<div><p>“Now then, next I’d like to explain how tokens will be awarded. However, before we proceed, each class within the group must first select one ‘representative.’”</p></div>\n<div><p>Up until now, neither Mashima-sensei’s explanation nor the written materials had mentioned anything about a representative.</p></div>\n<div><p>Hearing this unfamiliar role for the first time, the students exchanged puzzled glances.</p></div>\n<div><p>“Does becoming the representative come with any benefits?” Sonoda asked cautiously. “Actually… if there are disadvantages too, I’d rather hear about those now.”</p></div>\n<div><p>Though conscious of the students around him, Sonoda took the initiative and asked the question.</p></div>\n<div><p>“No,” Urushibara replied calmly. “There are no particular advantages or disadvantages attached to the role itself. However, the system has been designed so that any tokens earned by a class are awarded in bulk to that class’s representative.”</p></div>\n<div><p>A ripple of confusion spread through the group.</p></div>\n<div><p>“This will become relevant during the <em>Group </em>and <em>Team </em>categories,” he continued. “For example, let’s say Class A earns ten tokens through a Group or Team assignment. If Ike-kun has been selected as Class A’s representative, then all ten of those tokens will first be awarded directly to him.”</p></div>\n<div><p>Up until that moment, every student there, including me, had naturally assumed that any tokens earned would be distributed directly to the individuals who participated.</p></div>\n<div><p>That fundamental assumption had just been overturned completely.</p></div>\n<div><p>Whether tokens were granted individually or concentrated in the hands of a representative was an enormous difference.</p></div>\n<div><p>“Hah? What the hell is that supposed to mean?” Ibuki snapped immediately, realizing how abnormal this system was, she glared suspiciously at Urushibara. “So if they wanted to, the representative could just pocket all the tokens for themselves?”</p></div>\n<div><p>“The school has no intention of encouraging such behavior,” Urushibara answered evenly. “However, under the rules, it is technically possible. Contribution levels during assignments may vary depending on the task, after all, so classes may need to discuss internally how tokens should be distributed afterward. In that sense, the representative role may require a certain level of integrity.”</p></div>\n<div><p>The supervisor gave a seemingly reasonable explanation, but this setup had caused the risks to skyrocket.</p></div>\n<div><p>Exactly as Ibuki feared, placing all token management in the hands of a representative meant there was no guarantee that tokens would ever actually reach the students who earned them.</p></div>\n<div><p>Only the <em>Individual </em>category seemed exempt from this structure.</p></div>\n<div><p>But assuming the rewards across all three categories were distributed relatively evenly, then that meant a student could directly control only about one-third of the tokens tied to their own survival.</p></div>\n<div><p>“However, there is one important point you all need to understand regarding front-side and back-side tokens,” Urushibara continued.</p></div>\n<div><p>“Any token earned through the <em>Individual </em>category will, without exception, count as a front-side token. But tokens earned through the <em>Group</em> and <em>Team</em> categories work differently. The total number of tokens earned in a given assignment will first be divided according to the number of participants involved. For instance, let’s say a Group-category assignment awards forty-eight tokens. Since there are four classes represented within the group, each class representative would temporarily receive twelve tokens. But since the group itself contains sixteen students, only three of those twelve tokens per student would qualify as legitimate front-side tokens. That number becomes the upper limit recognized as a properly earned individual contribution. If a student were to receive four tokens in that situation, then one of those tokens would automatically become a back-side token. The right to possess front-side tokens does not expire and continues accumulating over time. As such, there is no disadvantage regarding <em>when </em>representatives choose to distribute tokens.”</p></div>\n<div><p>Putting it simply, the rules worked like this:</p></div>\n<div><hr></div>\n<div><p><strong>Token Distribution Rules</strong></p></div>\n<div><p>Categories of Assignments:</p></div>\n<div><p><em>Individual, Group &amp; Team</em></p></div>\n<div><p><strong>Individual Assignments:</strong></p></div>\n<div><p><em>All tokens earned personally are treated as front-side tokens.</em></p></div>\n<div><p><strong>Group / Team Assignments:</strong></p></div>\n<div><p><em>All earned tokens are first funneled through the class representative.</em></p></div>\n<div><p><em>The maximum number of front-side tokens that may be distributed is determined by:</em></p></div>\n<div><p><em>Total Tokens Earned ÷ Number of Participants</em></p></div>\n<div><p><em>Any tokens distributed beyond that limit automatically become back-side tokens.</em></p></div>\n<div><p><strong>Front-Side Token Rights:</strong></p></div>\n<div><p><em>Front-side eligibility accumulates over time.</em></p></div>\n<div><p><em>Representatives are free to choose the timing of distribution.</em></p></div>\n<div><hr></div>\n<div><p>“This rule seriously sucks.” Ibuki muttered under her breath.</p></div>\n<div><p>The distinction between front-side and back-side tokens likely existed to prevent representatives from simply monopolizing all earned tokens and charging toward the Special Reward themselves.</p></div>\n<div><p>But even with that safeguard in place, the privileges granted to representatives were enormous, far greater than what Urushibara’s casual tone implied.</p></div>\n<div><p>They controlled the distribution of tokens tied to Private Point rewards, and could potentially even avoid expulsion from finishing last.</p></div>\n<div><p>Urushibara also clarified that indivisible remainders created during division would simply be ignored.</p></div>\n<div><p>So even if 41 tokens were earned, dividing them among four people would still only create a front-side limit of 10 per class student. The extra one token wouldn’t increase the cap at all.</p></div>\n<div><p>“Now then,” Urushibara said, “please discuss among yourselves and decide who will act as representative for each class. If a decision cannot be reached within the allotted time, a vote will be held among the relevant team members.”</p></div>\n<div><p>“So they’re intentionally concentrating token control into one person’s hands,” Sanada said grimly. “From the students’ perspective, this rule feels almost entirely disadvantageous.”</p></div>\n<div><p>“Feels like they’re trying to provoke infighting,” Yoshida added.</p></div>\n<div><p>In truth, that was likely the case.</p></div>\n<div><p>At its core, the exam was testing whether classmates could trust one another. And whether the person receiving that trust could actually live up to it.</p></div>\n<div><p>“I don’t know who’s going to become the representative,” Ibuki said, narrowing her eyes, “but you’d better make sure you hand over my tokens properly.”</p></div>\n<div><p>The rule had already planted distrust in her. Without bothering to hide it, she turned that suspicion directly toward her own Class B teammates.</p></div>\n<div><p>Katsuragi answered her in his usual calm manner.</p></div>\n<div><p>“Generally speaking, it shouldn’t become a situation where someone tries to bring down another person. And to make sure we don’t choose that kind of person as representative, we should decide through a fair method.”</p></div>\n<div><p>In other words, a simple majority vote.</p></div>\n<div><p>It was the most straightforward and acceptable selection method.</p></div>\n<div><p>Meanwhile, other classes had begun moving in their own ways.</p></div>\n<div><p>“I’m thinking I’ll become the representative,” said a sharp, intimidating voice from within the Class A team. “That’s fine, right, Mii-chan?”</p></div>\n<div><p>The voice belonged to Shinohara.</p></div>\n<div><p>“A-Y-Yes, I don't mind that, but…”</p></div>\n<div><p>Mii-chan nodded, looking slightly bewildered, but not particularly inclined to reject Shinohara’s candidacy. She was not the type who liked standing out in front of others. If someone else was willing to take on the role, then perhaps she thought it was better to simply let them do it.</p></div>\n<div><p>“Mii-chan says she’s fine with it too,” Shinohara said, a confident smile appearing on her face. “So it looks like there’s no problem.”</p></div>\n<div><p>She acted as though one hesitant opinion had already secured the position for her.</p></div>\n<div><p>“Um,” Mii-chan said, instinctively speaking up as she realized her single vote was about to be treated as final, “shouldn’t we check with Ike-kun and Kushida-san too—”</p></div>\n<div><p>But Shinohara paid her no mind.</p></div>\n<div><p>In this special exam, falling to the bottom in token count was directly tied to expulsion. When one thought several moves ahead, there was still reason to question whether Shinohara or Ike, for that matter, should be chosen so easily as representative.</p></div>\n<div><p>Kushida likely understood that as well. Precisely because she did, she must have recognized that allowing herself to be swept along like Mii-chan would be nothing short of risky.</p></div>\n<div><p>The brief silence that fell over Class A was heavy and delicately long, one that couldn't easily blend into the surrounding conversations from the other classes.</p></div>\n<div><p>Before anyone could even voice opposition, the atmosphere had already shifted.</p></div>\n<div><p>Mii-chan glanced once between Kushida and Shinohara before quickly lowering her eyes again.</p></div>\n<div><p>Maybe she simply wasn’t used to being put in a position where her judgment mattered.</p></div>\n<div><p>Or maybe she understood exactly how much weight a single opinion carried right now.</p></div>\n<div><p>Either way, she showed no sign of answering decisively.</p></div>\n<div><p>Shinohara, meanwhile, didn’t miss even that tiny hesitation.</p></div>\n<div><p>Even before the discussion had properly concluded, she prioritized steering the momentum toward herself.</p></div>\n<div><p>She held her gaze without wavering, applying quiet pressure that left little room to escape.</p></div>\n<div><p>Riding that wave of momentum she shifted her attention to Kushida without hesitation.</p></div>\n<div><p>“So what is it, Kushida-san?” Shinohara asked. “You don’t want me as the representative? Would it be inconvenient for you if I took the role?”</p></div>\n<div><p>It was phrased like a question, but in reality the range of acceptable answers had already been narrowed down.</p></div>\n<div><p>If Kushida answered yes, friction would immediately erupt.</p></div>\n<div><p>If she answered no, then she would effectively be conceding the position.</p></div>\n<div><p>By forcing that binary choice onto her, Shinohara was clearly trying to seize control of the conversation from the get go.</p></div>\n<div><p>“Um… well… it’s not that there’d be any inconvenience or anything,” Kushida replied carefully, “but actually, I was thinking about volunteering too…”</p></div>\n<div><p>She asserted her intentions in a modest, yet firm manner.</p></div>\n<div><p>However, upon hearing those words, Shinohara's expression stiffened in apparent dissatisfaction.</p></div>\n<div><p>“Why?” she asked. “Is it because you don’t trust me?”</p></div>\n<div><p>“No, it’s not like that,” Kushida answered without missing a beat. “ I just intended to run from the very beginning.\"</p></div>\n<div><p>“Hmm?” Shinohara let out a small laugh. “Because honestly, it kinda feels like I’m not being trusted here.”</p></div>\n<div><p>Kushida faltered for only a moment beneath the pressure.</p></div>\n<div><p>Even so, she still pushed back.</p></div>\n<div><p>“But if you put it that way…” she answered carefully, “doesn’t that also mean <em>you </em>don’t trust<em> me</em>, Shinohara-san?”</p></div>\n<div><p>Though Kushida seemed somewhat bewildered and overwhelmed by her intensity, she still didn't stop arguing back.</p></div>\n<div><p>“Ehh? It’s not like that though—”</p></div>\n<div><p>Shinohara smiled faintly, almost amused.</p></div>\n<div><p>Then her voice rose slightly.</p></div>\n<div><p>“But Kushida-san… do you seriously think people can trust you unconditionally?”</p></div>\n<div><p>The surrounding groups had not started paying attention yet.</p></div>\n<div><p>But if the conversation escalated any further, it would inevitably draw eyes and ears from nearby.</p></div>\n<div><p>“I… I do try my best to earn people’s trust,” Kushida answered. “That’s exactly why I thought it’d be better not to place an unnecessary burden on you, Shinohara-san.”</p></div>\n<div><p>With other classes in the mix, Kushida had no choice but to continue playing the role of the usual cheerful, considerate Kushida.</p></div>\n<div><p>And Shinohara understood that perfectly.</p></div>\n<div><p>Which was exactly why she could afford to press forward so aggressively.</p></div>\n<div><p>“Burden? What do you mean by that?”</p></div>\n<div><p>“Managing all the tokens sounds like a hassle,” Kushida explained gently. “Even if it’s called a representative, it’s basically just becoming the class errand runner. I thought it might be better if I handled it instead.”</p></div>\n<div><p>“It’s not a hassle at all,” Shinohara shot back immediately. “So don’t worry about me, Kushida-san. Just leave it to me.”</p></div>\n<div><p>Then Kushida turned slightly.</p></div>\n<div><p>“Mii-chan… what do you think?”</p></div>\n<div><p>The question sounded almost like a plea for help.</p></div>\n<div><p>But before Mii-chan, caught painfully between the two of them, could even open her mouth, Shinohara’s expression darkened with irritation.</p></div>\n<div><p>“You heard her agree to leave it to me, didn’t you?” Shinohara pressed immediately. “So why are you asking again? You really <em>don’t </em>trust me after all, do you?”</p></div>\n<div><p>“No, that’s not it,” Kushida answered gently. “I just wanted to properly confirm everyone’s opinion…”</p></div>\n<div><p>“Then why don’t you ask Kanji too?”</p></div>\n<div><p>Shinohara gave a small snort as she turned toward Ike, utterly convinced he would side with her.</p></div>\n<div><p>“Mm… Ike-kun, what do you think?”</p></div>\n<div><p>Closing the distance slightly, Kushida looked up at him with an almost pleading gaze.</p></div>\n<div><p>“Huh? Well, I mean…”</p></div>\n<div><p>The moment Kushida turned those eyes on him, Ike’s composure vanished. Even though everyone in the class had seen her true nature, Kushida was still an angel on the surface. When she looked at him as though she were relying on him, his cheeks reddened almost instantly.</p></div>\n<div><p>“Well, Kikyō-cha—uh, I mean Kushida wouldn’t be bad at all either, yeah.”</p></div>\n<div><p>“Hey, Kanji…?”</p></div>\n<div><p>Shinohara’s mood soured at once. Apparently displeased by his unexpected reaction, she grabbed his left ear and pulled hard.</p></div>\n<div><p>\"Ow, ow-ow-ow! That hurts, Satsuki!\"</p></div>\n<div><p>“Tell me honestly.” Shinohara’s voice was sweet only in shape. “Between me and Kushida-san, who is better suited to be representative?”</p></div>\n<div><p>“Of course, of course!”</p></div>\n<div><p>Still crying out in pain, Ike hurriedly corrected course.</p></div>\n<div><p>\"I-It's safe to just leave it to Satsuki!\"</p></div>\n<div><p>Subjected to Shinohara’s openly suspicious stare, Ike chose the answer that let him escape with the least damage.</p></div>\n<div><p>“So there you have it,” Shinohara said, turning back to Kushida with a satisfied look. “That’s fine, right, Kushida-san?”</p></div>\n<div><p>“Understood,” Kushida said after a small pause. “Yeah. If everyone is fine with that, then I’m fine with it too.”</p></div>\n<div><p>She likely harboured immense dissatisfaction.</p></div>\n<div><p>But Shinohara and Ike already controlled two votes. Even if Kushida persisted and somehow managed to pull Mii-chan to her side, the result would only be a split vote, and the representative still would not be decided. Worse, after rejecting Shinohara this strongly, provoking her any further would be a poor move.</p></div>\n<div><p>Kushida had no choice but to step back.</p></div>\n<div><p>Of course, at this point, neither Shinohara nor Ike were likely planning to cheat Kushida or Mii-chan through token management. Their intentions were probably still ordinary enough.</p></div>\n<div><p>But that was only because they had not yet been pushed into a corner.</p></div>\n<div><p>If, from here on, they failed to increase their tokens as planned, or if they began losing them, then the authority Shinohara held as representative could grow stronger, and more difficult to control.</p></div>\n<div><p>Once again, it became clear just how important the role of representative truly was.</p></div>\n<div><p>There were probably almost no current third-years who could not see at least that much.</p></div>\n<div><p>And that was precisely why Kushida, more than anyone, would have to move with extreme caution from this point forward.</p></div>\n<div><p>“Looks like they ended up choosing Shinohara over there,” Yoshida murmured after quietly listening in on the exchange. “Well, if you’re someone at risk of expulsion, wanting to become the representative is only natural. On the other hand, for someone like Wang or Kushida, this has to be a headache.”</p></div>\n<div><p>His analysis was calm and matter-of-fact.</p></div>\n<div><p>“So what should <em>we </em>do for now?” Yoshida continued, stepping closer and lowering his voice. “We’re making you the representative, right?”</p></div>\n<div><p>“You’re willing to follow my lead?”</p></div>\n<div><p>“Of course.” Yoshida answered without hesitation. “I was sweating a little during the Survival Game Special Exam when it looked like we might lose, but in the end we finished exactly where you planned, second place. Hard to complain about that.”</p></div>\n<div><p>He shrugged lightly.</p></div>\n<div><p>“And besides, you’re the leader for this exam. Ideally we want this group taking first place.”</p></div>\n<div><p>Standing beside him, Sanada nodded immediately in agreement.</p></div>\n<div><p>“Then I presume that makes me the Representative, yes?” Morishita concluded.<span></span></p></div>\n<div><p>“You can ignore this one,” Yoshida said bluntly, jerking a thumb toward her. “She’s not the type to step forward anyway.”</p></div>\n<div><p>Morishita stood with her arms folded, nodding repeatedly to herself as though she alone had reached some profound conclusion.</p></div>\n<div><p>“I believe Morishita-san understands as well,” Sanada added, smoothing over the moment with calm politeness, “that among us, entrusting this to Ayanokōji-kun is the best option.”</p></div>\n<div><p>It felt like they were deliberately putting me on a pedestal, but I didn't pay it much mind.</p></div>\n<div><p>“One final confirmation,” I said. “You’re really fine with leaving this to me? Once I become the representative, I’ll be able to distribute the tokens we earn however I like. I might act to protect myself.”</p></div>\n<div><p>Yoshida looked at me as if the answer was obvious.</p></div>\n<div><p>“You're the weirdo who willingly dropped down from Class A, right, Ayanokōji? If you pull a stunt like betraying us just to save yourself, you wouldn't be able to stay as the class leader anymore, at the very least. That's why we trust you, or rather, your position which won't allow for such selfishness.”</p></div>\n<div><p>That was Yoshida’s reasoning for accepting me as representative.</p></div>\n<div><p>Sanada nodded again, showing that he agreed.</p></div>\n<div><p>Their attitude did not come from blind faith. They had already resolved themselves to the fact that if they could not place complete trust in me, the class would never rise again.</p></div>\n<div><p>“I, for one, certainly do not trust you,” Morishita declared. “But very well, let us treat this as a test to see if you are truly fit to reign over our class.”</p></div>\n<div><p>“Understood,” I said. “If Yoshida and Sanada are willing to place that responsibility in my hands, then I’ll fulfill the role properly.”</p></div>\n<div><p>I informed Urushibara that I would be serving as Class C’s representative, then waited for the remaining teams to finish making their decisions.</p></div>\n<div><p>In the end, Class A selected Shinohara as representative.</p></div>\n<div><p>Class B settled on Katsuragi. Ibuki looked far from pleased with the result, but since the remaining two supported him, the decision was effectively made.</p></div>\n<div><p>As for Class D, Amikura assumed the representative role without the slightest dispute.</p></div>\n<div><p>Compared to the distorted power balance festering inside Class A, the other selections were probably more or less reasonable.</p></div>\n<div><p>“So you <em>are </em>going to divide the tokens fairly, right?” Ibuki demanded immediately, glaring at Katsuragi.</p></div>\n<div><p>“Of course,” Katsuragi replied calmly. “Although I cannot guarantee that my definition of fairness matches yours.”</p></div>\n<div><p>“Hah? What’s <em>that </em>supposed to mean?”</p></div>\n<div><p>“This is still a special exam,” he answered evenly. “I am merely the one entrusted with managing the class’s collective tokens. I intend to distribute them fairly according to contribution. Those who produce results will receive rewards appropriate to their efforts. Those who hold the group back will receive only the minimum necessary.”</p></div>\n<div><p>He held Ibuki’s gaze without flinching.</p></div>\n<div><p>“If you want enough tokens to avoid expulsion, then contribute to the class.”</p></div>\n<div><p>“Tch… fine.”</p></div>\n<div><p>A very Katsuragi-like policy.</p></div>\n<div><p>His equality was not equal shares for all. It was fairness measured by evaluation, with token distribution tied directly to contribution. Whether one liked it or not, the logic was consistent.</p></div>\n<div><p>Amikura, on the other hand, seemed to be taking the opposite approach.</p></div>\n<div><p>For her team, performance was irrelevant. Any tokens earned by the four of them would be divided evenly among the four.</p></div>\n<div><p>That, too, was a form of equality.</p></div>\n<div><p>Because there was already trust between them, and because each student’s abilities were relatively well balanced, there was likely no room for conflict to arise.</p></div>\n<div><p>Then there was Shinohara, the representative of Class A.</p></div>\n<div><p>On the surface, her stance was the same as Amikura’s: equal distribution among all members. But the conditions beneath that statement were entirely different. In terms of ability, Kushida and Mii-chan clearly held a far greater advantage over Shinohara.</p></div>\n<div><p>In other words, Shinohara was using the authority of the representative role to create a version of equality that favored her own side.</p></div>\n<div><h2>Part 1</h2></div>\n<div><p>With the representatives from all four classes assembled, the supervisor stepped forward to address us.</p></div>\n<div><p>“Now then, without further ado, we will have you begin the individual category tasks,” he announced. “You have a maximum of sixty minutes to deliberate and decide by majority vote where this group will travel first, choosing from a list of candidate locations. Once everyone agrees to proceed, you will cast your vote via your smartwatches and then head out to the winning destination,” he paused.</p></div>\n<div><p>“As for the rewards: any student who votes for the destination with the most votes will receive one token. If the vote is unanimous, everyone will receive two. Those who vote for a location other than the majority will receive three tokens. Finally, in the event that a destination receives exactly one vote, that lone voter will be rewarded with five tokens.”</p></div>\n<div><p>So, our first task was simply to decide Group 3’s destination.</p></div>\n<div><p>“A word of warning before you begin your discussions,” the supervisor continued. “If there is a tie for the most votes, meaning multiple locations receive the highest number of votes, the students who voted for those tied locations will receive zero tokens. In such a scenario, we will randomly select your destination from among the tied options.”</p></div>\n<div><p>In short, it was a system that guaranteed a payout of tokens for everyone, provided there wasn't a tie for first place.</p></div>\n<div><p>“We will not disclose who voted for which location under any circumstances. Furthermore, showing your watch’s screen to others while voting is strictly prohibited. Please be aware that any such violations will incur a separate penalty resulting in the loss of tokens.”</p></div>\n<div><p>If we knew who was voting for what in real time, coordinating our choices would be far too easy. This strict anonymity was likely a necessary measure to prevent exactly that.</p></div>\n<div><p>Having briskly wrapped up his explanation, Urushibara, our assigned supervisor, read the list of candidate destinations aloud.</p></div>\n<div><p>“There are five candidate locations for your first destination: B9, E12, F14, I10, and I13. Regardless of which area you choose, the contents of your upcoming tasks will remain exactly the same. However, any time spent traveling to your next destination is simply time wasted, so please keep that in mind.”</p></div>\n<div><p>Sanada unfolded the map provided with our materials, immediately checking the coordinates.</p></div>\n<div><p>The available options were scattered across the grid, ranging from relatively close spots to those a fair distance away. Some even looked like they would require considerable effort to reach.</p></div>\n<div><p>“I will now start the timer,” Urushibara said, checking his smartwatch without a moment’s delay. “You are free to begin your discussion.”</p></div>\n<div><p>Reacting naturally, our group of sixteen shifted into a circle so that we could all see each other’s faces.</p></div>\n<div><p>“It's obvious a nearby place is best for this. The tasks won't change, either,” Sonoda from Class B muttered, sounding more like he was thinking out loud than asking a question.</p></div>\n<div><p>Catching his words, Ike immediately agreed. “True. Even the teacher—er, the supervisor, just said that travel time is a waste.”</p></div>\n<div><p>The assertion that closer meant easier was typical of Ike, who despised anything troublesome.<span></span></p></div>\n<div><p>“So we all just vote for the closest area and call it a day? It'd be a quick discussion, and we'd all get two tokens,” Minamikata chimed in.</p></div>\n<div><p>A unanimous vote for the closest location. It was the first and most obvious choice that came to mind.</p></div>\n<div><p>While the guarantee that the upcoming task wouldn't change was certainly a solid deciding factor, if we chose a nearby destination based on that alone, there would be no need for this discussion at all.</p></div>\n<div><p>The school had gone out of its way to give us a lengthy sixty-minute deliberation period. There had to be a meaning behind it, or rather, making us <em>think </em>there was a deeper meaning was likely exactly what the school was aiming for.</p></div>\n<div><p>“Isn't blindly voting for the closest area a bit too simplistic?” Yoshida argued. “There's probably more to this than meets the eye.”</p></div>\n<div><p>If travel distance was the only difference between the options, no one would ever vote for a faraway spot. Suspecting a trap lay hidden behind such an obvious answer, Yoshida spoke up to rein them in.</p></div>\n<div><p>“I have to agree,” Katsuragi said, casting a brief glance at Ike and Sonoda. “We should thoroughly examine the other areas first.”</p></div>\n<div><p>“But... Urushibara-san said the destination and the tasks aren't connected...” Morofuji muttered from her spot beside Katsuragi.</p></div>\n<div><p>“In that case, we may need to consider factors outside of the tasks themselves,” Katsuragi replied. “We cannot blindly proceed without first verifying which destination will provide the greatest benefit to our group.”</p></div>\n<div><p>“Isn't that just a waste of time?” Sumida retorted. “This task is centered around the exchange of tokens. I think ‘closer is better’ is a perfectly fine answer.”</p></div>\n<div><p>It seemed the discussion was already beginning to fray.</p></div>\n<div><p>It was supposed to be a simple vote to decide our next destination, yet reaching a consensus wasn't going to be easy.</p></div>\n<div><p>“The supervisor called this an individual battle, didn’t he? Does that mean we’re supposed to outmaneuver each other through the voting process?”</p></div>\n<div><p>Sanada turned to me as he asked the question.</p></div>\n<div><p>“That’s undoubtedly one of the core mechanics, yeah,” I replied.</p></div>\n<div><p>“A unanimous vote yields a solid reward of two tokens, but it’s certainly not the highest payout,” Sanada noted.</p></div>\n<div><p>It was a natural progression for the majority of the students to favor a nearby location as their destination. Consequently, the votes were bound to concentrate there. While a unanimous choice would distribute tokens equally among all sixteen participants, a calculated betrayal guaranteed a far more lucrative payout for the defector. To make matters worse, such a betrayal would slash the payout of the majority voters down to a single token. And if multiple defectors emerged, it opened the door for opportunists to secure three or five tokens under the safety of complete anonymity.</p></div>\n<div><p>“It’s a simple but troublesome task,” Sonoda muttered again, several students nodding in agreement. “Our overall motives align, but the reward system actively discourages us from cooperating.”</p></div>\n<div><p>The optimal strategy was to avoid voting for the desired destination yourself, while persuading others into voting for it instead.</p></div>\n<div><p>“Wait, isn’t this impossible?” someone argued. “Nobody is going to want to waste their vote on the closest place.”</p></div>\n<div><p>Exactly. Everyone agreed that a shorter distance was better. But if prioritizing that convenience meant settling for just one token, people would inevitably be tempted to secure three or five tokens instead, not caring if they had to walk further as a result.</p></div>\n<div><p>“But... if everyone thinks like that, all the votes will end up going to the distant places instead, right?” Mii-chan pointed out, having apparently foreseen the logical conclusion of that train of thought.</p></div>\n<div><p>“If we all avoid the shortest route and vote for the distant ones, then a distant location will get the most votes? Man, that won't work either.”</p></div>\n<div><p>In a space where friend and foe were jumbled together, the students exchanged probing glances, sizing each other up.</p></div>\n<div><p>An uncomfortable silence fell over the group. Ten or twenty seconds passed, and just as it seemed the heavy atmosphere would drag on, Katsuragi quietly broke the silence.</p></div>\n<div><p>“Engaging in a clumsy battle of wits will only breed suspicion,” he said calmly. “If we end up casting our votes blindly, then just as Wang pointed out, we run the risk of earning no tokens while being forced to march a long distance. The simplest way to handle this is to keep our discussion to a minimum, prioritize cooperation above all else, and unanimously vote for the closest area. We might not maximize our token earnings, but it guarantees an outcome, and a travel distance, that everyone can be satisfied with.”</p></div>\n<div><p>Naturally, the majority of the group wasn’t going to just nod along and agree to Katsuragi’s proposal immediately. Katsuragi himself was fully aware of that, of course. It was safe to say he had simply offered a baseline argument to kickstart the real discussion.</p></div>\n<div><p>“That might be true, but in order to guarantee the most votes, we need at least nine people to vote for the same spot,” Ike argued. “Are you seriously suggesting we just hand over three or five tokens to the remaining seven people?”</p></div>\n<div><p>“Tokens can be transferred,” Katsuragi countered calmly. “We could agree to pool our winnings and distribute them evenly afterward.”</p></div>\n<div><p>“You’ve gotta be kidding me,” Ike shot back. “If tokens end up with someone from another class, there’s zero guarantee they’ll actually hand them over. The voting is strictly anonymous, which means someone is definitely going to pull a fast one on us. Take Ayanokōji, for example... Yeah, someone exactly like Ayanokōji!” he continued, turning his gaze toward me. “You’re absolutely gunning for the five-token payout, aren’t you?”<span></span></p></div>\n<div><p>Just as Katsuragi had predicted, his proposal acted as the spark that ignited a flurry of opposition, with Ike fiercely leading the charge.</p></div>\n<div><p>Since he was glaring in my direction and calling me out by name, I met his gaze, if only to acknowledge him.</p></div>\n<div><p>“Seems like your attitude has gotten even worse since you betrayed our class,” Ike sneered. “I mean, anyone who transfers from Class A to a lower class just because they think they’re a little smart is crazy to begin with.”</p></div>\n<div><p>Ever since our groups merged, Ike hadn’t stopped complaining about my attitude. I was perfectly fine letting it slide without offering a rebuttal, but Katsuragi stepped in to answer on my behalf.</p></div>\n<div><p>“You are free to think whatever you want about transferring to a lower class,” Katsuragi said, crossing his arms and narrowing his eyes sharply. “But if stepping down to a lower class makes someone crazy, then I suppose I am crazy as well.”</p></div>\n<div><p>Realizing he had just caught Katsuragi in the crossfire, Ike awkwardly averted his gaze.</p></div>\n<div><p>The fallout from this exchange didn't stop at just the two of them; it cast a faintly heavy atmosphere over the students from Class C. Yoshida and the others used to be Katsuragi's allies, and now that he was their enemy after a long series of twists and turns, they likely harbored some complicated feelings about the matter.</p></div>\n<div><p>Unable to bear the suddenly tense mood, Moriyama from Class D stepped in to mediate. “Let's all calm down for a second. I think cooperating like Katsuragi suggested is a valid option. It's the most straightforward approach, right?”</p></div>\n<div><p>“But isn't the whole problem that we <em>can't </em>do that?” Shinohara retorted. “Neither Kanji nor I want to throw our votes away on the most popular choice.”</p></div>\n<div><p>“Yeah, exactly!” Ike chimed in, vehemently backing up her protest.</p></div>\n<div><p>“Of course, anyone would feel that way,” Sumida reasoned. “But if we just dig our heels in, we'll get nowhere. We need to figure out where we can compromise and find a balanced voting strategy first. There might be a solution we can all accept.”</p></div>\n<div><p>“Sumida's right,” another agreed. “The total number of tokens we get as a group undoubtedly changes depending on how we vote. The real question is, what kind of voting patterns are actually on the table?”</p></div>\n<div><p>Assuming we could control everyone's votes, the group was starting to realize that the distribution method directly impacted our total payout. Seeing this, I lightly raised my hand before speaking up.</p></div>\n<div><p>“A simple, unanimous vote yields two tokens each,” I explained. “That’s a total payout of 32 tokens. However, if we intentionally scatter our votes, there are six different patterns that yield the absolute maximum payout of 40 tokens. For example, Pattern 1 would be 7 votes, 6 votes, and three 1-vote destinations. Pattern 2 would be 6 votes, 5 votes, 3 votes, and two 1-vote destinations, and so on. Regardless of which of the six patterns we use, the maximum yield remains capped at 40.”</p></div>\n<div><p>I paused for a moment before delivering the optimal strategy. “Out of all six patterns, the easiest one to coordinate is a 4-3-3-3-3 split. We send exactly one person from each of the four classes to vote for the top destination, giving it a winning total of 4 votes. The remaining twelve people divide into groups of three and vote for the other four destinations.”</p></div>\n<div><p>That would yield eight more tokens than a unanimous vote, which wasn't a bad deal for any of the classes involved.</p></div>\n<div><p>“The only drawback,” I continued, “is that dividing 40 tokens by 16 people equals 2.5, meaning an even distribution on an individual level is impossible. However, we <em>can </em>divide the class cuts equally, giving each of the four classes exactly 10 tokens to distribute amongst themselves.”</p></div>\n<div><p>Purely in terms of efficiency, this was the absolute optimal solution. Of course, regardless of the pattern, the hurdle of actually pulling it off was anything but low.</p></div>\n<div><p>“You're incredibly fast at calculating all that, Ayanokōji,” Katsuragi said, clearly impressed. A few other students agreed, clapping their hands in an exaggerated show of admiration.</p></div>\n<div><p>“You didn't have to go out of your way to explain every little detail. I could've figured out the patterns right away,” Ike muttered defensively. “No need to act so smug just because you can do a little math in your head. I mean, are you even sure that's right? Are you really that confident?”<span></span></p></div>\n<div><p>“Yeah. The math is correct,” I said flatly.</p></div>\n<div><p>“...Listen to him, so completely sure of himself. It'll be damn embarrassing if you're wrong after all that.” Ike clearly wanted me to be wrong. He started counting on his fingers, but almost immediately abandoned the effort.</p></div>\n<div><p>“Honestly, you <em>do </em>sound pretty arrogant, Ayanokōji-kun,” Shinohara chimed in, rushing to defend Ike. Her tone shifted from angry to exasperated. “You never used to give off this kind of impression. You always just seemed... harmless. Did becoming a leader change you, or did you just stop hiding your true colors?”</p></div>\n<div><p>The rest of the group looked back and forth between me and Shinohara’s clique.</p></div>\n<div><p>The old me would’ve preferred not to rock the boat; I would have likely just ignored her remarks and let it slide. But this time, I decided to take the bait.<span></span></p></div>\n<div><p>“Maybe so,” I said flatly. “My previous class was quite uncomfortable, after all.”</p></div>\n<div><p>“Wow, he actually just said that out loud. You really do have a terrible attitude,” Shinohara scoffed, her face twisting in disgust.</p></div>\n<div><p>Faced with my unyielding, unapologetic stance, it wasn’t just Mii-chan and Kushida who looked rattled; even my new classmates, like Yoshida, showed obvious signs of agitation.</p></div>\n<div><p>“Hey, shouldn't you dial it back a little?” Yoshida whispered, his face twitching slightly.</p></div>\n<div><p>“There's no need to worry. I'm just speaking my mind.”</p></div>\n<div><p>“No, man, that's exactly the problem...” he trailed off.</p></div>\n<div><p>The hostile atmosphere lingered in the air, thick and unresolved. But Katsuragi, who had likely been quietly verifying my math in his head the entire time, gave a deep nod and stepped back into the conversation.</p></div>\n<div><p>“It seems his calculations are indeed correct,” Katsuragi announced. “Splitting the five destinations into a 4-3-3-3-3 pattern is a solid strategy. We cannot avoid competing within the group eventually, but if there's a way for everyone to earn tokens at maximum efficiency right now, I see great merit in taking advantage of it. The most important thing is for each of us to increase our token count and avoid dropping to the bottom of the school year.”</p></div>\n<div><p>Katsuragi had fully understood the core policy of ‘earn while you can’ and actively embraced it.</p></div>\n<div><p>“I guess I agree too,” Sonoda said. “The only reason someone would break ranks and try to outsmart everyone else is to squeeze out an extra token or two, right? But honestly, I don’t think the risk is worth it. Splitting the votes would only increase the chances of a tie. Once you realize that, even someone planning to defect would understand that securing a reliable ten tokens for the class is the smarter choice, wouldn’t they?”</p></div>\n<div><p>Clearly eager to maintain harmony, Sonoda once again expressed his support for cooperation. The true brilliance of this 4-3-3-3-3 strategy lay in the fact that votes would be cast for every single destination. Because every location would receive a minimum of three votes, even if one person decided to play the traitor, it would be mathematically impossible for them to snatch up the five-token reward reserved for a solo vote. And even if a group of traitors wanted to coordinate an ambush, pulling off a flawless conspiracy using nothing but eye contact in this mixed group would be a Herculean task.</p></div>\n<div><p>“I still don't like it,” Ike grumbled. “Just going along with a plan pushed by Ayanokōji rubs me the wrong way.”</p></div>\n<div><p>“There is no need for baseless suspicion,” Katsuragi replied firmly. “I ran the numbers several times myself, and Ayanokōji's pattern and projected results are entirely correct. Rather than complain, you should look at the bright side: by providing us with a conclusion faster, he has saved us valuable time that we can now allocate to discussing the actual execution.”</p></div>\n<div><p>The realization that this distribution method offered the highest efficiency had finally sunk in for everyone. However, understanding the logic and agreeing to execute it were two different things.</p></div>\n<div><p>“Yeah, I fundamentally agree. Don't you?”</p></div>\n<div><p>“It's a hundred times better than voting blindly without a plan. I'm in.”</p></div>\n<div><p>As expected, Class D was straightforward; they weren't the type to oppose a proposal that clearly benefited the majority.</p></div>\n<div><p>Seizing the moment, I turned my gaze toward Yoshida and Sanada. “Now that you've heard the discussion so far, have you made up your minds?”</p></div>\n<div><p>“If I had to choose, I'm in favor of the four classes getting ten tokens each,” Yoshida replied. “If our opinions split, we risk getting zero tokens in the worst-case scenario. Plus, this setup seems like a solid deterrent against betrayal, right?”</p></div>\n<div><p>Following Yoshida's lead, the two of them offered no resistance, clearly leaning toward the most efficient strategy. Curiously, Morishita, who was usually loud enough to be a nuisance, remained completely silent.</p></div>\n<div><p>Having secured Class C's agreement with a light nod, Katsuragi next turned to his own Class B to solicit their opinions.</p></div>\n<div><p>“I-I feel like it's better than aiming for an uncertain unanimous vote...”</p></div>\n<div><p>“As long as it guarantees me tokens, I'm fine with it,” Ibuki added bluntly.</p></div>\n<div><p>While perhaps not as enthusiastic as Class D or C, Ibuki and the others expressed a relatively agreeable stance.</p></div>\n<div><p>Now, the only ones left were Class A, which included Ike and Shinohara, who had been the most vocal in their opposition.</p></div>\n<div><p>“I’d like to hear Kushida and Mii-chan’s opinions on the matter, too,” I said.</p></div>\n<div><p>“H-hey, hold on a second,” Ike stammered, stepping forward. “Between you ignoring our greetings earlier and now this, you’re purposely leaving Satsuki and me out of the loop, aren’t you?”</p></div>\n<div><p>“It’s for the exact same reason I didn't greet you,” I replied flatly. “My bad, but I have no desire to seek opinions from either of you.”</p></div>\n<div><p>“Are you seriously saying that right now, Ayanokōji?” Ike snapped. “You know this is a group task, right? Stop doing things that are just gonna cause a split among us! Weren't we just talking about everyone cooperating?”</p></div>\n<div><p>It was a perfectly sound argument that left little room for rebuttal, and the rest of the group began to show obvious sympathy for Ike's position.</p></div>\n<div><p>Seeing Ike clench his fists in agitation, Shinohara gently grasped his hand, mindful of the stares from the rest of the group.</p></div>\n<div><p>“Kanji, let's be the adults here,” she urged softly. “I was definitely hurt when he ignored us earlier, but you said it yourself: this is a group battle, right? Fighting over pointless things will only drag us down.”</p></div>\n<div><p>“But still...!”</p></div>\n<div><p>“I got a little worked up too, but wasn't it partly your fault, Kanji? You were the one provoking Ayanokōji-kun, saying he couldn't be trusted. Am I wrong?”</p></div>\n<div><p>“...Well... I guess...”</p></div>\n<div><p>Though his anger hadn't completely subsided, Ike's resentment softened slightly at Shinohara's gentle reprimand.</p></div>\n<div><p>“...Yeah, you're right. ...I get it.”</p></div>\n<div><p>Forcing himself to swallow his pride by saying it aloud, Ike slowly unclenched his fists. He gave a stiff, slight bow of his head and desperately pasted a bright expression onto his face.</p></div>\n<div><p>“Earlier, how should I put it... look, my bad for saying things that made it sound like I doubted you. Of course you'd get mad over that... For now, I agree that making sure all the classes get an equal share of tokens is the way to go. So, as a way to test our trust in each other, let's just try to get along this once.”</p></div>\n<div><p>Having regained his composure, Ike extended an olive branch. Shinohara nodded, clearly ready to second his attempt at making peace.</p></div>\n<div><p>Looking back to when we first enrolled, it was clear that Ike and Shinohara had grown mentally, albeit unsteadily. I had noticed it even during the greeting stage. To think they would brush off my blatant rudeness and actively try to compromise with me again. Moreover, it wasn't just surface-level posturing; even if they had to force it, they genuinely seemed to be convincing themselves to let bygones be bygones for the sake of the group.</p></div>\n<div><p>I could sense a palpable wave of welcome relief from Yoshida and my other classmates standing beside me.</p></div>\n<div><p>I turned my gaze toward Ike and Shinohara to give them my answer.</p></div>\n<div><p>“I agree with aligning our voting intentions,” I said coldly. “But unfortunately, I simply cannot trust either of you.”</p></div>\n<div><p>Without a shred of hesitation, I shattered the fragile peace their goodwill had just created, freezing the atmosphere instantly.</p></div>\n<div><p>“Wha—”</p></div>\n<div><p>Before Ike even had a chance to react, the tentative smile on Shinohara's face hardened into a mask of shock. The rest of the group stared at me, their initial astonishment quickly morphing into blatant dissatisfaction at my unapologetic hostility.</p></div>\n<div><p>“Ayanokōji, I feel that is going a bit too far,” Katsuragi interjected. “I don't know what happened between you as former classmates, but there is absolutely no merit in making an enemy of Class A here.”</p></div>\n<div><p>“He's right, Ayanokōji,” another student agreed. “No matter how you look at it, you're the one in the wrong here. It's just plain immature.”</p></div>\n<div><p>“I have no intention of making enemies of them,” I replied calmly. “However, if we want this discussion to proceed smoothly, it's meaningless unless the right people step forward. As long as Shinohara and Ike uselessly intrude as the representatives of Class A, any discussion we hold is just a waste of time. For a task focused on dialogue, the natural choice is to have Kushida lead the talks, with Mii-chan advising her as an assistant. If we take that approach, we can trust each other and progress smoothly.”</p></div>\n<div><p>My implication was clear: those two needed to know their place and step back like the supporting characters they were.<span></span></p></div>\n<div><p>“You... are seriously pissing me off, Ayanokōji!”</p></div>\n<div><p>Ike once again clenched his fists, ready to lunge forward, but Shinohara tightly grabbed his shoulder to hold him back.</p></div>\n<div><p>Unlike earlier, however, Shinohara looked as though she had reached the absolute limit of her patience.</p></div>\n<div><p>“What the hell is that supposed to mean?” she demanded, her voice trembling. “Are you saying we shouldn't even be allowed to speak? Isn't that completely unfair? Did we say something so horrible that you have to treat us like this?”</p></div>\n<div><p>“I... well, I also think Ayanokōji-kun's remarks were entirely out of line,” said Sanada, stepping in front of me, with a grim expression on his face.</p></div>\n<div><p>“All sixteen of us have an equal right to speak, and just as Shinohara-san said, I don't think there was any particular problem with the two of them. Isn't this completely uncharacteristic behavior for you, Ayanokōji-kun?”</p></div>\n<div><p>“I have to agree. I can't defend you on this one,” Yoshida added, shaking his head.</p></div>\n<div><p>It seemed all of my new Class C peers were harboring the exact same negative feelings toward me.</p></div>\n<div><p>“Honestly, this whole thing makes me anxious,” Shinohara said, staring at me. “Even when we tried to compromise, you threw that attitude in our faces. If you keep creating this toxic environment, there’s no guarantee your plan will actually work out. The upcoming vote is strictly anonymous, meaning if someone actually does betray us, we won’t be able to pinpoint who it was. Doesn't this whole strategy fall apart if there are people from other classes we can't trust?”</p></div>\n<div><p>Her eyes were faintly moist, and despite her defiant glare, it was as if she was trying to hide how deeply my words had hurt her.</p></div>\n<div><p>“I don't think I'm making a difficult demand,” I replied. “If you just let Kushida and Mii-chan take the lead, things will proceed smoothly.”<span></span></p></div>\n<div><p>No matter how much it worsened their impression of me, I reiterated my stance.</p></div>\n<div><p>“You just pick on us out of nowhere and make whatever demands you want... Isn't that a waste of time too!?” Ike shouted.</p></div>\n<div><p>“Ah… I see. So that's how it is. Fine, I get it,” Shinohara scoffed. “Let's just do what he wants, Kanji. Kushida-san is definitely a good girl, after all. She's a great talker, and she's cute.”</p></div>\n<div><p>Throwing in the towel, Shinohara gave up, deciding I was no longer worth arguing with.</p></div>\n<div><p>“Anyway, we'll leave this task to you. Can we count on you, Kushida-san?”</p></div>\n<div><p>“M-Me...?” Kushida blinked.</p></div>\n<div><p>“Well, it's what Ayanokōji-kun wants. Apparently, we aren't capable of moving the discussion forward ourselves.”</p></div>\n<div><p>“Y-Yeah, I'm fine with taking the lead, but... Ayanokōji-kun, I think you should apologize to those two first. I want us all to cooperate on good terms, you know—”</p></div>\n<div><p>Kushida was making it clear that cooperation would be difficult if I maintained the hostile attitude I'd used to force Ike and Shinohara to back down. For the sake of proceeding smoothly, this was probably the right time to pull back.</p></div>\n<div><p>“Understood. It's true that I went a little too far. Kushida is right.”</p></div>\n<div><p>“What the hell? When Kushida-san tells you to, you just apologize, just like that?” Shinohara snapped.<span></span></p></div>\n<div><p>“That's not it. Looking back on it, she simply made me realize my mistake.”<span></span></p></div>\n<div><p>“...I highly doubt that. It didn't look that way to me...” Shinohara muttered. “Well, fine. Whatever.”</p></div>\n<div><p>Rather than forgiving me, she replied coldly out of pure exasperation, clearly done talking to me.</p></div>\n<div><p>“My bad,” I added.</p></div>\n<div><p>At my brief apology, Shinohara merely snorted. She grabbed Ike by the arm and pulled him a step back, distancing themselves slightly from the circle.</p></div>\n<div><p>“So, we've accepted Ayanokōji-kun's <em>heartfelt </em>apology. Kanji and I will step back now. Though, of course, if we have something to say later, we'll still say it.”</p></div>\n<div><p>“Sorry, Kikyō-chan. We're leaving this to you,” Ike added.</p></div>\n<div><p>“No, don't worry about it at all. I'm not sure how reliable I'll be, but I'll do my best,” Kushida replied with a cute smile.</p></div>\n<div><p>Seeing her gentle demeanor, Ike's angry expression finally softened a little.</p></div>\n<div><p>“Oh, right! Why don't you suggest a good idea, Kushida-san?” Shinohara prompted. “It'd be best if we had some sort of risk management method to prevent betrayers from popping up, right?”</p></div>\n<div><p>It was a pointed remark from Shinohara. Was that jab aimed at me, the person who had been grating on her nerves this whole time? Or was it aimed at Kushida, my former class's <em>other </em>traitor? Either way, the group's gaze naturally gathered on Kushida. Looking slightly troubled, she began to think.</p></div>\n<div><p>“Let's see...” Kushida started. “We can't prevent betrayal completely, but we can lower the risk by making sure we can narrow down exactly <em>who </em>betrayed us. If we publicly announce and assign exactly who will vote for which destination in advance, we'll be able to narrow down the suspects if a discrepancy occurs in the final results.”</p></div>\n<div><p>Kushida explained that, for example, if we agreed on a 4-3-3-3-3 split but the actual result came out as 4-2-3-3-4, it would definitively prove that one of the three students assigned to the second destination had betrayed the group.</p></div>\n<div><p>“Umm, something like that anyway. I hope my logic is right, but... I don't really have a lot of confidence in it,” she added, looking perplexed as she lightly scratched her cheek with her index finger.</p></div>\n<div><p>“For a spur-of-the-moment idea, I'd say it's not bad,” I noted. “What do you think of Kushida's proposal, Katsuragi?”</p></div>\n<div><p>By passing the conversational baton to Katsuragi, I forcefully shifted the dynamic away from the 'Ayanokōji vs. Class A' narrative that had been dominating the air.</p></div>\n<div><p>“I agree as well,” Katsuragi replied. “It is certainly a measure we should implement. Though, of course, it cannot be said to be foolproof.”</p></div>\n<div><p>Although Kushida had likely just come up with the idea on the spot, she didn't say anything to undermine it, obediently nodding along instead. After all, there was no point in obsessing over catching a betrayer with absolute certainty. As long as the voting remained anonymous, finding a workable compromise within those constraints was far more important.</p></div>\n<div><p>“Just the fact that it increases our chances of narrowing down a betrayer serves as a massive deterrent,” Katsuragi concluded.</p></div>\n<div><p>“Hey,” Ibuki interjected, her brows furrowing slightly. “With the plan you just laid out, there are definitely going to be four people forced to vote for the most popular destination, right?”</p></div>\n<div><p>“That's what it comes down to, yes,” Katsuragi replied immediately. “They'll be allocated evenly, one per class. By sending exactly one person from each class to the four-vote destination, the burden remains equal. That way, the loss isn't being pushed onto any single group.”</p></div>\n<div><p>“You say ‘equal,’ but the guys voting for the top destination are only going to receive one token. That means they're temporarily taking a loss, right?” Ibuki challenged. “Assuming this plan even works, is there actually a guarantee that the tokens will be split with them later?”</p></div>\n<div><p>“Of course,” Katsuragi nodded. “However, as we've already established, each class will earn a total of ten tokens. Even if you distribute them evenly, giving two to each of the four members in your class, that leaves two tokens left over. How to handle those leftovers will be up to each individual class to decide.”</p></div>\n<div><p>Hearing Katsuragi's explanation, Ibuki paused for a beat.</p></div>\n<div><p>“Whatever. But just so we're clear, I'm voting for one of the places that pays out three tokens.”</p></div>\n<div><p>She made her stance clear, lightly sweeping her gaze to the side.</p></div>\n<div><p>It was true. If all the classes kept in step with the plan, one out of the four people from each class would have to cast their vote for the most popular destination, meaning that at the moment of the vote, they would only receive one token. Her blunt remark meant that if there was no hard guarantee the tokens would actually be shared later, she wanted to be on the side obtaining three tokens from the very start.</p></div>\n<div><p>Hating the idea of taking on a risky role, Ibuki had clearly stated her refusal.</p></div>\n<div><p>“Ah, then I call dibs on one of the three-token spots, too,” Ike quickly jumped in, still standing toward the back. “I trust my friends and all, but I don't want to get wrapped up in any trouble. No point taking on unnecessary risks, right?”</p></div>\n<div><p>Piggybacking off Ibuki's declaration, Ike made it clear that he had no intention of falling on his sword for the top destination either.</p></div>\n<div><p>The atmosphere of the place shifted, just slightly.</p></div>\n<div><p>“Since we won't know who voted for what, someone could easily play dumb and keep their extra tokens later,” Shinohara continued, crossing her arms. “Even if you argue it's fine because the class as a whole still gets ten tokens, there's obviously going to be a difference on an individual level. Whether or not someone actually compensates you for taking that loss is a separate issue, isn't it?”</p></div>\n<div><p>Though she framed it as a general observation, her gaze was faintly sharp.</p></div>\n<div><p>Katsuragi shot a brief glance in Shinohara's direction.</p></div>\n<div><p>“Ibuki and Shinohara are exactly right,” Katsuragi declared, jumping in without missing a beat. “This task is premised on the results at the class level. Since there is no mechanism to guarantee perfect fairness between individuals, a guarantee of trust is absolutely necessary. Any student who feels anxious about getting properly compensated should take the initiative, self-declare their intent, and secure one of the spots paying out three tokens. I will take on the burden of voting for the most popular destination for Class B.”</p></div>\n<div><p>We only needed one person from each class to shoulder the risk, allowing the other three to safely secure at least two tokens. Acting decisively, Katsuragi stepped forward to be the first volunteer.</p></div>\n<div><p>“I'll do it for Class C,” I said, turning to Yoshida and the others as the second volunteer. Amikura from Class D immediately followed suit.</p></div>\n<div><p>Now, only Class A remained. With Ike having already explicitly refused the role, all eyes naturally fell on the other three members.</p></div>\n<div><p>“If possible, I recommend having Ike or Shinohara take on the role,” I added casually.</p></div>\n<div><p>Hearing my unnecessary remark, Shinohara furrowed her brows. Our dispute had supposedly been put to rest after my earlier apology, but my words threatened to reignite the issue.</p></div>\n<div><p>Seeing this, Yoshida stepped in. “Hey, what Class A does is for Class A to decide.”</p></div>\n<div><p>“You're right,” I replied. “Just ignore what I said.”</p></div>\n<div><p>“No, I can't just 'ignore it,'” Shinohara snapped. “You've been spouting baseless claims that we can't be trusted, talking down to us as if we don't even belong in a discussion! What on earth is your deal? Did we do something to you, Ayanokōji-kun?”</p></div>\n<div><p>“I'm not targeting you two specifically,” I replied smoothly. “I simply believe that people who lack the trust of the group should take the initiative to act in a way that <em>earns </em>that trust.”</p></div>\n<div><p>“Then let me ask you this: what about Ibuki-san?” Shinohara shot back, pointing an accusatory finger. “Ibuki-san explicitly refused to take on the role, yet you completely ignored that! Shouldn't you be forcing her to vote for the top spot instead of Katsuragi-kun?”</p></div>\n<div><p>Unexpectedly dragged into the crossfire, Ibuki glared at Shinohara, making no effort to hide her irritation.</p></div>\n<div><p>“Class B's internal dynamics are slightly complicated,” I explained calmly. “While I believe Katsuragi is a highly trustworthy individual, from Class B's perspective, he is still a transfer student who joined their ranks midway. Stepping up of his own volition to build up trust with his new classmates isn't a bad move on his part.”</p></div>\n<div><p>“I still don't buy it...” Shinohara muttered.</p></div>\n<div><p>“To begin with, the situation is entirely different from Class A's. If I were still a student in that class, voting for the primary destination and walking away with a single token wouldn't cause me a moment's hesitation. The reason is simple: as long as Kushida is an ally, I would have an absolute guarantee that she would distribute tokens to cover the deficit afterward. Even if I were intent on securing three tokens, should Kushida fail to provide two, I could simply request them from Mii-chan. In short, there would be absolutely no reason to fear being shortchanged.”</p></div>\n<div><p>The only people who couldn't be trusted were Ike and Shinohara, the very two who were explicitly scheming to snatch up three tokens for themselves if given the chance.</p></div>\n<div><p>“Conversely,” I concluded, “not assigning Ike or Shinohara to the top destination is a clear detriment to the group.”</p></div>\n<div><p>“...Hah. So the reason you're doubting Kanji and me so much is because you care so deeply about Kushida-san and Mii-chan?” Shinohara asked, narrowing her eyes in suspicion.</p></div>\n<div><p>“They are precious group members,” I replied flatly. “Naturally, I want to cooperate with them in any way I can.”</p></div>\n<div><p>“I thought this earlier, too, but you are awfully trusting of Kushida-san, aren't you?”</p></div>\n<div><p>“I am simply stating the facts. If you refuse to accept my assessment, you are free to ask Katsuragi, Sonoda, or anyone else from the other classes. Ask them who they think is more trustworthy: the duo of Shinohara and Ike, or Kushida and Mii-chan.”</p></div>\n<div><p>“Twenty minutes have passed. Forty minutes remaining.”</p></div>\n<div><p>The supervisor, who hadn't uttered a single word until now, muttered the time check, a stark reminder that the clock was steadily ticking down.</p></div>\n<div><p>“We stand to gain very little by succumbing to paranoia right now,” Katsuragi stated firmly, cutting through the tension. “Since the transfer of tokens is allowed, any final adjustments and compensations can be handled after the exam. The problem at hand is making sure our strategy doesn't collapse before we even reach that stage.”</p></div>\n<div><p>Katsuragi was making it clear: prioritize solving the group's problem first, and handle internal class disputes on your own time.</p></div>\n<div><p>“I agree. It's better to leave some time on the clock for the actual tasks,” Sumida said with a shrug, showing no hesitation.</p></div>\n<div><p>Moriyama took a short breath and immediately backed him up. “Likewise. I don't see any point in dragging out useless bargaining right now.”</p></div>\n<div><p>The members of Class D were practically unanimous. Because the four of them fully trusted one another, this entire debate was likely nothing but a waste of time from their perspective.</p></div>\n<div><p>“I think it’s about time we moved on,” Sanada said, glancing around the circle before focusing on the final group. “As for the remaining Class A...”</p></div>\n<div><p>“I am absolutely not doing it,” Shinohara stated flatly.</p></div>\n<div><p>“I’ll take it on,” Kushida volunteered.</p></div>\n<div><p>The resolute rejection from Shinohara and the self-sacrificing offer from Kushida overlapped perfectly. At the sheer contrast between their 180-degree different answers, Shinohara shot Kushida a mild glare.</p></div>\n<div><p>“I just don't want to see everyone arguing anymore...” Kushida added with a reserved smile, officially putting herself forward. “If I can be of use to the group right now, this is the least I can do.”</p></div>\n<div><p>“Is this acceptable to you, Ayanokōji-kun?” she asked.</p></div>\n<div><p>“If that's what you want, I won't stop you. Once the tokens are distributed, it becomes an internal class issue,” I replied, reiterating the risk one last time. “Just remember that I won't lift a finger to help when you inevitably argue over the payouts.”</p></div>\n<div><p>“Tch,” Ike clicked his tongue softly, clearly annoyed by my relentless warnings. “Don't worry, Kikyō-chan. Unlike a certain someone who betrayed his class, I'll absolutely share my tokens with you.”</p></div>\n<div><p>“Yeah, I completely trust you, Ike-kun. And Shinohara-san and Mii-chan, too, of course.”<span></span></p></div>\n<div><p>The students outside of Class A silently praised Kushida for taking the initiative and shouldering the risk. She seemed entirely genuine when she said she didn't doubt a single person in her class.</p></div>\n<div><p>Logic and emotion. The gap between the two could never be perfectly bridged. Still, the group managed to move on to the next stage, leaving behind only the faintest lingering friction.</p></div>\n<div><p>Our next order of business was deciding which of the candidate locations we would actually crown with the most votes and travel to.</p></div>\n<div><p>“Just to be absolutely clear: the contents of our upcoming tasks are not linked to our destination, correct?” Sanada asked, turning his head toward the supervisor.</p></div>\n<div><p>Naturally, the supervisor gave no reply. The silence itself was the only confirmation we needed.</p></div>\n<div><p>“In that case, I believe it's best to consolidate our votes on the closest destination to minimize our stamina consumption,” Sanada proposed to the group. “But if anyone has objections, I'd like to hear them.”</p></div>\n<div><p>Prompted by Sanada's logic, several students looked back down at the map. There were five candidate destinations, each presenting a distinct set of pros and cons.</p></div>\n<div><p>Should we choose the closest location? Or should we swallow the travel cost and hike to a further point? At this stage, there simply wasn't enough information to determine a definitively ‘correct’ answer. As a result, each student's personality and thought process bled directly into their opinions.</p></div>\n<div><p>“I'm good with Sanada's plan,” Sonoda was the first to speak up. Staring down at the map, he offered a frank, pragmatic take, wanting no part in unnecessary fatigue. “This exam is four days and three nights, right? It's obvious we're going to be exhausted by tomorrow. Besides, if we don't even know what the next task is, we should save every bit of stamina we can.”</p></div>\n<div><p>His words were unvarnished, but they perfectly captured the unspoken feelings of many students present. Setting aside those who had retired early, the sheer fatigue and exhaustion everyone had accumulated from the recent Survival Game Special Exam was no small matter. A distance that looked like a trivial gap on paper could hardly be ignored when actually hiking it on foot.</p></div>\n<div><p>“I agree, too...” Mii-chan nodded gently. Tracing a spot on the map with her fingertip, she quietly explained her reasoning. “Based purely on the information we currently have, there's very little reason to throw away the obvious advantage of a shorter distance. That holds especially true if the explanation about the destinations not affecting future tasks is accurate.”</p></div>\n<div><p>Her tone was soft as always, but her stance firmly supported taking the nearest route. She eliminated unnecessary speculation, drawing a logical conclusion based solely on the conditions presented to us. In that regard, her thought process was very similar to Sanada's and Moriyama's.</p></div>\n<div><p>On the other hand, there were naturally those who refused to simply follow the flow.</p></div>\n<div><p>“But that's assuming we take the supervisor's words at face value, right?” Sumida said, lifting his gaze from the map. Rather than outright opposition, his voice oozed with caution. “He said the <em>contents </em>of the tasks wouldn't change, but he never said the ease of travel or future developments wouldn't be indirectly affected. Isn't it just as dangerous to pick a spot simply because it's close?”</p></div>\n<div><p>It was a highly plausible point. In fact, during these special exams, looking for loopholes in the rules and doubting the exact wording used by the school was practically second nature. The moment someone voiced that suspicion out loud, the seed of doubt, <em>the what if, </em>took root in the group's mind.</p></div>\n<div><p>“He's right. That sounds exactly like something this school would pull, just like they always do.”</p></div>\n<div><p>Ike immediately bit onto the idea. Still dragging along some of his lingering hostility from earlier, he quickly hopped onto an argument that suited his sensibilities.</p></div>\n<div><p>“Going with the closest spot just 'cause it's the normal thing to do is <em>too </em>normal, you know? In exams like this, there's always a pattern where the guys who pick the ‘normal’ option end up getting screwed over.”</p></div>\n<div><p>He didn't have any concrete basis for the claim. However, it was incredibly easy to intuitively agree with him. After all, trying to read between the lines to uncover a hidden trap felt much more fitting for a special exam than simply choosing the most obvious, optimal route.</p></div>\n<div><p>Katsuragi crossed his arms, dropping his gaze as he pondered the point. “It’s true that we cannot completely rule out a trap. Given the nature of our past special exams, it is perfectly natural to try and read into the rules that aren't explicitly stated.”</p></div>\n<div><p>It wasn't quite an agreement; it was more like he was leaving the possibility open. Yet, just having one vague affirmation of Ike's paranoia was enough to thin out the prevailing ‘nearest spot only’ atmosphere.</p></div>\n<div><p>Sumida slid his gaze back to the map. “Be that as it may, if we overthink this, the discussion is going to spiral out of control. As long as distance is the only metric we actually have to compare, any other theory is purely speculation, right?”</p></div>\n<div><p>Several students nodded silently in agreement with his sharp, dividing logic. It was easy to doubt the rules, but once you started doubting, there was no end to the rabbit hole. What the group needed right now wasn't necessarily the ‘correct’ answer, but a unified standard they could base their votes on.</p></div>\n<div><p>In that sense, Sumida's words had pulled the group slightly back to reality.</p></div>\n<div><p>“I...” Kushida spoke up, her voice soft.</p></div>\n<div><p>She interjected so naturally that it didn't disrupt the flow of the conversation, yet her words carried an undeniable weight.</p></div>\n<div><p>“I feel like we won't find an answer even if we keep agonizing over things we simply don't know right now. Of course, being cautious is important, but the fact that a closer destination reduces our physical burden is indisputable. If saving stamina gives us more leeway for whatever comes next, I personally think we should prioritize that.”</p></div>\n<div><p>It was a gentle, tactful way of speaking that rubbed no one the wrong way. She hadn't shut down anyone else's opinion, yet she smoothly steered the conclusion back toward supporting the nearest destination. Her ability to navigate these kinds of social situations was as masterful as ever.</p></div>\n<div><p>“Well, if Kikyō-chan says so, maybe that's the way to go,” Ike said, his expression immediately softening as he effortlessly abandoned his previous stance.</p></div>\n<div><p>Shinohara shot him a side-eye but remained silent. No, it was more accurate to say she actively swallowed her words. The look on her face made it clear she didn't want to ruin the mood over something trivial.</p></div>\n<div><p>Ibuki had been watching the entire exchange with profound boredom, but eventually, she sighed in annoyance and spoke up. “At the end of the day, no one here can actually name a single real benefit to hiking all the way to a distant spot right now, can they? If that's the case, then going to a closer place is fine. If it turns out to be a trap, I'll be pissed, but for now, I'd rather just walk a shorter distance.”</p></div>\n<div><p>Her argument was rough around the edges, but it was rare for Ibuki to reach a conclusion so quickly. She was clearly exhausted and had zero patience for pointless deliberation.</p></div>\n<div><p>Sonoda nodded in agreement. “Right. At the very least, using distance as our core metric is the easiest way to move the discussion forward. Even if we can't get everyone to completely agree on the ‘why,’ using the closest spot as our baseline makes it much easier to reach a consensus.”</p></div>\n<div><p>With that, support for prioritizing a nearby location had grown significantly. Even if it wasn't a flawless, unanimous agreement, the momentum was strong enough to adopt it as our guiding principle.</p></div>\n<div><p>Of course, the matter wasn't quite simple enough to end there.</p></div>\n<div><p>Which of the ‘nearby’ places should we choose? And exactly how far were we willing to hike before a location was no longer considered ‘close’? In reality, executing the 4-3-3-3-3 voting distribution across those locations was going to be the real problem.</p></div>\n<div><p>Taking stock of the room's atmosphere, Yoshida once again pointed to the candidates on the map. “I'm going to sound like a broken record, but are we <em>really </em>sure it's that simple? Unlike the Uninhabited Island exam where we were free to roam, there's absolutely no guarantee we'll be allowed to move around freely this time. What if positioning ourselves as close to the center of the island as possible gives us a massive advantage later on?”</p></div>\n<div><p>“Isn't there also a chance that the further we travel, the better our rewards will be?” Shinohara chimed in.</p></div>\n<div><p>Everyone wanted to earn tokens efficiently, and they all understood the voting distribution required to make that happen. But as long as the lingering possibility remained that our destination might impact the rest of the special exam, it was only natural for the group's opinions to remain divided.</p></div>\n<div><p>“I understand the concerns raised by Yoshida and Shinohara,” Katsuragi countered calmly. “However, those concerns are entirely based on unsupported speculation. Whether we head toward the center of the island or hike to its outer edges, we haven't been given a single clue about what lies ahead in this task. The only concrete, undeniable difference is the travel distance. Thinking rationally, selecting a nearby location is the absolute optimal choice.”</p></div>\n<div><p>“You know, you’re pretty damn stubborn, Katsuragi,” Yoshida scoffed. “Have you already forgotten that that exact rigid way of thinking is the reason you got booted from our class in the first place?”</p></div>\n<div><p>“Let’s drop it, Yoshida-kun. That was uncalled for,” Sanada reprimanded.</p></div>\n<div><p>Ever since transferring, I felt I had come to understand my new classmates to a certain degree. Unlike me, Katsuragi hadn't willingly betrayed his class; he had been the one forced out. Yet, the hostility directed at him was surprisingly intense. I could easily imagine him repeatedly clashing with his old classmates whenever opinions were divided over class policies.</p></div>\n<div><p>“I'm casting my vote with Katsuragi,” Ike declared, watching the two glare at each other as if the conflict had nothing to do with him. “Like the man said, it doesn't matter where we go, since we have no idea what's coming next anyway.”</p></div>\n<div><p>Despite the various opinions presented so far, it was painfully obvious that our group was not in step. If we proceeded to the vote right now, there was a high chance things wouldn't go according to our initially solid strategy. It would only take one person changing their destination on a whim to cause the entire 4-3-3-3-3 structure to collapse.</p></div>\n<div><p>Letting their imaginations run wild, these students were desperately trying to convince themselves that reading into the exam's nonexistent subtext was the ‘correct’ choice.</p></div>\n<div><p>It was the epitome of confirmation bias.</p></div>\n<div><p>Opting for the closest destination was a perfectly sound, logical choice. Yet, people couldn't help but prioritize narrative over simple probability and efficiency. They wondered if heading further away might yield a hidden reward, or if choosing a spot nobody else would pick might somehow be to their advantage. They were being drawn in by the allure of an uncertain gamble.</p></div>\n<div><p>Of course, we simply didn't know if our choice of destination would influence the rest of the task or not. The only thing I knew for certain was that we were actively losing a precious resource with every passing second.</p></div>\n<div><p>“Personally, I'd like to value our time,” I interjected. “We were thrust into this Special Exam immediately after the Survival Game Special Exam, without even being given a proper chance to rest. I would highly appreciate it if we could move on to the voting sooner rather than later.”</p></div>\n<div><p>Precisely because it truly didn't matter which of the five options we chose, I considered this entire discussion a monumental waste of time.</p></div>\n<div><p>“Heh, if that's the case, maybe it's actually in our best interest to drag this out as long as possible,” Ike laughed, clearly still annoyed by my earlier cold shoulder.</p></div>\n<div><p>“This is a group battle, Ike,” Katsuragi warned him. “There is absolutely nothing to be gained from pointless bickering.”</p></div>\n<div><p>“Ayanokōji's the one who's been picking a fight with me this whole time!” Ike shot back. He looked like he was about to keep arguing, but instead, he just scratched the back of his head and sighed. “Ah, whatever. This is probably useless anyway. Let's quit talking and just get to the voting.”</p></div>\n<div><p>Following Katsuragi's lead, we finalized our class-based adjustments and cast our votes.</p></div>\n<div><p>“Since everyone has finished voting, I will announce the results,” the supervisor stated. “The final tally is: 3 votes for B9, 4 votes for E12, 3 votes for F14, 3 votes for I10, and 3 votes for I13. From here, Group 3 will proceed to E12. We will now distribute tokens to each student in accordance with these results.”</p></div>\n<div><p>“It seems safe to assume that everyone played their part perfectly,” Katsuragi noted.</p></div>\n<div><p>Our group had managed a safe start, perfectly executing the split. Every class walked away with ten tokens, and no difference was created whatsoever.</p></div>\n<div><p>Satisfied with the result, Katsuragi gave a deep nod of approval. Despite their various dissatisfactions, the other students had ultimately prioritized securing the guaranteed tokens dangling right in front of them.</p></div>\n<div><p>“None of the betrayers you were so worried about showed up. Good for you, Ike,” Katsuragi said.</p></div>\n<div><p>“Well... yeah, but that's because the idea to prevent betrayals came from <em>my </em>class, right?” Ike argued. “Before you start complaining to me, you should thank Kikyō-chan. Thanks, by the way.”</p></div>\n<div><p>While pushing back against Katsuragi, Ike forcefully asserted that their success was entirely thanks to Kushida.</p></div>\n<div><p>“No, not at all,” Kushida replied, maintaining her flawless, gentle smile amidst the mixed group of classmates and outsiders. “I really wasn't confident in the idea, but I'm just happy I was able to be of use to everyone.” She played the part of the slightly embarrassed, humble girl to perfection.</p></div>\n<div><p>“Yeah, yeah. Kushida-san really did think of a great way to prevent betrayals, didn't she? I guess the way she sees things is just... completely different from the rest of us,” Shinohara remarked.</p></div>\n<div><p>It was a stinging, pointed jab delivered in a way that only the members of Horikita's class would understand. Was it simply because she harbored lingering resentment toward Kushida, or was she annoyed that Ike was so openly praising her?</p></div>\n<div><p>Either way, Kushida didn't let her mask slip in the slightest, effortlessly letting the comment slide.</p></div>\n<div><h2>Part 2</h2></div>\n<div><p>By the time we finished our trek, it was already past 6:00 p.m.</p></div>\n<div><p>Following the supervisor's instructions, we decided to pitch our tents here for the night. The students set about erecting tents and installing temporary toilets with practiced efficiency, naturally segregating the living areas by class.</p></div>\n<div><p>Within the main campsite, the territory was loosely partitioned into four distinct sections, one for each class.</p></div>\n<div><p>However, the moment Ike spotted me, he shot me a glare and immediately started in on me.</p></div>\n<div><p>“I'm only gonna say this once, Ayanokōji: don't come anywhere near our tent without permission. And about what happened earlier too—”</p></div>\n<div><p>“I have no intention of making enemies out of you outside of the exam tasks.”</p></div>\n<div><p>“Like anyone would believe that. If you think you're gonna get me expelled, you've got another thing coming.”</p></div>\n<div><p>“I suppose telling you I have absolutely no intention of doing that wouldn't convince you.”</p></div>\n<div><p>“No shit! Even the way you were acting today—”</p></div>\n<div><p>Unable to just sit there and listen to Ike's rising hostility, Katsuragi stopped what he was doing and rose to his feet.</p></div>\n<div><p>“Need I remind you that, for the time being, we are allies in the same group?”</p></div>\n<div><p>Katsuragi delivered his warning firmly. Still, having felt repeatedly made a fool of, Ike’s anger wasn't going to cool down that easily.</p></div>\n<div><p>“Look, I am calm. But there's no way I can see him as an ally. Ayanokōji is a traitor to the class, and he treats us like idiots. You can't let your guard down around him. Who knows when he might try to slit our throats in our sleep?” Ike turned to me before continuing. “Anyway, sorry, but just keep away from us unless it's absolutely necessary.”</p></div>\n<div><p>“If one of the sixteen people in this group was guaranteed to be expelled, I might understand your hostility, but…”</p></div>\n<div><p>“It's fine, Katsuragi. What Ike is saying is fundamentally correct.”</p></div>\n<div><p>After that, I grabbed my bags and ducked into our newly assembled three-person tent. A moment later, Yoshida followed me inside.</p></div>\n<div><p>“Still, Ayanokōji... Do you have some kind of grudge against Class A? Or rather, against Ike and Shinohara?”</p></div>\n<div><p>“I don't hold any grudges. Though, considering the circumstances, they have plenty of reasons to hold one against me.”</p></div>\n<div><p>“Well, yeah, I guess that's true. But if that's the case, what was up with your attitude during the task earlier? You went a bit far, and some of the things you said didn't even make logical sense. Are you dealing with some kind of issue or special circumstance you can't easily talk about?”</p></div>\n<div><p>Even though I had answered him honestly, Yoshida didn't seem entirely convinced.</p></div>\n<div><p>“I mean, going out of your way to leave Class A is pretty bizarre in itself.”</p></div>\n<div><p>I paused my unpacking and looked over at Yoshida. He met my gaze with a serious expression and continued.</p></div>\n<div><p>“How do I put this... watching you just made me wonder if you really made the right call. With your abilities, you could've comfortably graduated as a member of Class A.”</p></div>\n<div><p>“Being in Class A doesn't mean much to me. Even without using class privileges, there are plenty of alumni who have successfully made it into university.”</p></div>\n<div><p>“Sure, someone like you could probably pass the entrance exams for a top-tier college on your own. Still... after enrolling in a tough school like this, don't you think you might as well take advantage of the Class A privileges while you're at it?”</p></div>\n<div><p>“Fair point. I won't deny that.”</p></div>\n<div><p>“You're not even gonna deny it?!” Yoshida laughed, landing a playful smack on my shoulder.</p></div>\n<div><p>“I'm sure the other guys have already grilled you about this, but have you decided where you're going after graduation?”</p></div>\n<div><p>“I'll be going to university. I just haven't decided exactly where yet.”</p></div>\n<div><p>Even though I knew university life was completely irrelevant to my future, I had done a fair bit of research on the subject just so I wouldn't slip up and expose my ignorance.</p></div>\n<div><p>For a third-year high school student, summer was the crucial period to narrow down their top-choice schools. From what I’d read, it was standard practice to have those choices locked in by November at the latest.</p></div>\n<div><p>\"Have you finalized your choice yet, Yoshida? You mentioned before that any decent university would be fine.\"</p></div>\n<div><p>“Nah, nothing's changed. If I had to pick, I'd say I kinda want to stay in Tokyo. That being said, if I can't graduate from Class A, worst-case scenario is I end up at some local college back home.”</p></div>\n<div><p>Unlike regular high schools, this school offers a unique perk: the Class A graduation privilege.</p></div>\n<div><p>Yoshida’s case, for example. His plan was to take the entrance exams for a local college and try to get in on his own merit first. I didn't know if this had always been the rule, but under the school's current system, the final Class A standings are locked in on March 1st, right before graduation. If a student chooses to exercise their privilege at that point, they bypass the standard admission process entirely and are accepted into their university of choice under a special quota.</p></div>\n<div><p>Naturally, entering a university that far exceeds your actual academic level comes with serious drawbacks. You'd be playing catch-up against fast-paced lectures, the higher comprehension levels of your peers, and your own lack of prerequisite knowledge. There would be no shortage of hurdles requiring immense effort to overcome. But ultimately, surviving that environment simply comes down to how hard you're willing to work once you're in.</p></div>\n<div><p>Under normal circumstances, high schools and universities have strict enrollment caps, meaning the number of accepted applicants is ruthlessly narrowed down. Add in the pressure of make-or-break entrance exams and the fact that the higher a university's prestige, the fiercer the competition, and the barriers to entry become incredibly steep. But if you can skip all those hurdles and guarantee your enrollment, all you have to do is push forward with everything you have.</p></div>\n<div><p>Granted, this strategy wouldn't work for every academic path. Forcing your way into medical school or certain highly specialized majors without the necessary foundation might not lead to a very bright future. For students lacking confidence in their academics, rather than half-heartedly using the Class A privilege to struggle through college, it would be far more valuable to use it to secure a job at a major corporation straight out of high school.</p></div>\n<div><p>“Well, before we start talking about our dreams, we actually have to win this special exam first,” Yoshida sighed, flopping down onto his side in our relatively spacious tent.</p></div>\n<div><p>I immediately told him to get up, prompting him to lift his upper torso back off the floor.</p></div>\n<div><p>“What is it?”</p></div>\n<div><p>“You're right. Winning this exam is crucial,” I said, holding out my smartwatch for him to see. “Fortunately, the other classes are tucked away in their own tents right now. There are a few things I want to test out while we have the chance, so keep me company for a bit.”<span></span></p></div>\n<div><p>“I don't really get it, but I'm guessing you've thought of something? Alright, let's do this.”</p></div>\n<div><p>Pushing past his exhaustion, Yoshida sat up across from me as we spent the next little while running through my tests.</p></div>\n<div><h2>Part 3</h2></div>\n<div><p>By 7:00 p.m., it was time for dinner. Rations in hand, I headed over to the girls' side of the camp and called out to Kushida, who was mid-conversation with Amikura.</p></div>\n<div><p>“Would you like to eat together?”</p></div>\n<div><p>Amikura's smile seemed to stiffen for a fraction of a second, <em>perhaps the invitation had brought someone else to mind? </em>but she quickly smoothed over her expression and urged Kushida to go ahead.</p></div>\n<div><p>Looking suitably bewildered, Kushida grabbed her meal and followed me. We walked until we were safely out of earshot, at which point she stopped, keeping a deliberate distance of about a meter between us.</p></div>\n<div><p>“What are you trying to pull, Ayanokōji-kun?”</p></div>\n<div><p>“Didn't you say you wanted to discuss our plans for tomorrow?”</p></div>\n<div><p>“I never said that. Besides, it's not like you actually need my help, right? Honestly, you're just being a massive pain.”</p></div>\n<div><p>“Is that so? I figured that giving you a chance to prove your worth to the group would satisfy your need for approval. I thought you'd be happy.”</p></div>\n<div><p>“Don't make me laugh. If it were just you, Ayanokōji-kun, that’d be one thing, but do you have any idea how agonizing it is to be put on a pedestal in front of Shinohara and the others when they already know my true nature? They're just messing with me for their own amusement.”</p></div>\n<div><p>She punctuated her rant by narrowing her eyes into a vicious glare.</p></div>\n<div><p>“Though, I suppose I understand that you can't exactly rely on Shinohara or Ike…” she muttered with an exasperated sigh, grudgingly accepting that she had been chosen by process of elimination. “Putting that aside, it looks like you're adjusting quite nicely to your new class.”</p></div>\n<div><p>“With Sakayanagi gone, they lost their safety net. They probably would’ve rallied around anyone in that position, wouldn’t they?”</p></div>\n<div><p>“You don't say,” she scoffed.</p></div>\n<div><p>Her response was brief, followed by a fleeting moment of hesitation. </p></div>\n<div><img alt=\"Chapter Image\" width=\"600\" height=\"800\" src=\"https://cdn.sanity.io/images/m1xj6lbt/production/19d2178379335e1edfc4c70580bf31039197ffa7-1852x2832.webp\"><span></span></div>\n<div><p>Yet, just as quickly as her guard had wavered, her usual composure returned.</p></div>\n<div><p>“If there's something you want to ask, go ahead.”</p></div>\n<div><p>“It's nothing in particular,” she fired back instantly. But sensing that I'd already caught her hesitation, she let out a quiet sigh. “It's just... the rumors about you right now are endless. I don't believe all of them, obviously, but I've been hearing plenty of things from Class D as well.”</p></div>\n<div><p>She shifted her gaze toward Amikura and the rest of Ichinose's class as she spoke.</p></div>\n<div><p>“Still—” Her expression shifted as she deliberately changed the subject. “Having my true nature exposed has been almost entirely a nightmare... but having moments like this where I can just drop the act and speak my mind might be the only salvation.\"</p></div>\n<div><p>Forcibly ending the conversation there, she took a step back. She still hadn't touched a single bite of her dinner.</p></div>\n<div><p>“Sorry, but I'm heading back. I really don't want to draw any more unnecessary heat from Shinohara and the others.”</p></div>\n<div><p>“Your double life sounds exhausting.”</p></div>\n<div><p>“It's a little late for that.”</p></div>\n<div><p>With that, Kushida turned on her heel and headed back to Amikura's group.</p></div>\n<div><p>It was true that Shinohara was partly using Kushida as an outlet for the frustration she felt toward me. Kushida obviously wouldn't enjoy being collateral damage in that conflict.</p></div>\n<div><p>Still, that didn't mean I was going to leave her out of things from tomorrow onward. This special exam carried a guaranteed penalty: someone was going to be expelled.</p></div>\n<div><p>Normally, the strategy would be to hunker down, protect everyone in your own group, and just pray that the last-place student comes from a different group or class. But I had no intention of playing it that way.</p></div>\n<div><p>It was far more rational to take control and select the expulsion target myself from among the fifteen other students in my group. I wouldn't neglect laying the groundwork so that anyone could be chosen, depending on how the situation unfolded.</p></div>\n<div><p>While her priority was low, Kushida was naturally one of those candidates. That was just the reality of the situation.</p></div>\n<div><h2>Part 4</h2></div>\n<div><p>As we finished our dinner, the supervisor approached our group, tablet in hand.</p></div>\n<div><p>“Seeing as you've all finished your meals, we will now have you take on a new individual category task,” the supervisor announced. “Since you will continue to work together as a group to tackle tasks from tomorrow onward, I would like you to officially elect a ‘Popular Person’ and an ‘Unpopular Person.’ Each of you will cast one vote for the Popular Person and one vote for the Unpopular Person. The student crowned the Popular Person will be happily rewarded with five tokens upon the task's completion. Conversely, the student chosen as the Unpopular Person will, unfortunately, lose half of their current tokens. As a relief measure, anyone holding only a single token will not lose anything. However, if the unfortunate student possesses an odd number of three or more, any fractions of their remaining tokens will be rounded down, meaning they could potentially lose more than half their stash. Finally, any student who votes for the overall Popular Person will be awarded two tokens.”</p></div>\n<div><p>A task to decide the most and least popular among us. Naturally, the eyes of the students from the other classes gravitated toward Kushida. Meanwhile, Ike, Shinohara, and Ibuki all shot me meaningful glances.</p></div>\n<div><p>“If there is a tie for the Popular Person, no tokens will be awarded,” the supervisor continued. “Conversely, should there be a tie for the Unpopular Person, all tied individuals will have their tokens halved. You will have thirty minutes for discussion, and the voting method will remain the same as before. Furthermore, whoever secures the title of Popular Person will be exempt from being designated as the Unpopular Person. In such a scenario, the Unpopular penalty will automatically cascade to the individual with the next highest vote count. You may now begin.”</p></div>\n<div><p>Between the previous task and this one, a sense of déjà vu drifted over the group.</p></div>\n<div><p>“We've done a special exam like this before, haven't we?” Yoshida, who was seated next to me, muttered under his breath to Sanada.</p></div>\n<div><p>“Yes, it's extremely similar,” Sanada replied softly. “It's possible that this entire special exam is designed to mirror the special exams we've faced in the past. If you think about it, the format of this mixed four-class group is quite close to the Mixed Training Camp, so it makes sense.”</p></div>\n<div><p>It was still too early to draw any definitive conclusions, but the plausibility of that was steadily increasing.</p></div>\n<div><p>If that really was the case, then from tomorrow onward, we might be hit with tasks mirroring the rules of the Paper Shuffle, the Event Selection Exam, or the Cooperative Comprehensive Written Test, albeit on a much smaller scale.</p></div>\n<div><p>Regardless, speculating about the future wouldn't help us right now. We needed to focus on the task directly in front of us, the one where the Popular Person raked in tokens.</p></div>\n<div><p>Unlike the previous task, which had been structured so that everyone could easily reap the benefits, only a single person would walk away with these five tokens. The reward couldn't be split among the fifteen of us. Given that reality, everyone naturally wanted to be voted the Popular Person.</p></div>\n<div><p>However, the reality was that very few students possessed the confidence to brazenly assert their own popularity.</p></div>\n<div><p>More often than not, those who loudly declared themselves popular were the very ones who ended up ostracized.</p></div>\n<div><p>Even Ike, despite his obvious urge to speak up, chose to keep his hand down. He was well aware that the Popular Person title was entirely out of his reach. More than that, he was terrified that drawing attention to himself would backfire, turning him into a prime candidate for the Unpopular Person votes.</p></div>\n<div><p>“This task is going to be a headache,” someone muttered. “If we all coordinate and vote for the same Popular Person, we each get two tokens, but the winner walks away with five. Reaching an agreement on who gets the lion's share won't be easy.”</p></div>\n<div><p>“If we're going to struggle to reach a consensus, wouldn't voting for Kushida be the safest bet, assuming we're basing this strictly on popularity?” I interjected, hoping to cut down on a drawn-out discussion.</p></div>\n<div><p>“M-Me?” Kushida blinked, feigning surprise.</p></div>\n<div><p>Actually, she might have been genuinely surprised. After all, every single student in Horikita's class had already witnessed the real Kushida. While she likely interpreted my suggestion as a surface-level endorsement of her ‘sweet’ persona, the raw surprise in her eyes suggested she was frantically trying to deduce my underlying motive.</p></div>\n<div><p>At the same time, Yoshida and my classmates were visibly taken aback. Recommending a student from a rival class essentially meant willingly handing over the biggest payout.</p></div>\n<div><p>While Kushida directed a suspicious gaze at me, I also felt the inward pressure of her asking <em>What are you plotting?</em> It might just be my imagination, so I ignored it and continued speaking.</p></div>\n<div><p>“Of course, this is just a suggestion. If anyone has a more suitable candidate in mind, I have no objections.” By framing it this way, I made it seem as though I wasn't forcing the issue. Even so, the first idea tossed into the ring inherently sets the baseline for the rest of the debate.</p></div>\n<div><p>“No, you're definitely right!” Ike immediately latched onto the idea. “Kikyō-chan is super popular. She gets along with everyone and never gets involved in unnecessary drama.”</p></div>\n<div><p>Glossing over the fact that it was my suggestion, he cheerfully voiced his support.</p></div>\n<div><p>Kushida possessed two faces. Even though everyone in her class knew about her true nature, as long as the other classes remained in the dark, her public persona was an asset that could be exploited. Ike understood that much perfectly well. Furthermore, his inherently high affection for Kushida was likely fueling his eagerness.</p></div>\n<div><p>“You... think so? I'm not really sure,” she murmured.</p></div>\n<div><p>“Nah, out of everyone here, it absolutely has to be you, Kikyō-chan. No question about it!” Ike nodded along enthusiastically, his face lit up with a wide grin.</p></div>\n<div><p>When Kushida responded with a bashful, sheepish smile of her own, Ike’s expression melted even further, his eyes crinkling with sheer delight as a goofy smile spread across his face.</p></div>\n<div><p>While Ike's endorsement was unmistakably providing tactical covering fire for the class, from the perspective of his girlfriend, Shinohara, there was absolutely nothing amusing about it.</p></div>\n<div><p>It was painfully obvious that her frustration was spiking at the sight of her boyfriend fawning over another girl. Under normal circumstances, she probably would have dragged him off by the ear and hurled a few insults his way. However, securing the Popular Person spot for Kushida directly benefited their own class.</p></div>\n<div><p>“Well... yeah,” Shinohara sighed, unable to keep a hint of sourness out of her voice. “It'd be a different story if someone like Ichinose-san were here, but out of this group, isn't Kushida-san the safest choice?” Swallowing her personal irritation, she opted to back up Ike's proposal.</p></div>\n<div><p>Naturally, this momentum didn't sit well with anyone outside of Class A. Pushback began almost instantly.</p></div>\n<div><p>“Hold on a second. I get why you'd say Kushida is popular, and I'm not denying that, but just handing her our votes like this is a bit…” Yoshida trailed off, his hesitation clear as he struggled to voice a solid counterargument.</p></div>\n<div><p>“Then who else are you gonna vote for?” Ike challenged. “Name one person here who's more popular than Kikyō-chan. Go on, I'll wait.”</p></div>\n<div><p>“That's…” Yoshida scanned the circle. He was looking for someone who could rival, or perhaps even surpass, Kushida's widespread appeal. But even if he tried to bluff, no such student existed in our current lineup.</p></div>\n<div><p>“See? No matter how you slice it, there aren't any other candidates. So it's decided, decided!”</p></div>\n<div><p>“I'm really not all that great, though…” Kushida offered another modest smile, but her denial was flimsy. Her demeanor clearly left the door wide open for her to accept the nomination.</p></div>\n<div><p>And that very vulnerability gave Ike and the rest of Class A all the more reason to keep pushing for her.</p></div>\n<div><p>“I get where you're coming from, Yoshida, but realistically, there's no better candidate than Kushida.” I offered this dry defense for the benefit of Class A, though I was ultimately just stating the facts.</p></div>\n<div><p>“If only Shiraishi were here…” Yoshida muttered under his breath, his quiet frustration slipping past the others' notice.</p></div>\n<div><p>I wouldn't go so far as to say Shiraishi was unpopular, but Yoshida's imaginary vote was fueled entirely by his own personal bias.</p></div>\n<div><p>“...I see.” Katsuragi, who had been quietly observing the exchange, finally spoke up. He stood with his arms crossed, his sharp gaze fixed directly on me. “Your logic certainly holds up. However, there is one glaring flaw in this discussion.”</p></div>\n<div><p>As expected, it seemed Katsuragi was the first to notice.</p></div>\n<div><p>“We are letting ourselves be misled by the words ‘Popular’ and ‘Unpopular,’ completely blinding ourselves to the conflicting interests of our respective classes.” His voice was quiet, yet the sheer weight of his words anchored the room. “This group is a mixture of all four classes. Naturally, depending on the outcome, some classes will profit while others will suffer losses.”</p></div>\n<div><p>“Well, that can't be helped, right? Kikyō-chan <em>is </em>actually popular—”</p></div>\n<div><p>“That's exactly my point. Her actual popularity is entirely irrelevant.” Katsuragi cut Ike off without hesitation. “True, the exam tasks us with electing a ‘Popular Person,’ but there is absolutely no rule stating the nominee must actually fit that description.”</p></div>\n<div><p>“Huh...? But the supervisor literally said we had to properly decide so we could tackle the task.”</p></div>\n<div><p>“So what? That was merely an instruction to complete the objective. I didn't interpret that statement as anything more or less than what it was, did you?”</p></div>\n<div><p>He had hit the nail on the head. This wasn't a genuine popularity contest. At its core, it was simply a contest over who could hoard tokens and who would be stripped of them. As long as we remained distracted by the superficial wording, we would never have a meaningful discussion.</p></div>\n<div><p>“Voting for Kushida simply benefits Class A.” Katsuragi's gaze sharpened slightly. It was more of a check than a mere point out.</p></div>\n<div><p>“Oh, so that's how it is…” someone murmured as the realization set in. “Right. Whether they're actually popular or not doesn't matter at all.”</p></div>\n<div><p>“Then the idea is rejected. Rejected,” Ibuki spat, not wasting a single second. But simply shooting it down wasn't enough for her. “Seriously, why the hell should we go out of our way to hand tokens over to Kushida, to a rival class? Are you guys actually idiots for almost getting swept along by that?”</p></div>\n<div><p>It was a blatant, visceral rejection now that the illusion was shattered. She wasn't arguing with logic anymore; it was pure, unadulterated emotion.</p></div>\n<div><p>But that was fine. If anything, that raw emotion was exactly what I needed to shift the dynamic.</p></div>\n<div><p>While things were playing out exactly as I intended, Katsuragi's intense focus shifted back to me.</p></div>\n<div><p>“There is no way Ayanokōji wouldn't realize something of this level. Am I the only one who thinks so?” He fired the accusation point-blank, questioning exactly why I had nominated Kushida in the first place.</p></div>\n<div><p>\"You aren't secretly colluding with Kushida-san behind our backs, are you, Ayanokōji-kun?\" Shinohara, who had been nominally on Kushida's side as a fellow classmate until now, suddenly pivoted, aiming her suspicion straight at me.</p></div>\n<div><p>“Eh, w-what do you mean, Shinohara-san?” Seeing the crosshairs drift her way, Kushida immediately cranked up her performance of flustered bewilderment.</p></div>\n<div><p>But Shinohara ignored the act entirely. “I meant exactly what I said. Well, I suppose there's no way Kushida-san would actually stoop to something like that.”</p></div>\n<div><p>“Of course not, We had no way of knowing what kind of tasks were coming up in the first place.”</p></div>\n<div><p>“Yeah, Satsuki, you're taking it a bit too far.”</p></div>\n<div><p>“And why exactly are you taking Kushida-san's side?!” Shinohara snapped.</p></div>\n<div><p>“Whoa, hey, wait a sec! There's no need to get so combative, right? I mean, I was thinking the same thing as Ayanokōji, so maybe he really was just trying to pick the safest option?”</p></div>\n<div><p>“I highly doubt that. Don't think I haven't noticed you doing nothing but staring at Kushida-san this whole time, Kanji!”</p></div>\n<div><p>“T-That's not true at all! I swear, seriously, I swear!”</p></div>\n<div><p>As the atmosphere rapidly deteriorated into a petty lovers' quarrel that threatened to derail the discussion, Ibuki snapped and kicked the ground in aggravation.</p></div>\n<div><p>“Whatever, the point is, I absolutely refuse to hand tokens over to Class A.”</p></div>\n<div><p>“Agreed. We're against it too,”</p></div>\n<div><p>One after another, the members of Class B voiced their dissent, and the remaining classes quickly followed suit. They showed no signs of backing down.</p></div>\n<div><p>“Man, come on... this is still better than getting into some weird, messy conflict, right?” Turning his back to actively dodge Shinohara's terrifying glare, Ike desperately tried to placate the group. “What's the point of jumping straight at each other's throats right from the start? For one thing, we'll never reach an agreement like this.”</p></div>\n<div><p>“Then we should just stop talking in circles,” Ibuki declared bluntly, having zero patience for drawn-out discussions. “Let's just pick whoever we actually want to vote for and be done with it.”</p></div>\n<div><p>If talking it out couldn't yield a favorable outcome, she preferred to level the playing field. To her, a straightforward clash was the simplest path forward and offered the cleanest chance of winning.</p></div>\n<div><p>Katsuragi quietly processed her suggestion. “Simply nominating whoever we please might actually be the safest option.”</p></div>\n<div><p>“I mean, if the whole point is that the Popular Person gets tokens, then voting normally makes the most sense. Not that I care how the results shake out,” Ibuki agreed with a casual nod, treating it as the most natural conclusion.</p></div>\n<div><p>“However, taking that route practically guarantees that each class will just consolidate their votes,” Sanada pointed out. “Even if we don't say a single word, it's easy enough to coordinate our votes through eye contact alone.”</p></div>\n<div><p>He was right. If we divided along class lines, it would only result in up to four ‘Popular People’ receiving three votes each. A multi-way tie meant zero tokens awarded across the board.</p></div>\n<div><p>“Yeah, exactly!” Ike seized the opening. “If we do that, the votes will just split, and nobody gets anything. In that case, it's absolutely better to pool our tokens on Kikyō-chan and boost the group's overall total! This special exam isn't just about individuals hoarding tokens, right? It's about helping each other out!”</p></div>\n<div><p>“You have a point, Ike,” Sonoda from Class B interjected. “I get what you're trying to say. But if pooling points is the goal, then someone from Class B... hell, even <em>I </em>would be fine. The total number goes up either way, so it's the exact same thing.”</p></div>\n<div><p>“Uh, that's actually a little different, Sonoda-kun,” Shinohara shot back. “Helping each other out means trusting that the person will actually lend a hand when someone is in trouble. No offense, Sonoda-kun, but you aren't exactly trustworthy. Kushida-san, on the other hand, is. Isn't that right, Ayanokōji-kun?”</p></div>\n<div><p>She was smoothly weaponizing the exact logic I had laid out earlier regarding Kushida's reliability, turning it directly back on Sonoda.</p></div>\n<div><p>“Yeah, that logic holds up,” I agreed.</p></div>\n<div><p>If Kushida was crowned the Popular Person, she would gain five tokens. While those tokens would ostensibly belong to Class A, if Sonoda or anyone else were to fall into a desperate situation later on, Kushida possessed the reputation of someone who would return the favor and bail them out. It served as a form of insurance for the future.</p></div>\n<div><p>“Sure, maybe it means our class gets a few more tokens right now,” Shinohara continued, pressing her advantage. “But you can think of it as a value of trust. Right, Kushida-san?”</p></div>\n<div><p>“I... I really don't know if I'm suited to be the Popular Person,” Kushida replied, her voice soft and earnest. “But if anyone ever found themselves in trouble, I would absolutely want to help them.”</p></div>\n<div><p>A heavy silence fell over the area, the sheer weight of their competing arguments lingering in the air.</p></div>\n<div><p>Those were the words of arguably the most trustworthy person in the entire group. Yet, despite that, the other classes couldn't bring themselves to simply nod in agreement.</p></div>\n<div><p>The core issue was the inevitable disparity in tokens. Handing Kushida the win meant willingly allowing a gap to form between the classes within our group, a scenario they desperately wanted to avoid. Even if it meant forfeiting the reward entirely by forcing a tie, stalling the creation of a clear hierarchy felt safer. The debate had shifted entirely from <em>‘who is popular’ </em>to <em>‘are we fine letting Class A take the lead?’</em></p></div>\n<div><p>“What do we do, Ayanokōji?” Yoshida whispered under his breath, leaning in so the others wouldn't hear. “Do you have some kind of plan?”</p></div>\n<div><p>I didn’t answer. I merely let my gaze drift sideways, observing the distance between Ike, Shinohara, and Kushida, who remained just beyond them.</p></div>\n<div><p>A very slight, yet undeniable gap had formed among the three, a subtle rift that hadn't been there moments before. For the purposes of this task, that alone was sufficient.</p></div>\n<div><p>It was nothing more than a tiny seed of discomfort right now, but given enough time and the right circumstances, it would inevitably blossom into something far more tangible.</p></div>\n<div><p>With no clear compromise in sight, the clock continued to tick down. One minute passed, then two.</p></div>\n<div><p>“Seriously, what are we doing here? We can't move forward if we don't actually decide on something,” Ike finally snapped, his patience wearing thin.</p></div>\n<div><p>However, the edge in his voice wasn't fueled by genuine anger. Rather, it was a desperate impatience to just get it over with, proof that he couldn't stomach the suffocating tension in the room for another second.</p></div>\n<div><p>“Regarding the Popular Person, it really feels like that's our only viable option,” Shinohara added, her gaze flicking up slightly.</p></div>\n<div><p>Naturally, a few sets of eyes immediately gravitated toward her. A clear sense of caution still lingered in those looks, but for the time being, that was fine.</p></div>\n<div><p>“Basing the vote solely on Kushida's personal trustworthiness, you say…” Katsuragi mused, his arms still crossed. “True, if you frame it strictly from that angle, the logic is sound, but…” His eyes remained narrowed, silently probing my intentions. It was obvious he still wasn't entirely sold on the idea.</p></div>\n<div><p>“I don't care if the class votes end up splitting or whatever. It just means we're stuck picking randomly in the end anyway, right?” Ibuki scoffed. “So why are we still rambling in circles? This is so stupid.”</p></div>\n<div><p>“Right? We basically just have to decide what's better: letting the votes split so nobody in the group gets any tokens, or giving the win to Class A so the group's overall total goes up,” Ike said, offering a quick shrug. “Trying to pull off some weird mind game and completely whiffing it is way worse.”</p></div>\n<div><p>“Besides, if the group is bringing in tokens, we should normally be grateful for it,” Shinohara chimed in with a small nod of agreement. Her comment sounded casual, but it carried exactly enough weight to decisively tip the scales.</p></div>\n<div><p>By shifting the focus to a simple, easily digestible matter of total profit, the resistance from the other classes weakened considerably.</p></div>\n<div><p>“...I can't say my objections have completely vanished,” Katsuragi finally conceded. “But seeing as there is no clear counter-proposal on the table at this moment... I am willing to tentatively accept this.”</p></div>\n<div><p>“Alright, then— are we officially good with Kikyō-chan as the Popular Person?”</p></div>\n<div><p>When no one voiced a direct objection to Ike's confirmation, a few seconds of heavy silence ticked by before it was quietly processed as unanimous approval.</p></div>\n<div><p>With that, the first major hurdle was cleared.</p></div>\n<div><p>“I guess that's fine,” Ibuki said suddenly, leaning forward. “But by the way, what exactly are we doing about the Unpopular Person?”</p></div>\n<div><p>The atmosphere changed instantly, the air around us growing noticeably heavier.</p></div>\n<div><p>If anything, one could argue that <em>this </em>was the true crux of the matter for Ibuki.</p></div>\n<div><p>Unlike with the Popular Person, no one dared to casually open their mouths this time.</p></div>\n<div><p>And naturally so. This wasn't about uplifting someone; this was a discussion about tearing someone down. There was no way this could end peacefully, which was precisely why everyone knew they had to tread carefully.</p></div>\n<div><p>“A debate where we just try to forcefully shove the penalty onto someone else will only end in a fruitless, ugly conflict. The simplest resolution is for someone willing to take the loss to step forward,” Katsuragi stated, deliberately cutting to the chase in an effort to prevent the atmosphere from turning hostile.</p></div>\n<div><p>“...Well, I suppose that's true,” a Class C student muttered, and the rest of his classmates mirrored his complicated, uneasy expression.</p></div>\n<div><p>“Locking in the Popular Person during this discussion is enough,” Katsuragi added after a brief pause. “As for the Unpopular Person vote, we simply need to let everyone judge the situation for themselves and cast their votes however they see fit.”</p></div>\n<div><p>“So it's a ‘no hard feelings’ kind of deal, right?” Shinohara confirmed, though a slight edge of irritation bled into her voice. She wasn't dumb; she knew perfectly well that if she voiced a strongly negative opinion right now, she would instantly paint a target on her own back.</p></div>\n<div><p>Ibuki, who had been the one to bring the issue up in the first place, also kept her mouth shut after that. Unlike Kushida, who had cleanly secured the Popular Person spot, Ibuki was exactly the type of student who was at high risk of gathering the Unpopular votes.</p></div>\n<div><p>“That's what it comes down to,” Katsuragi confirmed.</p></div>\n<div><p>“I see…” Sanada murmured, summarizing the strategy aloud. “By choosing not to unify our votes, we are conversely leaving room for mind games.” He gave a small nod, looking thoroughly convinced.</p></div>\n<div><p>He was right. If we forcefully nominated a single sacrifice right now, the thought process for everyone would remain simple and straightforward.</p></div>\n<div><p>But by dispersing the target, we were forcing everyone to read between the lines.</p></div>\n<div><p>And those readings… would inevitably become distorted.</p></div>\n<div><p>Ike relaxed his shoulders, and Shinohara mirrored him with a small sigh of relief. They exchanged a brief look. It was a perfect display of silent communication, a phenomenon the other classes were now unconsciously beginning to mimic.</p></div>\n<div><p>Claiming we would leave the unfortunate role up to luck without singling anyone out was nothing but a convenient facade.</p></div>\n<div><p>In reality, coordinated voting blocs form just as easily for negative penalties as they do for positive rewards. In fact, the psychological mechanics behind a negative vote drive an even stronger need for collusion. ‘Voting as you please’ sounded perfectly fair on paper, but in practice, it immediately sparked a web of mind games. Predictions are made, and people naturally piggyback on those predictions to protect themselves. If that bandwagon effect is left unchecked, it inevitably converges on a single point: the absolute safest, most convenient target.</p></div>\n<div><p>There was no need to wonder who that unlucky target would be.</p></div>\n<div><p>Ike and Shinohara were going to vote for me with one hundred percent certainty. Ibuki would read that and cast a third vote my way.</p></div>\n<div><p>Furthermore, astute students like Katsuragi would anticipate this exact flow and steer their own votes to push me securely into the Unpopular spot.</p></div>\n<div><p>This silent consensus was already spreading rapidly among the students outside of Class C. It was no wonder Sanada looked a bit anxious as he sensed the current solidifying against us, but he couldn't raise an objection. Since we had ostensibly agreed to leave the vote up to individual discretion, he had no grounds to stop it.</p></div>\n<div><p>“Well then, since that's settled, let's just get to voting,” Ike prompted.</p></div>\n<div><p>Short murmurs of agreement echoed around the circle, and the momentum of the room shifted entirely toward executing the vote. Kushida for the Popular Person, and individual discretion for the Unpopular Person.</p></div>\n<div><p>As a discussion, it was over. At least on the surface. Not everyone was entirely satisfied, but digging any deeper would inevitably expose the ugly reality that someone was about to be deliberately sacrificed. Given that fact, it was only natural that the group wanted to slap a lid on the debate while things were still relatively peaceful.</p></div>\n<div><p>In truth, cutting the conversation short here was the correct move for the majority. Probing too deeply could cause the wind to shift in an unpredictable direction. Precisely because they had just openly colluded to concentrate their Popular votes onto a single person, no one wanted to touch the Unpopular vote with a ten-foot pole. The superficial declaration of ‘not deciding’ was functioning perfectly as a collective safety measure.</p></div>\n<div><p>However, naturally, for me who was being targeted, I had no intention of letting the discussion end here.</p></div>\n<div><p>“I'd like to confirm one last thing before we proceed,” I spoke up, cutting through the final moments before the vote. “If we actually leave this up to individual discretion, the Unpopular votes will split. That means multiple students could end up having their tokens halved. Isn't that the absolute worst-case scenario?”</p></div>\n<div><p>“What gives? You're still dragging this out?” Ike groaned. “Enough already. It's not like we've decided the Unpopular Person is gonna be someone from Class C or anything.”</p></div>\n<div><p>His words were laden with thinly veiled subtext. What he was really saying was: <em>You're going to be the Unpopular Person, so a split vote isn't going to happen anyway.</em></p></div>\n<div><p>“I really don't wish to dig this back up either,” Sanada interjected, likely sensing this was his only window of opportunity. “But... in that case, what do you believe is the correct course of action, Ayanokōji-kun?”</p></div>\n<div><p>You could practically feel the irritation rolling off the other classes. This was a topic they desperately wanted to sweep under the rug.</p></div>\n<div><p>“It's a difficult problem,” I answered without missing a beat. “The reality is, being chosen as the Unpopular Person carries nothing but severe demerits.”</p></div>\n<div><p>“Which is precisely why we are conducting an equal, open vote,” Katsuragi stated. “If that results in a tie and multiple people take the penalty, then it simply cannot be helped.”</p></div>\n<div><p>Katsuragi's sharp gaze locked onto mine. His words carried an unmistakable, silent challenge: <em>Show me how you plan to maneuver out of this situation. Let's see how you turn the tide.</em></p></div>\n<div><p>“We concentrate our votes on Kushida, who naturally draws the fewest objections as the ‘Popular Person’ in both name and reality. That guarantees two tokens for all fifteen of us. Up to that point, there’s no problem,” I began, first laying out the premise.</p></div>\n<div><p>“The issue lies with the remaining Unpopular vote. If the votes split apart, there’s a real chance that two or three students could each lose half their tokens instead. To avoid that, we need to predetermine a single Unpopular Person from the very beginning, just as we did for the Popular vote.”</p></div>\n<div><p>“Huh? We're only having this conversation because we <em>can't </em>do that,” Ike scoffed. “What are you—”</p></div>\n<div><p>“I'm not finished,” I cut him off, turning back toward the group. “Therefore, our class will willingly take on the role of the Unpopular Person.”</p></div>\n<div><p>Rather than trusting our fate to some superficial illusion of equality, I was deliberately reaching out to claim the penalty. By doing so, I could steer the situation toward a conclusion that appeared similar, but was fundamentally different.</p></div>\n<div><p>“By accepting the Unpopular penalty in advance, we can establish a framework where the other classes are absolutely guaranteed to suffer zero casualties,” I explained.</p></div>\n<div><p>“Well, yeah. I agree, I totally agree! Right, Satsuki?”</p></div>\n<div><p>“Yeah, I think it's fine. If Class C is willingly volunteering for it, I don't have any complaints.”</p></div>\n<div><p>Since Ike and Shinohara had already internally cast their Unpopular votes for me anyway, neither of them raised a single objection.</p></div>\n<div><p>“However, in exchange for taking the hit, I want Kushida to transfer two tokens to our side after the task ends,” I added. “She will gain five as the Popular Person. Even if she hands over two, she still walks away with three, meaning her individual cut will still be the largest among everyone here.”</p></div>\n<div><p>“Well, if Class C is taking the penalty, I don't mind that condition at all, but…” Kushida began, showing her intent to consent, only for Ike to immediately interrupt.</p></div>\n<div><p>“Hold on, why does Kikyō-chan have to bear the burden for that? That's totally messed up!”</p></div>\n<div><p>“It's not messed up in the slightest,” I countered smoothly. “We are sacrificing ourselves to ensure that multiple Unpopular penalties aren't triggered. I am merely asking her for a slight compensation to mitigate our damage.”</p></div>\n<div><p>Since my role as the Unpopular Person was already locked inside Ike's head, it was no wonder he perceived the tax on Kushida as an utterly meaningless burden.</p></div>\n<div><p>“The logic appears sound,” Katsuragi mused. “In reality, even if Class C receives two compensatory tokens, they won't end up with a net positive. The number of tokens each student possesses at the start differs, but even assuming all four of them started with the bare minimum of two, combined with the earlier reward, their current stash would be three or more. The moment that count is halved, they will lose a minimum of two tokens. The net balance is zero. And if their starting count was any higher, the tokens they lose will only increase.”</p></div>\n<div><p>Because none of the sharper students had started this special exam with the bare minimum of two tokens, it likely hadn't even crossed their minds that someone could mathematically manipulate the penalty to result in a net balance of zero.</p></div>\n<div><p>“But something about this is weird! It might be a trap!” Ike protested.</p></div>\n<div><p>“I don't mind if you doubt my intentions,” I replied. “But if you don't like the proposal, Ike, then <em>you </em>are more than welcome to step up and take on the role of the Unpopular Person. Naturally, you would also be entitled to those two extra tokens as compensation.”</p></div>\n<div><p>“Th-That's... impossible! There's no way I can do that!” Ike immediately backed down, rejecting the offer vehemently.</p></div>\n<div><p>And rightly so. Ike almost certainly held more tokens than the proposed compensation would cover. If he was going to suffer a net loss of even a single token after having his stash halved and gaining the two extras, there was zero chance he would accept the deal.</p></div>\n<div><p>During the Survival Game Special Exam, students like Katsuragi and Ike had managed to survive for a decent chunk of time without getting eliminated. Consequently, they had started this current exam with a comfortable cushion of tokens. It was perfectly understandable if the idea of someone having three or fewer tokens at this stage had completely slipped their minds.</p></div>\n<div><p>Because there wasn't a single student in the other classes who could stomach having their tokens halved, it was practically impossible for them to reject the condition I had proposed.</p></div>\n<div><p>“I wondered how you were going to resolve this deadlock,” Katsuragi said, a hint of begrudging respect in his voice. “I see. So there was that perspective as well.”</p></div>\n<div><p>Even if the other classes wanted to complain out of sheer dissatisfaction, they couldn't offer themselves up as substitutes. Nor could they openly assert that I was going to be the Unpopular Person anyway without exposing their blatant collusion. I had completely cut off any avenue for a counterattack.</p></div>\n<div><p>“Well then, I guess I'll take on the role of the Unpopular Person,” Yoshida announced, raising his hand as if this was exactly the moment he had been waiting for. “Kushida, I'll be counting on those two tokens later.”</p></div>\n<div><p>At his overly casual volunteer, the atmosphere froze for a split second.</p></div>\n<div><p>Logically, everyone understood the concept of someone deliberately taking a loss for the group, but it was rare to see someone actually offer it out loud. Much less in a high-stakes situation where the results directly dictated the immediate loss of one's own tokens.</p></div>\n<div><p>“Hey, if someone has to do it anyway, it's better to just decide quickly and move on,” Yoshida said, looking directly at Ike and Shinohara, who had shown the strongest resistance thus far. “Besides, as far as our class is concerned, it wouldn't be amusing in the slightest if Ayanokōji somehow ended up gathering all the Unpopular votes by some crazy coincidence.”</p></div>\n<div><p>While volunteering subtly hinted that Yoshida possessed a comfortable amount of tokens to burn, it served as an incredibly strong deterrent.</p></div>\n<div><p>“...Well, in terms of actually being the ‘Unpopular Person,’ maybe they aren't wrong, right?” Shinohara muttered. “I still think it's way more natural to just leave it up to everyone and let the votes fall where they may.”</p></div>\n<div><p>Her desire to strike me while the iron was hot was entirely transparent; she wasn't even trying to hide it.</p></div>\n<div><p>“I thought a group was supposed to cooperate wherever possible, right?” Yoshida challenged lightly, flashing a small shrug. “If we just leave it to ‘chance’ here, and by some crazy coincidence a certain someone ends up gathering twelve whole votes... well, that's gonna look more like an organized voting than a coincidence. And honestly, I'd really hate for our cooperative relationship to completely fall apart moving forward.”</p></div>\n<div><p>There was no trace of seriousness in Yoshida's attitude. He hadn't been forced into the role; he had perfectly established the outward appearance of a man undertaking the burden entirely of his own volition for the sake of his class.</p></div>\n<div><p>Since the interests of the four classes would never perfectly align, situations where someone simply had to yield were inevitable. But since someone had stepped up and willingly volunteered to fall on their sword, any remaining justification to drag the discussion out completely evaporated.</p></div>\n<div><p>“You make a fair point. If that is the arrangement, I have no objections,” Katsuragi said with a quiet nod.</p></div>\n<div><p>Sonoda, Minamikata, and the rest of the Class B students exchanged looks, but none of them voiced any strong opposition. Even if they weren't entirely satisfied with the outcome, they likely judged that with no better alternatives on the table, they had no choice but to accept the compromise.</p></div>\n<div><p>Ibuki, too, simply offered a tiny shrug, making no move to interject. She knew perfectly well that pushing the issue any further ran the risk of turning the spearhead back toward herself.</p></div>\n<div><p>As for Class A, even if Ike and Shinohara stubbornly cast their Unpopular votes for me now, there was no guarantee I would rack up more votes than Yoshida. If a clumsy two or three stray votes landed on me, it would only breed suspicion and ultimately shatter our tenuous cooperative relationship.</p></div>\n<div><p>“Fine, I get it,” Ike grumbled. “We just have to vote for Yoshida, right?”</p></div>\n<div><p>And with that, the targets were officially locked in: Kushida, whom the group trusted, and Yoshida, who had stepped up as the sacrificial lamb.</p></div>\n<div><p>Not everyone was thrilled with the result, but it landed squarely on the minimum acceptable line for all four classes. It was a fragile equilibrium, maintained by the mutual understanding that pushing even an inch further would cause the entire discussion to collapse.</p></div>\n<div><p>Following the supervisor's instructions, we all dropped our gazes to our smartwatches. The input process was incredibly simple: one vote for the Popular Person, one vote for the Unpopular Person.</p></div>\n<div><p>In the brief window before the results were finalized, a heavy silence wrapped the space; no one dared to speak.</p></div>\n<div><p>And so, the task reached its conclusion.</p></div>\n<div><p>Once the results were confirmed and the suffocating tension finally broke, Yoshida casually flicked his gaze in my direction. Locking eyes with me for just a split second, he offered a quick thumbs-up.</p></div>\n<div><p>To anyone else watching, it was easily brushed off as the small, self-satisfied gesture of a guy who had just taken a hit to protect his class leader. To the rest of the group, Yoshida's volunteer act looked like a genuine, albeit minor, self-sacrifice. Even if they assumed his token stash was relatively low, they knew he mathematically couldn't profit from the exchange.</p></div>\n<div><p>But the reality was the exact opposite. Yoshida was actually walking away with a pure profit.</p></div>\n<div><p>That was because, through a few prior adjustments behind the scenes, I had already lowered Yoshida's token count down to the absolute minimum of one.<span></span></p></div>\n<div><p>According to the rules, anyone holding only a single token was exempt from the halving penalty. Therefore, even after being officially crowned the Unpopular Person, Yoshida lost absolutely nothing. In fact, since he was now guaranteed to receive those two compensatory tokens from Kushida, the entire maneuver carried zero hidden risks.</p></div>\n<div><p>Shortly before this task began, while we were still inside the tent, Yoshida and I had repeatedly tested the token transfer mechanics. We discovered a few key details. First, the basic condition for a transfer required both parties to operate their smartwatches and physically tap them together, which triggered a default notification sound. However, we realized this chime could be easily muted by simply turning the watch's volume down to zero beforehand.</p></div>\n<div><p>If transfers could be executed just by brushing two watches together, silencing the notification would be a massive security flaw. But since both parties were required to input their personal PINs to authorize a transaction, there was no risk of tokens being stolen in secret. Thus, the school had made the sound notification entirely optional.</p></div>\n<div><p>Next, we tested the actual speed and frequency of the transfers. While the system required you to input your PIN again after each completed transaction, there was practically zero lag. Once we got the hang of it, we found we could continuously fire off transfers in about ten seconds flat. You could send tokens one at a time on loop, or dump them all in a single lump sum.</p></div>\n<div><p>During our testing, we also discovered that the system threw up a severe warning error if you attempted to initiate a transfer when your balance was already down to one token.</p></div>\n<div><p>The fact that this special exam carries a risk of reducing tokens to zero implies that the rules allow for them to be stripped away during the challenges, not just through peer-to-peer transfers.</p></div>\n<div><p>However, if a challenge capable of draining three or four tokens were introduced right at the outset, students who started with a baseline of only two would face an immediate checkmate.</p></div>\n<div><p>My modeling of the school's habits suggested as much. If they intended to inject a negative element this early, they would opt for a mechanism like ‘halving’ to ensure a zero-balance was impossible.</p></div>\n<div><p>Still, to think I would be able to exploit that exact mechanic this early in the exam... things had worked out almost a little too perfectly.</p></div>\n<div><h2>Part 5</h2></div>\n<div><p>The previous task had barely concluded before the supervisor began tapping away at his tablet, offering no hint of a dismissal.</p></div>\n<div><p>“I have officially recorded the results and distributed your tokens,” he announced. “Now, we will take a brief five-minute intermission, after which we will commence the final individual task of the day. Thank you for your cooperation.”</p></div>\n<div><p>“You've gotta be kidding me. There's <em>another </em>one?”</p></div>\n<div><p>Groans of dismay rose from the girls first, who had clearly assumed we would be moving straight into free time before bed. Echoing their sentiment, murmurs of discontent began rippling through the boys as well.</p></div>\n<div><p>It was a four-day, three-night special exam. Tomorrow would likely be the main event, but even for a day focused mostly on talking, this schedule was relentless.</p></div>\n<div><p>True to her word, Kushida transferred two tokens to Yoshida. While some students killed the brief intermission by checking their smartwatch balances, it wasn't long before the exam was set in motion once more.</p></div>\n<div><p>“I will now explain the final task,” the supervisor began. “This one leans closer to a gamble, relying heavily on elements of luck. You can think of it as a simple game. However, because of its nature, I must first confirm whether or not each of you actually wishes to participate. Should you choose to play, you will be required to wager, and potentially lose, two tokens upon defeat.”</p></div>\n<div><p>“So participation is entirely voluntary... right?” Sanada asked cautiously.</p></div>\n<div><p>The supervisor gave a curt nod. “Yes. For instance, if you currently hold two or fewer tokens, you may choose to sit this one out. Alternatively, if you simply do not wish to shoulder the risk of losing, you are well within your rights to decline. However, choosing to abstain carries a penalty: you must pay one token as compensation.”</p></div>\n<div><p>We were faced with a choice: risk losing two tokens for a chance at victory, or pay a flat fee of one token to guarantee your safety.</p></div>\n<div><p>“I mean, you'd normally just play, right? Isn't it completely stupid to spend a token just to <em>not </em>participate?” Ike scoffed.</p></div>\n<div><p>“I wouldn't be so sure,” Katsuragi countered. “True, if your sole focus is hoarding personal tokens, maximizing your participation is the mathematically correct choice. However, if your absolute priority is avoiding expulsion at all costs, paying one token to sidestep a two-token loss is equally valid.”</p></div>\n<div><p>It was a running theme today, dilemmas where a single, objective ‘correct answer’ simply didn't exist. Regardless, the harsh reality was that very few students in our group could actually afford to casually bleed a token just to sit on the sidelines. In the end, everyone opted to participate.</p></div>\n<div><p>The supervisor announced the winner's reward, a handsome five tokens, and the task officially began.</p></div>\n<div><p>“I hold in my hands sixteen folded slips of paper,” the supervisor said, fanning them out. “There are exactly two slips for each number between one and eight. You will be facing off against the student who draws the same number as you. I will explain the rules shortly, so for now, please come forward and draw your lot. Do not unfold your paper until I give the signal.”</p></div>\n<div><p>Without any designated order, the students closest to the front stepped up first. I went sixth, drawing a folded slip and returning to my spot.</p></div>\n<div><p>“You may now check your numbers,” the supervisor instructed. “I will collect the slips afterward, so please refrain from tearing or crumpling them.”</p></div>\n<div><p>Bathed in the pale moonlight, the sixteen members of Group 3 simultaneously unfolded their slips. I glanced down at my palm. The number written there was ‘4’.</p></div>\n<div><p>“Please sit facing your designated opponent, arranged in numerical order starting from pair number one. I will now collect your slips.”</p></div>\n<div><p>As the supervisor gathered the scrap paper, he distributed a hand of five playing cards to each student. The backs featured a uniform, standard pattern, but the faces were unique: each card bore a single odd number— 1, 3, 5, 7, and 9— arranged sequentially in our hands. Catching a glimpse of the students to my left and right, I confirmed their hands consisted of the exact same 1-through-9 odd-number lineup.</p></div>\n<div><p>The matchups were as follows: Pair 1 was Katsuragi and Morishita. Pair 2 was Ibuki and Morofuji. Pair 3, Minamikata and Sonoda. Pair 4 was me and Wang. Pair 5, Ike and Kushida. Pair 6, Amikura and Shinohara. Pair 7, Yoshida and Sumida. And rounding it out, Pair 8 was Sanada and Moriyama.</p></div>\n<div><p>“Umm, Ike-kun and I are both in Class A,” Kushida raised her hand tentatively. “Do we still have to play against each other?”</p></div>\n<div><p>“Yes. Your class affiliations are completely irrelevant for this task,” the supervisor replied flatly.</p></div>\n<div><p>Given the bare-minimum explanation, Kushida blinked in mild bewilderment but obediently nodded her understanding.</p></div>\n<div><p>“The rules are simple,” the supervisor continued. “In each round, both players will select one card from their hand and place it face down. You will then reveal them simultaneously. The player who plays the higher number wins the round. If the numbers match, the round is a draw. Once a card has been played, it is consumed and cannot be used again. The first student to secure two wins will be declared the overall victor. The winner will acquire five tokens, while the loser will forfeit the two tokens they initially wagered. In the rare event of a complete draw after all five cards are consumed, you will retrieve your hands and play an overtime match until a single win is secured. Excluding the overtime match, please aim to finish within approximately 5 minutes.\"</p></div>\n<div><p>By giving a soft five-minute guideline rather than a hard limit, the school was implicitly warning us against deliberately stalling or overthinking. If a match dragged on for seven or eight minutes, it probably wouldn't result in an instant disqualification, but it wouldn't be surprising if a penalty was slapped onto whichever player was burning the clock.</p></div>\n<div><p>“I-I look forward to our match.” Wearing an incredibly nervous expression, Mii-chan offered a slight bow from across.</p></div>\n<div><p>She was clutching her five cards tightly to her chest; naturally, from my seated position, the numbers facing her were completely hidden from view.</p></div>\n<div><p>“Likewise,” I replied evenly.</p></div>\n<div><p>Then, at the supervisor's signal, the eight matches began simultaneously.</p></div>\n<div><p>I didn't hesitate. I instantly pulled the ‘7’ from my hand and slapped it face down on the ground.</p></div>\n<div><p>“Th-That was fast,” Mii-chan stammered, clearly taken aback.</p></div>\n<div><p>“It's purely a game of luck, anyway. I'm just thinking we should get this over with quickly,” I replied smoothly.</p></div>\n<div><p>I could hear some of the other students already starting to chatter, trying to engage their opponents in conversational mind games to fish for tells within the allotted time. I had no intention of doing that.</p></div>\n<div><p>“R-Right... umm, umm, then I'll…”</p></div>\n<div><p>Based on Mii-chan's personality alone, it was impossible to deduce whether she would open with a weak card or come out swinging with a strong one. There simply wasn't enough data. However, knowing her timid nature, it was incredibly easy to predict exactly how my words and actions would influence her.</p></div>\n<div><p>By declaring right out of the gate that this was a game of pure luck and actively shutting down any attempt at conversational strategy, I forced her to subconsciously accept that she had to play the same way. Granted, she wasn't the type to excel at that kind of verbal sparring anyway, but my dismissal completely sealed her lips. Furthermore, because her opponent had played a card instantly, she was suddenly hit with a wave of mounting pressure to hurry up and match my pace.</p></div>\n<div><p>Her fingertips hovered hesitantly over her hand. But she couldn't afford to take her time.</p></div>\n<div><p>Her hand darted out, grabbing the card perfectly in the center of her fan and placing it face down.</p></div>\n<div><p>“I'll go with this one…”</p></div>\n<div><p>“Let's flip them, then.”</p></div>\n<div><p>“Y-Yes.”</p></div>\n<div><p>Without even pausing to ask if she wanted to swap her card, we executed our first round. We were the fastest out of all eight pairs by a massive margin. The sheer speed of our match was so jarring that it actually drew the attention of Shinohara and the others sitting nearby.</p></div>\n<div><p>The cards were revealed. Naturally, mine was the ‘7’. Mii-chan's was a ‘5’.</p></div>\n<div><p>“Ah―”</p></div>\n<div><p>“Let's move right to the next one,” I said, cutting off any emotional reaction to the win or loss.</p></div>\n<div><p>Now, I immediately set my ‘9’ card face down.</p></div>\n<div><p>Faced with my relentless pace, Mii-chan's thought process clearly short-circuited for a second.</p></div>\n<div><p>The moment I clinched the opening round by crushing her ‘5’ with my ‘7’, the tide of the entire match swung heavily in my favor. As long as my ‘9’ wasn't canceled out by a tie, my overall victory was mathematically guaranteed.</p></div>\n<div><p>Looking flustered, Mii-chan gave a small, nervous gulp before decisively slapping her next card face down on the ground.</p></div>\n<div><p>The moment her hand left the card, I snatched my ‘9’ back up, swapping it for a different card from my hand and setting it face down instead.</p></div>\n<div><p>“You're... changing it?” she blinked.</p></div>\n<div><p>“There's no rule saying I can't swap my card before we reveal,” I pointed out. “If you want to change yours, Mii-chan, you're more than welcome to.”</p></div>\n<div><p>“Eh? Umm... no, I'm fine with this…”</p></div>\n<div><p>“Let's flip them, then.”</p></div>\n<div><p>Having obtained mutual consent, we turned the cards over. My number was ‘1’. Mii-chan's was ‘9’.</p></div>\n<div><p>With that, we were tied at one win apiece. However, because she had just burned her strongest card, my victory was now entirely locked in the moment I played my ‘9’.</p></div>\n<div><p>“Auu... I lost,” Mii-chan realized, her shoulders slumping.</p></div>\n<div><p>“Let's just play the final round properly as a formality,” I said.</p></div>\n<div><p>“...Okay.”</p></div>\n<div><p>Before a completely frozen Mii-chan, I quickly placed my third card face down.</p></div>\n<div><p>Naturally, that number was ‘9’. The card Mii-chan despairingly revealed was her ‘7’.</p></div>\n<div><p>“We're finished,” I reported to the supervisor, my tone flat.</p></div>\n<div><p>At this point, most of the other pairs were still just finishing up their opening rounds.</p></div>\n<div><p>Right now, Mii-chan was probably lamenting her terrible luck, convinced that the game had just been an unfortunate turn of events.</p></div>\n<div><p>But that wasn't true at all.</p></div>\n<div><p>Precisely because the game was so mind-numbingly simple, it was incredibly easy to overlook a fatal flaw in the initial setup: the default structure of the hand.</p></div>\n<div><p>When the supervisor dealt the five cards, they were perfectly arranged in numerical order. From the exact second the cards were handed to Mii-chan, I had been watching exactly how she held them. If she had shuffled her hand, or hidden the cards behind her back to reorder them, keeping track of their locations would have become impossible. However, she had gripped the cards in her hand exactly as they were dealt.</p></div>\n<div><p>Under normal circumstances, once the match officially started, she probably would have unconsciously shuffled her hand out of habit. But by playing my card instantly and aggressively rushing her, I completely deleted the concept of ‘shuffling’ from her mind. By making her feel like rearranging her hand was pointless since her opponent was already waiting, I crushed her under the pressure to simply play a card <em>now.</em></p></div>\n<div><p>From there, the rest was practically automatic. Because I knew exactly where every number was in her hand, all I had to do was observe which card she pulled and swap my own card to guarantee the highest possible win rate. If she had managed to shake off the pressure in the second round and scrambled her hand, I would have simply pivoted my strategy to using conversation to fish for tells.</p></div>\n<div><p>It just so happened that this time, even that wasn't necessary.</p></div>\n<div><p>Shortly after our match concluded, the other pairs began to settle their games sequentially. While a few cases dragged into overtime, the final victors were Katsuragi, Morofuji, Minamikata, Ike, Amikura, Yoshida, and Sanada.</p></div>\n<div><p>Chapter 2 Ends. Join our Discord (<a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://discord.gg/v9kBpcCH2Y\">https://discord.gg/v9kBpcCH2Y</a>) to get information on release dates and to have fun with fellow cote fans!</p></div>",
    "5": "<div><p>At six-thirty on the second day, the sun crested over the island, signaling the arrival of morning.</p></div>\n<div><p>The light was still young, pale at the edges, filtering through the fabric of the tent in a muted glow. I woke to the faint sound of footsteps approaching through the quiet morning air, then slowly pushed myself upright.</p></div>\n<div><p>Beside me, Yoshida and Sanada were still asleep. Their breathing remained calm and even, completely undisturbed by the presence outside.</p></div>\n<div><p>Peering out of my tent, I found Katsuragi standing nearby.</p></div>\n<div><p>For a brief moment, a faint look of surprise crossed his face, as though he hadn't expected me to emerge so quickly. But he quickly composed himself and offered a brief greeting.</p></div>\n<div><p>“Good morning.”</p></div>\n<div><p>I returned the greeting and stepped out into the morning air.</p></div>\n<div><p>“Sorry,” Katsuragi said. “Did I wake you up?”</p></div>\n<div><p>“I was already awake.”</p></div>\n<div><p>“I see.” He paused briefly before continuing. “I hate to ask this first thing in the morning, but I’d like a little bit of your time. There’s something I want to discuss regarding this special exam before the second day’s assignments begin.”</p></div>\n<div><p>Whether he had spent the night reaching his own conclusions, or if Ryūen had fed him instructions behind the scenes, I couldn’t tell.</p></div>\n<div><p>Still, I nodded and quietly followed him. Once we were a safe distance away from the tents, Katsuragi stopped and turned to face me.</p></div>\n<div><p>“In this special exam, there are several penalties that carry the risk of expulsion,” he began. “Among them, the only one that absolutely cannot be avoided is the expulsion tied to finishing in last place. Even if every student were to tie, it still cannot be bypassed. However, depending on the circumstances, I'm sure you understand that it can be overcome rather easily, don’t you?”</p></div>\n<div><p>“A student with a Protection Point could become the scapegoat instead,” I said. “Assuming things work out cleanly enough to make that possible.”</p></div>\n<div><p>“That’s right.” Katsuragi gave a small nod. “If this were only a problem within a single class, self-sacrifice would be a highly viable strategy. But in a competition involving the entire grade, that kind of sacrifice could easily end up benefiting the enemy.”</p></div>\n<div><p>“If there’s anyone who’d self-sacrifice without caring whether it benefited allies or enemies, it would probably be someone from Ichinose’s class.”</p></div>\n<div><p>Hearing that, Katsuragi fell silent for a moment.</p></div>\n<div><p>“…Is there anyone in Ichinose’s class who has a protection point?”</p></div>\n<div><p>There were certain details that had not been disclosed to the other classes. Katsuragi slipped the question in casually, as though it were nothing more than a natural extension of the conversation.</p></div>\n<div><p>“Sorry, but I wouldn’t know,” I replied. “And even if I did, I wouldn’t tell you.”</p></div>\n<div><p>“…Fair enough.”</p></div>\n<div><p>The internal situation of Ichinose’s class wasn’t something I could casually discuss with a rivalling class.</p></div>\n<div><p>In truth, I had already confirmed that, at present, no one in Class D possessed a protection point, not even Ichinose. Unfortunately, that meant executing such a strategy was entirely off the table.</p></div>\n<div><p>“This is just my own speculation,” I continued, “but regardless of whether she has a protection point or not, I believe Ichinose will hold off on making a move until the bitter end. While she wouldn’t hesitate for a second if it meant protecting her own classmates, the current Ichinose isn’t about to extend that same courtesy to the other classes.”</p></div>\n<div><p>“If your prediction holds true,” Katsuragi mused, “then unless a student with a Protection Point coincidentally ends up at the bottom, there’s a very high chance someone gets expelled the day after tomorrow. And since nobody can see the total token counts across the entire grade, students will naturally focus less on token multipliers and more on simply avoiding last place within their own group.”</p></div>\n<div><p>That alone would become enough of a psychological anchor.</p></div>\n<div><p>If someone could confirm they possessed even slightly more tokens than another student, it would at least provide temporary reassurance.</p></div>\n<div><p>Of course, reality was nowhere near that simple.</p></div>\n<div><p>Unless you physically verified someone’s token count, certainty was impossible.</p></div>\n<div><p>Furthermore, since tokens could be freely transferred twenty-four hours a day, that underlying anxiety surrounding the rankings could never truly be dispelled.</p></div>\n<div><p>“So, what do you plan to do?” Katsuragi asked.</p></div>\n<div><p>“That’s a rather straightforward question,” I replied. “Are you really that curious about my next move?”</p></div>\n<div><p>“There’s only so much I can do,” Katsuragi said calmly. “I don’t want anyone from Class B getting expelled, but I can’t keep track of classmates outside my own group. So at the very least, I want to make sure nobody in the group I’m assigned to gets expelled.”</p></div>\n<div><p>Katsuragi wasn't the only one who felt that way. In fact, the vast majority of the student body likely shared his sentiment.</p></div>\n<div><p>Allowing an expulsion to emerge from your own group carried a heavy burden of collective responsibility. That’s why it was only natural to want to save those within one's reach.</p></div>\n<div><p>“The way you went after Ike and Shinohara yesterday…” Katsuragi continued. “Wasn’t there a reason behind that as well?”</p></div>\n<div><p>The way Katsuragi framed the question made it clear he didn't believe I had picked a fight for no reason, nor did he think my attitude was born from petty personal grievances.</p></div>\n<div><p>However, I gave a light shake of my head, brushing off his suspicions.</p></div>\n<div><p>“If that’s what you thought, then I'm afraid you’re overestimating me,” I said. “Those two and I simply don’t get along.”</p></div>\n<div><p>“Are you saying you provoked your own group members based on personal feelings?” Katsuragi frowned slightly. “That seems highly uncharacteristic of you. I always thought you were the calm and quiet type.”</p></div>\n<div><p>“Ike and the others said it too, didn’t they?” I replied. “That maybe I revealed my true colours after becoming the class leader.”</p></div>\n<div><p>Katsuragi fell silent for a moment, studying me.</p></div>\n<div><p>“…I find that rather hard to believe,” he said at last. “But fine.”</p></div>\n<div><p>Perhaps sensing that pressing any further wouldn't get him any closer to the truth, Katsuragi steered the conversation forward.</p></div>\n<div><p>“Whatever your true intentions may be, our fundamental priorities should still align. Neither of us wants to see our classmates expelled. With that as a given, surely there’s room for us to cooperate in certain areas?”</p></div>\n<div><p>“It’s true that as members of the same group, there are areas where we can work together,” I replied. “But on a fundamental level, your way of thinking about the penalties differs greatly from mine. Joining hands might prove difficult.”</p></div>\n<div><p>“Differs...?”</p></div>\n<div><p>“Katsuragi, your desire to avoid expulsions stems entirely from the fact that they’re your classmates.”</p></div>\n<div><p>I paused briefly before continuing.</p></div>\n<div><p>“But drawing an arbitrary line between your own class and the others misses the point entirely. The real question is whether or not a student actually has the value required to survive this special exam. Whether they’re a member of the same group or the same class is irrelevant. If they don’t measure up to that standard, then their expulsion is simply inevitable.”</p></div>\n<div><p>Katsuragi listened quietly before responding.</p></div>\n<div><p>“I won’t deny that logic,” he said. “But treating everyone with perfect objectivity is far easier said than done. Furthermore, prioritizing one’s allies is not wrong. Rather, it’s a completely natural instinct. That isn’t just a rule born of this special exam; if you look back through human history, you’ll find the exact same principle at work.”</p></div>\n<div><p>Whether they shared the same birthplace. The same race. The same nation.</p></div>\n<div><p>Humanity has always drawn a line somewhere. Once those boundaries were set, people fought with everything they had to protect those they deemed allies, and struck down those they recognized as enemies.</p></div>\n<div><p>“I’m not saying that you have to think the same way,” Katsuragi concluded. “But that is what I believe the natural order should be.”</p></div>\n<div><p>It wasn't about forcing a specific outcome upon anyone.</p></div>\n<div><p>Rather, within the natural framework of society itself, those destined to receive penalties would emerge on their own, and those unfit to remain would quietly disappear.</p></div>\n<div><p>“So then, are you saying you would be fine with a student from Class C finishing last and being expelled in this exam?” Katsuragi’s brow furrowed. “If that is the case, then perhaps our views on penalties really are different.”</p></div>\n<div><p>His voice remained calm.</p></div>\n<div><p>“But if you truly think that way, I have to say… I’m somewhat disappointed.”</p></div>\n<div><p>“Eliminating those who lack ability or who disrupt the harmony of the class often triggers a self-purifying effect,” I replied with ease. “Of course, I’m not saying every student expelled so far fell into that category. But at the same time Yamauchi, Sakura, and Maezono disappeared. And though it happened before you transferred, Manabe was cut from Ryuen’s class as well. While losing numbers puts a class at a disadvantage, looking at the bigger picture, it isn't entirely a net loss.”</p></div>\n<div><p>It wasn’t the kind of logic that would ever resonate with someone like Katsuragi, who sought to protect his comrades. Then again, very few people would ever enjoy hearing something so callous.</p></div>\n<div><p>“Sorry for taking up your time so early in the morning.”</p></div>\n<div><p>It was a brief exchange, lasting less than five minutes. Katsuragi gave a single, curt nod, offered a brief apology, and walked back to his tent, making no effort to hide his disappointment in me.</p></div>\n<div><p>By the time we separated, it was just past seven in the morning.</p></div>\n<div><p>After waiting a short while, I returned to Class C’s tent. Yoshida was already awake, busying himself outside the tent with breakfast preparations. Sanada was up as well, working on some chores a short distance away.</p></div>\n<div><p>“Looks like you and Katsuragi were talking for quite a while, huh?” Yoshida remarked.</p></div>\n<div><p>“You noticed?”</p></div>\n<div><p>“After you left the tent, I heard Katsuragi’s voice for a bit,” he said. “I was curious, but I figured it’d be rude to interrupt. Was it about the special exam?”</p></div>\n<div><p>Since he already knew I had gone outside to talk, there was probably no need to hide it.</p></div>\n<div><p>“He asked whether we could cooperate to prevent expulsions from our classes.”</p></div>\n<div><p>“So, are you planning to team up with Class B?”</p></div>\n<div><p>There was no approval or objection in Yoshida’s voice. He simply seemed interested in what decision I would make as the leader.</p></div>\n<div><p>“Unfortunately, the negotiation broke down,” I said. “This isn’t a problem that can be solved between two classes alone anyway. Still, on this second day, we may start seeing movements in various places as people attempt for that kind of cooperation.”</p></div>\n<div><p>“Then we’d better keep our eyes peeled.”</p></div>\n<div><p>Yoshida’s expression hardened as he cast a wary, sweeping glance toward the tents of the other classes.</p></div>\n<div><h2>Part 1</h2></div>\n<div><p>Shortly after finishing breakfast with Yoshida and the others, the supervisor’s instructions echoed across the campsite.</p></div>\n<div><p>“Now then, I would like to announce the first task of the day. You will be taking on a large number of tasks starting this morning, so please remain focused and approach them with care.”</p></div>\n<div><p>Retrieving four tablets, he distributed one to each class representative.</p></div>\n<div><p>“For this ‘Team’ task, four classes will compete in a simple academic test, taking turns using a tablet. The order in which the four members of each team take the test is completely random. First place will receive 3 tokens, second place 2 tokens, third place 1 token, and fourth place will receive no reward.”</p></div>\n<div><p>With that preface complete, the supervisor started announcing details.</p></div>\n<div><p>If all four members of a class won their rounds, the class could earn twelve tokens. On the other hand, if all four finished last, they would walk away with nothing.</p></div>\n<div><p>There was no direct risk attached to the task. Even so, it was the kind of test that could create subtle disparities in the number of tokens held by each class.</p></div>\n<div><p>The important thing was the order in which we tackled the test. Rather than having top-tier students clash head-to-head, the ideal scenario was to be paired against opponents you could edge out by a narrow margin. For our Class C lineup, the randomized order fell to Morishita, Sanada, Yoshida, and myself.</p></div>\n<div><p>True to the supervisor’s word, the format was remarkably simple. Each round consisted of ten multiple-choice questions with five possible answers, drawn from a specific subject. If two or more students had the same number of correct answers, their ranking would be decided by the time taken to complete all ten questions.</p></div>\n<div><p>Morishita placed third in her round, and Sanada took first in his. Yoshida went next, but his opponents were Katsuragi, Mii-chan, and Amikura. With that lineup, he ended in fourth place. Finally, I anchored the group and secured a first-place finish.</p></div>\n<div><p>In total, Class C walked away with seven tokens. Over in Class A, despite Ike and Shinohara finishing dead last in their respective rounds, Kushida and Mii-chan were blessed with favorable matchups and both secured first place, bringing their total to six tokens. Class B earned five, while Class D matched Class A with six.</p></div>\n<div><p>All things considered, the opening task had produced almost no significant difference between the classes.</p></div>\n<div><p>“The gap didn’t widen nearly as much as I expected,” Yoshida muttered.</p></div>\n<div><p>He was right. As a single task, the difference amounted to only one or two tokens, well within the margin of error.</p></div>\n<div><p>However, judging from how smoothly the first task had been carried out, it was unlikely that things would end with just this.</p></div>\n<div><p>“Now then, we will move on to the next task. The order will once again be randomized.”</p></div>\n<div><p>The supervisor announced that the subject would change, and there on the uninhabited island, we once again turned toward the tablets.</p></div>\n<div><p>In total, we repeated the same process five times.</p></div>\n<div><p>At first, the results had been separated by only narrow margins. But as luck and ability began to show their uneven distribution, the scores gradually converged toward what could be called their natural expected values.</p></div>\n<div><p>From the second round onward, the tasks proceeded without changing format, but their underlying nature had certainly transformed. While the luck of the matchups and coincidence had influenced the results in the first round, as the rounds repeated, those elements were gradually filtered out, allowing each individual's pure academic and processing abilities to manifest directly as their rankings.</p></div>\n<div><p>The simple structure of ten multiple-choice questions stripped away any room for bluffing.</p></div>\n<div><p>Since ties in correct answers were decided by time, nearly perfect scores became the standard among the top students. Ultimately, the deciding factor became how efficiently one could process the questions without wasting time.</p></div>\n<div><p>The lack of hesitation, the speed of grasping the question's intent, and the accuracy in eliminating options. A slight delay in any one of those areas alone was enough to make someone fall one or even two ranks lower.</p></div>\n<div><p>Among all of them, the two who consistently remained near the top were Sanada and Katsuragi.</p></div>\n<div><p>Sanada was consistent from beginning to end. No matter what kind of question appeared before him, his judgment never dulled.</p></div>\n<div><p>The efficiency with which he operated made it seem as though his answer had already been decided the instant he finished reading the question, placing him far above the others in balancing speed and precision.</p></div>\n<div><p>Katsuragi, meanwhile, approached the competition differently.</p></div>\n<div><p>Rather than securing a perfect score, he prioritized staying firmly in the upper ranks. By dedicating time only to the necessary portions, he optimized his overall processing. As a result, he displayed great strength in time-based tie-breakers and made remarkably few mistakes.</p></div>\n<div><p>Just beneath those two, another layer of students gradually began to emerge:</p></div>\n<div><p>Mii-chan and Kushida.</p></div>\n<div><p>Neither possessed blistering speed, but they rarely misread a question. Their unshakeable grasp of the fundamentals ensured they never suffered any major collapses.</p></div>\n<div><p>Kushida finished last in the second round, but from the middle stages onward, she regained her balance. Once her rhythm returned, she began steadily stacking up correct answers, one after another.</p></div>\n<div><p>Mii-chan, meanwhile, progressed through the problems at the same rhythm throughout, leading to minimal fluctuations in her ranking, fulfilling a role where she steadily picked up 2nd and 3rd place finishes.</p></div>\n<div><p>In a prolonged competition like this, the existence of students who simply remained consistent and didn’t make mistakes translated directly into a steady accumulation of tokens.</p></div>\n<div><p>Of course, not everyone adapted so smoothly.</p></div>\n<div><p>As the rounds continued, the faces repeatedly settling near the bottom also became increasingly clear.</p></div>\n<div><p>Among them, Ibuki’s decline stood out the most.</p></div>\n<div><p>The questions themselves weren’t exceptionally difficult.</p></div>\n<div><p>Even so, Ibuki had a terrible habit of abandoning a problem before fully grasping its intent. The moment her understanding faltered, she'd simply give up and select an answer, practically leaving the outcome to chance.</p></div>\n<div><p>At first glance, that kind of decision-making might have looked efficient. It certainly allowed her to move quickly. But without any solid reasoning backing her choices, her results were inherently unstable.</p></div>\n<div><p>While she occasionally managed to scrape together a correct answer by sheer fluke, those fleeting moments of luck didn’t continue. As the rounds piled up, probability smoothed out the fluctuations, and her ranking naturally drifted to the bottom.</p></div>\n<div><p>It wasn't a temporary stroke of bad luck, but rather the consequence of her deeply flawed approach.</p></div>\n<div><p>What came as a mild surprise was the performance of Ike and Shinohara, two students who similarly struggled with academics.</p></div>\n<div><p>Contrary to initial expectations, they didn't throw in the towel on the questions, maintaining their stance of trying to get as close to the correct answer as possible within their limited knowledge. They scrutinized the options one by one, and while hesitating, attached reasoning to narrow down their answers. Their process could by no means be called efficient, and there were many moments where they needed time to make a decision, but at the very least, they did not abandon thinking.</p></div>\n<div><p>Unfortunately, their earnest effort didn't directly translate into favorable results. They simply couldn't bridge the gap left by their lack of foundational knowledge, which put a hard ceiling on their total correct answers. Furthermore, their extreme caution severely inflated their completion times, putting them at a massive disadvantage whenever a tie-breaker occurred.</p></div>\n<div><p>Consequently, they remained firmly entrenched in the lower ranks. While they rarely sank to dead last like Ibuki, they could never quite manage to break out of the bottom two or three spots.</p></div>\n<div><p>By the time all five trials had concluded, a gradual yet undeniable gap in the token counts had emerged between the classes.</p></div>\n<div><p>In the first round, differences of one or two places had been no more than margins of error. But with each repetition, those small differences accumulated. Eventually, they turned into a gap that could no longer be ignored.</p></div>\n<div><p>The divide wasn't overwhelmingly dramatic, but that was precisely what made it so difficult to overturn. More than anything, it was a perfectly accurate reflection of genuine ability.</p></div>\n<div><p>In other words, success here wasn’t determined by one standalone win, but by who could keep performing under pressure and produce results consistently.</p></div>\n<div><p>It ultimately boiled down to one single metric: the fundamental ability of the students.</p></div>\n<div><p>And those who failed to meet that standard were quietly and inevitably left behind.</p></div>\n<div><h2>Part 2</h2></div>\n<div><p>Up until now, the uninhabited island exam had been a primarily physical ordeal. Following this abrupt shift to intense mental exertion, the exhausted students simply collapsed right where they stood the moment a break was called.</p></div>\n<div><p>Unlike the sharp, burning ache of physical fatigue, this prolonged mental strain left a dull, lingering heaviness in the back of their minds. Unable to immediately shift gears and plan their next move, everyone simply surrendered to the brief, heavy silence.</p></div>\n<div><p>During this respite, the students naturally gravitated toward their own classmates, keeping a wary distance from the other groups. The class representatives then began the meticulous work of distributing the tokens earned from the tasks, adhering to their own pre-established rules.</p></div>\n<div><p>Our Class C was no exception.</p></div>\n<div><p>I took our total earnings and divided them by four, handing out the respective shares to Yoshida, Morishita, and Sanada. I intentionally opted for a completely even split, choosing not to stagger the distribution based on individual performance.</p></div>\n<div><p>“Ike keeps glancing over here,” Yoshida muttered.</p></div>\n<div><p>“Don’t worry about it,” I replied. “It isn’t just us. He’s curious about all three classes.”</p></div>\n<div><p>After all, the distribution of tokens was far more than a simple payout of rewards. It was a display of one's contributions laid bare as a numerical value. Naturally, people couldn't help but unconsciously fixate on the shares their peers were taking home.</p></div>\n<div><p>“It is a battle against the fear of ending up last, after all,” Sanada said.</p></div>\n<div><p>Perhaps his lenses had become dirty, as he quietly removed his glasses and wiped them with the edge of his shirt.</p></div>\n<div><p>“I have no idea who’s getting how many tokens,” Yoshida said after checking the amount he had been given. His eyes drifted, casually toward the other three classes. “Even looking at it by class, it’s getting harder to tell how much of a gap has opened up.”</p></div>\n<div><p>Since most of our focus had been devoted entirely to the tests themselves, it wasn’t surprising that nobody had perfectly tracked who placed where in every round.</p></div>\n<div><p>“I’m starting to feel a little anxious myself,” Morishita said. “Please give me five extra tokens for emotional stability.”</p></div>\n<div><p>I decided to ignore her unreasonable demand.</p></div>\n<div><p>More than the rankings themselves, what lingered in everyone’s minds were fragmented impressions and half-seen results. People tried piecing those fragments together to grasp the larger picture, but there simply wasn’t enough information to arrive at certainty. And that looming ambiguity only fanned the flames of everyone's anxiety.</p></div>\n<div><p>“Katsuragi-kun, Wang-san, and Kushida-san all seemed to be steadily taking higher places,” Sanada said. “So if we look at it by class, there may not actually be as much of a gap as we think.”</p></div>\n<div><p>Sanada, who had a clearer grasp of the situation than Yoshida, answered with calm precision.</p></div>\n<div><p>His words merely traced the facts. Even so, there was more behind them. On one hand, they carried the reassurance that, at this moment, no decisive gap had yet formed. On the other, they implied that precisely because things remained close, the next move could cause everything to shift at once.</p></div>\n<div><p>Of course, it was true that the gaps between classes were widening little by little.</p></div>\n<div><p>But each task offered only a limited number of tokens, so the difference had not yet opened dramatically. That much was also true.</p></div>\n<div><p>However, that applied only when looking at the whole. When viewing the results by team.</p></div>\n<div><p>Since each individual’s performance appeared directly as numbers, the situation within each class was different. Even among classmates, differences had begun to spread quietly, but surely.</p></div>\n<div><p>If we turned our attention to the individual level, the gaps were probably reaching the point where they would begin to widen faster than expected.</p></div>\n<div><p>“Wait a second!” Ibuki’s voice suddenly cut through the break. “What do you mean I only get two?!”</p></div>\n<div><p>Under normal circumstances, the exact number of tokens someone received was not information that should be allowed to leak to other classes. It was strategic data, the kind of thing better kept hidden.</p></div>\n<div><p>But in a class where distribution itself was based on comparing individual contributions, complete secrecy was rather difficult to maintain. And when the result was one a student could not accept, dissatisfaction had a way of spilling out before anyone could contain it.</p></div>\n<div><p>Ibuki, furious, seemed to have no thought at all for the information she was exposing. She rounded on Katsuragi and began shouting loudly enough for everyone nearby to hear.</p></div>\n<div><p>Her emotions had overtaken her. Profit, loss, risk, none of that seemed to matter in the moment. The only thing driving her actions was the fact that she could not accept the result.</p></div>\n<div><p>“I told you from the very beginning,” Katsuragi replied firmly. “Tokens would be distributed fairly, based on your performance. The tasks thus far have centered entirely around academics, which is your weak point, and you significantly dragged us down. You finished last every time. If anything, I could say I judged you leniently by giving you a reward at all.”</p></div>\n<div><p>His words contained no visible emotion. But for that very reason, they allowed no ambiguity. Katsuragi did not try to soften the truth or dress it in comfort. He simply placed the facts before her and, by doing so, closed off any room for rebuttal.</p></div>\n<div><p>The remaining two members of Class B seemed to have no objection to his reasoning. If anything, they appeared to agree.</p></div>\n<div><p>As long as the standard for distribution was clear, introducing personal feelings into it would only create the possibility that they themselves might be disadvantaged later. There was no reason for them to deny Katsuragi here.</p></div>\n<div><p>They had seen it themselves. Ibuki had finished last in every round.</p></div>\n<div><p>In other words, the number of tokens Ibuki had personally earned was zero. From that perspective, giving her even two tokens could only be described as Katsuragi’s generosity.</p></div>\n<div><p>\"Are you trying to make me come in last or something?\" Ibuki snapped.</p></div>\n<div><p>“Don’t be ridiculous,” Katsuragi replied. “I have not the slightest desire to see anyone from our class expelled. However, if I distributed tokens equally even to a student who dragged us down, I would be causing trouble for Sonoda and Morofuji.”</p></div>\n<div><p>His gaze remained steady.</p></div>\n<div><p>“This is a special exam where expulsion is at stake. I absolutely cannot endanger those two with an unfair judgement.”</p></div>\n<div><p>For Katsuragi, too, this was a bitter decision. That was the part he emphasized.</p></div>\n<div><p>To protect someone, another person had to swallow their dissatisfaction.</p></div>\n<div><p>That structure remained constant throughout the entire exam. This situation was no exception.</p></div>\n<div><p>“Then…” Ibuki said, her voice lower now, though the anger had not disappeared. “If I actually contribute properly, you’ll give me more, right?”</p></div>\n<div><p>“Of course.”</p></div>\n<div><p>Katsuragi answered without the slightest hesitation.</p></div>\n<div><p>Ibuki clicked her tongue sharply, then turned and walked away.</p></div>\n<div><p>Her back showed her dissatisfaction and frustration plainly. But at the same time, she understood the reality in front of her. If she wanted to overturn Katsuragi’s judgment, words would not be enough.</p></div>\n<div><p>She would have to do it by producing results.</p></div>\n<div><h2>Part 3</h2></div>\n<div><p>The sun was already high overhead, and the air across the island was beginning to feel humid.</p></div>\n<div><p>The clock had only just passed nine in the morning, yet the quiet hours of dawn already felt strangely distant.</p></div>\n<div><p>A breeze slipped through the gaps between the trees, brushing faintly against our sweat-damp skin. Under normal circumstances, the sensation might have been pleasant. Now, it only seemed like one more thing dulling the mind.</p></div>\n<div><p>After so many mentally demanding assignments in a row, everyone’s concentration had clearly been worn thin. The brief silence before the next physical task felt stretched out far longer than it actually was.</p></div>\n<div><p>Nobody could fully relax while waiting for the next task, and everyone remained where they were carrying an awkward lingering tension.</p></div>\n<div><p>“From this point onward,” Urushibara announced, “you will be taking on several physically oriented tasks.”</p></div>\n<div><p>The atmosphere among certain students visibly lightened. After being forced through round after round of mental battles, the prospect of a physical challenge offered relief to those who had been bottling up frustration.</p></div>\n<div><p>For anyone who had fallen behind in academic contests, this was finally their chance to show what they were truly capable of.</p></div>\n<div><p>“This will also be a Team task,” Urushibara continued. “Each class will form pairs of two. Just like before, the pairs will be selected randomly by us. This task will test your core strength. The pair that can stand on one leg the longest without putting a foot down will win. The class with the first-place pair will receive ten tokens, second place will receive five, and third place will receive three. The class with the last-place pair will have two tokens withdrawn from their representative.”</p></div>\n<div><p>The rules were simple enough.</p></div>\n<div><p>If either member of a pair placed both feet on the ground, that pair lost.</p></div>\n<div><p>It was classified as a physical challenge, but there was room for strategy. As long as one foot remained raised, students were apparently allowed to hold hands, link shoulders, or use whatever method they preferred. The details were left to each pair.</p></div>\n<div><p>At a glance, it looked like a straightforward test of physical endurance.</p></div>\n<div><p>However, it demanded compatibility and coordination between partners.</p></div>\n<div><p>Individual ability alone wouldn’t be enough. Victory would depend on whether each pair could adjust to the other’s condition and distribute the strain properly.</p></div>\n<div><p>“Huh? Pairs? Why isn't it individual...?”</p></div>\n<div><p>For someone as confident in her physical ability as Ibuki, being forced to cooperate with another person was a clear disadvantage.</p></div>\n<div><p>Depending on her partner, she might end up carrying a heavy burden, or worse, being dragged down entirely.</p></div>\n<div><p>It was only natural that she wasn’t pleased.</p></div>\n<div><p>The more confident someone was in winning alone, the more they hated uncertain variables like other people.</p></div>\n<div><p>For Ibuki, this kind of cooperation was less an advantage than a restriction.</p></div>\n<div><p>Meanwhile, I was paired with Sanada, and Yoshida ended up with Morishita.</p></div>\n<div><p>Considering Sanada’s build, his higher center of gravity, and the likely limits of his endurance, trying to support each other evenly would be unwise. The most stable approach would be for me to serve as the axis while absorbing as much of the strain as possible.</p></div>\n<div><p>Ibuki, who had already been muttering complaints, made no attempt to hide her disappointment and anger once she learned that Morofuji would be her partner.</p></div>\n<div><p>Given Morofuji’s temperament, it was obvious that any emotional instability would directly affect her posture.</p></div>\n<div><p>For Ibuki, it was probably one of the pairings she least wanted to draw.</p></div>\n<div><p>“So, what would be the optimal approach here?” Sanada asked. “There’s a bit of a height difference between us, so linking shoulders seems like it would throw off our balance… Also, to tell you the truth, I’m not very confident.”</p></div>\n<div><p>If the rules allowed one person to drop out while the other continued, then the best strategy would simply be for me to stand alone.</p></div>\n<div><p>In fact, I’d prefer not to have unnecessary support or cooperation at all.</p></div>\n<div><p>But if Sanada went down, I’d automatically be eliminated with him.</p></div>\n<div><p>Since there was no point in only one of us remaining, everything came down to how we designed the load distribution.</p></div>\n<div><p>“We should avoid clinging too tightly to each other,” I said. “That kind of strategy only works when both people are at high risk of falling.”</p></div>\n<div><p>“So you’re confident in standing on one leg?”</p></div>\n<div><p>“More or less.”</p></div>\n<div><p>I shifted my weight lightly.</p></div>\n<div><p>“Think of me as an object fixed in place, like a tree. Do whatever you need to stay balanced on one leg for even a second longer.”</p></div>\n<div><p>“You mean I can hold on or lean against you however I like… Are you sure?”</p></div>\n<div><p>“Yeah. As a pair, that’s probably the optimal solution available to us.”</p></div>\n<div><p>By taking on Sanada’s burden myself, we could extend our total endurance.</p></div>\n<div><p>It was a setup to prevent a collapse in the long term, rather than seeking short-term stability.</p></div>\n<div><p>“Now then,” Urushibara called. “We will begin the task. Ready— start.”</p></div>\n<div><p>At the supervisor’s signal, all sixteen students lifted one foot into the air at once.</p></div>\n<div><p>While everyone moved at the same time, the real differences wouldn’t reveal themselves immediately. The question was how long each pair could hold out.</p></div>\n<div><p>At the start, there was no major gap between any of the pairs. Some supported each other. Some kept their distance. Some rested their weight against each other’s shoulders. Their chosen methods differed, but none of their postures looked fragile enough to fall apart right away.</p></div>\n<div><p>The real problem lay beyond that. After several dozen seconds, or once the first minute passed, the tiniest distortions in posture would begin to accumulate.</p></div>\n<div><p>Those distortions wouldn’t be large enough to be noticed at a glance, but they would definitely become the seeds leading to a collapse. If they failed to correct their posture in time, a chain reaction would send them tumbling to the ground.</p></div>\n<div><p>The strain concentrated in the supporting leg increased steadily with every passing second.</p></div>\n<div><p>The sensation of the sole against the ground began to blur. The ankle, which had been quietly making tiny adjustments, could no longer fully suppress the tremors.</p></div>\n<div><p>The balance they had initially maintained through conscious effort eventually gave way, plunging them into a desperate, agonizing struggle just to stay upright.</p></div>\n<div><p>The transition from merely maintaining a pose to desperately enduring it. How quickly a student could adapt to that shift would dictate how long they could survive.</p></div>\n<div><p>“S-sorry, Kikyō-chan,” Ike said, “You know… we kind of ended up pressed close together like this.”</p></div>\n<div><p>Whether it was for the tokens, or because the task had given him a legitimate excuse to press close to her, Ike tried his best to sound calm.</p></div>\n<div><p>His voice betrayed him anyway. An unmistakable pitch of excitement had already slipped into it.</p></div>\n<div><p>Under the pretext of maintaining their posture, Ike’s shoulder touched Kushida’s. It was obvious that he was far too conscious of the sensation carried through that contact, and of the distance, or lack of it, between them. His eyes weren’t focused on the task in front of him either. They kept drifting toward Kushida beside him.</p></div>\n<div><p>The moment his attention had strayed from where it ought to be, the risk had already taken root.</p></div>\n<div><p>The problem was that Ike himself didn’t realize it.</p></div>\n<div><p>“That bastard Ike…” Yoshida muttered beside me while struggling together with Morishita. “Honestly, I’m kind of jealous…”</p></div>\n<div><p>Perhaps he had imagined himself paired with Shiraishi, the girl he had his eye on. Or perhaps he simply couldn’t stand the fact that Ike had been paired with a cute girl at all.</p></div>\n<div><p>“You’re legally allowed to touch my body right now, you know,” Morishita said. “Deep down, you are actually thrilled about it, aren’t you?”</p></div>\n<div><p>“Who the hell would be thrilled, idiot?!”</p></div>\n<div><p>His denial came out too forcefully.</p></div>\n<div><p>Whether that brief outburst disrupted his core or threw off his focus, Yoshida’s balance faltered. Morishita, dragged along by the movement, ended up putting her foot down as a result.</p></div>\n<div><p>They were eliminated.</p></div>\n<div><p>But perhaps realizing that raising their voices might disturb Sanada, who was still fighting to hold on, both of them immediately sealed their mouths shut.</p></div>\n<div><p>A single reaction from the losers could break the concentration of those still remaining. Their silence came from understanding that much.</p></div>\n<div><p>Kushida, meanwhile, showed no sign of rejecting Ike’s behavior. Nor did she give him any special encouragement.</p></div>\n<div><p>She simply smiled naturally, treating the closeness as nothing more than part of the cooperation required for the task.</p></div>\n<div><p>Her sense of distance was exquisite. Not too close and not too far. She maintained a position that allowed the other person to mistake it for permission. He was not being rejected at least. That alone was enough for someone like Ike to interpret the situation positively, and perhaps that thought accelerated his awareness of her even further.</p></div>\n<div><p>He nearly lost his balance for a moment, but somehow managed to recover.</p></div>\n<div><p>“Uwooooh! I'm not done yet!”</p></div>\n<div><p>Shinohara, who was paired with Mii-chan, glared sharply at Ike as he got carried away. But perhaps because she had no room to carelessly call out to him, she remained silent.</p></div>\n<div><p>Even so, her gaze carried unmistakable emotion.</p></div>\n<div><p>She was desperately enduring, trying not to lose her balance, yet part of her attention remained fixed on Ike and Kushida. She should not have had any spare room to be distracted by something unnecessary, but the sight in her field of vision was impossible for her to ignore.</p></div>\n<div><p>As a result, subtle disturbances began creeping into Shinohara’s posture.</p></div>\n<div><p>She tried to correct it, but Mii-chan was pulled along as well, her own concentration chipped away by the movement. The situation grew increasingly difficult for both of them.</p></div>\n<div><p>As long as they were a pair, one person’s instability would inevitably spread to the other.</p></div>\n<div><p>Here too, the very burden they shared became their weakness.</p></div>\n<div><p>Unaware of the strain those two were suffering through, Ike kept his arm around Kushida’s shoulder and whispered near her ear.</p></div>\n<div><p>“Heh… Maybe we’re actually more compatible than I thought.”</p></div>\n<div><p>“Mm, maybe so,” Kushida replied with a soft smile. “You’re really good at this, Ike-kun, so that helps a lot. Let’s keep going as long as we can.”</p></div>\n<div><p>“O-of course. I’ll keep going… even one second longer…!”</p></div>\n<div><p>A single compliment was enough to warp his concentration even further.</p></div>\n<div><p>What he needed to maintain was his posture, but his attention had already been pulled somewhere else entirely.</p></div>\n<div><p>One minute passed then two.</p></div>\n<div><p>A one-legged stance that would never last long alone was being prolonged through cooperation between partners.</p></div>\n<div><p>From this point onward, it was no longer a contest of stamina, but of how long they could postpone collapse.</p></div>\n<div><p>Still, standing on one leg was never something the human body could maintain indefinitely. Even with mutual support, the time gained wasn’t dramatic. As the three-minute mark approached, one pair fell. Then another.</p></div>\n<div><p>Limits did not arrive equally for everyone. The moment of collapse in a person came suddenly and often chained down the other one as well.</p></div>\n<div><p>The next pair to fall was, as expected, Shinohara and Mii-chan.</p></div>\n<div><p>The instant one of them lost balance, that tremor propagated directly to the partner, and they collapsed in a chain reaction without any room to correct it. The choice to support each other was effective, but at the same time, it carried the risk of falling together.</p></div>\n<div><p>Conversely, pairs that kept too much distance soon began to drop out as well. Relying on individual stability alone made the opening moments easier, but as time passed, the burden of standing alone accumulated. Once one person reached their limit, if support did not arrive in time, the end came immediately.</p></div>\n<div><p>The remaining pairs all occupied the space between those extremes.</p></div>\n<div><p>They didn't completely support each other, nor were they completely independent. They only made contact and distributed the load when necessary. Whether or not they could make those adjustments became the difference here.</p></div>\n<div><p>“Get it together,” Ibuki snapped. “Don’t you dare put your foot down until I say it’s okay. We’re absolutely winning this!”</p></div>\n<div><p>In contrast to Ibuki’s fierce determination, Morofuji’s face was already twisted in pain.</p></div>\n<div><p>“This is… actually really tough…”</p></div>\n<div><p>Mental pressure and physical exhaustion were hitting her at the same time.</p></div>\n<div><p>Sanada, who was gripping onto me, was in a similar state. The strain on the sole and ankle of his supporting right foot had clearly become too much to bear, and little by little, more of his weight began shifting onto me.</p></div>\n<div><p>“Sorry,” Sanada said, his voice strained. “I think this is starting to get a little hard for me too…”</p></div>\n<div><p>“Just hold out as long as you can.”</p></div>\n<div><p>“But Ayanokōji-kun…” His small tremors had begun to increase. “Are you still all right?”</p></div>\n<div><p>I answered only with a slight glance.</p></div>\n<div><p>Of course, supporting an unstable Sanada meant I could not continue indefinitely either. No matter how steady I kept myself, absorbing another person’s shifting weight would eventually consume stamina.</p></div>\n<div><p>The pairs still holding on were Ibuki and Morofuji, and Amikura and Minamikata.</p></div>\n<div><p>Third place wouldn’t have been a bad result, but this was probably the moment to make a move. If there was a chance to raise our ranking by even one place, it was worth taking.</p></div>\n<div><p>The question was how to make that happen.</p></div>\n<div><p>“Morofuji.”</p></div>\n<div><p>I deliberately called out her name.</p></div>\n<div><p>There was no rule forbidding students from speaking while standing on one leg.</p></div>\n<div><p>The moment she heard her name, Morofuji’s shoulders jolted, and her gaze, until then fixed desperately on her footing, snapped toward me.</p></div>\n<div><p>All I needed was to divert her attention.</p></div>\n<div><p>That alone was enough to disrupt balance.</p></div>\n<div><p>“W-ww-what?”</p></div>\n<div><p>The fear Morofuji had carried toward me ever since our group first formed was still there.</p></div>\n<div><p>I said nothing more. Instead, I simply held her gaze and continued staring directly into her eyes.</p></div>\n<div><p>She seemed to have a strong sense of discomfort around me, that was enough.</p></div>\n<div><p>Fear, by itself, places a burden on both mind and body.</p></div>\n<div><p>And what she was supporting now wasn’t only physical weight.</p></div>\n<div><p>“H-hey, Morofuji, you’re wobbling!” Ibuki snapped.</p></div>\n<div><p>Ibuki herself still had some room to spare. But once her partner’s core began to collapse, the burden on her increased sharply. A disturbance on one side led directly to collapse.</p></div>\n<div><p>Meanwhile, Sanada no longer had the room to pay attention to an opponent’s movements.</p></div>\n<div><p>“Why is this so tough...ugh…”</p></div>\n<div><p>The surrounding noise no longer seemed to reach him. His awareness had turned inward, toward the battle with his own body.</p></div>\n<div><p>Core strength mattered, but the calves and ankles bore more strain than most people imagined. In an extreme state, outside information was discarded. Only the battle within remained.</p></div>\n<div><p>Sanada’s weight gradually leaned toward me.</p></div>\n<div><p>Each time it did, I used a small amount of strength to correct it. A slight adjustment of the shoulder. A minor shift through the hip. A quiet compensation through the leg acting as my axis.</p></div>\n<div><p>None of it was large on its own.</p></div>\n<div><p>But the accumulation of those small corrections rapidly whittled away at my physical strength. The limit of an individual.</p></div>\n<div><p>Before long, Sanada reached his limit and put his foot down.</p></div>\n<div><p>Fortunately, Morofuji had done the same just moments earlier.</p></div>\n<div><p>Thanks to that, we managed to slip into second place.</p></div>",
    "6": "<div><img alt=\"Chapter Image\" width=\"600\" height=\"800\" src=\"/assets/shiinamashiro.webp\"><span></span></div>\n<div><p>It was eleven in the morning.</p></div>\n<div><p>High above the decks of the passenger ship, where the sea breeze softened against glass walls and the sunlight spilled cleanly across the water, lay a completely secluded private pool.</p></div>\n<div><p>Appearing a little ahead of the appointed time, there was Amasawa Ichika of Class 2-A. </p></div>\n<div><p>Already changed into her swimsuit, she stepped out into the deserted oasis.</p></div>\n<div><p>“Being in a private rental really does feel special~” she said, her voice bright and teasing as she glanced around the empty poolside. “You're seriously footing the bill for this, right, Nanase-chan?”</p></div>\n<div><p>Arriving at the pool just a step behind her was Class 2-D’s Nanase Tsubasa.</p></div>\n<div><p>“Yes,” Nanase replied with her usual composure. “Since I was the one who selfishly called you out here today, please do not worry about the expense.”</p></div>\n<div><p>Nanase had booked the private pool for a sixty-minute block. With another student scheduled to take over right at noon, their time here was strictly limited.</p></div>\n<div><p>“This place was twenty thousand points last year, but now it costs twenty-five thousand, doesn't it? It's hilarious how the rental fee just casually went up. Looks like the wave of inflation has even reached us out here~”</p></div>\n<div><p>But the clock was ticking, even as they made small talk. Amasawa immediately claimed a lounge chair and snatched up a menu.</p></div>\n<div><p>“I'm totally ordering something expensive,” she hummed, tapping her index finger against the glossy pictures as she pondered her options.</p></div>\n<div><p>“Please, order whatever you like,” Nanase replied. “Though, from the standpoint of preventing food waste, I ask that you try not to leave any leftovers.”</p></div>\n<div><p>“So <em>that's </em>what you're worried about. Must mean you have plenty of Private Points saved up, nya?”</p></div>\n<div><p>“Not necessarily. I am simply a saver by nature,” Nanase answered with cool indifference.</p></div>\n<div><p>Hearing this, Amasawa narrowed her eyes in a sly smile.</p></div>\n<div><p>“In that case, you must have paid for all this because you decided a little private time with me was worth the splurge.”</p></div>\n<div><p>Keeping her gaze glued strictly to the menu, Amasawa casually guided the conversation forward.</p></div>\n<div><p>“That is correct.” Nanase said. “I intend to make our time together worthwhile.”</p></div>\n<div><p>Intentionally avoiding Nanase's expression, Amasawa gave a small nod and snapped the menu shut with a definitive <em>thwack.</em></p></div>\n<div><p>“I think I'll go with a melon cream soda! What about you, Nanase-chan?”</p></div>\n<div><p>She held the menu out to Nanase, who accepted it only to place it back onto the table unopened.</p></div>\n<div><p>“I am fine, thank you.”</p></div>\n<div><p>“Hmm, really? Well, suit yourself~”</p></div>\n<div><p>After casually placing the order for her melon cream soda, Amasawa turned her attention back to the girl standing beside her. Slowly, deliberately, she let her eyes roam up and down the length of Nanase's body, her appraising gaze trailing over her as if licking her from head to toe.</p></div>\n<div><p>Nanase’s face remained a completely blank slate. Betraying neither anger nor amusement, she kept her true feelings perfectly concealed behind an emotionless facade.</p></div>\n<div><p>Driven by an irresistible urge to peel that mask away, Amasawa lowered her gaze.</p></div>\n<div><p>“But seriously, Nanase-chan, haven’t you grown another cup size this past year?” Amasawa teased. “I think I’ve developed pretty well myself, but... it looks like you've got me beat~”</p></div>\n<div><p>“That is sexual harassment.”</p></div>\n<div><p>“Oh, come on. It’s your fault for having the kind of body that is just asking for it~”</p></div>\n<div><p>“Under normal circumstances, that would be an unforgivable statement,” Nanase replied coldly. “I do not believe I am at fault in the slightest.”</p></div>\n<div><p>An ordinary high school girl would have reacted with intense embarrassment or disgust. Yet, Nanase radiated absolutely nothing. It wasn’t that Amasawa thought she was completely devoid of emotion; rather, whenever Nanase flipped a certain internal switch, her mental defenses became impenetrably high.</p></div>\n<div><p>“That swimsuit is pretty bold, too. Quite the aggressive fashion statement.” Fully expecting a reprimand, Amasawa forcefully pressed the attack, desperate to find a crack in the Nanase's armor.</p></div>\n<div><p>“I merely rented a design that a classmate recommended. Is there a problem with that?”</p></div>\n<div><p>“Not a <em>problem, </em>exactly. I just figured the boys wouldn't know where to look.”</p></div>\n<div><p>“Are you not in the exact same situation, Amasawa-san?”</p></div>\n<div><p>It was a fair point. Amasawa was wearing a swimsuit a full grade flashier than any of the other girls they’d seen at the pool, proving her tastes were just as daring as Nanase's.</p></div>\n<div><p>“In my case, it's totally fine, because I'm showing off on purpose!” Amasawa laughed. “The boys stare at me with lust in their eyes, and the girls glare at me with raging jealousy. I love being the center of attention.”</p></div>\n<div><p>“...Is that so?”</p></div>\n<div><p>Perhaps unable to process that particular brand of exhibitionism, a slightly troubled frown flickered across Nanase's face. It was the first genuine display of emotion she had shown, but just as quickly as it appeared, her rigid, stoic mask slammed back into place.</p></div>\n<div><p>“Anyway, to change the subject for a sec…” Amasawa hummed. “I heard someone from Class 2-D was forced to say bye-bye during the Special Exam the other day. Is your class holding up okay, nya?”</p></div>\n<div><p>The question wasn't born out of genuine interest. Amasawa was simply tossing it out as a way to kill time until her drink arrived.</p></div>\n<div><p>For a fraction of a second, Nanase’s expression stiffened. Letting out a soft exhale, she averted her eyes and stared off into the distance.</p></div>\n<div><p>While the third-year students had landed on an uninhabited island to begin their survival exam, the second-years had been locked in a fierce competition of their own through a unique Special Exam. The results had been definitive: Class A secured first place, Class C took second, and Class B came in third. That left Nanase’s Class D sitting dead last.</p></div>\n<div><p>Up until this point, the dynamic among the second-years had been a slow, steady crawl, with Class A gradually pulling away from the rest of the pack. Now, however, that gap was widening into a chasm. But this latest exam had been more than just a simple defeat for Class D. During the course of the trial, an expulsion had been finalized. They had suffered a casualty.</p></div>\n<div><p>“The class itself is functioning without issue,” Nanase replied quietly. “However, since the responsibility for his expulsion ultimately lies with me, I am left with mixed feelings on the matter.”</p></div>\n<div><p>“Wait, it's <em>your </em>responsibility, Nanase-chan? Was that how the story went? I thought he broke a rule or something.”</p></div>\n<div><p>Amasawa hadn't paid much attention to the Special Exam, but she had overheard a few rumors regarding the circumstances of the expulsion.</p></div>\n<div><p>“In truth,” Nanase said. “another student was supposed to be expelled.”</p></div>\n<div><p>“That's a pretty provocative way of putting it. Are you saying <em>you </em>tried to get someone expelled, Nanase-chan?”</p></div>\n<div><p>“That is correct.”</p></div>\n<div><p>It was the kind of statement that would earn a harsh scolding even if said as a joke, yet Nanase affirmed it instantly, without a shred of hesitation.</p></div>\n<div><p>“However, my target realized my intentions early on and devised countermeasures,” Nanase explained. “Then, as a warning, they cornered a student in Class D who had absolutely nothing to do with the incident. Knowing full well the severe penalty he would face, the expelled student must have been driven into such a mental corner that he felt he had no other choice but to break the rules.”</p></div>\n<div><p>Having her curiosity slightly piqued, Amasawa sat up from her lounge chair and scrutinized Nanase's face.</p></div>\n<div><p>While she couldn't detect any hints of guilt or regret in Nanase's eyes, there was an undeniable frustration seeping through her rigid mask.</p></div>\n<div><p>“Doesn't sound like a very peaceful story.”</p></div>\n<div><p>“Does that interest you?”</p></div>\n<div><p>“Eh? Sorry, not really.” Sensing she was about to be dragged into something tedious, Amasawa offered a dismissive reply.</p></div>\n<div><p>But Nanase had clearly anticipated the evasion and pressed on without hesitation. “You are not entirely divorced from this incident, Amasawa-san. In fact, you already know the details, do you not?”</p></div>\n<div><p>“My heart belongs solely to Ayanokōji-senpai,” Amasawa answered, her tone dripping with mock devotion. “I couldn't care less about silly squabbles between classmates, y'know?”</p></div>\n<div><p>Unfazed by the flippant deflection, Nanase continued. “The student I was trying to expel was from Class 2-A.”</p></div>\n<div><p>“Ah, so <em>that's </em>where the ‘not divorced’ part comes in. Sorry to disappoint, but I seriously had no clue. Nor do I care about this even a tiny bit. Still... who were you targeting?”</p></div>\n<div><p>Amasawa tilted her head, genuinely curious as to who in her class could have possibly provoked Nanase into wanting them expelled.</p></div>\n<div><p>“Ishigami-kun,” Nanase replied.</p></div>\n<div><p>“Ishigami?” Amasawa repeated. “The cool, handsome guy? He doesn't exactly seem like the type to make moves out in the open.”</p></div>\n<div><p>Despite sharing a class with him for over a year, Amasawa had practically zero contact with the boy. In truth, she had absolutely no interest in anyone in her own grade. Because she never bothered interacting with her peers, she barely even knew their basic personalities. It was safe to say the girl standing right in front of her was her one and only object of interest in the entire second year.</p></div>\n<div><p>As these thoughts drifted casually through Amasawa's mind, she noticed Nanase fixing her with a razor-sharp glare.</p></div>\n<div><p>“He is far sharper than one might imagine,” Nanase warned.</p></div>\n<div><p>“Hmm. Well, I know he's essentially in a leader-like position, but Ishigami-kun, huh... So, what made you decide to pick a fight with him? Y'know, just to pry a little.”</p></div>\n<div><p>“There are... certain circumstances behind it.”</p></div>\n<div><p>The atmosphere around Nanase underwent a subtle shift. Instantly, Amasawa became absolutely certain that this topic, one she had brought up purely to kill time, was the actual reason she had been summoned here today.</p></div>\n<div><p>“I'm starting to get the feeling that this little story and my invitation to the pool are connected.”</p></div>\n<div><p>“Just to be absolutely certain,” Nanase said, her voice dropping a fraction, “you were not involved in this incident, were you, Amasawa-san?”</p></div>\n<div><p>“Do I really look like a suspect here?” Amasawa asked.</p></div>\n<div><p>“If you truly mean it when you say you only have eyes for Ayanokōji-senpai... then I concluded your involvement was a distinct possibility.”</p></div>\n<div><p>Normally, if a girl was strictly interested in Ayanokōji, it would stand to reason that someone like Ishigami wouldn't matter to her in the slightest. Yet, Nanase’s tone implied a completely different, paradoxical logic: <em>If </em>you were deeply obsessed with Ayanokōji, <em>then </em>you would naturally be deeply concerned with Ishigami.</p></div>\n<div><p>“Sorry, but I seriously couldn't care less, and I definitely had no part in it.” Flapping her left hand back and forth, Amasawa offered a genuine, outright denial.</p></div>\n<div><p>“I understand. Regardless, I had fully intended to broach this subject myself.” Dismissing the slight detour in their conversation, Nanase pressed on, firing off her carefully chosen words in rapid succession. “I will speak under the assumption that you truly know nothing. He... Ishigami Kyō is not entirely unconnected to the White Room.”</p></div>\n<div><p>With that single sentence, Nanase sliced right to the heart of the matter, abruptly dragging the core issue out into the open.</p></div>\n<div><p>“Ishigami-kun has ties to the White Room? If he’s my age, that would mean he’s a White Room student, but that’s impossible. And Ayanokōji-senpai is the absolute only one in the generation above us... Wait, could he be younger? Hmmm... I think I'd be even <em>less </em>interested if he were a junior, though~”</p></div>\n<div><p>“You are saying that while knowing full well it is not the case, are you not?”</p></div>\n<div><p>Noting the sharp, unmistakable flicker of anger in Nanase's glare, Amasawa brought her hands together in a playful gesture of apology.</p></div>\n<div><p>“My bad, my bad. So basically, you're saying he's connected, just not as a student. And since you actively moved to eliminate him, that must mean Ishigami-kun is working for the White Room's side. An assassin sent in to get Ayanokōji-senpai expelled, does that sound about right, nya?”</p></div>\n<div><p>Even as she voiced the theory, an obvious contradiction sprang to mind. If that were true, wasn't Ishigami leading an awfully leisurely, remarkably ordinary school life?</p></div>\n<div><p>And that wasn't all. The assassins specifically dispatched under Tsukishiro's orders to expel Ayanokōji were Amasawa and Yagami. If Ishigami was <em>also </em>tangled up with the White Room on top of that, things were certainly turning into quite a lively party. A faint smile touched Amasawa's lips at the thought.</p></div>\n<div><p>However, she was currently taking this entire story with a grain of salt. She wasn't about to swallow the claims at face value. After all, the true allegiances of the girl standing beside her, Nanase Tsubasa, were still steeped in a murky gray area, neither definitively white nor undeniably black.</p></div>\n<div><p>“The situation has changed drastically since you and Yagami-kun first made your moves shortly after enrolling,” Nanase explained. “The question of whether or not to expel Ayanokōji-senpai is nothing more than a single current in a much larger flow—”</p></div>\n<div><p>Mid-sentence, Amasawa lightly raised a palm, gesturing for her to stop. Right on cue, the door to the private pool opened, and a female staff member walked in carrying the melon cream soda Amasawa had ordered.</p></div>\n<div><p>Accepting the drink with a bright, charming smile, Amasawa waited politely for the staff member to leave before taking a generous gulp through her straw.</p></div>\n<div><p>“Wow, so sweet! But <em>so </em>tasty~” Pressing a hand to her cheek, she let out a small, exaggerated shiver, playing the part of an innocently cute girl to perfection.</p></div>\n<div><p>“May I continue?”</p></div>\n<div><p>“Go right ahead.”</p></div>\n<div><p>“Amasawa-san, you were ordered by the White Room side, specifically by Tsukishiro-san, to have Ayanokōji-senpai expelled. That is correct, yes?”</p></div>\n<div><p>Amasawa nodded encouragingly, urging her to go on.</p></div>\n<div><p>“From the very beginning, Tsukishiro-san believed the odds of you actually succeeding in expelling him were fifty-fifty.”</p></div>\n<div><p>“Wait, so he knew right from the start that our abilities were no match for Senpai's?”</p></div>\n<div><p>“It might be more accurate to say that he simply did not care which outcome came to pass.”</p></div>\n<div><p>The spoon in Amasawa's hand, which had just scooped up a bite of vanilla ice cream, froze in midair.</p></div>\n<div><p>When she had been sent to Advanced Nurturing High School, she was ordered to follow Tsukishiro's instructions. Because of that, she had indirectly assumed he was an ally. Was that fundamental premise completely wrong? She turned the thought over in the back of her mind.</p></div>\n<div><p>“That definitely brings up a lot of things I want to dig into,” Amasawa said slowly, “but can I ask a fundamental question first?\"</p></div>\n<div><p>“What is it?”</p></div>\n<div><p>“Nanase-chan, at the end of the day... Are you Ayanokōji-senpai's ally? Or are you his enemy?”</p></div>\n<div><p>Ayanokōji himself had previously asked Amasawa to look into Nanase. Right now, the girl was running around acting like his loyal knight, but there wasn't a single shred of concrete proof to back up her allegiance.</p></div>\n<div><p>“Yes, you make a fair point. It would probably be best to make my stance explicitly clear, including the matter regarding Tsukishiro-san.”</p></div>\n<div><p>Nanase pulled a smartphone from her bag, tapped the screen a few times, and held it out.</p></div>\n<div><p>As Amasawa reached out to take it, her gaze drifted to <em>another </em>phone resting innocently on the table.</p></div>\n<div><p>“For someone playing the honors student, you're actually quite a bad girl, Nanase-chan. Carrying two phones around, and one that looks like a carbon copy of the school-issued models, no less. If you get caught with that, a simple suspension might not cover it.”</p></div>\n<div><p>Teasing her with a playful lilt, Amasawa finally lowered her eyes to the screen she had been handed.</p></div>\n<div><p>“To answer one of your earlier questions, Ishigami-kun is not Ayanokōji-senpai's enemy,” Nanase declared. “Putting his own personal feelings aside, his faction is unambiguously the White Room... or, to be entirely precise, Ayanokōji Atsuomi's faction.”</p></div>\n<div><p>Ayanokōji Atsuomi was Ayanokōji Kiyotaka's biological father and the founder of the White Room. To Amasawa and the other students raised within its walls, he was their absolute ruler.</p></div>\n<div><p>The phone contained a comprehensive dossier on Ishigami Kyō, detailing everything from his upbringing to the circumstances that led to his enrollment.</p></div>\n<div><p>During his childhood, he had met Atsuomi and was profoundly inspired by him. Upon entering middle school, Ishigami leveraged his parents' connections to contact Atsuomi independently. He was subsequently highly praised by the man as a brilliant individual with a natural intellect, and ultimately enrolled at Advanced Nurturing High School to act as an observer over Kiyotaka.</p></div>\n<div><p>Scrolling through the profile, Amasawa’s eyes landed on a specific passage. It noted that while Ishigami deeply craved Atsuomi's acknowledgment, he harbored a bitter resentment over the fact that Atsuomi rated his own son much higher.</p></div>\n<div><p>“I see. It's precisely because he reveres ‘Sensei’ so much that he's jealous of Senpai, the masterpiece.”</p></div>\n<div><p>For a moment, another figure overlapped faintly with Ishigami in her mind.</p></div>\n<div><p>Yagami.</p></div>\n<div><p>Imagining the undeniable parallels between both of them, Amasawa felt a slight, involuntary stir of emotion in her chest.</p></div>\n<div><p>“That may well be the case,” Nanase agreed. “However, unlike you White Room students, he was not ordered to expel Ayanokōji-senpai. His mandate is strictly limited to surveillance.”</p></div>\n<div><p>No matter his personal feelings, Ishigami would never defy Sensei's wishes. If anything, his position was simply to watch over and preserve the masterpiece.</p></div>\n<div><p>“I was pretty confident in my ability to keep tabs on Ayanokōji-senpai,” Amasawa murmured, “but I never once noticed him in the picture.”</p></div>\n<div><p>For over a year, her own monitoring of Ayanokōji had bordered on stalking. Yet, in all that time, she had never caught Ishigami attempting to make contact. Since she couldn't stick to Ayanokōji twenty-four seven, Ishigami might have slipped through the cracks here and there, but if he were making frequent contact, she undoubtedly would have noticed.</p></div>\n<div><p>“Unless there’s some unexpected development,” Nanase said, “he may believe there is no need for him to interfere.”</p></div>\n<div><p>“So he does recognize Senpai's abilities.\" Amasawa let the thought settle before shifting to the next point. “By the way, does Ishigami-kun know about us too?”</p></div>\n<div><p>“I doubt he knows about me, but I am certain he has received detailed information regarding you and Yagami-kun directly from the White Room.”</p></div>\n<div><p>“Makes sense. If that's the case, he must be pretty capable.”</p></div>\n<div><p>Amasawa had never once been approached by him, nor had she ever sensed an unnatural gaze or hostile vibe aimed in her direction. That was exactly why she had paid absolutely zero attention to Ishigami throughout her entire school life.</p></div>\n<div><p>“I cannot speak to his basic academic metrics, but in terms of deductive reasoning, I would assess him as being at least a step above you and Yagami-kun.”</p></div>\n<div><p>“Eeeh~?” Amasawa’s voice rose with theatrical disbelief. “Aren't you just underestimating me a little? Or maybe you're overestimating him?”</p></div>\n<div><p>“It would certainly be helpful for us if that were true,” Nanase said dryly. “Regardless, his current policy seems to be to maintain his surveillance until graduation. But should the tide change, he will likely take immediate action.”</p></div>\n<div><p>“Meaning Ishigami-kun will make a move to force Ayanokōji-senpai out of the school?”</p></div>\n<div><p>Even when asked this, Nanase did not affirm. Instead, she briefly averted her gaze, and looked up at the clear blue sky.</p></div>\n<div><p>“At this point, the word expulsion alone is no longer enough to describe it,” she said. “What matters to Atsuomi is ensuring that Ayanokōji-senpai is brought back into his own hands. If he decides expulsion is necessary for that purpose, Ishigami-kun will follow his orders. If he decides it is best to leave him alone until graduation, then Ishigami-kun will do nothing until the very end. At least, that’s my understanding of the current situation.”</p></div>\n<div><p>Amasawa stared at her. “For someone who isn't a White Room student, you're vastly more knowledgeable about this whole mess than I am, and I'm the actual assassin sent to get Senpai expelled. You got that phone from Tsukishiro, too, didn't you? Just who are you, Nanase-chan?”</p></div>\n<div><p>That was the very core of the mystery, the absolute root of Nanase’s guiding principles, and the very thing Ayanokōji himself likely wanted to uncover.</p></div>\n<div><p>And now, Amasawa was stepping right into it.</p></div>\n<div><p>“Did you truly think I would just hand over that information so easily?”</p></div>\n<div><p>“Ah, figured as much. I guess I can't blame you, seeing as I'm a White Room student.”</p></div>\n<div><p>Thinking she might have probed a bit too deep, Amasawa was surprised when a faint smile graced Nanase's lips.</p></div>\n<div><p>“I am joking. You respect, no, you revere Ayanokōji-senpai. Because of that absolute devotion, I am completely convinced you would obey his every word. But precisely because the Ayanokōji-senpai you are loyal to belongs to the White Room, there are certain things I cannot share.”</p></div>\n<div><p>Amasawa understood what Nanase was implying.</p></div>\n<div><p>If Nanase’s true intentions were brought to light, Ishigami would undoubtedly make his move. That was Nanase's rationale. That was why she had struck first, attempting to get him expelled before he could act.</p></div>\n<div><p>Inside Amasawa's mind, the puzzle pieces rapidly began falling into place.</p></div>\n<div><p>“However, I <em>can </em>tell you my ultimate objective,” Nanase offered.</p></div>\n<div><p>“Then give it to me straight. What exactly is your goal, Nanase-chan? Y'know, within the boundaries of what you're actually allowed to say.”</p></div>\n<div><p>“Initially, my goal was to defeat Ayanokōji-senpai and have him expelled. That was the sole reason I enrolled in this school.”</p></div>\n<div><p>Seeing Nanase deliver this statement with such a deadpan, serious expression, Amasawa couldn't help but burst into laughter.</p></div>\n<div><p>“A for effort, but no matter what you do, Nanase-chan, you wouldn’t be able to beat Ayanokōji-senpai.”</p></div>\n<div><p>Even if Nanase had been hiding her true strength this entire time, that fundamental truth would never waver.</p></div>\n<div><p>“I am well aware,” Nanase replied calmly. “But do you not think that is only true if I were to fight him head-on?”</p></div>\n<div><p>Without speaking boastfully, Nanase continued, implying that she had a chance of winning.</p></div>\n<div><p>“No, no, frontal assault or sneak attack, it doesn't matter. It's totally impossible.”</p></div>\n<div><p>Ayanokōji simply wasn't the kind of opponent who would fall for conventional tactics, surprise attacks, or underhanded tricks. Amasawa felt a slight wave of disappointment, having assumed Nanase was at least smart enough to understand that much.</p></div>\n<div><p>However, the next words out of Nanase's mouth were something Amasawa could never have anticipated.</p></div>\n<div><p>“The enemy I must defeat is no longer Ayanokōji-senpai. It is the man lurking in his shadow: Ayanokōji Atsuomi, the founder of the White Room. And to accomplish this, I must steal Ayanokōji-senpai away, take control of him, and seize the initiative. After all, he is the most vital piece in his father's plans.”</p></div>\n<div><p>“Hold on, there's no way I can see that actually working.”</p></div>\n<div><p>“That depends entirely on the method. Ayanokōji-senpai is formidable. As long as I interact with him as an enemy, bringing him under my control is an absolute impossibility. However, if my goal is to induce a change of heart in him, the story changes.”</p></div>\n<div><p>“...A change of heart?”</p></div>\n<div><p>“Let me ask you, Amasawa-san. What do you think Ayanokōji-senpai will do once he graduates?”</p></div>\n<div><p>“What else? Wouldn't he just go back to the White Room? Whether Senpai becomes a new instructor or follows Sensei to accomplish something massive, I wouldn't know.”</p></div>\n<div><p>“I was told his future would be one of those two options. In other words, if that comes to pass, Atsuomi wins. I intend to prevent that at all costs. Tsukishiro-san said it himself: while Ayanokōji-senpai may have fled the White Room's environment out of intellectual curiosity, he certainly does not hate the place. Nor does he have any real intention of defying them. No, he is fully prepared to willingly return to his origins.”</p></div>\n<div><p>“Well, I don't know how it looks from your perspective, Nanase-chan, but I don't exactly have a bad image of the White Room either,” Amasawa shrugged. “It's where I've spent every single day since I was born. Simply put, it's my home.”</p></div>\n<div><p>Having recently lost that very place to return to, one could say Amasawa’s heart carried a quiet, hidden wound.</p></div>\n<div><p>“That is completely unacceptable,” Nanase replied. “That man is simply biding his time, waiting for the perfect moment to use Ayanokōji-senpai. To send him back to a man like that... I absolutely refuse to let it happen.”</p></div>\n<div><p>Realizing her hands had unconsciously balled into white-knuckled fists, Nanase forced herself to loosen her grip.</p></div>\n<div><p>“So, you're going to try your absolute best to stop Ayanokōji-senpai from returning to the White Room, huh? Nanase-chan.”</p></div>\n<div><p>“Yes.”</p></div>\n<div><p>“Then what? Are you just gonna bow your head and beg, ‘Please Ayanokōji-senpai, go and live a normal, happy life~’? Come on now~”</p></div>\n<div><p>“I know it will not be that simple. Ayanokōji-senpai is not going to just nod his head and agree.”</p></div>\n<div><p>“I don't know if he has any actual interest in a ‘normal life,’ but I definitely think returning to the White Room holds a lot more appeal to him.”</p></div>\n<div><p>“Indeed. And on the off-chance that he did agree, there is no way Ayanokōji Atsuomi would tolerate such a rebellion.”</p></div>\n<div><p>“Then how exactly do you plan to change Senpai's heart?”</p></div>\n<div><p>“To be completely honest, I have not fully pieced together the answer to that yet. But I believe I have found a hint. Before I can put it into action, however, the stage must be perfectly set. Persuading him and tearing him away from the White Room will require careful groundwork. The moment I begin making overt moves toward that answer, Ishigami-kun will undoubtedly notice, and he will come to stop me</p></div>\n<div><p>“So you tried to strike first and get him expelled to clear the board....I see.” Amasawa murmured.</p></div>\n<div><p>But now that Nanase’s preemptive strike had failed, a dangerous new reality loomed over them. If Ishigami was truly as capable as Nanase claimed, there was a very real chance that he had already sensed the anomaly. In all likelihood, he was investigating who had targeted him, quietly preparing to eliminate the threat.</p></div>\n<div><p>“Making that move to get Ishigami-kun expelled this time might have been a bit of a blunder on your part, Nanase-chan.”</p></div>\n<div><p>“I will not deny it.”</p></div>\n<div><p>Yet, Nanase didn't seem panicked in the slightest. Watching her, Amasawa deduced that the preemptive strike had likely doubled as a probing attack to test her opponent's strength and gather intelligence. And if Ishigami was truly as sharp as Nanase claimed, then targeting an unrelated student in retaliation was an absolutely brilliant, perfectly calculated move, a flawless warning shot that established dominance without escalating the situation completely out of control.</p></div>\n<div><p>“Okay, I think I've grasped the general picture,” Amasawa said. “Though I have no idea how much of this little story is actually true.”</p></div>\n<div><p>“Of course. I am not asking you to blindly believe every word I say.”</p></div>\n<div><p>Even while taking it all with a grain of salt, Amasawa couldn't detect the faintest scent of falsehood from Nanase. At the very least, Nanase's claims were persuasive enough that Amasawa was willing to treat them as the working truth.</p></div>\n<div><p>“So, what's my role in all this? It's not like you just want me to play messenger and relay everything to Ayanokōji-senpai, right?”</p></div>\n<div><p>If that were all Nanase wanted, there would have been no reason to involve Amasawa like this.</p></div>\n<div><p>“I want you to become my ally.”</p></div>\n<div><p>“Ally? You mean you want me to help induce this ‘change of heart’ in Ayanokōji-senpai?”</p></div>\n<div><p>“That is certainly part of it. But first and foremost, I would appreciate it if you could act as my backup in the event that I am expelled.”</p></div>\n<div><p>“Heeh, so you've even factored in the possibility of being taken out by Ishigami-kun.”</p></div>\n<div><p>“I will do everything in my power to ensure that does not happen, but there is no telling how things will unfold.”</p></div>\n<div><p>When combining Ishigami's raw capabilities with the classified intelligence provided by the White Room, the threat level skyrocketed. Amasawa deduced that Nanase simply couldn't guarantee her own safety against such overwhelming odds.</p></div>\n<div><p>“Sorry, but at the end of the day, I'm still a White Room student through and through,” Amasawa sighed, shaking her head. “I've lived my entire life taking pride in that, and I still have lingering attachments to it. I don't dislike you, Nanase-chan, but personally? I want to support whatever future Senpai desires. And beyond that, assisting Sensei is my true, original purpose.”</p></div>\n<div><p>What Nanase was trying to do was no minor adjustment. It was an attempt to take Ayanokōji’s future and bend it away from its expected course, forcing it from one path onto another.</p></div>\n<div><p>Whether that intervention was right or wrong, Amasawa could not yet judge. That was precisely why she had no choice but to refuse.</p></div>\n<div><p>“What is your dream, Amasawa-san?” Nanase asked quietly. “To return to the White Room alongside Ayanokōji-senpai... is that it?”</p></div>\n<div><p>“So what if it is?” Amasawa replied. “Got a problem with that?”</p></div>\n<div><p>Of course, she already knew deep down that such a dream would never come true.</p></div>\n<div><p>The White Room had branded her a failure, and there was no returning from that exile.</p></div>\n<div><p>Even so, finding solace in the fact that she was still free to dream, Amasawa offered Nanase a bright, unapologetic smile.</p></div>\n<div><p>“I understand how you feel,” Nanase said. “However, miracles do not happen. That wish of yours is one hundred percent unattainable. No matter what grand achievements you might accomplish, there is no bright future waiting for you.”</p></div>\n<div><p>“How can you be so sure about that?” Amasawa countered lightly. “For all you know, I might just be on the verge of awakening my true potential, y'know?”</p></div>\n<div><p>“This is a matter that goes far beyond your individual capabilities. Do you have any idea what your father is currently planning?”</p></div>\n<div><p>“My father? Sorry, but I have absolutely zero interest in that kind of thing. Doesn't that have exactly nothing to do with me?”</p></div>\n<div><p>“Your opinion is irrelevant. The simple fact of the matter is that the legal 'ownership' of you, Amasawa-san, lies with your father.\"</p></div>\n<div><p>Nanase smoothly took back the smartphone she had handed over and began tapping at the screen.</p></div>\n<div><p>“Even if some so-called ‘parent’ I've never even met tries to butt in—”</p></div>\n<div><p>“I am well aware that you are an existence your father cannot control,” Nanase interrupted. “And because he knows this just as well as you do, he has been in close contact with the White Room to advance his preparations.”</p></div>\n<div><p>As Nanase laid this out with quiet, clinical detachment, the playful smile began to slip from Amasawa's face.</p></div>\n<div><p>“What is it, re-education? Discipline? Whatever grim future he's planning, bring it on.”</p></div>\n<div><p>“If you were truly prepared for the reality of it, that would be fine,” Nanase warned. “However, massive fraud has recently been uncovered in his company. Short on funds and backed into a corner, he is desperate. It seems there are certain syndicates overseas willing to pay exorbitant prices for beautiful young women, and he is currently scrambling to secure a buyer for you.”</p></div>\n<div><p>Nanase handed the phone back. On the screen Amasawa was now scrolling through was the photo and profile of a man presumed to be her biological father.</p></div>\n<div><p>“So I've outlived my usefulness, and now I'm just going to be sold off to the highest bidder. Hilarious.”</p></div>\n<div><p>Regardless of whether this was the truth or an elaborate lie, Amasawa cheerfully clapped her hands together and laughed out loud.</p></div>\n<div><p>But her eyes were completely dead. It was as if the harsh reality had just been violently shoved in her face, the agonizing truth that she didn't even possess the fundamental right to dream of a future.</p></div>\n<div><p>“If you choose to cooperate with me, I may be able to save you from that fate.”</p></div>\n<div><p>As Amasawa continued swiping across the screen, the display switched to an English webpage. It detailed exactly which overseas brokers her father was currently in contact with. It also outlined the horrific reality of what awaited her at her destination, a living hell so depraved one would hesitate to even put it into words.</p></div>\n<div><p>“Oh my, look at that crazy price tag attached to me,” Amasawa giggled. “I could buy anything in the world with this kind of money.”</p></div>\n<div><p>“From the perspective of an ordinary person, yes,” Nanase replied coldly. “However, given President Amasawa's massive debts, that amount is merely a drop in the bucket.”</p></div>\n<div><p>Amasawa thought about it over and over again. Her entire life was something she couldn't even verify as truth or lie. However, one thing was absolutely certain: the future she had just been shown held zero salvation.</p></div>\n<div><p>“Upon successfully inducing Ayanokōji-senpai's change of heart, I will extend ample protection to you after graduation, just as I plan to do for him. If that happens, you will be able to start a life that belongs entirely to you.”</p></div>\n<div><p>Meaning she would finally be allowed to stand on the starting line as an individual, autonomous human being.</p></div>\n<div><p>“...Could you really pull something like that off?”</p></div>\n<div><p>“I can. It is true that Ayanokōji Atsuomi is a man of considerable power with deep connections to the underworld. However, the faction backing me is large enough to easily swallow them whole. Given the circumstances, even you can imagine that much, can you not?”</p></div>\n<div><p>“Well…” Amasawa said slowly, “assuming you were actually serious about protecting me, maybe so.”</p></div>\n<div><p>But Amasawa wasn't naive enough to blindly swallow such sweet promises. If she held the same kind of absolute value as Ayanokōji Kiyotaka, then perhaps Nanase's faction genuinely would mobilize to protect her. But there was no guarantee they would afford her that same luxury. After all, she possessed no such value.</p></div>\n<div><p>“Could you give me a little time to think about it?”</p></div>\n<div><p>“Of course,” Nanase nodded smoothly. “I will be waiting for a favorable reply.”</p></div>\n<div><p>Flashing a defiant smirk, Amasawa scooped up a bite of the ice cream, which had now begun to melt.</p></div>",
    "7": "<div><p>Nearly two grueling hours of alternating between academic hurdles and physical exertion had finally come to an end. The supervisor announced a thirty-minute break, bringing the trials for the four teams of Group 3 to a temporary pause.</p></div>\n<div><p>Some students collapsed right where they stood, while others made a beeline for their backpacks, desperately digging out bottles of mineral water. It was perfectly understandable; the ordeal had felt like taking a comprehensive exam while baking under the blazing sun.</p></div>\n<div><p>“That really took a toll on me... I don't think I'll be able to manage even a single step for a while.”</p></div>\n<div><p>Slumped on the ground, Sanada removed his glasses and let out a heavy sigh, voicing his sheer exhaustion. His dirt-streaked jersey was a clear testament to his efforts; anyone looking could see he had given it his all. He was usually the type who kept his composure intact. His cool manner rarely cracked, and he did not often allow fatigue or emotion to show plainly on his face. But under these conditions, even he could not conceal the toll.</p></div>\n<div><p>“You're seriously insane, you know that? Sweeping every single individual match across both the academic and physical tasks…”</p></div>\n<div><p>Yoshida wandered over as he spoke, his expression caught somewhere between exasperated disbelief and genuine admiration. Although his tone was casual, a distinct gleam of shock lingered in his eyes. Sanada, twisting the cap off his plastic bottle, too, offered several firm nods of agreement.</p></div>\n<div><p>A single victory could be brushed off as a fluke or a favorable matchup. But consistently crushing such a diverse range of tasks painted a very different picture. Even to classmates who hadn't known me for very long, it was undeniably clear that this stemmed from true ability.</p></div>\n<div><p>Wiping the sweat from his brow, Sanada looked at me with an expression of quiet acceptance.</p></div>\n<div><p>“To be honest, I knew you were capable to some extent, but... this far exceeded my expectations.”</p></div>\n<div><p>He took a slow sip of water before meeting my gaze once more. Unlike Yoshida's, his words held no trace of exaggeration.</p></div>\n<div><p>“No, seriously,” Yoshida added. “While we were desperately trying to just survive the tasks, this guy was completely unfazed the whole time. Honestly, I'm just glad he didn't go all out against us back when he was still in Horikita's class.”</p></div>\n<div><p>When people genuinely acknowledge someone who produces results, and at the same time feel that they belong to that same circle, they become far more honest than one might expect. The tense atmosphere softened slightly, and within this brief period of rest, the outline of Class C was steadily growing firmer, taking shape once more.</p></div>\n<div><p>“Still,” Sanada said after a moment, glancing around, “I was just thinking it was unusually quiet around here. It turns out Morishita-san isn't with us.”</p></div>\n<div><p>Catching sight of Morishita resting her back against a distant tree trunk, Yoshida followed up on Sanada's observation.</p></div>\n<div><p>“Well, she's terrible at anything physical,” he said. “She probably doesn't even have the energy left to open that loud mouth of hers.”</p></div>\n<div><p>After the two of them had recovered a little, I began handing over the tokens in order. With each transfer, a matching electronic chime rang out from my smartwatch and echoed from Yoshida's and Sanada's as they received them.</p></div>\n<div><p>I set off toward Morishita to hand her the tokens as well, but no sooner had I started walking than I heard another set of footsteps hurrying toward me.</p></div>\n<div><p>“U-Um, Ayanokōji-kun…” The voice came from close by, soft enough that it was almost swallowed by the noise of the break. “Do you have a minute?”</p></div>\n<div><p>Mii-chan stood there looking visibly unsettled. Her eyes did not stay in one place for long, and even before she said another word, it was clear that she had not come to speak casually.</p></div>\n<div><p>“Um... over here.”</p></div>\n<div><p>She gestured for me to follow, slipping away from the prying eyes of the other students and moving to a secluded spot where our voices wouldn't carry.</p></div>\n<div><p>“There's something I want to consult you about,” she began, lowering her voice even further. “I know it's not really my place since we aren't in the same class anymore, but this is something I feel like I can only tell you, Ayanokōji-kun…”</p></div>\n<div><p>Her restless gaze darted around, and it was plainly obvious who she was looking out for: her own classmates from Class A. Judging by the fact that Ike and the others were currently nowhere to be seen, she had clearly waited for the perfect window to make her move. I stayed silent, gently prompting her to continue.</p></div>\n<div><p>“It's... about Kushida-san. Since today's tasks started, right up until this break... Shinohara-san hasn't given her a single token. And so…”</p></div>\n<div><p>“I understand why you wanted to keep this quiet, but that's highly sensitive internal information,” I interrupted. “Are you sure you want to be telling me this?”</p></div>\n<div><p>“Even though our classes are competing against each other, Ayanokōji-kun,” she replied, hesitating over each word. “we're still allies in the same group right now. Plus, it seemed like you genuinely value Kushida-san's abilities, so…”</p></div>\n<div><p>Normally, information about who had handed over how many tokens, and to whom, was something that should never be revealed carelessly. But the fact that she was bringing this to me meant that <em>it </em>had finally begun.</p></div>\n<div><p>“Assuming what you're saying is true, you and Ike have still been receiving your shares without any issues right?”</p></div>\n<div><p>She responded to my question with two small nods. “Yes, we've both... received ours perfectly fine.”</p></div>\n<div><p>“If Shinohara is keeping hold of all of Kushida’s tokens and refusing to hand over only her share, then that is certainly a problem.”</p></div>\n<div><p>Even without witnessing the scene firsthand, it was easy to picture the suffocating atmosphere it must have created.</p></div>\n<div><p>“Shinohara-san was complaining last night,” Mii-chan continued. “She said Ike-kun was constantly staring at Kushida-san. Even during the one-legged balancing task this morning, them being paired up was purely a coincidence, but her mood has been terrible ever since.”</p></div>\n<div><p>“Knowing Ike, he's always had a soft spot for cute girls. Throw Kushida into the mix, and it's bound to be even worse.”</p></div>\n<div><p>“B-But Shinohara-san is his girlfriend…” Mii-chan’s voice trembled with an earnest kind of discomfort. “I honestly think Ike-kun is completely at fault here…”</p></div>\n<div><p>She wasn't wrong. In reality, however, one cannot spend an entire eternity with eyes only for their precious girlfriend. It is often said that as a relationship went on, intimacy deepened while the initial spark inevitably faded. Considering Ike had harbored feelings for Kushida to begin with, a wandering eye was, to some extent, unavoidable.</p></div>\n<div><p>“I thought that once Ike learned more about Kushida’s true nature, he would put some distance between himself and her,” I said. “But I suppose that hasn’t happened.”</p></div>\n<div><p>“I suppose not. Lately, Kushida-san has often been isolated in the classroom, and Ike-kun has been going out of his way to talk to her. That's probably been bothering Shinohara-san for a while too.”</p></div>\n<div><p>“But even taking all of that into account, the root cause of everything goes back to the Unanimous Special Exam... doesn't it?”</p></div>\n<div><p>Mii-chan closed her eyes tightly, and then nodded deeply.</p></div>\n<div><p>“In truth, the words that Kushida hurled at Shinohara back then were so intense, they were impossible to forget.”</p></div>\n<div><p>I remembered it clearly enough.</p></div>\n<div><p>During the Unanimous Special Exam, Kushida had mocked Shinohara in front of the entire class, casually declaring her to be ‘on the ugly side.’ If Shinohara's boyfriend had then been constantly doting on and acting chummy with the very person who had humiliated her, it was all too easy to imagine the resentment boiling inside her.</p></div>\n<div><p>Even so, maliciously withholding tokens exclusively from Kushida was a secret she couldn't possibly keep forever.</p></div>\n<div><p>Up until now, Shinohara had likely bitten her tongue for the sake of the class. She had kept Kushida's toxic nature under wraps, taking a step back to avoid causing any public friction. But now that she had been handed the power of a representative, it seemed her restraints were finally beginning to snap.</p></div>\n<div><p>“Still, this is surprising,” I noted. “I thought you'd come to hate Kushida too, Mii-chan.”</p></div>\n<div><p>While it might not have been quite as brutal as insulting Shinohara's physical appearance, Mii-chan had also been a victim; her innocent crush on Hirata had been ruthlessly exposed during the Unanimous Special Exam.</p></div>\n<div><p>Putting aside the fact that most of our classmates had already noticed her feelings long before the reveal, the humiliation had still driven her into such a deep depression that she temporarily stopped coming to school.</p></div>\n<div><p>“It's true that Kushida-san... really hurt me,” she admitted softly. “But even so, I feel like if I let myself become a hateful person just like her, it would be wrong.”</p></div>\n<div><p>She was bringing this delicate issue to me, someone who had essentially betrayed her class by transferring out, despite knowing full well the complex circumstances at play. It was safe to assume her words were grounded in genuine moral conviction, not just surface-level pleasantries.</p></div>\n<div><p>“From what you've told me, there's no doubt she's abusing her position as representative to harass Kushida,” I said. “But your biggest concern is the worst-case scenario: that Kushida might actually end up in last place. Am I right?”</p></div>\n<div><p>“Yes…”</p></div>\n<div><p>If Shinohara monopolized all the tokens and refused to give Kushida a single one, Kushida would be fighting a steeply uphill battle, no matter how many tokens she managed to earn on her own.</p></div>\n<div><p>This Special Exam was divided into three categories— individual, team, and group— but having the entire class united was an overwhelmingly massive advantage.</p></div>\n<div><p>If a class treated the trivial Private Points reward as an afterthought and simply distributed their tokens equally, that solidarity alone would act as a tremendous shield against falling into last place. To counter such a strategy, the other classes would be forced to unite as well, ultimately boiling the exam down to a sheer numbers game where the expulsion would fall on the class with the lowest overall total.</p></div>\n<div><p>However, the logistical hurdles required to reliably execute that kind of strategy were staggering. It demanded trusting unseen classmates, coordinating meetups in the forest, transferring tokens, and meticulously adjusting the totals. The entire plan rested on the fragile premise that no one would betray the group.</p></div>\n<div><p>“There's no doubt that Shinohara's pent-up frustrations are manifesting in her actions,” I continued. “However, it's highly unlikely she'll withhold Kushida's tokens all the way to the bitter end. If word of this reaches Horikita, Shinohara's own standing within the class would be in serious jeopardy.”</p></div>\n<div><p>“So... I don't need to worry?”</p></div>\n<div><p>“For now, it should be fine. Do you honestly think she would go so far as to force Kushida into expulsion over a personal grudge? It's safe to assume this is just her way of exacting petty revenge.”</p></div>\n<div><p>Driving a classmate to expulsion solely out of personal dislike wasn't a simple line to cross.</p></div>\n<div><p>When I added that, Mii-chan seemed to relax slightly. A small breath escaped her, as though she had finally been allowed to set down a little of the weight she had been carrying.</p></div>\n<div><p>“But if you're still worried, just keep a close eye on the situation for me,” I added. “If Kushida still hasn't received any tokens by the end of the third day, or going into the final day, I'll step in and contact Horikita myself. After all, if Shinohara finds out you were the one who tipped her off, she might end up holding a grudge against you instead.”</p></div>\n<div><p>“...You're really willing to help?”</p></div>\n<div><p>“If we want Group 3 to take first place, we'll need the cooperation of every class,” I replied. “The order in which we cross the finish line on the final day has a massive impact on our score multiplier. I don't know the precise rules yet, but there's no guarantee we'll win if we're carrying around a powder keg like this.”</p></div>\n<div><p>When I told her that, Mii-chan bowed her head deeply. “Thank you so much...!”</p></div>\n<div><p>“More importantly, you should probably head back now,” I cautioned. “It'll be a hassle if Shinohara and the others spot us together.”</p></div>\n<div><p>Giving a small, earnest nod, Mii-chan hurriedly jogged off. She nearly tripped over her own feet in her haste, but she managed to slip away, successfully putting enough distance between us before Shinohara's group ever noticed she was gone.</p></div>\n<div><p>“Pray tell, what mysterious matters were you whispering about just now, Ayanokōji Kiyotaka?”</p></div>\n<div><p>Appearing beside me seemingly out of nowhere, Morishita leaned in with her sudden question.</p></div>\n<div><p>“Looks like you've recovered your stamina,” I noted.</p></div>\n<div><p>“Pardon? Whatever do you mean? My boundless energy is simply overflowing in an endless fountain of vitality, you know?”</p></div>\n<div><p><em>Perhaps her panting heavily just a few minutes ago had merely been an optical illusion.</em></p></div>\n<div><p>I decided not to press the issue any further.</p></div>\n<div><p>And so, the quiet dissonance brewing within Class A was steadily beginning to take root.</p></div>\n<div><h2>Part 1</h2></div>\n<div><p>After completing several more Individual and Team category tasks, with lunch and a longer break in between, we followed our supervisor’s instructions and made our way toward B7.</p></div>\n<div><p>As we ventured deeper into the forest the dense canopy overhead gradually swallowed the sunlight, casting the area into a dim greenish gloom. Cut off from the breeze, the humidity clinging to our bodies felt even more oppressive.</p></div>\n<div><p>The ground beneath our feet was soft, mixed with patches of deep mud, giving us the constant, dreadful sensation of our feet sinking into the earth.</p></div>\n<div><p>Exhausted from the relentless string of tasks, the students' footsteps were heavy and sluggish across the board.</p></div>\n<div><p>Everyone unconsciously shortened their strides, trying to conserve whatever stamina they had left.</p></div>\n<div><p>This was especially noticeable with Morishita. Her shoulders drooped as she tried to maintain a steady rhythm, but her breathing had begun to falter slightly.</p></div>\n<div><p>“What in the world is going on...? Are we seriously still not there yet...?”</p></div>\n<div><p>“They're literal demons!” Ike groaned, his voice carrying the same exhaustion he was clearly unable to hide. “Do they have any idea how much we've been walking around these past few days?!”</p></div>\n<div><p>Shinohara glanced sideways at him, offered a few words of comfort, and slowed her pace to match his. She did not say much, but fatigue was clearly visible on her face as well. Even so, she did not stop walking. She was probably conscious of not falling behind the others.</p></div>\n<div><p>In stark contrast, Katsuragi remained completely unfazed. He walked at a steady, consistent pace, with a perfectly straight posture. It wasn't as though he was free of fatigue, but he didn't show any of it on the surface, simply keeping his eyes fixed dead ahead as he continued walking. His efficient, waste-free movements likely helped suppress unnecessary stamina loss.</p></div>\n<div><p>Ibuki walked a little behind him, wearing an expression of complete boredom.</p></div>\n<div><p>Her gaze wasn't fixed on her feet or straight ahead; instead, she seemed to be staring blankly off into space. She walked while occasionally kicking a loose pebble, using the small motion to distract herself from the faint irritation simmering inside her.</p></div>\n<div><p>A considerable number of assignments had been thrown at us over the course of the day, but to put it plainly, Ibuki’s results had been extremely poor.</p></div>\n<div><p>At the start, the number of tokens she held had probably been almost the same as mine. Now, though, there was no need to check the exact figures. Within Group 3 as a whole, she was competing with Kushida for last place.</p></div>\n<div><p>So far, Katsuragi had shown no signs of leniency.</p></div>\n<div><p>There was probably a deliberate reason for that. By being strict with Ibuki, he may have been trying to force her to produce results. But that was only one side of it. The more immediate reality was that he simply had not secured enough surplus tokens to spare any for her.</p></div>\n<div><p>When it came to contests of academic ability, the advantage inevitably went to the other classes. No matter how many assignments we cleared, the more we completed, the more the gap between us and them would gradually widen. And even in physical contests, the one area where Ibuki should have had her chance to shine, luck had not been on her side. There had been cases where the teammates she was paired with dragged her down, and other times when she had the misfortune of running into me in succession.</p></div>\n<div><p>There was no way she could possibly find this situation amusing.</p></div>\n<div><p>A thin veil of light slipped through the gaps between the trees, faintly illuminating the path ahead. Our destination was still nowhere to be seen. Conversations had dwindled until only the sound of footsteps remained, falling into a steady, almost mechanical rhythm against the damp forest floor.</p></div>\n<div><p>Each of us continued forward in silence, confronting our own exhaustion in our own way.</p></div>\n<div><p><em>What exactly was waiting beyond the forest?</em></p></div>\n<div><p>No one had the room to think about it, let alone confirm it. We simply kept moving our feet, one step after another, as though our bodies had been reduced to that single repeated motion.</p></div>\n<div><p>Suddenly, the supervisor leading the way slowed his pace. He didn't come to a complete stop, but he did glance back over his shoulder, his eyes sweeping across our entire formation.</p></div>\n<div><p>After a few more steps, he called out in a clipped voice.</p></div>\n<div><p>“Kushida-san, there's an incoming call for you over the radio. Can you take it?”</p></div>\n<div><p>Kushida gave a small jolt the moment she was called out by name.</p></div>\n<div><p>“Me?”</p></div>\n<div><p>The faint tilt of her head was natural enough, but there was a distinct hint of caution laced in her voice. It was the first external contact we had received since the exam began, so her wariness was perfectly understandable.</p></div>\n<div><p>The supervisor offered no further explanation, simply gesturing lightly to the device in his hand.</p></div>\n<div><p>Kushida looked around once, then quickly complied without breaking her pace. She reached out, accepting the radio from the supervisor, and placed the small earpiece into her ear.</p></div>\n<div><p>Shinohara and the others stared at her intently, wondering what was going on.</p></div>\n<div><p>After a few moments of nodding to whatever was being said through the earpiece, Kushida exhaled softly and spoke.</p></div>\n<div><p>“It seems to be Horikita-san.”</p></div>\n<div><p>With that single sentence, the air around us shifted.</p></div>\n<div><p>She had kept her voice low, but it was loud enough to be easily heard by anyone standing nearby.</p></div>\n<div><p>A contact from outside the group, and from Horikita no less, was unlikely to be some mere routine work.</p></div>\n<div><p>From where we were, there was no point in trying to eavesdrop on the radio itself. Whatever came through the receiver would belong to Kushida alone. Her own voice, however, was another matter. If someone wanted to listen, it would not be impossible to catch what she said.</p></div>\n<div><p>Because of that, the gazes around her naturally began to gather.</p></div>\n<div><p>The first to move were the three students from Class A.</p></div>\n<div><p>As Kushida separated from the supervisor, they adjusted their positions and began walking around her, forming a loose screen. At the same time, they kept watch, making sure no one tried to come too close.</p></div>\n<div><p>There were no explicit rules stating we couldn't approach, but it was an unspoken agreement. Maintaining our distance now would make it easier to demand that same level of privacy when we inevitably needed it for ourselves.</p></div>\n<div><p>Katsuragi and I issued quiet instructions almost at the same time and moved toward the front. A moment later, the students from Class D also began putting distance between themselves and Kushida’s group.</p></div>\n<div><p>As I walked ahead, I cast a quick glance over my shoulder.</p></div>\n<div><p>Shinohara was walking beside Kushida, and the expression on her face held a different shade from before.</p></div>\n<div><p>The faintest hint of irritation.</p></div>\n<div><p>The fact that Horikita had called Kushida, not her.</p></div>\n<div><p>During the Unanimous Special Exam, Kushida had revealed her true nature and placed the class in danger. Her credibility had fallen visibly after that, as had her standing within the class’s internal hierarchy.</p></div>\n<div><p>And yet, despite all of that, Horikita had contacted Kushida first.</p></div>\n<div><p>For Shinohara, those two facts were becoming a source of invisible stress, quietly eating away at her from within.</p></div>\n<div><p>On top of that, there was a faint trace of anxiety. If Kushida reported Shinohara’s petty behavior as a representative to Horikita, a reprimand would almost certainly follow. While I couldn't be absolutely certain, with Shinohara hovering right over her, Kushida likely wouldn't do that.</p></div>\n<div><p>After all, in the eyes of those around her, Kushida was not the kind of bad girl who would go around voicing complaints.</p></div>\n<div><p>Even so, a different kind of silence from the one we had been carrying earlier had undoubtedly fallen over the group.</p></div>\n<div><h2>Part 2</h2></div>\n<div><p>We had crossed into Area C9, our destination finally within reach, when the supervisor stopped in his tracks and turned to face us.</p></div>\n<div><p>“If we proceed at this pace, I think we'll cross into Area B7 in about fifteen to twenty minutes,” he announced. “We're almost there, so hang in there just a little longer.”</p></div>\n<div><p>Receiving those words of encouragement, a few students offered weary murmurs of acknowledgment before we resumed our grueling march.</p></div>\n<div><p>Not long after, a burst of noise reached us from somewhere nearby; voices, footsteps, the faint disorder of another group in motion. A moment later, the first figure to come into view was another sweat-drenched supervisor, walking at the head of the formation. And behind him came Group 6.</p></div>\n<div><p>The supervisor assigned to Group 6 approached Urushihara almost immediately, and the two exchanged a few brief words.</p></div>\n<div><p>On the afternoon of the exam's second day, this marked our first genuine encounter with another group.</p></div>\n<div><p>Among the Class C students assigned to Group 6 were Kitō, Yamamura, Satonaka, and Machida. From the look of them, they had also covered a considerable distance. Fatigue clung visibly to many of the students, weighing down their shoulders and slowing their steps.</p></div>\n<div><p>While many students likely felt a flicker of relief at seeing fresh faces, a seed of suspicion no doubt took root alongside it.</p></div>\n<div><p>“Please rest assured, everyone,” Urushihara called out. “We simply happened to cross paths. There are no inter-group tasks scheduled for today.”</p></div>\n<div><p>With that single announcement, the tension in the air dissipated. The students' underlying suspicions had fortunately been off the mark. With the reassurance that this was nothing more than a chance encounter, they dropped their guard, and tentative smiles slowly began to spread across their faces.</p></div>\n<div><p>“It appears Group 6 is heading to Area B8, so you're welcome to travel together for the time being,” he continued. “There's no issue with you chatting or exchanging tokens if necessary. Please, feel free to do as you like.”</p></div>\n<div><p>That permission was all it took.</p></div>\n<div><p>Students from the other classes began moving toward one another, closing the distance quickly. Questions were exchanged almost at once. <em>How was your group doing? Were you managing to collect tokens? </em>A little later, the Class C students; Satonaka, Machida, and Yamamura, also approached us.</p></div>\n<div><p>“You guys holding up alright with the tasks?” Yoshida asked, casually opening with some small talk.</p></div>\n<div><p>Machida gave a noncommittal nod. “We're barely scraping by right now. It's hard to tell exactly how much everyone else is earning. Would it be faster if we just showed you our tokens?”</p></div>\n<div><p>His gaze shifted to me for approval, so I quickly shot the idea down.</p></div>\n<div><p>“No, that won't be necessary. Right now, instead of worrying about where we stand, it's better to focus entirely on gathering as many tokens as possible, even if it's just one more.”</p></div>\n<div><p>“You might be right…” Machida admitted. “But honestly, I'd be lying if I said I wasn't anxious.”</p></div>\n<div><p>“You can rest easy,” I assured him. “I've already decided on a strategy for how we'll survive this Special Exam. Right now, we're just waiting for the right moment to put it into action. I have no intention of letting anyone from Class C get expelled. When the time comes for detailed instructions, I'll definitely contact you over the radio.”</p></div>\n<div><p>Leaving the rest of the intra-class chatter to Yoshida and Sanada, I shifted my focus beyond our class.</p></div>\n<div><p>My primary concern right now was Class B's movements. Katsuragi was already at the center of a discussion, where the events and developments within Group 3 over the past day would undoubtedly be shared in meticulous detail.</p></div>\n<div><p>He would pass on any information he could without relying on the radio, such as exactly how many visible tokens I currently held.</p></div>\n<div><p>I knew it wouldn't be long before that intel reached Ryuen's ears, prompting him to formulate his countermeasures.</p></div>\n<div><p>There was no need to rush, I will just proceed with the strategy as planned───</p></div>\n<div><p>“Hey, Ayanokōji-kun...“</p></div>\n<div><p>The voice came hesitantly from beside me.</p></div>\n<div><p>“Do you have a minute?”</p></div>\n<div><p>It was Hasebe from Class A. When I glanced past her, the other Class A students were gathered a short distance away, smiling and talking with Kushida at the center of the group. Hasebe’s departure from them had not drawn any particular attention. At least for the moment, no one seemed to be watching us closely.</p></div>\n<div><p>“Let's walk a bit slower,” I suggested.</p></div>\n<div><p>“Yeah, thanks.”</p></div>\n<div><p>We hung back to let the other students move ahead, then stepped off the main path toward the nearby beach, staying just close enough to keep the trail in sight. The sound of footsteps and conversation thinned behind us, replaced by the dry rush of wind and the steady breeze of the sea.</p></div>\n<div><p>Spotting a large rock nearby, I had Hasebe take a seat to keep her from burning through any more of her stamina.</p></div>\n<div><p>“How are your legs holding up?” I asked. “You must be burning through a lot of energy too with the endless hiking and tasks.”</p></div>\n<div><p>“Yeah, I'm managing,” she replied. “What about you, Ayanokōji-kun? Are you... actually, never mind. I doubt I need to worry about you.”</p></div>\n<div><img alt=\"Chapter Image\" width=\"600\" height=\"800\" src=\"/assets/y3v4_ch5.webp\"><span></span></div>\n<div><p>“I'm doing well enough in my own way,” I said. “How are things on your end?”</p></div>\n<div><p>“I'm not really sure. It’s hard to say without knowing how the other groups are doing, but I think we’re holding our own well enough.”</p></div>\n<div><p>It seemed that, for now at least, neither Hasebe nor the rest of the Class A students were feeling overly anxious.</p></div>\n<div><p>A stronger sea breeze swept across the shore.</p></div>\n<div><p>Hasebe narrowed her eyes against it and turned her gaze toward the water, where the sunlight scattered in countless bright fragments across the surface.</p></div>\n<div><p>“Do you feel guilty?” I asked.</p></div>\n<div><p>At my question, she turned back to face me, pausing for a moment in quiet contemplation.</p></div>\n<div><p>“If I said I didn’t feel any guilt at all,” she said at last, “that would be a lie…”</p></div>\n<div><p>With that preface out of the way, she continued. “But it's better than seeing you get expelled, Ayanokōji-kun. That's what I told myself... so I can honestly say I don't have any regrets. Was my advice helpful?”</p></div>\n<div><p>“Yeah, pretty much. Thanks to you, I managed to avoid taking the fall and getting expelled.”</p></div>\n<div><p>“I see. I'm glad.”</p></div>\n<div><p>It wasn't a forced smile; it was a genuine expression that Hasebe showed from the bottom of her heart.</p></div>\n<div><p>“Can I... you know, um... go back to calling you Kiyopon...?”</p></div>\n<div><p>“You really fixate on the strangest things,” I noted. “I don't mind, if that's what you prefer.”</p></div>\n<div><p>“...I'm glad. For me, using that nickname is kind of like a barometer, I guess? It just makes me feel a certain way... probably. Ugh, I don't know. What am I even saying?”</p></div>\n<div><p>She let out a self-deprecating laugh, fully aware her words were turning into a jumbled mess.</p></div>\n<div><p>“Once this uninhabited island exam is over and we're back at school, we should hang out over summer break,” she suggested.</p></div>\n<div><p>“I highly doubt Miyake or Yukimura would welcome that.”</p></div>\n<div><p>“Oh, right. I guess so. Then it can just be the two of us... ah, I mean, just for starters, you know?”</p></div>\n<div><p>“Alright. Just let me know whenever.”</p></div>\n<div><p>Seeing that I hadn't rejected her, but instead agreed without a second's hesitation, Hasebe broke into a genuinely delighted smile.</p></div>\n<div><h2>Part 3</h2></div>\n<div><p>It was half past six in the evening.</p></div>\n<div><p>The campsite for the second day had been fixed at B7, and no sooner had the decision been made the students began moving with practiced efficiency. Packs were lowered, tools were brought out, and the quiet rhythm of preparation spread through the site.</p></div>\n<div><p>Back when we were first-years, pitching a base camp had been an agonizing struggle. Now, regardless of whether they were boys or girls, it was something they had all grown incredibly well-accustomed to.</p></div>\n<div><p>“Their movements are finally starting to look the part, aren't they?” Morishita said, folding her arms with an air of authority. “If you ask me, they still have a long way to go, but I suppose I should offer some praise for achieving this much as mere high school students.”</p></div>\n<div><p>A rather bold stance for someone who had done absolutely nothing but watch since day one.</p></div>\n<div><p>“Ayanokōji-kun, you have an incoming radio call. It's from Nishikawa-san in your class. Can you take it?”</p></div>\n<div><p>The supervisor walked over relaying the message as he extended a two-way radio in my direction.</p></div>\n<div><p>I accepted it immediately and slipped the earpiece into place.</p></div>\n<div><p>“Could it be some sort of trouble?” Morishita mused aloud. “How bothersome.”</p></div>\n<div><p>“Sorry, but could you get the fire started in my place?” I asked.</p></div>\n<div><p>“Eeek.”</p></div>\n<div><p>I engaged the safety lock on the utility lighter and handed it over to Morishita, who had made a small joke (I guess?) with an expressionless face.</p></div>\n<div><p>“Well, just leave it to me,” Morishita said solemnly. “I'll make sure Ayanokōji Kiyotaka's bed is reduced to ashes.”</p></div>\n<div><p>“That would almost certainly result in expulsion, so please take this seriously.”</p></div>\n<div><p>I was slightly concerned, but I couldn't afford to keep Nishikawa waiting. Deciding to put my faith in her, I left the lighter in Morishita's hands.</p></div>\n<div><p>“Sorry for the wait.”</p></div>\n<div><p>The moment I responded, Nishikawa launched right in, her tone brimming with her usual energy.</p></div>\n<div><p>“Yahoo, Ayanokōji-kun. Do you have a second? There's something I wanted to get your advice on.”</p></div>\n<div><p><em>Advice? Did something happen?</em></p></div>\n<div><p>“What is it?”</p></div>\n<div><p>“I was just getting a little worried about the token counts for the other groups. Aren't you worried, Ayanokōji-kun?”</p></div>\n<div><p>“Of course it's on my mind. I'm especially concerned about Shiraishi and the others who ended up in Ryūen's group. Under normal circumstances, I don't think they'd make a mistake that would wipe out their tokens, but in this case, even that isn't a guarantee.”</p></div>\n<div><p>The possibility that they could fall into some sort of trap and hit zero, even if only for a fleeting moment, couldn't be completely ruled out.</p></div>\n<div><p>“Even if they haven't hit zero, someone might be struggling because they're dangerously close to it.”</p></div>\n<div><p>“Is there a specific student you're worried about?”</p></div>\n<div><p>Her tone practically gave the answer away, but I deliberately feigned ignorance.</p></div>\n<div><p>“I want to know how Asuka is doing.”</p></div>\n<div><p>Perhaps sensing I had seen right through her, Nishikawa dropped the pretense and got straight to the point. She must have been harboring the same concerns I had since early on.</p></div>\n<div><p>To find out a specific person's exact token count, the only surefire methods were to make direct physical contact or call them on the radio. The former relied heavily on luck, while the latter cost precious tokens. Neither was a simple matter.</p></div>\n<div><p>“Wouldn't calling Shiraishi directly solve your problem?” I asked.</p></div>\n<div><p>“She's a kind girl. Even if she were in trouble, I feel like she'd hide the truth from me. But since you're the class leader, Ayanokōji-kun, I think she'd answer you honestly.”</p></div>\n<div><p>“I see. It's true that the only way to confirm her exact tokens without meeting in person is over the radio. Unfortunately, I have no intention of wasting a token just for that. I don't approve of how you're using the radio right now, either.”</p></div>\n<div><p>“...But what if she really is in trouble?”</p></div>\n<div><p>I had laced my words with a hint of reprimand, but Nishikawa's voice remained completely unfazed.</p></div>\n<div><p>“She might be desperately hoping for help,” she added.</p></div>\n<div><p>“You really don't want to see Shiraishi expelled, do you?”</p></div>\n<div><p>“Of course I don't. She's a dear friend of mine.”</p></div>\n<div><p>“That may be true. But plenty of other students share those exact same feelings and relationships. ‘I don't want him to be expelled,’ or ‘I want to protect her’— you aren't the only one who thinks that way, Nishikawa.”</p></div>\n<div><p>“That's why I came to you for advice,” she said. “Honestly, I'm perfectly willing to use my own tokens to contact her. But it might end up being a waste, and more importantly, I don't want to disrupt the class's harmony. That's why I'm asking.”</p></div>\n<div><p>“So, if I tell you ‘no’ right now, will you obediently hold back?”</p></div>\n<div><p>“I wonder about that…”</p></div>\n<div><p>Perhaps Nishikawa also understood what my answer would be, as she muttered evasively but with a hint of irritation.</p></div>\n<div><p>“How you use your personal tokens is up to you. If you absolutely must know how Shiraishi is doing, I have no right to stop you. However, confirming her token count now will only buy you a fleeting moment of peace of mind. In fact, if you find out she really is struggling, it will only fuel your anxiety.”</p></div>\n<div><p>If that happened, she would inevitably use the radio to contact Shiraishi again a few hours later, wasting even more tokens. Her focus on the exam would fracture, leading to a drop in efficiency. Factoring that in, even if Shiraishi were to inflate her token count to reassure her, she certainly wouldn't under-report it.</p></div>\n<div><p>“Shiraishi is highly capable. Don't you think the odds of her falling to last place are quite low right now?” I asked.</p></div>\n<div><p>“I won't deny that. But there are no absolute guarantees, right?”</p></div>\n<div><p>“I suppose it depends on who she's up against.”</p></div>\n<div><p>“If she only has a few tokens left, I have to do something.”</p></div>\n<div><p>“Are you prepared to protect her even if it means sacrificing yourself?”</p></div>\n<div><p>“No way, that's impossible. It wouldn't mean anything if Asuka gets to stay at this school but I get expelled,” Nishikawa answered without hesitation. “However, if it means protecting Asuka, I don't care if someone else has to be the sacrifice.”</p></div>\n<div><p>“Are you saying that, in a worst-case scenario, I should sacrifice someone other than you or Shiraishi?”</p></div>\n<div><p>“Exactly. That's precisely why we made you the leader, Ayanokōji-kun. Because I believe you're capable of making ruthless decisions for us.”</p></div>\n<div><p>It seemed Nishikawa's little ‘consultation’ carried far more weight than I had originally anticipated.</p></div>\n<div><p>“Sorry, but I have my own way of doing things.”</p></div>\n<div><p>“Are you saying... you won't help her?”</p></div>\n<div><p>“My role isn't to decide whether or not to save Shiraishi. It's to ensure we never end up in a situation where we have to make that kind of binary choice in the first place.”</p></div>\n<div><p>“That's reassuring,” Nishikawa said. “But doesn't that also mean if push comes to shove, we have no idea what kind of decision you'll actually make?”</p></div>\n<div><p>“If you can't trust me, then you'll just have to handle it yourself. If you manage to earn more tokens than anyone else, there's a chance you could save Shiraishi entirely on your own.”</p></div>\n<div><p>“Hey, Ayanokōji-kun. You don't actually think our class doesn't matter, do you? Because if you're secretly a spy for Class A, that really wouldn't be funny.”</p></div>\n<div><p>With a cold, accusatory tone, she mercilessly stabbed the words into me.</p></div>\n<div><p>“I won't say it's too late to be bringing that up now,” I replied. “I know it will take time to earn everyone's understanding.”</p></div>\n<div><p>“I guess so. I just can't place my complete trust in you yet. So, if you want me to get to that point, cooperate with me. Contact Asuka.”</p></div>\n<div><p>“I have no intention of repeating myself.”</p></div>\n<div><p>“Right... That's a shame, but it looks like we're out of time. I'll hold back for today, but I’ll make no promises about tomorrow.”</p></div>\n<div><p>Saying that, Nishikawa ended the call.</p></div>\n<div><p>“Thank you,” I said as I handed the radio back to the supervisor.</p></div>\n<div><p>I turned my eyes toward Morishita at once, who was supposed to be busy setting up the fire.</p></div>\n<div><p>“What exactly are you doing?”</p></div>\n<div><p>“Eeek.”</p></div>\n<div><p>“No, never mind that.”</p></div>\n<div><p>Instead of holding the ignition lighter I had just given her, Morishita was crouching on the ground, drawing a picture in the dirt.</p></div>\n<div><p>“I thought I'd leave behind a dying message,” she said. “It's a sketch of the culprit.”</p></div>\n<div><p>“I have no idea who that's supposed to be, but more importantly, I’m fairly certain I asked you to start the fire.”</p></div>\n<div><p>“Oh, details like that hardly matter,” Morishita replied, “It will be all the same if Ayanokōji Kiyotaka does it now. Please, feel free to burn it to your heart’s content.”</p></div>\n<div><p>Saying that, she lifted her foot, picked up the lighter she had been stepping on, and held it out to me: the nozzle pointed directly at my face. Much like a pair of scissors, common sense dictated handling these tools over in a way that posed no danger to the recipient, but she clearly didn't care. To make matters worse, her finger was resting right on the lever.</p></div>\n<div><p>Just as I reluctantly reached out to take it, she suddenly squeezed the trigger, attempting to ignite it right in my face.</p></div>\n<div><p>However, nothing happened..</p></div>\n<div><p>“A misfire?!” she gasped.</p></div>\n<div><p>Naturally, it didn't ignite. I had engaged the safety lock before handing it to her.</p></div>\n<div><p>“You're a dangerous person, you know that?”</p></div>\n<div><p>“It was a joke, of course,” she replied. “I knew the lock was on; I merely wanted to give you a fright.”</p></div>\n<div><p>“Knowing the lock is on doesn't excuse trying to ignite a lighter while pointing it at someone.”</p></div>\n<div><p>“More importantly,” Morishita said, brushing past that point with no sign of reflection, “what were you discussing with Ryōko Nishikawa?”</p></div>\n<div><p>“She said she was worried about Shiraishi and wanted me to check on her. When I refused, she accused me of being a spy for Class A.”</p></div>\n<div><p>“Oho. A rather sharp observation, coming from her. I must admit, I was just beginning to harbor that very same suspicion once again myself. The ‘Ayanokōji Kiyotaka is a Class A Spy’ theory.”</p></div>\n<div><p>“Is that so?”</p></div>\n<div><p>“Watching you up close these past two days, I can't help but feel like you've been particularly preoccupied with Kushida Kikyō. It certainly seems to go far beyond simply worrying about a former classmate.”</p></div>\n<div><p>\"I see. So it looks that way even from an outside perspective?\"</p></div>\n<div><p>\"It certainly does. Or rather, that ‘even’ is practically a confession! You just said, ‘even from the outside.’ I caught that!”</p></div>\n<div><p>She flashed me a smug little grin, looking exactly like a detective who had just backed a criminal into a corner.</p></div>\n<div><p>\"It's true that Kushida Kikyō appears to be quite capable in her own right,” Morishita continued. “But even so, you two have been a bit too close. To the point where I'm honestly startin' to think, ‘Are ya actually in love with her or somethin', yo?’”</p></div>\n<div><p>Why did she suddenly switch to a casual tone? Or rather, why does she sound like a total delinquent now?</p></div>\n<div><p>“Let me ask you something. Even if that were the case, would it cause any problems?” I asked.</p></div>\n<div><p>“Let me ask you this in return: do you honestly think it wouldn't?”</p></div>\n<div><p>“Anyone can see that Kushida is an exceptional student,” I said. “Even you can't deny that. Therefore, there's no doubt that she's the most suitable person to keep this group running smoothly. The presence or absence of romantic feelings is completely irrelevant.”</p></div>\n<div><p>“If you desire an exceptional student, why not your classmate Sanada so-and-so, or Katsuragi so-and-so? There's no need to limit it exclusively to Kushida Kikyō, is there?”</p></div>\n<div><p>“We were in the same class for two years. I have a much clearer understanding of Kushida's capabilities.”</p></div>\n<div><p>“Because she's a former classmate, you say? My, my, how very suspicious. The plot thickens. It almost sounds like you'd swoop in and protect her from Shinohara so-and-so and her friends if push comes to shove. Let me be perfectly clear: I will not give you a single one of my tokens, you thief.”</p></div>\n<div><p>I had already settled today’s portion properly, but it seemed likely she would continue pressing me on the details from tomorrow onward.</p></div>\n<div><p>“Interpret it however you like.”</p></div>\n<div><p>“Well, rest assured, I won't get angry at you for looking at Kushida Kikyō through rose-tinted glasses and playing favorites. Because as long as I am kept safe, I'm perfectly willing to turn a blind eye to it. Therefore, please make absolutely sure to prioritize me over Sanada so-and-so and Yoshida so-and-so.”</p></div>\n<div><p>So, in the end, all that mattered to Morishita was that her own safety was guaranteed.</p></div>\n<div><p>“Even so, you sure use ‘so-and-so’ a lot. I've been pondering this for a while now, but if you don't know their given names, there's no need to force yourself to use their full names, is there?”</p></div>\n<div><p>“Then allow me to ask you this,” Morishita said. “What would you do if there were thirty people in the class with the surname Yamada? If you called out, ‘Hey, you there, Yamada,’ thirty boys and girls would all turn around at once. It would be absolute chaos! Surely it would be more convenient to know whether one meant Yamada Jirō or Yamada Hanako?”</p></div>\n<div><p>While Yamada is certainly a common surname, it wasn't exactly the most populous in the country. A scenario where thirty people in the same class shared the exact same surname was practically unthinkable anyway.</p></div>\n<div><p>It had been quite some time since I first met Morishita, but I still couldn't figure her out.</p></div>\n<div><p>“Ayanokōji, come here a sec.”</p></div>\n<div><p>Yoshida raised his voice and beckoned me over. A shadow had fallen over his expression, leading me to suspect that, right on the heels of my conversation with Nishikawa, yet another problem had cropped up.</p></div>\n<div><p>“Let's go, Morishita,” I said.</p></div>\n<div><p>“No, thank you,” Morishita replied at once. “It may be a troublesome matter, and I would prefer to avoid such things. I shall remain here and light the fire. Please lend that to me.”</p></div>\n<div><p>With that, she snatched the lighter right out of my hand.</p></div>\n<div><p>Leaving her in charge of the fire felt incredibly risky, but I decided to put my faith in her just this once. Then I hurried over to Yoshida to hear what was going on.</p></div>\n<div><p>“I don't really want to stick my nose in other people's business, but Shinohara is seriously crossing a line,” he muttered gesturing vaguely with his chin toward the members of Class A, who were huddled together in a tight group. “It looks like she distributed tokens to Wang and Ike, but Kushida hasn't been given a single one.”</p></div>\n<div><p>“Kushida hasn't? Why?” I asked.</p></div>\n<div><p>It appeared that Class A's internal drama, which was supposed to be kept under wraps, had already leaked. Whether Shinohara had let it slip, Kushida had skillfully orchestrated the leak, or it had come from an entirely different source altogether, I couldn't be sure. Regardless, there was no point in trying to track down the culprit now.</p></div>\n<div><p>A short distance away, Katsuragi and several Class D students who had evidently caught wind of the rumor were already approaching Class A. An argument seemed to be breaking out, and I could already see the anger flashing across Shinohara's face.</p></div>\n<div><p>“We should probably head over there,” Yoshida said. He broke into a jog, and Sanada and I quickly followed suit.</p></div>\n<div><p>“You guys are here too? What the hell is going on?” Shinohara immediately directed her frustration at Yoshida before shooting a sharp glare in my direction.</p></div>\n<div><p>“I heard you aren't giving any tokens to Kushida,” Yoshida said. “Just because you're the representative doesn't mean you get to do whatever you want.”</p></div>\n<div><p>“...This has nothing to do with you, Yoshida-kun.” Shinohara shot back. “We in Class A have our own strategies we're desperately trying to figure out in order to win. I don't know if you eavesdropped or what, but mind your own business. Don't butt in when you're from another class.”</p></div>\n<div><p>Her counterargument was perfectly valid; under normal circumstances, this wasn't a matter Yoshida and the others had any right to interfere in.</p></div>\n<div><p>“But we're in a group together,” Yoshida argued. “Stop disrupting the harmony.”</p></div>\n<div><p>“Who's the one disrupting things here?” Shinohara demanded. “If we change our strategy because of you and end up losing, are you going to take responsibility for it?”</p></div>\n<div><p>“That's…”</p></div>\n<div><p>Faced with her forceful rebuttal, Yoshida faltered and took a step back. I, on the other hand, stepped forward, closing the distance between Shinohara and myself.</p></div>\n<div><p>“What?” she said, fixing me with a hard, unflinching stare. “Do you have something to complain about too, Ayanokōji-kun?”</p></div>\n<div><p>Her eyes held a stronger wariness toward me than they had toward Yoshida.</p></div>\n<div><p>“If Horikita were to find out about this,” I said. “Wouldn't your position be in a bit of jeopardy?”</p></div>\n<div><p>“Huh? Is that a threat?” She scoffed. “...This has nothing to do with you, Ayanokōji-kun.”</p></div>\n<div><p>“If this were a strategy meant to secure victory, I could understand it. But what you’re doing is letting your own self-preservation and personal resentment take priority.”</p></div>\n<div><p>“Satsuki ain't that kind of person! You just don't get her!”</p></div>\n<div><p>Stepping in to protect his girlfriend, Ike shoved himself right into my face. He was practically seething, radiating an intensity that made it seem like he might grab me by the collar at any second.</p></div>\n<div><p>Sonoda and Morofuji, who had been watching from farther away, seemed to notice the rising tension as well. Drawn by the commotion, they began moving toward us.</p></div>\n<div><p>“Perhaps you really are executing this as a legitimate strategy,” I said. “But to the people around you, it certainly doesn't look that way. It looks like you're abusing your authority as the representative to suppress and control someone more capable than yourself. It looks like, in a worst-case scenario, you're planning to save your own skin even if it means kicking Kushida down to do it.”</p></div>\n<div><p>“Are you kidding me? What's with these baseless accusations!” Shinohara snapped. “I became the representative for the sake of Class A, and I'm managing things so we can win. Stop making up stories based on your own warped speculation!”</p></div>\n<div><p>Ever since we had formed this group, a lingering grudge had festered between us. Naturally, confronting her with such a harsh rejection of her methods was bound to invite hostility.</p></div>\n<div><p>At this point, I shifted my gaze toward Katsuragi, who had been observing from the sidelines, and the two Class B students who had hurried over.</p></div>\n<div><p>“Since we're on the subject,” I continued, “I’ll say this as well. I have some doubts about Class B’s policy too. I’m not saying a performance-based reward system is inherently bad. But when it’s handled too openly, I can’t say I’m impressed.”</p></div>\n<div><p>Sonoda, clearly not expecting the sparks to fly his way, furrowed his brows in annoyance.</p></div>\n<div><p>“What the hell is that supposed to mean?” he said. “Another class has no business criticizing our policy. And I hate to put it this way, but especially not you.”</p></div>\n<div><p><em>A class traitor. </em>It was obvious they had no intention of taking advice from me, a person already at odds with Class A.</p></div>\n<div><p>“Yeah, exactly! This ain't something for an outsider to butt into, Ayanokōji!” Seizing the opportunity, Ike quickly sided with Sonoda, attempting to drag their representative into the fray. “Right, Katsuragi?”</p></div>\n<div><p>“It's true that it's none of his business. But the same goes for you and Class A, Ike,” Katsuragi replied heavily. Unable to stand being lumped into the same category as Shinohara, he made his dissatisfaction clear. “I am making judgments fairly in my own way, and distributing tokens among my three group members accordingly. But as Ayanokōji pointed out, Shinohara is controlling Class A's tokens entirely on a whim. That is not fair.”</p></div>\n<div><p>“No, no, it's completely different! Satsuki is managing things on our end so we don't lose. The strategy is to properly redistribute them at the right time. Were you even listening to the explanation?” Ike complained, as if to say, <em>And here I went out of my way to become your ally.</em></p></div>\n<div><p>“If that is truly the case, then you should conduct yourselves in a way that actually convinces Kushida of that.”</p></div>\n<div><p>At Katsuragi's words, Shinohara let out a mocking laugh.</p></div>\n<div><p>“Isn't that, like, the exact same for you, Katsuragi-kun? Can you confidently say Ibuki-san is completely convinced by your methods?”</p></div>\n<div><p>As evidenced by the fact that Ibuki was nowhere to be seen, it was safe to assume she was highly dissatisfied with Katsuragi's policies.</p></div>\n<div><p>“...Perhaps you are right.”</p></div>\n<div><p>Receiving Shinohara's unexpected counterattack, Katsuragi averted his gaze, patted Sonoda on the shoulder, and backed away.</p></div>\n<div><p>“There, see?” Ike said, raising his voice. “The rest of you, back off! Don’t get in our way!”</p></div>\n<div><p>At his words, the Class D students began to withdraw. Class C quickly followed as well.</p></div>\n<div><p>Within Group 3, irreversible misalignments in the gears had begun to steadily form due to the clashing policies of the representatives. On one side was Kushida, who was performing well enough but hadn't received a single token due to Shinohara's management. On the other was Ibuki, who was unable to perform as she wished and was thus drip-fed a meager amount of tokens.</p></div>\n<div><p>Of course, Kushida simply hadn't received her distribution yet, so her situation wasn't completely identical to Ibuki's. However, since her chances of receiving her fair share rested entirely in Shinohara's hands, the two girls were in remarkably similar positions when it came to their underlying anxiety.</p></div>\n<div><p>Without a doubt, within Group 3, those two were currently the prime candidates for last place.</p></div>\n<div><p>“What a wonderfully harmonious group we are.”</p></div>\n<div><p>As I looked over to find the source of the comment, I saw Morishita spectating from afar.</p></div>\n<div><p>The campfire still had not been lit.</p></div>\n<div><h2>Part 4</h2></div>\n<div><p>After a break filled with unrest, and after dinner had passed in much the same unsettled air, two more tasks were announced, just as they had been the previous day.</p></div>\n<div><p>The category was ‘Team’.</p></div>\n<div><p>In these tasks, Class A managed a respectable result of taking second place twice, but naturally, Shinohara showed no sign of handing any tokens over to Kushida.</p></div>\n<div><p>Though a faint look of anxiety occasionally surfaced on Kushida's face, she outwardly maintained the stance that she had complete faith in Shinohara.</p></div>\n<div><p>The student known as Kushida Kikyō was the type of person who was kind to everyone, perpetually cheerful, and deeply trusting of others. From the perspective of students in other classes, the impression she gave wasn't vastly different from Ichinose. Because of that carefully crafted image, she couldn't simply air her grievances in public and demand, ‘I can't trust you, Shinohara, so hand over my tokens.’</p></div>\n<div><p>That was precisely Shinohara's aim, and it seemed Kushida was being successfully taken advantage of.</p></div>\n<div><p>I walked over to where Class A was huddled together and called out to her.</p></div>\n<div><p>“I need to talk to you for a second.”</p></div>\n<div><p>“The hell do you want, Ayanokōji? What're you plotting?”</p></div>\n<div><p>Ike immediately jumped to his feet, stepping into my path as if to protect Kushida.</p></div>\n<div><p>More accurately, I figured he was doing it to prevent anyone from interfering with Shinohara's policies as the representative. However, far from pleasing his girlfriend, his aggressive posturing seemed to be having the exact opposite effect as Shinohara looked rather displeased with him.</p></div>\n<div><p>“I just came to talk to her as a fellow member of Group 3,” I said.</p></div>\n<div><p>“You think that excuse is gonna fly?” Ike shot back. “Sorry, but we don't trust you.”</p></div>\n<div><p>“I wasn't asking you, Ike,” I said, before walking past him. “Kushida, there are too many distractions here, so why don't we go somewhere else to talk?”</p></div>\n<div><p>At my invitation, Kushida slowly rose to her feet.</p></div>\n<div><p>“You can't go,” Shinohara warned her. “You know it'll look like an act of betrayal, right?”</p></div>\n<div><p>“It's fine, Satsuki, I won't let her go,” Ike said before turning toward Kushida, his tone softening at once. “Kikyō-chan, we're definitely not gonna treat you badly or anything, so you shouldn't get involved with Ayanokōji. We have no idea what he's scheming.”</p></div>\n<div><p>“It's okay, Ike-kun.” Kushida looked away from me, turning to offer him a gentle smile. “People have been saying all kinds of things, but I believe in everyone from Class A. I believe in you, Ike-kun.”</p></div>\n<div><p>Saying that, she shifted her gaze from Ike to Shinohara, then to Mii-chan, before looking back at Ike once more.</p></div>\n<div><p>“You especially have been looking out for me this whole time. I’m really grateful for that.”</p></div>\n<div><p>“R-Really?” Ike’s expression loosened. “Well, I mean, it's only natural since we're allies.”</p></div>\n<div><p>He chuckled, lightly rubbing a finger under his nose in a bashful display. However, upon noticing Shinohara glaring daggers at him, he immediately snapped back into a serious expression.</p></div>\n<div><p>“So, I'm sorry, but I can't go with you, Ayanokōji-kun,” Kushida said to me.</p></div>\n<div><p>Mouthing the words <em>‘Serves you right’ </em>from an angle where Shinohara couldn't see his face, Ike shooed me away.</p></div>\n<div><p>“Looks like you got rejected pretty harshly,” Yoshida laughed teasingly, having watched the exchange from near the tents.</p></div>\n<div><p>“It's only natural for Class A to be wary of you, Ayanokōji-kun,” Sanada added. “Even if I were in their position, I imagine I would have handled it similarly. Though, I wouldn't have been so hostile about it, of course.”</p></div>\n<div><p>“But why are you so concerned about Kushida?” Yoshida asked. “I mean, sure, I feel bad for her, but like they just said, it's not really something another class should be sticking their nose into.”</p></div>\n<div><p>“I just can't leave her alone,” I replied.</p></div>\n<div><p>“Wait...” Yoshida’s eyes narrowed slightly. “Don’t tell me…”</p></div>\n<div><p>“Have you finally noticed?” Morishita chimed in. “It seems our dear Ayanokōji Kiyotaka harbors simply extraordinary feelings for her.”</p></div>\n<div><p>“Oh, man,” Yoshida said, pressing a hand to his forehead.</p></div>\n<div><p>Without giving an answer to the two of them as they got worked up over their own assumptions, I stepped away and headed into my tent ahead of them.</p></div>\n<div><p>Not only Shinohara and Ike, but Yoshida and the others had now thoroughly taken note of my unusual behavior.</p></div>\n<div><p>That was a major gain for me.</p></div>\n<div><p>Ibuki and Kushida. The candidates I intended to have expelled from this school.</p></div>\n<div><p>By the day after tomorrow, their fates would be sealed.</p></div>",
    "8": "<div><p>The morning of the third day dawned. Just as most of us had anticipated, the supervisor explained that today’s itinerary would center heavily around the ‘Group’ category. Our schedule had been pre arranged by the school, pitting us against a gauntlet of rival groups throughout the day.</p></div>\n<div><p>Victory against an opposing group would yield tokens, which could be distributed through one of two distinct methods. The first was an equal split, awarding a uniform number of tokens to everyone in the victorious group; under this system, no disparity in standing would arise among the members of Group 3. The alternative method rewarded individual merit rather than collective success: regardless of whether the group won or lost overall, the top three performing students would be evaluated and granted a set number of tokens. Yet, no matter which distribution method was applied, the tokens would still be handed over in bulk to the group's representative first.</p></div>\n<div><p>To make matters worse, shorter Individual and Team tasks were slated to be squeezed into the brief intervals between these larger events. It was guaranteed to be an exhausting day; just as much as the second, if not more so.</p></div>\n<div><p>That collective sense of dread shared by the students soon proved entirely justified.</p></div>\n<div><p>The moment we broke camp at eight o'clock, we immediately ran into Group 10, which belonged to Hashimoto. With scarcely a moment to exchange pleasantries, we were thrust right into a unique task that made use of the uninhabited island's terrain.</p></div>\n<div><p>By the time the hour-long match concluded, there wasn't even a spare second to congratulate one another on a hard-fought battle; we were immediately herded toward the next designated area. After repeating this exhausting cycle of marching and competing against other groups three separate times, our much-needed lunch break finally arrived.</p></div>\n<div><p>Though this thirty-minute window ostensibly doubled as free time, most students still huddled closely with their respective teams to eat. There were probably various things to discuss, such as checking the tokens acquired in the morning and consulting about the afternoon. Even someone as typically solitary as Ibuki remained close to the Class B encampment.</p></div>\n<div><p>Amidst all that, Kushida stood out as the sole, glaring exception.</p></div>\n<div><p>While she was seated nearest to Class A, she maintained a deliberate physical distance, quietly eating her lunch in total isolation.</p></div>\n<div><p>The rift that had formed between her and Shinohara was painfully obvious, and there was no doubt she was suffering the fallout of that fractured dynamic. It wasn't as if her sudden isolation had gone unnoticed, students like Yoshida and Katsuragi cast concerned glances her way, but given the nature of the exam and the constant friction between teams, no one could afford to carelessly extend a helping hand.</p></div>\n<div><p>“I can barely stomach watching this,” Yoshida muttered. “They keep hiding behind excuses like ‘strategy’ and ‘team policy,’ but isn't this going a bit too far? Does Shinohara have some kind of vendetta against Kushida?”</p></div>\n<div><p>“If you observe her boyfriend's attitude, it's not entirely incomprehensible. His eyes are constantly chasing after Kushida Kikyō, after all,” Morishita noted.</p></div>\n<div><p>“You mean Ike? ...Are you saying he's comparing her to Shinohara or something?” Yoshida shot Morishita a skeptical look, clearly thinking she was reading too much into it.</p></div>\n<div><p>“Even you would hate it if your girlfriend was mesmerized by another man, right, Yoshida so-and-so? Oh, wait, since you don't have a girlfriend and never will, that might be too hard for you to grasp.”</p></div>\n<div><p>“Shut up. Don't just casually spit venom at me,” he grumbled. “...Though, if that were true, yeah, I'd definitely hate it.”</p></div>\n<div><p>Even without a girlfriend of his own, he could easily imagine how much that would sting.</p></div>\n<div><p>“But it can't really be helped, can it? I mean, between Kushida and Shinohara, they're just on entirely different levels, or rather…”</p></div>\n<div><p>“That line of thinking makes you absolute trash, Yoshida so-and-so.”</p></div>\n<div><p>“Stop with the ‘so-and-so’ already. At least call me Kenta. If you're going to use my full name, that is.”</p></div>\n<div><p>Those two seemed convinced that Shinohara had isolated Kushida, but the reality was likely quite different. It was far more probable that Kushida was intentionally distancing herself, carefully orchestrating her own isolation.</p></div>\n<div><p>She was playing the tragic heroine to the hilt, monopolizing the sympathetic gazes of everyone around her. Her goal was simple: to firmly establish Shinohara as the villain unless she coughed up some tokens to make amends. It was a brazen, all-or-nothing tactic, and whether it would actually work on Shinohara remained to be seen.</p></div>\n<div><p>“Ayanokōji-kun. Nishikawa-san is requesting to contact you via the radio,” the supervisor said.</p></div>\n<div><p>I had been curious to see what Nishikawa would do after I’d given her a day to mull things over. So she was already reaching out again, huh?</p></div>\n<div><p>I accepted the radio handed to me by the supervisor.</p></div>\n<div><p>“Is she calling to confirm Shiraishi Asuka's survival again?” Morishita asked.</p></div>\n<div><p>“Huh? What about Shiraishi?” Yoshida chimed in.</p></div>\n<div><p>\"Please do not butt into the conversation without permission. Having you listen in will only make things unnecessarily complicated, Kenta Yoshida.\"</p></div>\n<div><p>“Why is my first name first!?”</p></div>\n<div><p>Leaving Morishita to handle Yoshida— no, rather, leaving Yoshida to handle Morishita— I stepped a short distance away to take the call.</p></div>\n<div><p>Ultimately, her questions were identical to the ones she’d asked the other day: she wanted to verify Shiraishi's token count and needed reassurance that the girl was absolutely safe. My answer hadn't changed, but the situation certainly had. I told her over the radio to sit tight just a little longer, assuring her that within a few hours, I would arrange an outcome she would find acceptable.</p></div>\n<div><h2>Part 1</h2></div>\n<div><p>Once everyone had finished their lunch, I returned the radio to the supervisor.</p></div>\n<div><p>I then made my way back to Class C, who were already packing up.</p></div>\n<div><p>“That was quite a long talk. Did Nishikawa Ryoko persistently cling to you?” Morishita asked.</p></div>\n<div><p>“No, I was speaking with someone else about a separate matter.”</p></div>\n<div><p>“A separate matter? I see, so Ayanokōji Kiyotaka has finally made his move?”</p></div>\n<div><p>Morishita's gaze sharpened slightly. I had expected her to follow up with one of her usual nonsensical jokes, but it seemed I was mistaken.</p></div>\n<div><p>“You don't need to hide it,” she continued. “This special exam has felt a bit too ordinary, or rather, devoid of any significant developments. I had a sneaking suspicion you were just biding your time, waiting for the perfect moment to strike.”</p></div>\n<div><p>For all her eccentricities and goofing around, she truly possessed a sharp mind beneath the surface.</p></div>\n<div><p>“Yes, I did let an arrow loose,” I admitted.</p></div>\n<div><p>“Oho-ho-ho, an arrow, you say? And what exactly are we supposed to do from here on out?”</p></div>\n<div><p>“Instructions haven't changed. As long as the groups are operating separately, your fundamental goal is simply to collect tokens in earnest. Even though there’s no restriction on transferring them, the moment a token changes hands, it’s treated as a back-side token. Therefore, all you need to focus on is tackling the tasks and acquiring as many front-side tokens as possible. That remains the most optimal path toward victory.”</p></div>\n<div><p>“Indeed. Within Group 3, Ayanokōji Kiyotaka is undoubtedly a head above the rest and currently winning. Even if there's a student in a rival group who has amassed a similar number of front-side tokens, as long as you secure a 100% multiplier on the final day, you'll have a solid chance of clinching the win. Well, I suppose our opponents are banking on that exact same logic.”</p></div>\n<div><p>“It's not a system that strictly demands overwhelmingly dominant individual scores,” I explained. “If anything, it’s designed so that any well-rounded student can amass a high number of front-side tokens depending on how the match-ups play out.”</p></div>\n<div><p>Despite the structural elements of teams and groups, the exam was ultimately a framework where individual talent and effort directly translated into results. Overcomplicating the mechanics would only leave you overwhelmed.</p></div>\n<div><p>“But that’s only if you're solely focused on winning,” I added. “The other face of this special exam is the severe weight of its penalties. The real test lies in devising a strategy to reliably avoid them.”</p></div>\n<div><p>“Ah, so that's the kind of arrow you let loose… Well then, how exactly do you intend to avoid it?”</p></div>\n<div><p>“That is still a secret.”</p></div>\n<div><p>“Good grief. Do the higher-ups not understand that excessive secrecy only leads to unnecessary casualties?”</p></div>\n<div><p>With a dismissive shrug, Morishita turned and walked away, looking as though she’d entirely lost interest in the topic.</p></div>\n<div><p>“She backed down surprisingly easily,” I muttered to myself.</p></div>\n<div><p>Or perhaps she judged that simply confirming I had set things in motion was enough.</p></div>\n<div><p>Whether she trusted me or not, she was undeniably a difficult person to read.</p></div>\n<div><h2>Part 2</h2></div>\n<div><p>The trials marched on, though the routine quickly grew monotonous. We were essentially just tackling tasks reminiscent of past special exams, scraping together whatever tokens we could across the three categories.</p></div>\n<div><p>Naturally, the other students were fighting tooth and nail to secure every last token, but my focus had long since shifted past that stage. The total number of tokens in circulation had been fixed from the very beginning; the only variable was which group, which class, and which specific individuals they would ultimately fall to. To put it bluntly, I had already concluded that winning or losing the exam itself was little more than an added bonus.</p></div>\n<div><p>The arrow I let loose now sped unerringly toward its destined victim.</p></div>\n<div><p>Tomorrow, it would find its mark.</p></div>\n<div><p>Before they even realized it, most of the students had already found their eyes drawn to its flight, quietly predicting how it would all end. Only a select few remained ignorant of what was coming.</p></div>\n<div><p>If everything proceeded according to plan, the arrow would pierce its intended target, and the masses would emerge unscathed.</p></div>\n<div><p>Yet there were always exceptions.</p></div>\n<div><p>With so many eyes following its flight, it wouldn't be surprising if someone tried to snatch the arrow from the air before it struck.</p></div>\n<div><p>By six o'clock that evening, we reached our final destination for the day and were finally granted a reprieve.</p></div>\n<div><p>At that moment, Yoshida let out a heavy sigh, exhaling the day's accumulated exhaustion all at once.</p></div>\n<div><p>“This is the last time we'll have to pitch these tents, isn't it?” Sanada asked.</p></div>\n<div><p>“Sure feels like the end is finally in sight, but who knows?” Yoshida answered. “Even if this specific special exam wraps up tomorrow, there's always a chance the school keeps us out here on the uninhabited island.”</p></div>\n<div><p>“I'd really prefer to hope... that isn't the case,” Sanada replied.</p></div>\n<div><p>As I listened to their exchange, movement caught the corner of my eye. Shinohara was marching off with Kushida in tow, with Ike and Mii-chan trailing slightly behind them. They began setting up their camp a considerable distance away from the rest of us.</p></div>\n<div><p>Of the four classes in our group, only theirs was isolating itself to such an extreme degree.</p></div>\n<div><p>“What's with that? What are those guys doing?” Yoshida muttered, following my gaze.</p></div>\n<div><p>“Perhaps they're dissatisfied with having outsiders meddle in Class A's policies,” Sanada suggested. “If they distance themselves that much, there's no way we can eavesdrop on their conversations.”</p></div>\n<div><p>He was right. No matter how hard we strained our ears, picking up their voices from here would be impossible. And if anyone tried to close the gap, the attempt to make contact would be instantly obvious to Class A.</p></div>\n<div><p>“That's definitely Shinohara's doing,” Yoshida concluded. “Let's just leave them be.”</p></div>\n<div><p>After that, we slowly proceeded with our preparations, and by the time we finished eating dinner, darkness had fully settled over the surrounding area.</p></div>\n<div><p>Mii-chan, who emerged from the vicinity of Class A's tents, scanned the area before her eyes locked onto mine.</p></div>\n<div><p>Her gaze sent a clear, desperate signal: Help.</p></div>\n<div><p>“Sorry, but I'll leave the rest of this to you for a bit,” I told Sanada. He willingly agreed, and I briskly made my way over to Mii-chan.</p></div>\n<div><p>Seeing me approach, she jogged over to meet me halfway.</p></div>\n<div><p>“This is about Shinohara and the others, isn't it?” I asked.</p></div>\n<div><p>“...Yes,” she admitted. “Kushida-san begged them to share some tokens with her, but Shinohara-san completely refused to listen... They're arguing about it right now.”</p></div>\n<div><p>“Understood. I'll go see what's going on.”</p></div>\n<div><p>“Um, but... that might be a problem…” She stopped me, her expression fraught with guilt, and quietly began to explain why. “I was told to keep watch and make sure no one else comes near them. If anyone tried to approach, I was ordered to stop them at all costs... especially you, Ayanokōji-kun... Those were Shinohara-san's orders.”</p></div>\n<div><p>Just as I suspected. Shinohara was highly vigilant against Kushida and me making contact. Ever since this special exam began, my stance of consistently evaluating Kushida highly while treating Shinohara and Ike with dismissive indifference had triggered her intense wariness. From her perspective, my motives were an unknown variable, so physically preventing us from interacting was the safest play. Given her limited options, it was probably the best strategy she could muster. Still, if I simply forced my way past here, the chances of Mii-chan becoming their next target weren't zero. I wanted to avoid that outcome.</p></div>\n<div><p>“But... maybe I should let you go...? I just don't know what to do…”</p></div>\n<div><p>Although we were technically functioning as a single, unified group, we spent the vast majority of our time segregated by class. It seemed the internal environment within Class A was considerably worse than it appeared on the surface.</p></div>\n<div><p>Because the entrance to their tent was facing away from us, I couldn't get a read on the three of them from here.</p></div>\n<div><p>“For now, I'll circle around through the trees and quietly check on the situation. Mii-chan, just stay here and keep playing the lookout.”</p></div>\n<div><p>I instructed her to return to her post before slipping away into the forest. Moving swiftly through the cover of the trees, I looped around to the front of Shinohara's campsite. The two Class A tents were pitched side by side. I could see Shinohara and Ike standing just outside the one on the right.</p></div>\n<div><p>Was Kushida… inside the tent?</p></div>\n<div><p>At a quick glance, I couldn't see her anywhere, so I slowly shifted my angle until I had a clear line of sight into the tent's interior. That was when I realized exactly why I hadn't spotted her right away.</p></div>\n<div><p>There at the entrance, Kushida was down on the ground in a full dogeza, prostrating herself entirely before Shinohara and Ike.</p></div>\n<div><p>Translator’s Note: Dogeza (土下座) is one of the most extreme gestures of apology, supplication, or deference in Japanese culture. By kneeling and bowing until one's head touches the ground, a person demonstrates profound humility and a willingness to cast aside their pride, often in the face of overwhelming remorse, desperation, or earnest pleading.</p></div>\n<div><p>Looking down at her, Shinohara wore an expression of sheer, unadulterated delight.</p></div>\n<div><p>I could only imagine the violent vortex of anger currently swirling inside Kushida's heart. But even with their campsite pitched an unusually far distance from the rest of the group, they were still in a shared area. If she carelessly raised her voice, or if her foul-mouthed true nature was exposed to a third party, all the effort she had spent endlessly enduring hardships to maintain her ‘good girl’ facade would come crumbling down in an instant.</p></div>\n<div><p>It seemed she was utterly committed to acting the part of the humble, submissive victim from beginning to end, hoping to somehow smooth things over.</p></div>\n<div><p>Knowing I couldn't carelessly call out to them either, I was trying to figure out my next move when Shinohara's jeers finally reached my ears. Because she was directing her vitriol down toward the tent, the exact words were muffled, but the sheer fury in her tone was unmistakable.</p></div>\n<div><p>As I observed the situation from the shadows for a moment longer, I noticed another presence approaching the area.</p></div>\n<div><p>Having grasped the gist of the conflict, I decided it would be best to slip back to the Class C tents before I was discovered.</p></div>\n<div><h2>Part 3</h2></div>\n<div><p>Just shortly before Ayanokōji began circling through the trees, Shinohara’s festering suspicions had finally exploded into outright fury. She simply couldn’t let go of the incident on the second night, when it became glaringly obvious that their policy of cutting Kushida out of the tokens had been leaked to the other classes.</p></div>\n<div><p>“You're the one who blabbed to everyone that I wasn't going to give you any tokens, didn’t you, Kushida-san?” Shinohara demanded. “Just admit it already.”</p></div>\n<div><p>“I didn't…” Kushida pleaded. “No matter how much I deny it, you still won't believe me, will you...?”</p></div>\n<div><p>“Then what? If there's someone else, who is it? Are you saying Mii-chan leaked it?”</p></div>\n<div><p>“I don't know about that, but... it wasn't me. It would have to be either Mii-chan or Ike-kun.”</p></div>\n<div><p>Despite her desperate denials, nothing could shake Shinohara’s absolute conviction that Kushida was the prime suspect.</p></div>\n<div><p>“Satsuki,” Ike interjected hesitantly. “it doesn't feel like Kikyō-chan is lying, though…”</p></div>\n<div><p>“Huh?” Shinohara turned on him at once. “Then who are you saying leaked it? It wasn't you, Kanji, was it?”</p></div>\n<div><p>“Of course it wasn't! There's no way I'd do that!” Ike shook his head quickly, then searched for somewhere else to place the blame. “Look, maybe that Ayanokōji guy spread it around or something... You know he's capable of anything.”</p></div>\n<div><p>“Listen to me,” Shinohara said sharply, “Even if that were true, Class A was the one who decided on this policy in the first place, right? Even if Ayanokōji-kun is involved, it still means one of our classmates had to leak the information to him first. Seriously, Kanji, you're such an idiot.”</p></div>\n<div><p>“M-my bad…”</p></div>\n<div><p>“Mii-chan hates Kushida-san, so she has no reason to leak it,” Shinohara pressed on. “Kushida-san is the only one who stands to benefit from making this public. The culprit was obvious from the very beginning.”</p></div>\n<div><p>“But still, Kikyō-chan is smart enough to know you'd scold her if she carelessly leaked it, right?” Ike argued.</p></div>\n<div><p>“She's trying to outsmart us! Kushida-san is supposed to be this brilliant, excellent student, isn't she?”</p></div>\n<div><p>Unable to look directly at Kushida, who was sitting formally in a seiza position looking apologetic, Ike averted his gaze and squeezed out his voice.</p></div>\n<div><p>“But you don't have solid proof it was Kikyō-chan, right? In that case—”</p></div>\n<div><p>“Kikyō this, Kikyō that! that’s all you keep saying!” Shinohara’s anger burst out all at once. “Why are you so comfortable calling only Kushida-san by her first name!?”</p></div>\n<div><p>“N-no...!”</p></div>\n<div><p>It was a sudden, violent eruption of emotion. Ike panicked, choking on his words as he scrambled to formulate a defense. Before Shinohara could lay into him again, he forcefully talked over her.</p></div>\n<div><p>“Even if you say that... I've called her that since way before you and I started dating…”</p></div>\n<div><p>“Then you should just change it back to her last name starting right now!” Shinohara snapped. “I mean, seriously! Kushida-san is the one who called me ugly right in the middle of the classroom! She said those awful things to your own girlfriend, and you're still acting all buddy-buddy with her? Don't you think that's pathetic? It's embarrassing for me!”</p></div>\n<div><p>Her eyes red and glaring, Shinohara snapped her gaze away from Ike and back down to Kushida.</p></div>\n<div><p>“If you don't want to tell the truth, that's fine. I might not have hard proof that you betrayed us, but this relationship of trust is officially broken. Because of that, I can't give you any tokens anymore.”</p></div>\n<div><p>After delivering that ultimatum, Shinohara forced a venomous smile.</p></div>\n<div><p>“Or maybe you've already figured out a plan to avoid expulsion?” she continued. “Kushida-san is smart, after all. I wouldn't be surprised if you were out wagging your tail at guys other than Kanji, sweet-talking them into promising you their tokens.”</p></div>\n<div><p>“I haven't done that…” Kushida whispered. “I haven't even thought about it…”</p></div>\n<div><p>“This isn't like you, Satsuki... Just stop it already,” Ike pleaded.</p></div>\n<div><p>“I said shut up! Why... why are you always defending someone like Kushida!?”</p></div>\n<div><p>Dropping all honorifics, Shinohara dissolved into a hysterical fit. Ike couldn't hide the bewildered, helpless expression on his face.</p></div>\n<div><p>“We're supposed to be comrades, aren't we?” Ike pressed. “You've been acting really strange ever since this special exam started, you know…”</p></div>\n<div><p>Ike dropped his voice low, quickly warning her to quiet down. Even with this kind of distance, someone from another class was bound to hear her if she kept yelling.</p></div>\n<div><p>“I can't help it! Kanji, Yoshida, Ayanokōji— all of you! You guys always just take Kushida's side!”</p></div>\n<div><p>Rather than calming down at Ike's warning, Shinohara's emotions flared even higher.</p></div>\n<div><p>“Your voice! You're being too loud!” Ike hissed.</p></div>\n<div><p>Shinohara's chest heaved with ragged breaths. For several seconds she said nothing, only stood there trying to steady herself, until at last she dragged in a breath and violently brushed her disheveled bangs out of her face.</p></div>\n<div><p>“Nobody is listening out here,” she said, her voice lower now but no less sharp. “so why don't you just show us your true colors, Kushida-san? You might feel a lot better if you do.”</p></div>\n<div><p>“...Even if you tell me to show my true nature, it troubles me. I don't really have any intention of fighting with you, Shinohara-san…”</p></div>\n<div><p>“Oh, really? Then why are you parading around like some tragic heroine? Making me out to be the villain. Why are you putting on this big show, whining ‘I can't get any tokens~’ to everyone?”</p></div>\n<div><p>“That's just…” Kushida faltered, then corrected herself. “I just want you to keep your promise... No, I just want you to properly transfer my share of the tokens up until today. When I think about the fact that I might get expelled, I can't help but feel anxious…”</p></div>\n<div><p>“Anxious?” Shinohara repeated. “Even though I told you I'd give them to you later? See, you really don't trust me after all.”</p></div>\n<div><p>“...It's not that I don't trust you. But───”</p></div>\n<div><p>“I've told you over, and over, and over again, haven't I?” Shinohara immediately cut her off. “I will definitely give you your tokens before we reach the goal. Until then, I'm just holding onto them for the sake of adjustments. Get that through your head already.”</p></div>\n<div><p>‘Adjustments’. It was a highly convenient excuse. She hadn't revealed a single detail about what this supposed strategy was or how it benefited anyone.</p></div>\n<div><p>Naturally, Kushida understood what was actually happening. Her tokens were being confiscated purely out of spite; they were being held hostage as insurance to guarantee that Shinohara and Ike wouldn't be the ones expelled in a worst-case scenario. Forced to endure this one-sided oppression, Kushida's own frustration had to be boiling over. Yet, she didn't simply explode in a fit of rage like Shinohara. Even though their camp was isolated, they were still relatively close to the others. There was no telling when someone might wander by and see her.</p></div>\n<div><p>“In the first place,” Shinohara continued, “this is all your fault for insulting me in front of everyone. You're at least aware of that much, aren’t you?” Shinohara demanded.</p></div>\n<div><p>“...You're right,” Kushida replied. “I'm truly reflecting on my actions regarding that…”</p></div>\n<div><p>“Hmph. If you're really so sorry, then show me some actual sincerity for starting all this.”</p></div>\n<div><p>“Sincerity...?” Kushida asked quietly. “Is it enough if I quietly leave the tokens in your care until just before the goal?”</p></div>\n<div><p>At Kushida's questioning words, Shinohara let out a derisive snort, rejecting the idea entirely before thrusting her true demand forward.</p></div>\n<div><p>“People might make fun of me for this, and maybe it is a bit unreasonable. But everyone has a line they absolutely will not let someone cross, right? Kushida-san, you crossed that line. I think an appropriate display of submission is necessary.”</p></div>\n<div><p>With that, Shinohara pointed down at the dirt floor inside the tent.</p></div>\n<div><p>“Then get down and do a dogeza right here in front of me. As proof that you trust me. Me, of all people.”</p></div>\n<div><p>It was a demand that truly crossed the line. For a split second, both Kushida's expression and her heart completely froze.</p></div>\n<div><p>Shocked by the absurdly cruel ultimatum, Ike reached out to touch Shinohara's shoulder to soothe her, but she violently brushed his hand away.</p></div>\n<div><p>“Can you do it?” Shinohara asked. “Or not?”</p></div>\n<div><p>It was, in essence, a forceful binary choice: Do you want your tokens or not?</p></div>\n<div><p>For Kushida, there was no room to choose.</p></div>\n<div><p>“I beg of you... please believe me───”</p></div>\n<div><p>Placing her hands on the ground, she lowered her head deeply, executing a flawless, beautiful dogeza at Shinohara's feet.</p></div>\n<div><img alt=\"Chapter Image\" width=\"600\" height=\"800\" src=\"/assets/y3v4_ch6.webp\"><span></span></div>\n<div><p>It was a deeply humiliating posture. Yet, far from being satisfied, Shinohara found an unspeakable irritation swelling inside her.</p></div>\n<div><p>For Shinohara, it was an unbearable reality that even while groveling in the dirt, a posture meant to be ugly and degrading, Kushida still looked infinitely more poised and put-together than she ever could.</p></div>\n<div><p>“...Somehow, I'm just not feeling any heartfelt sincerity in that. I mean, you have two different faces, right, Kushida-san? You must be so pissed off at me right now you can hardly stand it.”</p></div>\n<div><p>It wasn't as if Kushida's mere existence was causing Shinohara any direct harm. Ike's feelings for Shinohara were genuine, and nothing romantic had ever actually happened between him and Kushida.</p></div>\n<div><p>Even so, Shinohara was consumed by a suffocating inferiority complex, the inescapable feeling that she was lesser in every conceivable way, from her face and her intelligence to the very curves of her body. It was a merciless reality; even after learning just how rotten Kushida was on the inside, it was no wonder Ike still found himself captivated by her.</p></div>\n<div><p>Shinohara knew this. She knew that if they competed on an even playing field, she could never win. It was an insurmountable gap in natural-born gifts. Therefore, her only recourse was to leverage her position and power to forcefully grind Kushida down into the dirt.</p></div>\n<div><p>“That's not true…” Kushida pleaded, still bowing low. “Please, you have to believe me…”</p></div>\n<div><p>The words repeated themselves. Shinohara knew full well those words were completely hollow. The true, venomous nature Kushida had exposed during the Unanimous Special Exam had been far too intense to ever forget.</p></div>\n<div><p>But it was also true that she couldn't force her to stay in a dogeza forever. She had to consider when to pull back.</p></div>\n<div><p>“Aren't you a good girl, groveling so obediently like that?” Shinohara said at last. “...Yeah, I get it. I'll give you the tokens just as promised. But it's going to be right before the goal on the final day. Right before transfers become impossible, that is.”</p></div>\n<div><p>Within Group 3, the most likely candidates to finish dead last in tokens were Ibuki and Kushida.</p></div>\n<div><p>From Shinohara's perspective, as long as she crossed the finish line with even a single token more than either of them, she was 100% guaranteed to survive this special exam.</p></div>\n<div><p>As for Ibuki, Katsuragi was currently clamping down on her for failing to produce results, but there was no telling when or if he might step in to save her at the last minute. Shinohara needed to hoard as much insurance as she possibly could.</p></div>\n<div><p>“Is this... enough now?” Kushida asked quietly. “Someone might come by…”</p></div>\n<div><p>“No,” Shinohara ordered. “Stay exactly like that for one more minute. Still, it really is a shame we don't have our phones on us, right, Kanji?”</p></div>\n<div><p>“N-no... how should I put it,” Ike’s voice faltered. “aren't you going a bit too far? At this point, it's just bullying…”</p></div>\n<div><p>“Huh?” Shinohara’s anger, which had only barely begun to settle, flared again in an instant. She turned on him with a glare. “What about the humiliation I suffered? That was bullying too, wasn’t it? Why do you keep taking her side?”</p></div>\n<div><p>“You prefer Kushida over me, don’t you?” Her voice rose, sharp and unstable. “That’s it, isn’t it!?”</p></div>\n<div><p>“N-No! I'm telling you, it's not like that!”</p></div>\n<div><p>With his face twitching at her unstoppable rampage, Ike cautiously touched her shoulder again in a desperate bid to calm her down.</p></div>\n<div><p>“Hey— what kind of sickening game are you guys playing?”</p></div>\n<div><p>An unusually low, entirely deadpan voice suddenly echoed from the darkness behind them.</p></div>\n<div><p>Ike panicked, grabbing the hand of Kushida who was still in a dogeza, trying to haul her to her feet, but it was too late. Ibuki, who had circled around to investigate the noise, had a crystal-clear view of Kushida groveling on the floor of the tent.</p></div>\n<div><p>“...Huh?” Shinohara stammered. “What... what are you talking about, Ibuki-san?”</p></div>\n<div><p>“About that dogeza.” Ibuki’s gaze remained flat. “You guys are supposed to be allies, aren't you?”</p></div>\n<div><p>“This was something Kushida-san did voluntarily,” Shinohara said quickly. “Right, Kanji?”</p></div>\n<div><p>“W-Well, yeah…” Ike answered with lacked conviction. “Something like that... Wait, why the hell are you even here, Ibuki!?”</p></div>\n<div><p>“What do you mean, ‘what’? I was just taking a walk when I heard all that ‘gyaa gyaa’ yelling, so I came to take a look.”</p></div>\n<div><p>After saying that, Ibuki added, as though she had suddenly remembered something.</p></div>\n<div><p>“Oh, by the way, I already know all about Kushida's true nature, so don't sweat it. The girl has a genuinely piss-off personality, so I totally get the urge to make her grovel.”</p></div>\n<div><p>Hearing her casually touch upon the secret they were most desperate to protect, Shinohara and Ike exchanged terrified glances.</p></div>\n<div><p>“W-What, you knew...?” Ike asked. “Wait, do the other guys in Class B know, too?”</p></div>\n<div><p>“Pretty sure they don't,” Ibuki replied. “So that little secret you're trying so hard to protect is safe. However—”</p></div>\n<div><p>Not breaking her stride, Ibuki looked away from Kushida and stepped right in front of Shinohara.</p></div>\n<div><p>“What is it?” Shinohara snapped, defensive. “Do you have a problem with me? You just said you understood how I felt, didn't you?”</p></div>\n<div><p>“Well, yeah. If I made Kushida grovel, I'd probably feel pretty damn good about it, too. But I just realized that watching someone else make her do it is incredibly obnoxious. Anyway, why don't you get up already?”</p></div>\n<div><p>“...Just leave us alone, Ibuki-san,” Kushida finally spoke up, her voice calm. “This is an internal Class A matter. It has nothing to do with you.” Then she turned her words toward Shinohara. “And don't worry, Shinohara-san. Ibuki-san really does know about me, so you don't need to worry.”</p></div>\n<div><p>Hearing that, Shinohara's resentment cooled slightly, allowing her to regain a measure of composure. The fact that Ibuki had wandered over meant other students might follow soon. If word of this dogeza leaked to the rest of the camp, it would only spell trouble for Shinohara and Ike.</p></div>\n<div><p>“I’m glad you’re on my side, Kushida-san,” Shinohara said, her voice returning to something closer to calm. “Come on, Kanji. Let’s go back to everyone else.”</p></div>\n<div><p>“...Y-yeah.”</p></div>\n<div><p>Still harboring a visible knot of guilt, Ike let Shinohara grab his hand and drag him hurriedly away into the dark.</p></div>\n<div><p>Ibuki watched them leave, then looked back at Kushida.</p></div>\n<div><p>“I went out of my way to save your ass, and you tell me to ‘leave you alone’?” She scoffed at Kushida. “Who the hell do you think you are?”</p></div>\n<div><p>“I'm just fighting desperately to survive in my own way,” Kushida replied flatly. “As long as Shinohara holds the actual power over the tokens, I have to do whatever it takes, right?”</p></div>\n<div><p>“And ‘whatever it takes’ means kissing the dirt? Do you have zero pride?”</p></div>\n<div><p>“I’m fighting because I do have pride. I suppose you wouldn’t understand that, Ibuki-san.” Kushida rose slowly, touching her knees as though soothing the ache left by the position she had been forced to hold. “Sorry, but if something happens from here on, could you not interfere? Even if I look miserable right now, it’s still better than being expelled. If I obey those two, I can get more tokens than you. In that case, something like this isn’t a big deal.”</p></div>\n<div><p>“I see.” Ibuki’s expression twisted faintly. “Now that you mention it, you were always thick-skinned.”</p></div>\n<div><p>Kushida stepped out of the tent, then turned her back as if the conversation no longer mattered.</p></div>\n<div><p>“You should try harder too, Ibuki-san,” she said. “Otherwise you’ll be expelled.”</p></div>\n<div><p>“Shut up. I know that.”</p></div>\n<div><p>“Could it be that you've half-given up?”</p></div>\n<div><p>Ibuki, who had already turned to head back to her own tent, froze mid-step.</p></div>\n<div><p>“I haven't given up or anyth—”</p></div>\n<div><p>“That's fine. Honestly, if you end up dropping out, my chances of survival go up by exactly that much.”</p></div>\n<div><p>With a small, dismissive scoff over her shoulder, Kushida walked away into the night.</p></div>\n<div><p>“What a total bitch. I never should've called out to her,” Ibuki muttered to herself in the empty clearing.</p></div>\n<div><p>Even after spitting those words out into the dark, she couldn't bring herself to move from that spot. She was irritated, certainly. But it wasn't just anger.</p></div>\n<div><p>Shinohara's distorted, petty obsession. The spineless half-measures of Ike, who couldn't bring himself to properly stop her. And that infuriatingly pragmatic attitude of Kushida's.</p></div>\n<div><p>She despised all of it. Every single part of this situation pissed her off. But what angered her the most right now was her own existence.</p></div>\n<div><p>If this were a problem she could solve just by punching it, things would be easy. But this special exam... this wasn't something she could just fight her way through. She couldn't subdue it with physical violence, nor could she bulldoze through it with sheer stubborn emotion. It was a deeply frustrating, suffocating school life.</p></div>\n<div><p>To survive, she had no choice but to think. Yet she never expected the act of thinking itself to be this troublesome and infuriating.</p></div>\n<div><p>She clicked her tongue once and dropped her gaze to the dirt.</p></div>\n<div><p>She knew her token count was sinking straight to the bottom of the rankings. But even knowing that, she had no clear idea of what her next move should be.</p></div>\n<div><p>Should I simply leave things in Katsuragi's hands? When it comes down to it, would he save me in the end, saying it couldn't be helped?</p></div>\n<div><p>No. She didn't possess that kind of value.</p></div>\n<div><p>Then should I take matters into my own hands and seize an opportunity myself?</p></div>\n<div><p>In this exam, someone was absolutely going to be expelled. That harsh reality was why Kushida was fighting so ruthlessly, not even hesitating to do a dogeza.</p></div>\n<div><p>I couldn't find an answer. Or perhaps─── I already had.</p></div>\n<div><p>“...There's no point in me clinging to this school if it means obsessing over crap like this,” she whispered into the empty air. “I'm just hopelessly unsuited for this place.”</p></div>\n<div><p>Spitting out that quiet realization, Ibuki finally forced her feet to move.</p></div>\n<div><h2>Part 4</h2></div>\n<div><p>Afterward, Shinohara strolled back over to the rest of the group, wearing a perfectly innocent expression as she joined in on the idle chatter. Her expression gave nothing away. She chatted lightly, wearing the same casual face as before, and then confirmed with her own eyes that Ayanokōji was still there, speaking amiably with Yoshida.</p></div>\n<div><p>A few seconds later, Ike arrived as well.</p></div>\n<div><p>Unlike Shinohara, he could not quite conceal what had happened. His steps were restless, his movements faintly unsettled, as if some part of him were still caught back at the tent.</p></div>\n<div><p>“Thanks, Mii-chan. It looks like Ayanokōji-kun didn't make a move after all,” Shinohara whispered.</p></div>\n<div><p>“Y-yes,” Mii-chan replied hesitantly.</p></div>\n<div><p>A few minutes later, Kushida emerged from the tent. Having properly dusted herself off and fixed her appearance, she wore her usual, impeccably bright expression.</p></div>\n<div><p>Are you okay? Mii-chan desperately wanted to ask her that softly, but with Shinohara standing nearby, wearing a smug, triumphant smile as she kept a watchful eye on them, she didn't dare to speak up.</p></div>\n<div><p>“Shinohara-san, you have an incoming call from Horikita-san,” Urushihara called out, approaching their group.</p></div>\n<div><p>“From Horikita-san...?” Mii-chan murmured.</p></div>\n<div><p>“...Looks like it,” Shinohara replied.</p></div>\n<div><p>During the first radio check-in, Shinohara had been deeply irritated that Horikita had contacted Kushida instead of her. Because of that, she had forced Kushida to tell Horikita to direct all future communications to the actual group representative, meaning her. Seeing that demand finally come to fruition filled her with a petty, lingering sense of joy.</p></div>\n<div><p>Right before accepting the radio from the supervisor, Shinohara reached out and tightly clamped her hand around Kushida's wrist just as the girl tried to turn away.</p></div>\n<div><p>“Don't try anything funny that might betray me, okay?” she said in a low voice. “If you do, I'll expose your true colors to everyone here.”</p></div>\n<div><p>“I know,” Kushida replied softly. “I won't do anything like that.”</p></div>\n<div><p>Shinohara was actively preempting her, aggressively tying down Kushida's every word and action.</p></div>\n<div><p>Even if Kushida somehow managed to secretly lay the groundwork to receive token assistance from someone else, the actual transfer of points would require direct physical proximity right in front of the others. Deceiving Shinohara during that critical moment would be a monumental task.</p></div>\n<div><p>Here, on the night of the third day, Shinohara's resolve hardened. She decided right then and there that she absolutely would not take her eyes off Kushida until the very moment they crossed the final finish line. Whether it was someone from Class A, Ayanokōji, or some random student trying to earn Kushida's favor with an ulterior motive, it didn't matter who it was. The second anyone showed even the slightest sign of transferring tokens to her, Shinohara would intervene and shut it down.</p></div>\n<div><p>If Kushida suddenly claimed she didn't need any tokens right before the goal, or if she refused to disclose her current count, Shinohara would instantly judge that a secret transfer had taken place. If that happened, she and Ike would simply keep the stockpile of tokens she was supposedly ‘managing’ for Kushida and split it entirely between the two of them. By doing so, they could completely eliminate their own risk of finishing dead last in the school year.</p></div>\n<div><p>Without even realizing it, Shinohara's twisted obsession with Kushida had continued to swell, completely eclipsing her concern over Ibuki, the person who was actually heavily favored to finish in last place.</p></div>\n<div><p>“Sorry, Kanji, but keep a close eye on Kushida-san for a second.”</p></div>\n<div><p>“U-understood.”</p></div>\n<div><p>A moment later, she lifted the radio.</p></div>\n<div><p>“Hello, Horikita-san? Do you need something?”</p></div>\n<div><p>Answering the radio in incredibly high spirits, Shinohara broke into a smug grin and walked a short distance away. It was a deliberate, exclusionary display, a physical declaration that she was the one holding the reins of power in their group, and that mere underlings weren't allowed to eavesdrop on her conversation.</p></div>\n<div><p>“Ike-kun... do you have a minute?” Kushida whispered.</p></div>\n<div><p>She kept her voice just low enough to avoid arousing Shinohara's suspicion as she spoke to her newly appointed guard.</p></div>\n<div><p>“Hm? W-what is it.”</p></div>\n<div><p>“Shinohara-san really is going to share the tokens with me before we reach the goal... right?”</p></div>\n<div><p>“...Of course she is,” Ike answered. “Seriously, there's nothing to worry about.”</p></div>\n<div><p>“Yeah, I trust Shinohara-san. I just... I just can't help feeling anxious. It's true that I said some awful things about her, but... I was desperate back then. There were so many things I said that I didn't truly mean.”</p></div>\n<div><p>As she spoke, Kushida reached out and gently gripped the hem of Ike's jersey between her fingertips.</p></div>\n<div><p>“K-Kikyō-chan!?” Ike’s voice nearly cracked. “If Satsuki catches us doing this, it'll be really bad...!”</p></div>\n<div><p>“Don't move,” Kushida whispered. “Shinohara-san can't see us from here.”</p></div>\n<div><p>It was a veiled threat. If they were caught, Kushida would undoubtedly incur more of Shinohara's wrath, but Ike would find himself equally in the firing line.</p></div>\n<div><p>“I don’t have anyone else I can rely on anymore,” Kushida said. “It’s only you, Ike-kun...”</p></div>\n<div><p>“I-It'll be fine,” Ike said quickly. “I promise, there is absolutely no way Satsuki would ever abandon you, Kikyō-chan.”</p></div>\n<div><p>“Really...?”</p></div>\n<div><p>“If Satsuki seriously tries to say she won't give you any tokens, I'll step in and set her straight. You can rest easy about that.” His expression tightened with guilt. “I'm sorry... making you grovel in the dirt like that was going way too far, no matter how you look at it...”</p></div>\n<div><p>“No, it was my fault, too... But still, just hearing you say that... makes me so happy.”</p></div>\n<div><p>Kushida paused for a brief moment. Then, with glistening, teary eyes, she looked up softly into his.</p></div>\n<div><p>“If you come through and save me when it really matters, Ike-kun... then when that time comes... I'll do anything you want.”</p></div>\n<div><p>“Eh───?”</p></div>\n<div><p>He could feel the sweet warmth of her breath ghosting over his skin. A split second after Ike inhaled her scent, Kushida's fingertips slipped smoothly away from his jersey.</p></div>\n<div><p>Shortly after, Shinohara returned, radio in hand. Completely oblivious to the exchange, she grabbed the arm of a visibly flustered Ike and practically dragged him briskly toward their tent.</p></div>\n<div><p>“Listen to this, Kanji. Ayanokōji-kun is plotting something completely unbelievable.”</p></div>\n<div><p>Hearing Ayanokōji's name leave Shinohara's smugly smiling lips, Ike's eyes went wide.</p></div>\n<div><h2>Part 5</h2></div>\n<div><p>The four students of Class A had initially been huddled together in their own isolated camp, but the moment Shinohara finished her radio transmission, she dragged Ike a short distance away.</p></div>\n<div><p>After retreating to their tent, the two began discussing something in secret, occasionally shooting glances in my direction. The fact that someone, no, the fact that Horikita had directly contacted Shinohara meant she had finally begun making moves as well.</p></div>\n<div><p>Considering the timing, it was safe to assume Horikita had set this up fully expecting me to catch wind of it.</p></div>\n<div><p>“She has definitely grown, slowly but surely,” I murmured to myself. “So in the end, she did reach out for the arrow.”</p></div>\n<div><p>I was genuinely surprised. I had calculated that there was a greater than fifty percent chance she wouldn't attempt to stop the arrow mid flight.</p></div>\n<div><p>No, it was still too early to tell.</p></div>\n<div><p>I didn't know yet if Horikita's hand was actually meant to stop the arrow's flight, or if she was merely feigning the attempt. Either way, by making this very visible move, she was probing to see how I would react.</p></div>\n<div><p>Right now, with Shinohara thoroughly distracted by whatever she'd heard over the radio, making contact with Kushida would be incredibly simple.</p></div>\n<div><p>“Yoshida, come here for a second,” I called out.</p></div>\n<div><p>“Hm? Oh, sure.”</p></div>\n<div><p>Without even asking why I'd called him over, Yoshida pushed himself up and stepped out of our tent.</p></div>\n<div><p>With him in tow, I walked directly over to Kushida.</p></div>\n<div><p>“Could you give me just five minutes? There's something I want to ask you,” I said.</p></div>\n<div><p>Kushida turned to face us. She immediately flashed her perfectly crafted smile and answered without a second's hesitation. “Sure.”</p></div>\n<div><p>“Sorry Yoshida, but could you head back to the tent?” I said, turning to Yoshida. “I want to talk to Kushida alone.”</p></div>\n<div><p>“Huh? Wait, then why did you even bring me...?” Yoshida replied, surprised. “Well, whatever.”</p></div>\n<div><p>He tilted his head in mild confusion, but rather than pressing the issue, he simply turned around and headed back toward the Class C camp.</p></div>\n<div><p>“That was pretty underhanded, using Yoshida-kun like that,” Kushida remarked quietly once he was out of earshot.</p></div>\n<div><p>“If I hadn't gone that far, I figured there was a solid chance you wouldn't even entertain the conversation,” I replied.</p></div>\n<div><p>Because I had approached her with Yoshida present, Kushida, who was always hyper-aware of public perception, had been forced to readily agree to my request to maintain her friendly facade. Now that she had publicly consented, she had no choice but to stand there and listen to what I had to say, whether she liked it or not.</p></div>\n<div><p>“What is it now?” Kushida asked, her tone shifting to her usual brusque self once we were alone.</p></div>\n<div><p>“It seems Shinohara still isn't willing to transfer the tokens to you.”</p></div>\n<div><p>“Looks like she's holding a serious grudge over me calling her ugly, so I guess I can't really blame her. But honestly, part of me wants to say, ‘What's wrong with stating a fact’─── lol, nevermind.”</p></div>\n<div><p>With a derisive snort, Kushida flicked her gaze over toward Shinohara's camp without turning her head.</p></div>\n<div><p>The root cause of Shinohara's refusal to hand over the tokens seemed to stem entirely from the grudge she had harbored since the Unanimous Special Exam. Over by their tent, Shinohara, who had been keeping a close eye on our movements, had clearly noticed us talking. Ike tried to head over in our direction, but Shinohara grabbed his arm and stopped him with a laugh.</p></div>\n<div><p>“The way Ike looks at me... completely unable to hide his gross ulterior motives... makes me sick,” Kushida muttered. “They really are a match made in heaven.”</p></div>\n<div><p>Perhaps because I was the only one listening, she freely spat out her venom right here in the middle of the campsite.</p></div>\n<div><p>“If you distance yourself from Ike, won't Shinohara calm down a bit?” I asked.</p></div>\n<div><p>“Doing that would only buy me more of Shinohara's animosity. Besides, even if I wasn't making eyes at Ike right now, his attitude toward me wouldn't have changed, would it?”</p></div>\n<div><p>That might be true. The fact that Ike had such a glaring soft spot for Kushida, combined with the fact that I actively valued her while treating Shinohara with dismissive indifference, were likely just acts that added fuel to a fire that had already been smoldering.</p></div>\n<div><p>“Either way, in the worst-case scenario, I'll be abandoned. To prevent that, I have to think about not only pulling tokens from Shinohara, but from Ike as well. Even if I try relying on Mii-chan, well, since she doesn't like me, it's probably impossible.”</p></div>\n<div><p>During the Unanimous Special Exam, Mii-chan's private romantic situation had been publicly dragged out into the open as a direct result of Kushida's rampage. Even though Mii-chan interacted with her normally now, it was a humiliating trauma she wouldn't soon forget. Although she suppressed her resentment enough to worry about Kushida, her position meant she likely couldn't transfer any tokens to her anyway. It was certain she couldn't be counted on.</p></div>\n<div><p>“I know this sounds bitchy,” Kushida continued, “but part of the reason I'm struggling this much right now is because of you, Ayanokōji-kun. You praised me in front of everyone when our groups were first put together, didn't you? It seems like that's what originally lit the fire under her. Is this your way of getting payback because I held a grudge and refused to tell you who the VIP was during the Survival Game Special Exam?”</p></div>\n<div><p>When I had slipped into the Class A campsite just barely within the time limit back then, I had made a brief contact with Kushida, silently confirming if she would tell me the VIP's identity. She had refused through her attitude alone. It was a silent visual exchange that lasted less than a few seconds. No one could have possibly noticed it.</p></div>\n<div><p>“I thought you were just hesitating about whose side to take,” I said. “Weren't you afraid I would expose your true nature to the others? If the entire school finds out, you'll have no place left here.”</p></div>\n<div><p>“It's far too late for that. The people in my class already hold my secret anyway.”</p></div>\n<div><p>In reality, Kushida had allowed herself to be completely controlled and rendered powerless by someone like Shinohara. But that wasn't the whole story. Clearly, her internal evaluation of Horikita had begun to shift, and her own way of thinking was gradually changing along with it. Not that she would ever admit it if I pointed it out.</p></div>\n<div><p>“I didn't intend it as payback,” I told her. “What happened with Shinohara was entirely unintentional.”</p></div>\n<div><p>“Well, if you tell me that I'm the one who sowed the seeds of this mess in the first place, I can't exactly argue back. Anyway, what's clear right now is that neither Shinohara nor Mii-chan are going to take my side. Given that, my only option is to rope in at least Ike and persuade him into transferring his tokens to me.”</p></div>\n<div><p>There seemed to be an extraordinary resolve and determination in her expression.</p></div>\n<div><p>“You have a look on your face that says you'll do absolutely anything.”</p></div>\n<div><p>“Damn right I will,” she said flatly. “I'll even let him grope my breasts if that's what it takes. Even that idiot would hand over some tokens after that, wouldn't he?”</p></div>\n<div><p>“That would probably be extremely effective.”</p></div>\n<div><p>If she went that far, wringing out not just one or two, but ten or twenty tokens wouldn't be impossible.</p></div>\n<div><p>“It seems a trump card like that didn't work on a certain someone, though,” she added, shooting me a cold, sideways glare for a fraction of a second.</p></div>\n<div><p>It felt like a lifetime ago now, but of course, I remembered that incident perfectly well.</p></div>\n<div><p>Kushida claimed her trump card had no effect, but that was strictly regarding the outcome involving my fingerprints and everything that followed.</p></div>\n<div><p>If we were purely talking about my state of mind at the time... well, it had certainly been plenty effective for a healthy high school boy.</p></div>\n<div><p>“If Ike ends up sacrificing his own tokens for my sake, Shinohara won't have a choice but to help him in the end, even if she's pissed about it. Making a move like that might completely cement them as my enemies here and now, but surviving this special exam takes priority. If Ike alone isn't enough, I'll go after Yoshida or Sonoda. In the worst-case scenario, I'll just shift my target to them.”</p></div>\n<div><p>That meant if push came to shove, she was fully prepared to use the same physical trump card she had planned for Ike on students from entirely different classes. Of course, if she misread her target's personality, it could easily escalate into a serious incident, exponentially inflating the risk.</p></div>\n<div><p>“I'll ask just in case, but... you have no intention of actually helping me, right, Ayanokōji-kun?”</p></div>\n<div><p>“In exchange, are you willing to offer me that trump card— your body— again?”</p></div>\n<div><p>When I asked her back with a completely straight face, Kushida froze for a split second before her jaw dropped.</p></div>\n<div><p>“H-Hah!? W-What kind of stupid crap are you spouting!? Like hell I would!”</p></div>\n<div><p>“I thought you were perfectly willing to throw away your dignity if it meant making Ike and the others fall for it?”</p></div>\n<div><p>“...That's... well, because those guys are practically garbage... and they're incredibly simple-minded? Or rather, you're just messing with me, aren't you? You aren't actually going to help me, Ayanokōji-kun. Right?”</p></div>\n<div><p>“Unfortunately for you, that's correct. I will produce results for my current class; that remains my absolute highest priority.”</p></div>\n<div><p>“Then are we done here? I don't want to keep talking to you when you aren't even going to help me, only to gather more pointless hate from Shinohara. Just leave me alone.”</p></div>\n<div><p>Saying that, Kushida instantly flipped her expression back into a perfectly crafted, bright smile. She offered a cheerful little wave, putting on a friendly show for anyone watching as she naturally distanced herself from me.</p></div>\n<div><p>Whether things would actually play out as smoothly as she intended remained to be seen.</p></div>\n<div><p>After all, the other party’s vault was considerably tough to crack.</p></div>",
    "9": "<div><p>The second and third days of the exam continued with a flurry of tasks. Individually, these trials had yielded small, almost negligible shifts in the overall tokens— hardly enough to warrant concern. But minor gains had a way of compounding. Like drops of water wearing away at a stone, the steady accumulation had subtly reshaped the landscape of the exam. Before long, a handful of students had quietly amassed three-digit fortunes.</p></div>\n<div><p>It was against this tense, shifting backdrop that the final morning broke. Faint rustling outside her tent pulled Ibuki from her sleep.</p></div>\n<div><p>For a moment, she lay still inside the tent, listening. The air was quiet in that thin, early-morning way, before the camp had fully begun to stir. She blinked against the gloom, shifting her arm to glance at her wristwatch. The luminous hands pointed just past six o'clock.</p></div>\n<div><p>Straining her ears, it did not take long for the sound to reveal itself as footsteps. They passed along the side of the tent, then continued on, gradually fading into the distance. Judging by the direction, whoever it was seemed to be heading toward the shore.</p></div>\n<div><p>It wasn't completely unusual for an early riser to take a morning stroll, and her first instinct was to just ignore it. Yet, for some reason, the footsteps nagged at her.</p></div>\n<div><p>Careful not to wake Morofuji, Ibuki quietly sat up and peeled back the tent flap just enough to peek outside.</p></div>\n<div><p>The retreating figure slipping into the forest was none other than Kushida.</p></div>\n<div><p>“That girl…”</p></div>\n<div><p>The image of Kushida pressing her forehead to the dirt in a desperate dogeza yesterday flashed through Ibuki's mind; a raw, unforgettable display of her fierce determination to survive at this school.</p></div>\n<div><p>If the special exam ended right now, there was a very real chance Ibuki would finish in dead last. She had earned so few tokens herself that it was almost laughable.</p></div>\n<div><p><em class=\"italic\">What would happen to her once the exam concluded today?</em></p></div>\n<div><p><em class=\"italic\">Would she be confined to the cruise ship on standby until the others returned, or would they toss her on a small boat and ship her back to the mainland immediately?</em></p></div>\n<div><p>Either way, she might never get another chance to speak with Kushida one-on-one.</p></div>\n<div><p>Unable to suppress her curiosity, Ibuki slipped out of the tent and followed the path she had taken.</p></div>\n<div><p>Before long, Kushida’s back came into view. She was standing barefoot at the water's edge, gazing out across the vast expanse of the ocean.</p></div>\n<div><p>Kushida was fighting a war inside her own head. A massive, suffocating wave of frustration had been building within her since the very start of the special exam. She was gripped by a powerful urge to scream her lungs out, but she firmly swallowed it down.</p></div>\n<div><p>Even though she had put some distance between herself and the campsite, a loud shriek might still carry through the morning air.</p></div>\n<div><p>“This is so damn irritating…” she muttered.</p></div>\n<div><p>On top of the exhausting effort to constantly maintain her ‘good girl’ mask, having her true nature exposed to her classmates was a source of immeasurable stress. Shinohara confiscating her tokens. Ike’s vulgar, lingering stares. And worst of all, being coerced into a humiliating dogeza; her pride torn to absolute shreds under the threat of exposure to the other classes.</p></div>\n<div><p>Kushida was harboring a darker, more intense rage than she had ever felt in her entire life.</p></div>\n<div><p>Even so, the only reason she managed to keep herself from screaming was the bitter lesson she had learned in the past. Ever since she had foolishly let her guard down and allowed Ayanokōji to discover her true self, the gears of her meticulously crafted life had started to slip out of sync. She wouldn't— or rather, <em class=\"italic\">couldn't— </em>make that same mistake again.</p></div>\n<div><p>Standing there, she entrusted the sea with the dark emotions swirling inside her, desperate for the tide to wash them away.</p></div>\n<div><p>She had come here seeking a small, solitary world of her own, a fleeting respite born of sheer desperation, like a drowning girl grasping for air.</p></div>\n<div><p>Kushida took another step forward. The returning tide washed over her feet, soaking her to the ankles. Narrowing her eyes at the faint, cooling comfort of the water, she steadied her breathing.</p></div>\n<div><p>“I'll figure something out…” she whispered to the wind. “Even if the absolute worst comes to pass, and I have to go crying to Horikita... I will <em class=\"italic\">definitely </em>stay here───!?”</p></div>\n<div><p>Right then, a sudden, heavy impact slammed into her back. Before her brain could even process what was happening, she was sent pitching forward. She instinctively threw her hands out to catch herself, but with nothing to break her fall but the ocean, she plunged face-first into the seawater, getting completely drenched.</p></div>\n<div><p>Sputtering and completely bewildered, Kushida pushed her upper body off the wet sand and whipped her head around. Standing right behind her, legs planted wide and glaring down sharply, was Ibuki.</p></div>\n<div><p>“...Huh?”</p></div>\n<div><p>Kushida stared in sheer disbelief. Her mind couldn't make sense of the situation, but the moment the low sound escaped her lips, her irritation surged forward like a tidal wave.</p></div>\n<div><p>“Ibuki-san…” she said, her voice darkening. “just what do you think you're doing?”</p></div>\n<div><p>“What does it look like? A tackle, I guess,” Ibuki replied flatly. “You had your back turned to me, looking completely, stupidly defenseless. I just couldn't help myself.”</p></div>\n<div><p>“I have absolutely no idea what you mean...! <em class=\"italic\">Why </em>would you do that?”</p></div>\n<div><p>“Why?” Ibuki looked down at her without the slightest hint of apology. “Well, a while back, Horikita was moping around with that exact same gloomy aura hanging over her back. I gave her a good kick from behind when she did it, so... I guess I felt a similar urge?”</p></div>\n<div><p>“No, even with an explanation, I seriously do not get it!” Kushida looked down at herself, drenched by the seawater. “Look at me— what are you going to do about this!?”</p></div>\n<div><p>Seawater had already seeped all the way through to her underwear. It was a lost cause.</p></div>\n<div><p>“Serves you right,” Ibuki said.</p></div>\n<div><p>“I don't see why I have to take that from... Ow...!”</p></div>\n<div><p>Kushida tried to rise, only for pain to twist across her face. Her strength gave out, and she dropped back into the shallow water with a muted splash.</p></div>\n<div><p>A small, muffled groan escaped her lips.</p></div>\n<div><p>She placed one hand near her waist and made no further attempt to stand.</p></div>\n<div><p>“What,” Ibuki frowned. “Did you actually hurt yourself just from that...?”</p></div>\n<div><p>Thinking she might have gone a bit too far against an amateur, Ibuki tossed her shoes aside and waded into the water.</p></div>\n<div><p>“I can't really stand... Pull me up,” Kushida said, reaching out a trembling hand.</p></div>\n<div><p>Reluctantly, Ibuki took it, only to be violently yanked forward.</p></div>\n<div><p>“Wha───!?”</p></div>\n<div><p>Because she had genuinely believed Kushida might actually be hurt, Ibuki's guard had been completely down. With a massive splash, she pitched face-first into the sea, saltwater instantly rushing into her parted lips.</p></div>\n<div><p>“Ptooh! Ptooh! God, that's salty!”</p></div>\n<div><p>Right on cue, as if to add insult to injury, Kushida scooped up a double handful of seawater and splashed it directly into Ibuki's face.</p></div>\n<div><p>“Uwah! What the hell are you doing?!”</p></div>\n<div><p>“I think that's my line, isn't it?” Kushida shot back, her tone suddenly bright and venomous.</p></div>\n<div><p>“Faking an injury, you dirty sneak!”</p></div>\n<div><p>Scrambling to her feet, Ibuki put some distance between them and violently kicked the surface of the water, sending a retaliatory wave crashing back at Kushida. From there, it devolved into a petty, childish brawl, a relentless battle of splashing seawater back and forth.</p></div>\n<div><p>Whether it lasted one minute or two, in the end, there was no victor. The battle ended in a complete draw, leaving both of them soaked, breathless, and sitting in the water.</p></div>\n<div><p>“Haa, haa... Why do I have to deal with this first thing in the morning…” Ibuki panted. “you idiot Kushida.”</p></div>\n<div><p>“Like I said, that's my line…” Kushida replied, also short of breath. “Fufu... You really are an idiot, Ibuki-san…”</p></div>\n<div><img alt=\"Chapter Image\" width=\"600\" height=\"800\" src=\"/assets/y3v4_ch7_1.webp\"></div>\n<div><p>The two of them sat chest-deep in the ocean, glaring at one another. But then, in a sudden, shared moment of clarity, they both burst out laughing at the sheer absurdity of what they were doing.</p></div>\n<div><p>“...You know,” Ibuki muttered once their laughter finally subsided, “maybe you don’t need to be that pessimistic about getting expelled.”</p></div>\n<div><p>Kushida looked toward her.</p></div>\n<div><p>“The initial tokens,” Ibuki continued. “They were distributed based on how long students lasted in the survival game special exam, right? You lasted pretty close to the end too, didn’t you? Even if Shinohara’s managing your tokens, you should still have a bigger safety net than me. I don’t think you need to panic over missing out on a few tokens now.”</p></div>\n<div><p>“That's just a margin of error,” Kushida dismissed. “More importantly, I don't think Katsuragi-kun would just abandon you like this.”</p></div>\n<div><p>If Katsuragi were to provide her with twenty or thirty tokens, the individual gap between her and the others would easily close.</p></div>\n<div><p>“So you're saying I'm the prime candidate for last place?” Ibuki sighed. “That guy Katsuragi... he genuinely intends to distribute our tokens equally. He was dead serious about it. Giving preferential treatment to someone like me who can't produce individual results, and potentially sacrificing another hard working classmate in the process, he'd never forgive himself for that. Besides, he was talking with Ryūen on the radio last night. He might have even gotten direct orders to just cut me loose.”</p></div>\n<div><p>It was a strangely un-Ibuki-like thing to say. There was no anger in it. Only a kind of detached resignation. Hearing this, Kushida was completely convinced that the suspicion she had harbored yesterday was spot on.</p></div>\n<div><p>“I see. It's true that you don't have a single redeeming quality, Ibuki-san, so that's probably the right call,” Kushida replied bluntly.</p></div>\n<div><p>Even though there had been tasks where Ibuki could have shined, she had been forced to compete directly against Ayanokōji at crucial moments. Thanks to a cascading series of bad luck, all her efforts had merely spun their wheels in vain. Despite her fretting over the tasks being systematically checked off by the others, time marched on, refusing to wait for her.</p></div>\n<div><p>“So, I guess I've just given up…” Ibuki murmured. “I don't know, it's a weird feeling.”</p></div>\n<div><p>For some reason, Manabe’s face flashed inside her mind, her former classmate who had been expelled.</p></div>\n<div><p>In Manabe’s case, it had been an instant ‘death’. A surprise attack. Something like being struck down before she even understood the blade had fallen.</p></div>\n<div><p>This was different.</p></div>\n<div><p>“How should I put it…” she said. “It feels like I'm slowly ‘dying’ from poison.”</p></div>\n<div><p>Back when she and Ryūen had challenged Ayanokōji during the survival game and suffered a crushing defeat, she never could have imagined it would come to this. A hollow laugh bubbled up in her throat at the thought of how drastically her environment and position had shifted in just a few short days.</p></div>\n<div><p>“You don't know that for sure yet,” Kushida said. “You might be close to the bottom, but there are plenty of other groups out there. It's highly unlikely that there are zero other students struggling just as much as you.”</p></div>\n<div><p>“What's that?” Ibuki asked. “Supposed to be comforting?”</p></div>\n<div><p>“Not really. I only care about saving myself. It's just reassuring for me to have you down at the bottom.” Kushida replied. “And it would be even <em class=\"italic\">more </em>reassuring if there was someone lower than you. I just said it because it's what I was thinking.”</p></div>\n<div><p>It was such a perfectly Kushida-like answer that Ibuki felt, strangely enough, a little relieved.</p></div>\n<div><p>“Do you really want to graduate from Class A that badly?” Ibuki asked.</p></div>\n<div><p>“Obviously. I'm an honors student, after all,” Kushida declared as she stood up and began wading toward the shore. “I'm going to graduate from Class A. I'm going to be respected by everyone around me, respected by my parents, and become a member of society that everyone else envies. I will do whatever it takes to make that happen.”</p></div>\n<div><p>Reaching the wet sand, Kushida glanced back. “There are only a few tasks left now, and I really don't see you making a sudden comeback, Ibuki-san. Still, it wouldn't hurt to hold onto a little hope that someone else might trip up, or that Katsuragi-kun will save you, right?”</p></div>\n<div><p>“I'm heading back,” she added, leaving those words behind as she returned to the campsite ahead of her.</p></div>\n<div><p>It was a situation much like yesterday. Yet, despite the looming threat of expulsion, Ibuki's heart felt undeniably lighter than before.</p></div>\n<div><p>“I'm different from Kushida,” she murmured to the empty beach. “I still don't feel any burning desire to avoid expulsion. But…”</p></div>\n<div><p><em class=\"italic\">If she were to be expelled just like this...</em></p></div>\n<div><p>Thinking about it in those terms, she realized there was exactly one lingering regret left inside her.</p></div>\n<div><h2>Part 1</h2></div>\n<div><p>Our current location was F7.</p></div>\n<div><p>The clock had just struck 5:00 p.m in the evening when the supervisor called everyone together.</p></div>\n<div><p>“Thank you for your hard work over this three-night, four-day special exam,” Urushihara said, diving right into his explanation. “I will now announce your final task.”</p></div>\n<div><p>They could finally return to the ship; that fact slightly, but surely, lightened the hearts of the students.</p></div>\n<div><p>“Your task is to head to the goal location by 7:00 p.m. The destination is Area F13.”</p></div>\n<div><p>F13 was almost the same as our starting point.</p></div>\n<div><p>In other words, we were being told to return to where we had begun, and to do so within the allotted time.</p></div>\n<div><p>“The other groups will be aiming for the exact same goal,” Urushihara continued. “While their current locations differ, they are starting from roughly the same distance away. You may even spot students from other groups along the route.”</p></div>\n<div><p>Though the school had tried to distribute everyone fairly, the reality of the island's terrain meant there would inevitably be some groups with a slight advantage or disadvantage in terms of distance.</p></div>\n<div><p>“Your arrival will be officially recognized thirty seconds after your wristwatches register that you've entered Area F13. Students who reach the goal within the time limit will be awarded three tokens as a reward. Should you fail to arrive on time, Class Points will be deducted in accordance with the rulebook. Furthermore, the penalty for straying too far from your supervisor is nullified from this moment forward. Finally, as I mentioned during the initial briefing, please keep in mind that the moment you cross the finish line, your token count will be permanently locked in. You will absolutely not be able to transfer tokens after that point, so please plan accordingly.”</p></div>\n<div><p>With that, Urushihara pulled out four cell phones.</p></div>\n<div><p>“I will now distribute one of these specialized phones to each class representative. Checking the GPS will help you navigate to the goal. Furthermore, these devices function as walkie-talkies. By linking them to your wristwatch and paying a one-token fee, you can contact the phones of other groups or reveal their locations. Feel free to use these features as needed.”</p></div>\n<div><p>It seemed the communication and tracking functions we’d had access to since the start of the exam were fully integrated into these phones.</p></div>\n<div><p>“From here on, I will not be able to accompany you. Therefore, any penalties related to my presence will be invalidated,” Urushihara concluded. “Please proceed toward the goal at your own pace. I wish you all the best of luck.”</p></div>\n<div><p>Basically, it was up to each group to decide whether to run or walk.</p></div>\n<div><p>The phones were not merely there to keep us from losing sight of the goal, or to prevent members from becoming separated. They were probably also meant to grant us a grace period to transfer tokens as needed before reaching the goal, thereby expanding the range of our strategies.</p></div>\n<div><p>For the most part, events were unfolding exactly as I'd anticipated. There was no need to alter my plan.</p></div>\n<div><p>“What's our move, Ayanokōji?” Yoshida asked. “We could head for the goal separately, but having a majority of the group arrive is the absolute minimum requirement. If we fall out of step and get separated, it could create a massive headache later on. We should definitely move together as one.”</p></div>\n<div><p>“I agree,” I replied. “Does anyone have any objections?”</p></div>\n<div><p>Figuring that none of the Class D students would raise an issue, I turned my attention to the remaining Class A.</p></div>\n<div><p>“I'm on board too,” their representative, Shinohara, answered without hesitation. It was the brightest smile she had shown in days. “In the end, we all need to cross the finish line together.”</p></div>\n<div><h2>Part 2</h2></div>\n<div><p>It was just past 5:30 p.m. Group 2 had already set out, determined to be the first to reach the goal.</p></div>\n<div><p>Given that all the groups had started at roughly the same distance, it was highly unlikely that anyone had crossed the finish line yet.</p></div>\n<div><p>Hirata marched at a brisk, unrelenting pace, his expression growing grimmer by the minute. The exact same could be said for Ryūen. However, their minds were occupied by vastly different concerns.</p></div>\n<div><p>Hirata was solely focused on the physical safety of the group and the stability of his class. Ryūen, on the other hand, was entirely consumed by the exam’s impending results and the massive shift in class rankings it would trigger.</p></div>\n<div><p>So far, Ryūen had amassed a total of 110 front-side tokens. He was undoubtedly the top earner in his group, securing what could easily be called a solid result. Reaching the goal would add another three tokens to his count, and if their group finished in first place, they would retain 100% of their tokens through the final multiplier.</p></div>\n<div><p>It was by no means a bad position. Even so, by his own rough calculations, he had missed out on at least twenty tokens along the way. Knowing Ayanokōji, there was a very high probability that he had secured far more tokens than Ryūen had managed.</p></div>\n<div><p>Even assuming Ayanokōji only had 130, Ryūen would need a 20% multiplier advantage to beat him. That meant if Group 2 defended first place with their lives, Ayanokōji’s group would still need to place fifth or lower.</p></div>\n<div><p>That was the absolute minimum baseline required to keep any hope of victory alive. It would be easy enough to contact Katsuragi and order him to stall outside the goal area. But since a group's ranking was locked in the moment a simple majority finished, the conditions would still be met even if Katsuragi and all the Class B students in that group resisted. All the sabotage would accomplish was leaving the resisters with a severe penalty for failing to finish.</p></div>\n<div><p>If Ayanokōji coasted safely to the finish line as things stood, the Class Point gap between them would shrink by 100. And if, by some stroke of luck, his group also took first place? The gap would widen by 200. It would be an undeniable, crushing defeat.</p></div>\n<div><p>How could he proactively sabotage Ayanokōji and snatch that victory away?</p></div>\n<div><p>“...Guess I’ve got no choice,” Ryūen muttered.</p></div>\n<div><p>You had to be willing to let the enemy cut your flesh if you wanted to sever their bones. Without that kind of ruthless resolve, he would never be able to drag Ayanokōji down into the dirt and deal him his first real loss. He couldn't grasp victory without discarding his hesitation and taking a massive risk.</p></div>\n<div><p>Ever since he had deciphered the hidden mechanics of this special exam, a certain strategy had been smoldering in the back of Ryūen's mind.</p></div>\n<div><p>Just as he was about to put that plan into action, Hirata made a move.</p></div>\n<div><p>“Ryūen-kun, do you mind if I confirm something with you?”</p></div>\n<div><p>Despite their need to hurry, Hirata stopped in his tracks, forcibly dragging Ryūen into a conversation.</p></div>\n<div><p>“What is it?” Ryūen asked.</p></div>\n<div><p>“Having come this far, there's no way you haven't realized anything, right?”</p></div>\n<div><p>Hirata's words were heavy with implication. His gaze bore into Ryūen, sharp and analytical, as if trying to peer straight through into his thoughts.</p></div>\n<div><p>“No idea what you're talkin' about,” Ryūen replied casually. Then, finding the situation unintentionally amusing, he let out a dark chuckle. “What exactly are you aimin' for, Hirata? Let's hear it.”</p></div>\n<div><p>“We’ve taken this exam seriously and earned as many tokens as we possibly could,” Hirata began. “And right now, we’re using a single ‘indicator’ to buy ourselves a fleeting sense of safety. But even so, I know there are students here who are still feeling anxious. So, before we go any further, I want anyone who is worried to come forward, regardless of what class you're in. If you check your token count and feel there's even a slight chance you might end up in last place, tell me. I will support you as much as I possibly can.”</p></div>\n<div><p>He addressed the entire group, his tone implying that even Ryūen was no exception to the offer.</p></div>\n<div><p>“I thought I had your personality figured out to some extent,” Ryūen scoffed. “But it seems you're an even bigger softhearted idiot than I imagined. Or do you have some ulterior motive?”</p></div>\n<div><p>“You think I have some ulterior motive?” Hirata's eyes remained perfectly calm, completely unreadable as they locked onto Ryūen. “After spending this entire exam in the same group, I think you already know the answer to that, Ryūen-kun.”</p></div>\n<div><p>“Hah. Well, do whatever the hell you want,” Ryūen shot back. “As long as the group's total token count doesn't drop, it ain't got a damn thing to do with me.”</p></div>\n<div><p>Following Hirata's declaration, two students cautiously stepped forward. After confirming their standings, Hirata transferred a few of his own tokens over to them to ensure their safety.</p></div>\n<div><p>“Alright, we can't afford to fall behind any further,” Hirata announced, turning back toward the trail. “We're almost there. Let's do our best.”</p></div>\n<div><p>As Hirata resumed his brisk pace, Ryūen followed close behind. But inside his head, the gears of his strategy never stopped turning.</p></div>\n<div><p>“Ain't no way I'm letting this special exam end just like this,” Ryūen muttered.</p></div>\n<div><p>“...What do you mean by that?” Hirata asked.</p></div>\n<div><p>“The token-gathering tasks in this exam were pretty much tailor-made for the highly capable,” Ryūen explained. “A guy with high academic ability could scrape together close to a hundred tokens just off that alone. Throw in being quick on your feet and having good intuition, and you could stack up even more.”</p></div>\n<div><p>At Ryūen's gesture, Kaneda immediately stepped up beside him.</p></div>\n<div><p>“Indeed. Unlike the absurd survival test on the uninhabited island, the contents this time constituted a proper academic exam,” Kaneda noted.</p></div>\n<div><p>“Which begs the question...Just how many tokens do you think that bastard Ayanokōji managed to gather?”</p></div>\n<div><p>Ryūen turned his gaze to Hirata, former classmate of the subject in question.</p></div>\n<div><p>“A proportionate amount, I'd imagine,” Hirata replied calmly. “Knowing him, it wouldn't surprise me if he's already exceeded one hundred and thirty, or even one hundred and forty.”</p></div>\n<div><p>“I share that assessment, Hirata-shi,” Kaneda agreed. “That is precisely why it is paramount we force his reward multiplier down, even if only by a fraction. It is the very reason we are currently rushing to the goal.”</p></div>\n<div><p>“But even if we knock his multiplier down a peg, it won't mean jack shit if that bastard’s holding enough tokens to blow right past it anyway,” Ryūen shot back.</p></div>\n<div><p>Ever since the rules of this special exam had been announced, a singular thought had been swirling in the back of Ryūen's mind.</p></div>\n<div><p>A massive gamble to prevent Ayanokōji from winning.</p></div>\n<div><p>“There's someone I need to contact right now,” Ryūen declared, his voice rough.</p></div>\n<div><p>Recalling his decision to show no mercy, he made Kaneda use a token and grasped the cell phone in his hand.</p></div>\n<div><p>A call to Shiina. After waiting for about 7 rings, the line connected, and Ryūen called out to her.</p></div>\n<div><p>“Is something the matter, Ryūen-kun?” Shiina's voice crackled through the radio.</p></div>\n<div><p>Ryūen had fully intended to cut straight to the chase, but for a split second, the words caught in his throat.</p></div>\n<div><p>“No───”</p></div>\n<div><p>He was a man entirely accustomed to being called atrocious, a tyrant who reveled in his own cruelty. So why, at the very last second, was he hesitating?</p></div>\n<div><p>But that tiny gap of silence was more than enough for Shiina to understand exactly why he was calling.</p></div>\n<div><p>“You're thinking... that if things stay as they are, we will lose, at least in terms of individual token counts. Am I right?”</p></div>\n<div><p>\"According to Katsuragi's report, Ayanokōji's done pretty damn well for himself,\" Ryūen admitted.</p></div>\n<div><p>“I see…” she murmured softly. “What should I do? Please, give me your orders.”</p></div>\n<div><p>“...Right. I'll relay the instructions now.”</p></div>\n<div><p>As Ryūen coldly outlined the plan, Kaneda, who had been quietly eavesdropping beside him, rapidly turned pale.</p></div>\n<div><p>And finally, when he was finished, Shiina voiced a single wish.</p></div>\n<div><p>“Even if I end up being expelled over this... please do not use your Private Points to save me.”</p></div>\n<div><p>Ryūen had been hoarding Private Points for a long time, desperately saving them up to bring his plan closer to reality. If he coughed them up now, he could invalidate her expulsion. But doing so would cause his entire overarching strategy to collapse. If the opponent knew that saving her using Private Points was the premise, even if he employed similar methods in the future, a reliable effect could not be obtained. It was precisely because he would truly cut her off that it became a meaningful strategy.</p></div>\n<div><p>“Obviously,” Ryūen replied.</p></div>\n<div><p>“I'm relieved to hear that. Well then…”</p></div>\n<div><p>With those soft words, the call abruptly cut off. Ryūen lowered the phone and cast a sideways glance at Kaneda, whose lips were trembling.</p></div>\n<div><h2>Part 3</h2></div>\n<div><p>It was 5:40 p.m. Our group had made good time, advancing just far enough to slip out of Area G11.</p></div>\n<div><p>Up to this point, our march had gone smoothly, with no one sustaining any major injuries. However, it was also around this time that the creeping anxiety began to take a visible toll on the students.</p></div>\n<div><p>“Damn it, I wonder how we're holding up right now,” Sonoda muttered restlessly from the middle of the pack. “I can't help but worry about where all the other groups are.”</p></div>\n<div><p>We <em class=\"italic\">could </em>use our tokens to verify the positions of the other groups. But spending a token only revealed the location of a single person. To pinpoint the whereabouts of all nine groups currently racing toward the goal, we would need to burn through a minimum of nine tokens.</p></div>\n<div><p>We had the authority and the means to check, but we simply couldn't afford to pull the trigger. It was like having a terrible itch, scratching it to suppress the urge was easy, but if you wanted the wound to truly heal, you had to endure the agonizing urge to touch it.</p></div>\n<div><p>As the students continued their march through this frustrating stretch of time, the Class C cell phone in my pocket began to vibrate.</p></div>\n<div><p>I pulled it out. The screen simply displayed the name ‘Ayanokōji Kiyotaka’, meaning this call was directed specifically at me. Because it didn't show a caller ID, I wouldn't know exactly who was on the other end until I picked it up, but I already had an idea who it could be.</p></div>\n<div><p>Telling Yoshida and the others to go on ahead, I let myself fall to the very back of the group. Ike and Shinohara were bringing up the rear, walking side-by-side. I gave them a brief gesture with the phone to signal I was taking a call, prompting them to pass me by.</p></div>\n<div><p>“Looks like you raked it in on those tasks,” Ryūen's voice crackled through the earpiece the instant the line connected. “I already got Katsuragi's report on you.”</p></div>\n<div><p>“Just decently well.” I replied. “Did you go out of your way to confirm something like that right before the goal?”</p></div>\n<div><p>“How many tokens did you gather?” Ryūen asked.</p></div>\n<div><p>“That's quite a straightforward question, but unfortunately, I can't tell you.”</p></div>\n<div><p>“130? 140? I might not know the exact number, but I can easily guess you earned more than me.”</p></div>\n<div><p>He knew I had no intention of answering, yet he pressed on anyway.</p></div>\n<div><p>“If I had to list my one real advantage here, it's just that the goal is right before our eyes.”</p></div>\n<div><p>Whether he was telling the truth or bluffing, there was only one logical response I could give him.</p></div>\n<div><p>“Then I recommend you hurry up and reach the goal.”</p></div>\n<div><p>“Yeah, well, I figured I wouldn't be breakin' a sweat if I could win just on the multiplier alone,” Ryūen said. “You've probably got all the rules memorized anyway, so I'll put it simply. Group 4 is currently in Area H10. And I just ordered one of my classmates in that group to march straight toward K14, completely in the opposite direction of the goal. You understand what that means, right?”</p></div>\n<div><p>Group 4. One of the groups I hadn't encountered even once during this Special Exam.</p></div>\n<div><p>And it was the group that Shiina Hiyori from Ryūen's class belonged to.</p></div>\n<div><p>“And?” I asked.</p></div>\n<div><p>“Hah, ‘and’ you say.” Ryūen scoffed. “If things go south, Shiina's gonna get expelled.”</p></div>\n<div><p>I quickly ran the numbers in my head. Assuming it took Hiyori an hour to hike out to Area K14, it would take her at least an hour and a half to double back to the goal at F13. Given her walking speed, it was a mathematical certainty: she absolutely would not make it back in time.</p></div>\n<div><p>“That doesn't sound like a bad thing to me,” I replied. “But what's the purpose of sending Hiyori off on a solo counter-march? The issue concerning Class B is your problem, not mine.”</p></div>\n<div><p>“I wonder if you actually mean that, or if you're just putting on a tough front.”</p></div>\n<div><p>Ryūen, dropping his voice to a low tone, continued further.</p></div>\n<div><p>“I had her leave just one token on hand and entrust all the rest to her team mates. Then I told her to just wait on standby at K14 until the Special Exam ends───”</p></div>\n<div><p>“Did you want to choose the student to be expelled yourself?” I interrupted. “If you didn't need the groundwork I laid for you, I would've appreciated being told.”</p></div>\n<div><p>“To you, Shiina is a person with value,” he replied.</p></div>\n<div><p>“Using a friend as a decoy is certainly an interesting strategic move,” I conceded, “but since we're in different classes, its effectiveness is incredibly thin. We are friends, nothing more, nothing less. You're calling me under the assumption that I'll abandon my position to go save her. If your expectations are off, this is nothing more than an act of self-destruction.”</p></div>\n<div><p>Whether Hiyori reached the goal or got expelled had absolutely no bearing on the outcome of this exam. However, the price of losing an excellent student would have a massive negative impact on Class B in the long run.</p></div>\n<div><p>“You aren't that foolish,” I continued. “Which means there's a very real possibility you're just feeding me a fabricated story.”</p></div>\n<div><p>Ryūen's lie, concocted with the thought that I, worried about Hiyori's current location, would consume tokens to verify the truth at least a few times from here on out. His aim was to shave off my tokens, even if only slightly.</p></div>\n<div><p>But ultimately, avoiding that was also easy. I just had to ask Yoshida, Sanada, and the others to consume theirs instead.</p></div>\n<div><p>“Even if everything you just said is true,” I added, “losing Hiyori is a massive blow to Class B. You'd bail her out even if it cost you twenty million Private Points.”</p></div>\n<div><p>“Shiina said the exact same thing. That's why she told me absolutely not to save her with points.”</p></div>\n<div><p>“If you earnestly executed this strategy, then that is the only correct answer. Bait only works when it actually functions as bait. Either way, though, both you and Hiyori made the same miscalculation.”</p></div>\n<div><p>Staring quietly ahead, I kept my pace steady toward the goal.</p></div>\n<div><p>“I have acquired as many tokens as possible. Assuming I secure a decent overall rank, there's a very high probability I'll earn a special prize for my individual results. And since we've temporarily dropped down to Class D, earning Class Points here is an absolute must. By any reasonable measure, I am not going to save Hiyori.”</p></div>\n<div><p>Without waiting for a response, I severed the connection.</p></div>\n<div><p>Picking up my pace, I quickly caught back up with Yoshida and the rest of the group.</p></div>\n<div><p>“Who was that on the phone?” Yoshida asked.</p></div>\n<div><p>“Just a final obstruction from another class,” I replied. “A desperate, futile struggle.”</p></div>\n<div><p>“Obstruction? ...Is everything okay?”</p></div>\n<div><p>“Don't worry about it. More importantly, let's pick up the pace and aim for the goal. Our group's ranking is far more crucial right now.”</p></div>\n<div><p>I hadn't expected any response to the arrow I'd set in motion, let alone an attempt to catch me off guard, but..</p></div>\n<div><p>“You've played a bold hand, Ryūen.” I muttered softly.</p></div>\n<div><p>Even knowing there was a very real chance it would amount to nothing, he had gone through with it anyway.</p></div>\n<div><h2>Part 4</h2></div>\n<div><p>Right after the communication with Ayanokōji ended, Kaneda, unable to suppress the emotions he had been enduring, pressed in on Ryūen.</p></div>\n<div><p>“What exactly are your intentions here... Ryūen-shi...!”</p></div>\n<div><p>“Hah? What's there to wonder about? It's exactly like you heard,” Ryūen replied callously. “I feel bad for Shiina, but I had her play the bait to lure Ayanokōji out. If that bastard doesn't bite, I'll just have her get expelled right here.”</p></div>\n<div><p>“T-That's completely absurd! Shiina-shi is an incredibly important student to our class! For you to do something like this...!”</p></div>\n<div><p>“Ain't it just that you're lettin' your own damn feelings get in the way 'cause you don't want her expelled?”</p></div>\n<div><p>Like a frog caught in the glare of a snake, Kaneda stiffened, momentarily paralyzed by fear.</p></div>\n<div><p>However, he immediately shattered that invisible curse through sheer force of will and argued right back.</p></div>\n<div><p>“No, you are entirely mistaken...! Even <em class=\"italic\">you </em>should understand that much, Ryūen-shi! It's clearly a foolish plan... No, to call it foolish is far too generous. It's nothing short of barbarism!”</p></div>\n<div><p>Behind the lenses of his glasses, Kaneda's eyes were blazing with an unprecedented, unconscious intensity.</p></div>\n<div><p>“I think it's best if you calm down and cool your head, Kaneda-kun,” Hirata interjected softly, trying to defuse the situation.</p></div>\n<div><p>Having been granted permission to listen to Ryūen's entire conversation, he had heard everything from start to finish.</p></div>\n<div><p>“I <em class=\"italic\">am </em>calm,” Kaneda snapped back. “It is precisely because I am calm that I am saying this!”</p></div>\n<div><p>“It's real simple,” Ryūen said, his voice dropping low. “Just shut your mouth and obey what I decided.”</p></div>\n<div><p>\"I cannot obey... Please lend me the phone. I will contact Shiina-shi and tell her it's unnecessary.\"</p></div>\n<div><p>“If you absolutely cannot bring yourself to obey me, then you’ll just have to try making me yield by force,” Ryūen sneered, lazily looking away.</p></div>\n<div><p>“Tch!”</p></div>\n<div><p>Utterly infuriated by the blatant disrespect, Kaneda impulsively shot out his right arm, and grabbed Ryūen by his collar.</p></div>\n<div><p>“You're shaking, Kaneda,” Ryūen mocked softly. “You actually got it in you to hit me?”</p></div>\n<div><p>“I-if raw force is the only language you'll listen to….even then… I’m prepared to—!”</p></div>\n<div><p>“Stop it!” Hirata stepped in before the situation could escalate any further, forcefully prying Kaneda's grip off of Ryūen's uniform. “Doing this won't solve anything.”</p></div>\n<div><p>Kaneda stumbled back, adjusting his glasses with trembling fingers. “...Excuse me. This is the first time I've ever felt quite like this... But things have certainly become clear. So, this is the emotion known as anger... Ryūen-shi, I don't care what logic you devise, I will absolutely never accept this.”</p></div>\n<div><p>“It's true that as a strategy, there’s nothing to be praised,” Hirata said, stepping between the two. “I also think you should contact Shiina-san again even now. But let me ask you one thing. Can you declare that this is the absolute best plan to prevent Ayanokōji-kun from winning? I am genuinely curious.”</p></div>\n<div><p>“I gave the order 'cause that's what I decided,” Ryūen growled, glaring at Hirata. “I ain't got no obligation to sit here and spell it out for you.”</p></div>\n<div><p>Kaneda had been terrified by that very same glare, but Hirata received it head-on, not shrinking back in the slightest.</p></div>\n<div><p>“...I see,” Hirata murmured. “You truly believe that Shiina-san is someone Ayanokōji-kun would save even at the cost of victory.”</p></div>\n<div><p>Because he was missing context, there were parts of this conflict Hirata didn't fully understand. At the same time, there were parts he found easy enough to accept. It was certainly true that Ayanokōji treated Shiina differently from everyone else. However, he had never imagined her as an existence Ayanokōji would voluntarily abandon victory for, someone he would go so far as to save even at the risk of his own expulsion.</p></div>\n<div><p>“Seems you got your own thoughts about Ayanokōji too,” Ryūen sneered at Hirata. “Well, can't really blame ya.”</p></div>\n<div><p>“I would like to see it,” Hirata murmured, his eyes narrowed slightly. “I'd like to see how Ayanokōji-kun actually answers your question.”</p></div>\n<div><p>“Hirata-shi, you are ultimately just a bystander,” Kaneda snapped, turning to Hirata. “You can say it so lightly because you aren't a student in our class! And the exact same goes for Ayanokōji-shi! He is in a position where he <em class=\"italic\">must </em>continue to produce results in order to carry his class to victory. I absolutely refuse to believe he would willingly throw himself into massive risk just to go save Shiina-shi!”</p></div>\n<div><p>“You can't believe it?” Ryūen taunted. “Or is it just that you don't <em class=\"italic\">wanna </em>believe it?”</p></div>\n<div><p>“T-That's not...!”</p></div>\n<div><p>A vivid memory flashed through Kaneda's mind: an exchange he had witnessed between Ayanokōji and Shiina in the library. The way her expression softened when she spoke to him, a look that seemed identical to her usual smile, yet felt entirely, undeniably special, reserved for Ayanokōji alone.</p></div>\n<div><p>The realization hit Kaneda like a physical blow. Delight at the sheer purity of her unmasked face clashed instantly with searing, defensive rage. A fierce cocktail of conflicting emotions coursed violently through Kaneda’s veins.</p></div>\n<div><p>“If you wanna stop it that badly, then go pick her up yourself right now,” Ryūen provoked him. “But with those slow legs of yours, you'll never make it in time.”</p></div>\n<div><p>“Then I will stop it even if I have to consume my Protection Point. Right now, I will drop my tokens to 0───”</p></div>\n<div><p>“That's useless, Kaneda-kun,” Hirata interrupted gently. “Even if you transfer all your tokens and drop to zero, the penalty you incur for deliberate insolvency is entirely different from finishing in last place. The fact that you didn't even think of that is proof you aren't thinking clearly.”</p></div>\n<div><p>If Kaneda dropped his tokens to zero right now, he would simply be disqualified and forced to wait out the rest of the exam on the ship. It wouldn't offer Shiina any salvation whatsoever.</p></div>\n<div><p>“Furthermore, even if you ended the exam with exactly one token to tie with Shiina-san, your overall OAA rating is higher,” Hirata continued. “The tiebreaker would still dictate that Shiina-san is the one who gets expelled.”</p></div>\n<div><p>In truth, Hirata didn't actually remember Shiina and Kaneda's exact OAA scores. However, he had deduced that if Kaneda could become a substitute using that method, Ryūen would’ve never let him listen in on the phone call to begin with.</p></div>\n<div><p>“Guh...!” Kaneda gritted his teeth.</p></div>\n<div><p>Desperately formulating a counter-plan, he briefly considered lowering Group 2’s overall rank to decrease the final token multiplier. However, he immediately realized that if Hiyori only possessed a single token, she wouldn't be affected by the multiplier math anyway. There was nothing the current Kaneda could do to shield her from expulsion.</p></div>\n<div><p>“The only reliable way to save her is to physically reach Shiina-san before the exam ends and transfer your tokens directly to her,” Hirata explained. “Ryūen-kun waited until this exact moment to bring it up because he knew that.”</p></div>\n<div><p>“If Ayanokōji goes to save Shiina, he ain't makin' it back to the goal in time, putting his final multiplier at 70%,” Ryūen explained. “And if he transfers his own tokens to her to save her, it'll also drain Group 3's total stash. That’s two birds with one stone.”</p></div>\n<div><p>The only variable Ryūen couldn't control was whether he could force Ayanokōji to spend his visible ‘front-side’ tokens. There was always a chance Ayanokōji's groupmates had entrusted him with hidden, unrecorded tokens to act as a secret safety net.</p></div>\n<div><p>“Since when…” Kaneda's voice trembled. “Since when did you decide to use Shiina-shi like this?”</p></div>\n<div><p>“I ain't answering that.”</p></div>\n<div><p>This was undeniably a major gamble for Ryūen as well. He may have set it all in motion, but the power to decide the outcome now rested with Ayanokōji.</p></div>\n<div><p>Either Shiina would be expelled, or Ayanokōji would be defeated. There was no third possibility.</p></div>\n<div><p>“If, by any chance, Shiina-shi actually ends up getting expelled…” Kaneda spat, his voice laced with venom. “I will never forgive you.”</p></div>\n<div><p>“Before you start barkin' about forgiveness, first fulfill your own damn responsibility as a member of this group,” Ryūen ordered coldly. “Use those legs to reach the goal as fast as possible to make the class win.”</p></div>\n<div><p>Ryūen was telling him the hard truth: the only thing Kaneda could do right now was reach the goal. That was it.</p></div>\n<div><p>“And one more thing─ if you wanna punch me, next time grab my collar with your left hand.”</p></div>\n<div><p>Punching with the dominant arm is what's important, Ryūen declared with a faint smirk playing across his lips.</p></div>",
    "10": "<div><p>6:07 p.m., the endgame of the special exam. Through gaps in the deep forest, open vistas gradually came into view.</p></div>\n<div><p>The sheer toll of simply walking—so consuming it felt almost illusory—had driven everyone's fatigue to its absolute limit. Their breathing was shallow, their sweat long since dried; only the sensation of sea salt clinging to their skin remained. Yet no one stopped walking. Having come this far, stopping now was not an option that existed in anyone's mind.</p></div>\n<div><p>—Reach the finish line as a Group as quickly as possible, and maintain a high multiplier.</p></div>\n<div><p>—This meant greater rewards, and the avoidance of penalties.</p></div>\n<div><p>Step by step, the distance was steadily shrinking.</p></div>\n<div><p>At last, that moment arrived.</p></div>\n<div><p>\"Whoa, stop, everyone. I think this is the finish zone.\"</p></div>\n<div><p>Yoshida, who had been walking at the front, caught the signal on his wristwatch and stopped short in a fluster—then quickly retreated a few steps to exit the zone.</p></div>\n<div><p>\"Final confirmation of everyone's tokens... that's all right, yeah;?\"</p></div>\n<div><p>\"Yeah. Better to double-check, just to be safe.\"</p></div>\n<div><p>Thirty seconds after entering the zone, arrival at the finish line would be registered and the tokens would lock, becoming immovable. They wanted to reach the finish line even a moment sooner, but they had to restrain themselves—this step demanded meticulous care.</p></div>\n<div><p>—Their final results were the crucial link that would prevent expulsions and pave the way for the next stage.</p></div>\n<div><p>\"But even with a final confirmation, nobody knows exactly how many tokens are safe to hold, right?\"</p></div>\n<div><p>Yoshida muttered. But he was wrong.</p></div>\n<div><p>—Within this group, more than half the students already had a firm grasp of their own token counts.</p></div>\n<div><p>To complete the information sharing, I turned and swept my gaze across the entire Group before speaking.</p></div>\n<div><p>\"The minimum token count you need to secure before reaching the finish line is '51.' Holding that number guarantees you will not be expelled.\"</p></div>\n<div><p>—At my assertion, neither Class C nor Class D showed any surprise.</p></div>\n<div><p>—On the other hand, Sonoda and a few other students looked bewildered.</p></div>\n<div><p>\"Why can you say that? Don't talk nonsense, Ayanokouji.\"</p></div>\n<div><p>\"Yeah, where did the number '51' even come from?\"</p></div>\n<div><p>The first to snap back was Ike. Immediately after, Shinohara chimed in.</p></div>\n<div><p>—But there was something about these two that didn't feel like genuine confusion—a hint of play-acting.</p></div>\n<div><p>—Kushida and Mii-chan, who genuinely didn't understand where the number came from, looked baffled.</p></div>\n<div><p>\"No, this number isn't nonsense. It's because I have now confirmed that the lowest token count within this group is '50.' \"</p></div>\n<div><p>—With those words, Ike and the others swiveled their gazes toward Ibuki Mio in unison.</p></div>\n<div><p>—Ibuki hastily hid her wristwatch, though the display hadn't been in its normal state to begin with.</p></div>\n<div><p>\"It's not especially difficult. For three nights and four days, we have been acting together as a Group and undertaking all the same challenges. The initial token counts were also linked to survival time in the Survival Game Special Exam. Simple addition and subtraction—even an elementary schooler could figure out the answer.\"</p></div>\n<div><p>\"...But... what about what I received from Katsuragi? How many tokens in total—\"</p></div>\n<div><p>Ibuki, about to argue back, realized—even she, slow as she was—the reason I could assert this with such certainty.</p></div>\n<div><p>—All of this had been set up from the very beginning.</p></div>\n<div><p>\"You don't mean...\"</p></div>\n<div><p>Ibuki's gaze shifted from me to Katsuragi.</p></div>\n<div><p>—Since there was no longer any need to conceal it, Katsuragi's expression also shifted slightly.</p></div>\n<div><p>\"Yes. The number of tokens I transferred to you—all of it was shared with Ayanokouji as information.\"</p></div>\n<div><p>—Katsuragi's confession. His betrayal. I followed up with a few more words for Ibuki.</p></div>\n<div><p>\"In a special exam where someone will be expelled, the tension persists throughout. But if you designate a person to bear that responsibility in advance and share the information, the other members can be freed from the psychological pressure.\"</p></div>\n<div><p>Just as I was about to continue, Shinohara cut in ahead of me.</p></div>\n<div><p>\"How pitiful, Ibuki-san. Ayanokouji-kun has been using you from the very start.\"</p></div>\n<div><p>\"...Since when? When did you decide to cut me loose?\"</p></div>\n<div><p>\"Probably from the very beginning? Or from when Katsuragi-kun became the Representative. Roped in by Ayanokouji-kun, so you never gave Ibuki an equal share of tokens from the outset. Isn't that right?\"</p></div>\n<div><p>\"Remarkably well-informed, Shinohara. I don't recall telling you about my collusion with Katsuragi.\"</p></div>\n<div><p>—None of the others present had noticed that Katsuragi and I were in a cooperative relationship either.</p></div>\n<div><p>—Only Shinohara grasped it, making her narrow her eyes smugly.</p></div>\n<div><p>\"You must have concealed it precisely to avoid detection.\"</p></div>\n<div><p>—She practically seemed to be flaunting that she had figured it out through her own ability.</p></div>\n<div><p>\"Then there's no further need to hide the details.\"</p></div>\n<div><p>—Once the remaining time ran out, the results would be announced. Letting someone be expelled without understanding why wouldn't sit well either.</p></div>\n<div><p>\"I discussed with Katsuragi whom to use as the benchmark—the designated sacrifice, so to speak. The choice was Ibuki. Then, at lunchtime on the final day, I informed each class via wireless of the token count they needed to secure. The only ones kept in the dark were the four Class A members in Group 3, and all of Class B except Katsuragi.\"</p></div>\n<div><p>\"...Why didn't you tell us?\"</p></div>\n<div><p>Kushida, who had heard nothing at all, spoke up with a mixture of anxiety and discontent.</p></div>\n<div><p>\"Not everyone is an actor. If they knew the truth, it would create a sense of dissonance within the group. By keeping roughly half in the dark, Ibuki would not grow suspicious.\"</p></div>\n<div><p>\"Furthermore, this strategy only began to be shared across the entire third-year cohort starting last night.\"</p></div>\n<div><p>—At this point, I began to recount the process of releasing the arrow.</p></div>\n<div><p>—Rewinding the timeline to the night of Day 3, after the second radio communication from the field.</p></div>\n<div><p>—I had the wireless connected to Group 8, where Ichinose was. After Monitor Sakagami-sensei answered, he immediately handed the radio device to Ichinose-san.</p></div>\n<div><p>\"Sorry to keep you waiting, Ayanokouji-kun. What do you need?\"</p></div>\n<div><p>—Ichinose's voice carried a trace of brightness as she spoke steadily into the wireless.</p></div>\n<div><p>\"It's nearly the end of Day 3. The outcome is essentially settled—the trajectory is set. Is Horikita nearby? If it's convenient, have her listen in.\"</p></div>\n<div><p>—Wireless communications were essentially one-on-one. Handing the device to someone else mid-call was prohibited, and having others join the conversation was against the rules—but removing the earphone and letting my voice carry to those nearby was not a violation.</p></div>\n<div><p>\"Understood, just a moment. Horikita-san, can you come over?\"</p></div>\n<div><p>—Ichinose readily agreed and called Horikita over.</p></div>\n<div><p>\"...Understood, I'm listening from beside her.\"</p></div>\n<div><p>—Horikita's voice, slightly tinged with confusion, came through the wireless. Though the main speaker was still Ichinose.</p></div>\n<div><p>\"I've called her. She's listening now.\"</p></div>\n<div><p>\"I'll keep this brief. In this special exam, one person will inevitably be expelled. Even if it could be avoided with a Protection Point or a large sum of Private Points, the third-years currently have no such margin.\"</p></div>\n<div><p>\"Indeed. We've been fighting with that hanging over us the entire time.\"</p></div>\n<div><p>\"The orthodox approach we can take is to adjust token counts as much as possible so that no student from Class A or Class D ends up at the very bottom. But there's no clear safety line.\"</p></div>\n<div><p>\"The risk of tying for last place will always remain.\"</p></div>\n<div><p>\"To avoid that—I've preemptively decided on a student to bear that responsibility.\"</p></div>\n<div><p>\"A student to bear that responsibility...?\"</p></div>\n<div><p>—What was Horikita, listening beside her, thinking?</p></div>\n<div><p>—It wouldn't be strange for her heart to beat faster with unease.</p></div>\n<div><p>—If the token count and multiplier of the student with the fewest tokens were known with one hundred percent certainty, then the remaining students could reliably avoid expulsion simply by holding one more token.</p></div>\n<div><p>—What should have surfaced first in Horikita's mind were the four members of Class A, led by Kushida.</p></div>\n<div><p>But at the same time, another kind of anxiety would also surface: if someone from Class A really was to be expelled, would he have asked her about it first?</p></div>\n<div><p>\"Ayanokouji-kun, who is it that you intend to expel?\"</p></div>\n<div><p>—Ichinose's question. This composure matched her stance of \"showing no mercy for the sake of her classmates.\"</p></div>\n<div><p>\"Ibuki, from Class B, who belongs to my Group 3.\"</p></div>\n<div><p>\"Ibuki-san... I see.\"</p></div>\n<div><p>—No one would be happy upon hearing that name.</p></div>\n<div><p>—She would likewise have doubts, but she might also feel relief that \"thank goodness it's not my class.\" Or complex emotions might churn within her.</p></div>\n<div><p>—Why Ibuki—she was probably desperately restraining herself from asking.</p></div>\n<div><p>—And on the other end of the radio, listening, was Ibuki's homeroom teacher, Sakagami-sensei.</p></div>\n<div><p>—Hearing that a student from his own class was being pushed toward expulsion, his heart would of course not be calm—but a homeroom teacher could not intervene in a special exam.</p></div>\n<div><p>\"Why it's Ibuki-san—I won't ask. Since Ayanokouji-kun has decided this, it's because he has judged it to be optimal.\"</p></div>\n<div><p>\"Yes. At this stage, this is a settled matter in my mind. If an expulsion candidate were to emerge randomly from an unspecified mass, there is a risk of losing excellent talent. That is unavoidable in a special exam—but where control is possible, I want to avoid accidents as much as possible. Going forward, on my end, before reaching the finish line I will fully share Ibuki's acquired token count with the entire Group. To be certain, the multiplier will be calculated at one hundred percent. In other words, holding just one token more than Ibuki guarantees you will avoid expulsion.\"</p></div>\n<div><p>\"That's why you're having Horikita-san listen as well. But what's your explanation for Class B?\"</p></div>\n<div><p>\"No explanation is needed. Sharing it with the three other classes is sufficient.\"</p></div>\n<div><p>—I added a supplementary remark: as long as no one within Class B was made to have fewer tokens than Ibuki, there would be no risk, and continued.</p></div>\n<div><p>\"Horikita and Ibuki do share a certain connection. After hearing this, if she wants to prevent Ibuki's expulsion, she is free to try. But if I detect even a hint of movement on her part, the very next second I will switch the expulsion target to someone from Class A. Ike or Shinohara—easy enough to drop—or Kushida or Mii-chan, whose loss would deal a heavy blow to the class. That judgment will be mine.\"</p></div>\n<div><p>—I delivered a strong warning to Horikita, whose expression had probably begun to stiffen.</p></div>\n<div><p>\"Ibuki currently holds 36 tokens. I'll contact you again tomorrow if there are any changes. The current number is important, but what's more important is the number held at the moment of reaching the finish line.\"</p></div>\n<div><p>\"Yes, understood. I'll prepare for sharing on my end as well.\"</p></div>\n<div><p>—After Ichinose answered thus, I cut the radio.</p></div>\n<div><p>\"Sakagami-sensei, connect a wireless to Ayanokouji immediately.\"</p></div>\n<div><p>\"That's fine, but Horikita, how do you intend to speak with him?\"</p></div>\n<div><p>\"Wait, Horikita-san. After hearing Ayanokouji-kun's words, you can't just docilely obey with a 'yes,' right?\"</p></div>\n<div><p>\"Turning the spear toward us unilaterally—I won't accept that. Wasn't our aim from the start to avoid producing an expulsion from our own classes? Ayanokouji-kun's proposal is surprising, but as a tactic, there's nothing wrong with it.\"</p></div>\n<div><p>\"Th... That I understand, but to deliberately have a specific person expelled in the special exam...\"</p></div>\n<div><p>\"Acting within the bounds permitted by the rules does not constitute a violation. Is that not so, Sakagami-sensei?\"</p></div>\n<div><p>\"Yes, my feelings are complicated, but what Ayanokouji-kun is doing does not violate the rules. He will continue to proceed shrewdly from here. If you dislike it, then... it would require you, Horikita, to choose another student in his place and counterattack using the same method, wouldn't it? In other words, you too would have to use Ayanokouji-kun's approach.\"</p></div>\n<div><p>—Deliberately guiding someone's token count below Ibuki's was, in effect, intentionally causing their expulsion.</p></div>\n<div><p>—If one didn't want to do it deliberately, the only alternative was to leave it to chance.</p></div>\n<div><p>—If he used the B11 information about Ibuki, he could make Ibuki's expulsion highly probable. If he left it to chance, Ayanokouji might switch the target to a Class A student. He might also mobilize Ryuuen-kun. From the perspective of the Class B homeroom teacher, that outcome would be the most reassuring for him.</p></div>\n<div><p>—At Sakagami's words, which verged on heartfelt truth beyond his role as an exam officer, Horikita bit her lip and pondered.</p></div>\n<div><p>\"Wanting to protect your friends isn't a bad thing. But first, you must face the situation squarely. What you can do, Horikita. What Ibuki herself can do. If necessary, I'll help you.\"</p></div>\n<div><p>—\"Thank you,\" Horikita answered, then left on her own.</p></div>\n<div><p>\"There will certainly be moves made—but Ayanokouji-kun really has done it... Being in the same Group as him could be called misfortune, and that's the only way to accept it... No, Ibuki-san was always a student from an opposing class, one we had to defeat. If we continue following his strategy, our class simply reaps the benefits.\"</p></div>\n<div><p>—Ibuki couldn't be counted among the honor students. But in terms of physical ability, she was a troublesome opponent, and she also had good relationships with Ryuuen-kun, Ishizaki, and Albert. Expelling such a student would deal a heavy blow to the momentum of Class B, which was closely trailing them.</p></div>\n<div><p>—Moreover, no one from Class A would suffer harm. Letting things proceed as they were had no drawbacks.</p></div>\n<div><p>\"Don't let personal feelings interfere. Once more, look squarely at the dart Ayanokouji has thrown.\"</p></div>\n<div><p>—Whether the words heard over the wireless were entirely true.</p></div>\n<div><p>—What if \"making Ibuki the expulsion\" was a diversion, and he actually intended to expel someone else?</p></div>\n<div><p>—Process of elimination. Having someone from Ichinose's class expelled was unlikely—there was no benefit to aiming his arrow at her class. Of course, if he judged it necessary he would act, but now was not the time. That left someone from Ryuuen's class other than Ibuki.</p></div>\n<div><p>—How would Ayanokouji strike? For a moment, Horikita felt as if she could see how it would end.</p></div>\n<div><p>—The scene returned to just before the finish line. Everyone listened in silence, ears pricked.</p></div>\n<div><p>—Having finished recounting what I told Ichinose and Horikita, I turned to look at Ibuki.</p></div>\n<div><p>\"If you knew you were one hundred percent certain to be cut, you might take some negative action against the group. That is why the notification came at the very, very end—during the final confirmation before reaching the finish line.\"</p></div>\n<div><p>\"Hmph... I see.\"</p></div>\n<div><p>—So saying, Ibuki located Katsuragi, who was waiting in the rear with his arms folded.</p></div>\n<div><p>\"I didn't expect anything from you, Ayanokouji. But being abandoned by my own allies—that, I didn't see coming.\"</p></div>\n<div><p>\"Don't blame me. It was a necessary measure. Losing excellent talent through a mistaken choice is unacceptable.\"</p></div>\n<div><p>\"That's true. I'm well aware myself that I'm dead weight.\"</p></div>\n<div><p>—Coldly, yet as if accepting it, Ibuki let it out.</p></div>\n<div><p>\"But why reveal it now? You could've just said so after we reached the finish line.\"</p></div>\n<div><p>\"You're free to think that. Shall I tell you the reason?\"</p></div>\n<div><p>\"No... forget it. Hearing it won't change the fact that I'm getting expelled anyway.\"</p></div>\n<div><p>—Ibuki glanced at Sonoda and Morofuji.</p></div>\n<div><p>—Both of them, bewildered and unable to meet her gaze directly, averted their eyes. The atmosphere spoke. If they extended a hand here, the target would simply be rotated.</p></div>\n<div><p>—By making it common knowledge, anyone tempted to act in the opposite direction was blocked—that was the method.</p></div>\n<div><p>\"The only recourse you have now is to refuse to reach the finish line until the very end, preserving the hope that someone might transfer tokens to you. But don't get your hopes too high. Even if someone wanted to save Ibuki, the deviation that would result—causing another classmate to be expelled as a consequence—is something no one wants to bear. No one is willing to shoulder that responsibility.\"</p></div>\n<div><p>—The enormous advantage of the current situation was this: I, the instigator, had concentrated the responsibility.</p></div>\n<div><p>—Everyone was freed from an intense sense of guilt.</p></div>\n<div><p>\"Is that so... I get it.\"</p></div>\n<div><p>—Glaring at me, Ibuki planted her feet firmly and walked toward me.</p></div>\n<div><p>\"I accept the expulsion. So at the end, let me punch you once.\"</p></div>\n<div><p>—I had considered various scenarios, and in the end, what emerged from Ibuki was this demand, very much in her style.</p></div>\n<div><p>\"Violence carries a heavy penalty. If you really go through with it, there's no telling what might happen.\"</p></div>\n<div><p>\"Don't make me laugh. What's it matter to someone who's getting expelled?\"</p></div>\n<div><p>—She hadn't expected that answer. Ready to pounce at any moment, she grabbed my chest with her left hand.</p></div>\n<div><p>—The resolve of one who has accepted expulsion.</p></div>\n<div><p>\"I'm the one who decided to expel you. So I suppose I can at least grant you that much.\"</p></div>\n<div><p>—Ibuki, not expecting me to stand my ground, looked slightly surprised.</p></div>\n<div><p>\"You've got some nerve. Fine, then I won't hold back.\"</p></div>\n<div><p>—Turning away and slowly putting distance between us, Ibuki seemed genuinely intent on going through with it.</p></div>\n<div><p>—An unforeseen development. Was she really going to punch him? Suspicious gazes were cast from everyone toward Ibuki and me.</p></div>\n<div><p>—Though the respective stances had shifted subtly, no one noticed during this brief interval.</p></div>\n<div><p>\"Tch... Here I come.\"</p></div>\n<div><p>\"Wait. For real?\"</p></div>\n<div><p>\"You think I'm joking? Completely serious. You accepted it, so get ready.\"</p></div>\n<div><p>\"...Is that so. Then—\"</p></div>\n<div><p>—I paused briefly to buy time. Then, exhaling, I gave a clear nod.</p></div>\n<div><p>\"I won't fight back. Let Ibuki hit me—one-sidedly.\"</p></div>\n<div><p>—Ibuki, who had been holding a long-standing grudge, smiled.</p></div>\n<div><p>\"This is for all the resentment I've built up—die, Ayanokouji!\"</p></div>\n<div><img alt=\"Chapter Image\" width=\"600\" height=\"800\" src=\"/assets/y3v4_bw6.webp\"></div>\n<div><p>—Stomping the ground, she charged at me.</p></div>\n<div><p>—Her clenched right fist flew straight at my cheek without the slightest hesitation.</p></div>\n<div><img alt=\"Chapter Image\" width=\"600\" height=\"800\" src=\"/assets/y3v4_ch8.webp\"></div>\n<div><p>—A dull <i>thwack</i> sounded as the impact landed on my left cheek.</p></div>\n<div><p>\"Whoa, she really slugged him!\"</p></div>\n<div><p>—Inwardly shaken, Shinohara momentarily furrowed her brow and shut her eyes.</p></div>\n<div><p>—The surroundings were stunned into silence.</p></div>\n<div><p>\"Under normal circumstances, this act of violence would clearly be punishable. Fortunately, the monitor isn't here, and I have no intention of pursuing it. We'll treat it as if it never happened.\"</p></div>\n<div><p>—If Ibuki were expelled for violence, the point of having pushed her into this position would be lost. That was why Ike, Shinohara, and the others would not delve deeply into the matter.</p></div>\n<div><p>\"Satisfied?\"</p></div>\n<div><p>\"At least pretend it hurt.\"</p></div>\n<div><p>\"I'm toughing it out.\"</p></div>\n<div><p>\"...Hmph.\"</p></div>\n<div><p>—Having finally landed the punch she'd been fixated on, Ibuki stepped back, satisfied.</p></div>\n<div><p>\"Right, we should be getting to the finish line soon.\"</p></div>\n<div><p>—Katsuragi, about to leave his allies behind, was pinned in place by Ibuki's glare.</p></div>\n<div><p>\"In the end, you didn't give me a single token.\"</p></div>\n<div><p>\"That was the policy I decided upon. This is where you exit the stage.\"</p></div>\n<div><p>\"Tch.\"</p></div>\n<div><p>—No support was forthcoming from her allies. Abandoning her last hope, she prepared to walk toward the finish line.</p></div>\n<div><p>—Seeing Ibuki like this, it was not Kushida but Shinohara who moved first—before Kushida could act.</p></div>\n<div><p>—Shinohara absolutely could not allow Ibuki to reach the finish line like that.</p></div>\n<div><p>\"Come to think of it, doesn't this whole sequence look like a performance to you?\"</p></div>\n<div><p>—Shinohara looked coldly at Ibuki, Katsuragi, and me.</p></div>\n<div><p>\"Explaining the plan to Ibuki-san right before the finish line, letting her punch you—aren't you just putting on a play titled 'Ibuki-san Is Going to Be Expelled'?\"</p></div>\n<div><p>\"Wh-What exactly do you mean, Satsuki?\"</p></div>\n<div><p>\"Kanji, I didn't tell you this, but Horikita-san warned me privately: 'Never completely believe that Ayanokouji is going to expel Ibuki.' See, we've never actually confirmed Ibuki-san's token count. The fifty can't be verified either.\"</p></div>\n<div><p>—Shinohara walked in front of Ibuki, who was heading toward the finish line, blocking her path.</p></div>\n<div><p>\"If I were truly in danger, I'd be desperately begging for help. But normally, you wouldn't just give up and walk straight to the finish line. Which leaves only one answer: you actually have more tokens, don't you?\"</p></div>\n<div><p>—Ibuki's 50 tokens weren't particularly large.</p></div>\n<div><p>—She had failed in individual battles; in team and group battles, she had only received the bare minimum of transfers from Katsuragi.</p></div>\n<div><p>—On the surface, she looked like the bottom rank within the group.</p></div>\n<div><p>—But Shinohara suspected that the part she could see wasn't the whole picture.</p></div>\n<div><p>\"That guess is way off. I gave up completely after that punch just now.\"</p></div>\n<div><p>\"Maybe. But we have no way of knowing the truth. What Ayanokouji-kun said, what Katsuragi-kun said about abandoning Ibuki-san—it could all be a fabrication.\"</p></div>\n<div><p>—She shot a sharp, momentary glance at Katsuragi.</p></div>\n<div><p>—Tokens could be transferred up to the very last moment before reaching the finish line, so the possibility that Katsuragi had transferred tokens to Ibuki was not 0. A kind-hearted person from Ichinose's class, or Kushida—even Class D had opportunities. Perhaps Ayanokouji had given some instruction behind the scenes.</p></div>\n<div><p>\"I haven't received anything from anyone.\"</p></div>\n<div><p>\"Oh. But giving up this easily isn't quite right, is it?\"</p></div>\n<div><p>\"What?\"</p></div>\n<div><p>\"What if we were to say, 'We'll save Ibuki-san'? The situation might change.\"</p></div>\n<div><p>\"...Save? I don't get it.\"</p></div>\n<div><p>\"Now, show me your tokens. Let me confirm with my own eyes. If it's genuine, then we'll share tokens with you and have you surpass Kushida-san. That way, you'd escape being at the very bottom, wouldn't you?\"</p></div>\n<div><p>\"W-Wait, Shinohara-san—\"</p></div>\n<div><p>—The first to be shocked was Mii-chan.</p></div>\n<div><p>—The statement, which sounded as if she were about to abandon her ally, made her involuntarily gasp.</p></div>\n<div><p>—But Kushida calmly and quietly reassured her.</p></div>\n<div><p>\"It's all right. That's probably... not Shinohara-san's true intention. She's lying in order to confirm Ibuki-san's token count.\"</p></div>\n<div><p>\"B-But...\"</p></div>\n<div><p>—Ibuki, faced with this unexpected proposal, immediately arrived at an answer in her head.</p></div>\n<div><p>\"I'm not an idiot. You think I'd fall for a cheap trick like that? Even if I show you, it doesn't mean you'll actually give me tokens.\"</p></div>\n<div><p>\"But it leaves the possibility open. Right?\"</p></div>\n<div><p>—If she didn't show, she'd absolutely get nothing; if she showed, she might get something.</p></div>\n<div><p>—Shinohara's temptation, strict on one hand, sweet on the other.</p></div>\n<div><p>\"Where would I have gotten tokens from? There's no way.\"</p></div>\n<div><p>\"Up until now, right here, I haven't seen any sign of you receiving a transfer. But last night—who knows. You might have received some early this morning. And we haven't been watching Ibuki-san twenty-four hours a day. Transfers happen in the blink of an eye. If you show me, I'll give you five tokens upfront.\"</p></div>\n<div><p>—In order to draw out Ibuki's holdings, Shinohara initiated this kind of negotiation.</p></div>\n<div><p>\"In the end, it's just for your own sake. Giving me 5 tokens won't change the outcome for me.\"</p></div>\n<div><p>\"Setting aside what our objective is, isn't it better to get a little more? You shouldn't ignore a 1% possibility. Someone in another Group might only have 54 tokens.\"</p></div>\n<div><p>\"Sorry, but I'm not interested in acting for your safety.\"</p></div>\n<div><p>—Shinohara flung this at Ibuki, who was heading to the finish line.</p></div>\n<div><p>\"Strange. As I thought, you must have received tokens from somewhere. Katsuragi-kun? Or someone else? Even Ayanokouji-kun? It doesn't matter who—if that's the case, then I can't give Kushida-san many tokens after all. Because I'd be worried.\"</p></div>\n<div><p>—Shinohara's best insurance was to confirm Ibuki's token count.</p></div>\n<div><p>—But even if she couldn't confirm them, she had a powerful trump card. Over the past two and a half days, she had withheld the tokens meant for Kushida without transferring them.</p></div>\n<div><p>\"Do whatever you want. In any case, Kushida has more than me, right? But—\"</p></div>\n<div><p>—Ibuki glared at her and bent her arm.</p></div>\n<div><p>—She entered the passcode and displayed the total.</p></div>\n<div><p>\"What I can't stand is the idea of being saved by Ayanokouji.\"</p></div>\n<div><p>—She forcibly thrust the clear evidence that she \"hadn't received any transfers\" before Shinohara's eyes.</p></div>\n<div><p>—Irritated, Shinohara pushed her arm aside and scrutinized the display.</p></div>\n<div><p>\"It really is 50...\"</p></div>\n<div><p>—...So simple-minded... Even Shinohara couldn't hide her bewilderment at Ibuki's action.</p></div>\n<div><p>\"Can the watch be taken off and swapped or something? Like, is it at all possible to make it display an old token count...?\"</p></div>\n<div><p>—She was pondering impossible methods.</p></div>\n<div><p>—In reality, the wristwatch could not be removed. Even if it were removed, that would naturally be a rules violation. Nor was there any function to falsify the display.</p></div>\n<div><p>—If Ibuki entered the finish zone like this, her tokens would be locked in.</p></div>\n<div><p>\"Thank you, Ibuki-san. Then I'll honor the promise. I'll transfer 5 tokens.\"</p></div>\n<div><p>\"I don't want them.\"</p></div>\n<div><p>—Ibuki turned her back and walked away.</p></div>\n<div><p>—Shinohara circled around in front of Ibuki and showed her her own wristwatch.</p></div>\n<div><p>—She switched Ibuki's unresisting wristwatch to reception mode.</p></div>\n<div><p>—Seizing it by force would be a violation, but unilaterally transferring to the other party was not.</p></div>\n<div><p>\"I keep my promises.\"</p></div>\n<div><p>—Just as she said this and tried to forcibly bring the wristwatches into contact, Kushida suddenly cut in.</p></div>\n<div><p>\"Wait, Shinohara-san. Shouldn't you return the tokens that are rightfully mine first—or at least some of them? You were supposed to give them to me before the finish line. That was the promise, wasn't it?\"</p></div>\n<div><p>\"Kushida-san's holdings are more than Ibuki-san's, so there's no need—\"</p></div>\n<div><p>—As Shinohara spoke, Kushida, her anger undisguised, slightly raised her voice.</p></div>\n<div><p>\"Return all of them to me. If you're going to give five tokens to Ibuki-san, then transfer them from your own share. Are you telling me to tear up the promise? Mii-chan too—I want the full thirty-four tokens back.\"</p></div>\n<div><p>—The implication of tearing up the promise—Kushida asserted this fiercely.</p></div>\n<div><p>—But this was an indisputably legitimate demand. For Shinohara to stubbornly refuse here would be irrational.</p></div>\n<div><p>\"I'll transfer them from my own share. But first, I'll transfer 5 tokens to Ibuki-san. That's fine, right? We're about to reach the finish line anyway.\"</p></div>\n<div><p>\"...No. I won't allow it. Because—the tokens I currently hold are fifty-four. I showed you during the final confirmation just now. Shinohara-san is well aware of that, isn't she?\"</p></div>\n<div><p>—Kushida, without concealing her anger, clearly refused Shinohara.</p></div>\n<div><p>—Shinohara averted her gaze with irritation.</p></div>\n<div><p>—The most surprised person in this exchange was Ibuki, who stood closest.</p></div>\n<div><p>\"You have fifty-four?\"</p></div>\n<div><p>\"Yes. I'm sure you understand the situation now.\"</p></div>\n<div><p>\"Shinohara... you weren't trying to save me by getting Kushida expelled, were you?\"</p></div>\n<div><p>—If Shinohara transferred 5 tokens to Ibuki, the bottom rank would switch to Kushida.</p></div>\n<div><p>—Was it simple coincidence, or was it calculated—</p></div>\n<div><p>\"Of course not, I wouldn't have such a nasty scheme—\"</p></div>\n<div><p>\"Really? Then transfer the tokens to me immediately.\"</p></div>\n<div><p>\"...Fine, Kushida-san. I didn't expect you to be so distrustful. Show me your wristwatch.\"</p></div>\n<div><p>—In front of everyone, Shinohara could no longer be forceful, and began operating her wristwatch. Before long, a transfer chime sounded from both their wristwatches.</p></div>\n<div><p>\"I'm leaving, then. I don't need those 5 tokens you promised to transfer. I just got enough from Kushida.\"</p></div>\n<div><p>—After this transaction was completed, Ibuki once again headed toward the finish line.</p></div>\n<div><p>—Katsuragi tried to step forward but was stopped by a signal from my eyes.</p></div>\n<div><p>—Kushida pushed Shinohara aside, grabbed Ibuki's arm, and pulled her back.</p></div>\n<div><p>—Shinohara, who had nearly stumbled, glared at Kushida.</p></div>\n<div><p>\"Wait, Ibuki-san. Let me see your current token count too.\"</p></div>\n<div><p>\"Huh? Didn't I just show Shinohara a moment ago? Has anyone come near us since then?\"</p></div>\n<div><p>—No one had come near Ibuki.</p></div>\n<div><p>—It was 100% impossible for a transfer to have occurred.</p></div>\n<div><p>\"Show me, quickly.\"</p></div>\n<div><p>\"...Fine.\"</p></div>\n<div><p>—Kushida applied an unidentifiable pressure, making Ibuki enter the passcode again.</p></div>\n<div><p>—It proved the token count was 50.</p></div>\n<div><p>\"Thank you. I can't rest easy unless I confirm it with my own eyes. Because—\"</p></div>\n<div><p>—After a beat of silence, Kushida turned toward Shinohara and, beaming, said:</p></div>\n<div><p>\"A person like Shinohara-san—someone so ugly—can't be trusted even a millimeter, can she?\"</p></div>\n<div><p>—Kushida let it out.</p></div>\n<div><p>—For an instant, as if she had misheard, Shinohara's mouth fell open in stunned disbelief.</p></div>\n<div><p>—Even Ibuki was now stunned.</p></div>\n<div><p>\"W-Wait! What did you just say!? Hey!\"</p></div>\n<div><p>\"Ugly, I said you're ugly. Your face, your personality, and your figure. All of it.\"</p></div>\n<div><p>\"Didn't you hear me?\"</p></div>\n<div><p>—Ignoring the shrieking Shinohara, Kushida gripped Ibuki's arm and walked toward the finish line.</p></div>\n<div><p>\"Sorry, Ibuki-san, but I'm going to the finish line with you.\"</p></div>\n<div><p>\"W-Wait, Kushida—\"</p></div>\n<div><p>—Katsuragi, unable to restrain himself, spoke up, but Kushida immediately smiled.</p></div>\n<div><p>\"I can't wait. Katsuragi-kun, it's written all over your face that you want to save Ibuki-san. If I'm casually sympathized with again, I'll be put back in danger.\"</p></div>\n<div><p>—Seeing Katsuragi in a position where he had no choice but to act, she answered with a laugh.</p></div>\n<div><p>—Kushida and Ibuki arrived at the spot before the finish line where Yoshida and the others were waiting.</p></div>\n<div><p>\"I'll reach the finish line first, Yoshida-kun.\"</p></div>\n<div><p>\"Eh, ah, uh...\"</p></div>\n<div><p>—Still unable to digest Kushida's words and the situation, Yoshida could not respond.</p></div>\n<div><p>\"You... can you do that?\"</p></div>\n<div><p>\"Of course. I've decided it's all so stupid. It actually feels pretty refreshing.\"</p></div>\n<div><p>—Saying this, Kushida deliberately operated her wristwatch.</p></div>\n<div><p>\"Before entering the finish line zone—Ibuki-san, I'll give you one last present. Accept it.\"</p></div>\n<div><p>\"What? What kind of present.\"</p></div>\n<div><p>\"In the end, that miser Shinohara-san—when I told her to give me the thirty-four tokens, she only transferred ten. Right up to the very end, she was harassing me. Pretty disgusting, right?\"</p></div>\n<div><p>\"Guh...!\"</p></div>\n<div><p>—As expected, Shinohara had harassed her to the very end and covered herself.</p></div>\n<div><p>—She had likely intended to keep an amount that, even after splitting evenly with Ike, would still just barely allow her to surpass Kushida.</p></div>\n<div><p>\"Even if I give you half, I won't be expelled. Take them.\"</p></div>\n<div><p>\"No, even if you give me half, the outcome of my expulsion won't change.\"</p></div>\n<div><p>\"That's only natural. Ibuki-san will remain below me to the very end. But Ayanokouji-kun and the others' plan was for everyone to hold fifty-one tokens. What if there's a miscalculation somewhere? Besides, tokens as disgusting as Shinohara-san's—I don't want to keep even one more than I have to.\"</p></div>\n<div><p>\"...That really is your style, Kushida.\"</p></div>\n<div><p>—Deeming it pointless, but accepting anyway, Ibuki brought their wristwatches together.</p></div>\n<div><p>\"W-Wait! Everything I've just heard—!\"</p></div>\n<div><p>—Enraged at being called ugly repeatedly, Shinohara closed in on Kushida and grabbed her arm to stop her.</p></div>\n<div><p>\"Everyone heard that, didn't they! Kushida-san is a cruel-hearted woman! Th-That's exactly why I worked so hard for Class A—managing the tokens—!\"</p></div>\n<div><p>\"I don't deny it. I do have a nasty personality. But regarding this terrible woman—your boyfriend is completely smitten at her, you know. When I told him, 'Save me and I'll do anything,' he practically drooled. He really needs to be disciplined.\"</p></div>\n<div><p>—Before long, the finish line confirmation signals chimed from the wristwatches of Ibuki, Kushida, and Shinohara in turn.</p></div>\n<div><p>—But Shinohara, paying no heed to this, shouted furiously.</p></div>\n<div><p>\"Kanji?!\"</p></div>\n<div><p>\"Huh? Uh, n-no, I don't know! She's making it up, right!?\"</p></div>\n<div><p>—His gaze wandered; he couldn't get the words out.</p></div>\n<div><p>—His clumsy motion of wiping the sweat from his forehead showed he was completely out of control.</p></div>\n<div><p>—While denying it desperately, his voice trembled slightly, his panic utterly unconcealed.</p></div>\n<div><p>—As Shinohara, still making excuses, chased after Ike's retreating figure and moved further away, Kouenji appeared dashingly from the underbrush behind Katsuragi.</p></div>\n<div><p>\"It seems the troublesome business has concluded.\"</p></div>\n<div><p>—An unexpected interloper right in front of Katsuragi, who had been about to close in on me.</p></div>\n<div><p>\"You appear in strange places. You weren't watching the entire time, were you?\"</p></div>\n<div><p>—Katsuragi turned and asked. Sweeping his hair aside, Kouenji smiled mischievously.</p></div>\n<div><p>\"I thought it would be rude to interrupt, so I waited.\"</p></div>\n<div><p>\"You came alone? The other members of your Group still need time to arrive, don't they?\"</p></div>\n<div><p>\"It's better for me to move alone. It will be a while yet before my Group arrives.\"</p></div>\n<div><p>—Answering lightly, he passed by Katsuragi and walked up to Mii-chan.</p></div>\n<div><p>\"Sorry to bother you, but could you listen to me for a moment?\"</p></div>\n<div><p>—He extended his hand as if inviting her for a stroll.</p></div>\n<div><p>\"Uh, wh-what?\"</p></div>\n<div><p>\"This isn't the place. Let's walk a little.\"</p></div>\n<div><p>—He led Mii-chan, who was about to reach the finish line, away to a spot with no one around.</p></div>\n<div><p>\"What's he doing?\"</p></div>\n<div><p>—Sonoda tilted his head, puzzled.</p></div>\n<div><p>—Kouenji brought Mii-chan to a location out of earshot of others and pushed her up against a large tree.</p></div>\n<div><img alt=\"Chapter Image\" width=\"600\" height=\"800\" src=\"/assets/y3v4_bw7.webp\"></div>\n<div><p>\"Let me see your wristwatch.\"</p></div>\n<div><p>—He said this after flicking a glance in my direction.</p></div>\n<div><p>\"Eh, what do you mean?\"</p></div>\n<div><p>\"Your token holdings. I'd like to know the specific amount. If you have a reason you can't show me, so be it.\"</p></div>\n<div><p>\"No, well, I can... but—\"</p></div>\n<div><p>—Not understanding Kouenji's intent, Mii-chan bewilderedly operated her wristwatch.</p></div>\n<div><p>—She entered the passcode and displayed her token count.</p></div>\n<div><p>\"Mm. It seems you've stably accumulated a fair number. But you should still be careful, just to be safe. Considering the multiplier, this number is still in the danger zone.\"</p></div>\n<div><p>—So saying, Kouenji operated his own wristwatch and made a transfer action.</p></div>\n<div><p>—Both of their wristwatches chimed.</p></div>\n<div><p>\"Eh, eh!? Th-This many, eh!?\"</p></div>\n<div><p>\"There's no need to worry. This is but the insurance I'm providing. Please don't transfer them to anyone else.\"</p></div>\n<div><p>—He pulled her into the finish line zone.</p></div>\n<div><p>—Flashing a white-toothed grin at the bewildered Wang-san, he reached the finish line together with her.</p></div>\n<div><p>\"What was that just now?\"</p></div>\n<div><p>—Yoshida had absolutely no idea what was going on. But explaining to Katsuragi and dealing with the next steps—those two things took priority for now.</p></div>",
    "11": "<div><p>The long battle of six nights and seven days, from the Survival Game Special Exam through the Token Collection Special Exam—had come to an end.</p></div>\n<div><p>Past 8 p.m., all third-year students were informed of the special exam results and returned to the ship, gathering immediately in the cafeteria. But the expelled students were not among those invited.</p></div>\n<div><p>They had either been isolated or sent back by a smaller boat. None of the students would know where they were now.</p></div>\n<div><p>A slightly delayed dinner hour approached. Dishes of a luxury the uninhabited island could never offer were spread across the tables in abundance, and the students eagerly awaited them—but for the class that had lost one of its own, even this feast seemed hazy, drained of any brightness.</p></div>\n<div><p>\"Sorry about that, Yoshida. You ended up shouldering a lot at the end.\" I had given him several important roles in this special exam, so I owed him thanks first.</p></div>\n<div><p>\"Nah, it's nothing…\" Yoshida tilted his head back and let out a huge sigh. \"That remark of yours hit way too close to home—I couldn't argue with it.\"</p></div>\n<div><p>\"Even hearing it put like that, I couldn't deny it. Well, it was definitely rough.\" He threw an arm around my shoulder with a wry smile and gave me a pat—it seemed we had completely made up.</p></div>\n<div><p>Across the table, Hashimoto narrowed his eyes, studying my face. \"You two seem to be getting along well, Ayanokouji. I'd like to hear a few things about you too.\"</p></div>\n<div><p>\"What do you want to hear?\"</p></div>\n<div><p>\"That matter with Shiina—is it really okay to leave as it is?\" There was weight behind his words.</p></div>\n<div><p>Yoshida's expression was slightly complicated. \"This isn't really the place for that.\"</p></div>\n<div><p>\"I made the correct judgment,\" I answered, then added: \"Hashimoto, do you think a different outcome would have been better?\"</p></div>\n<div><p>\"No… I was just asking. As long as you can accept it.\" He broke off there, folding his hands behind his head as his gaze drifted toward Class A. \"But whether Class A won or lost—I really can't tell,\" he added, his expression turning serious.</p></div>\n<div><p>Prompted by Hashimoto's words, Yoshida looked toward Class A as well. \"A win is a win, right? They picked up Class Points.\"</p></div>\n<div><p>Group 8—Horikita and Ichinose-san's group—had reached the finish line in first place. Their 100% multiplier was fully active, and with the group ranking 1st, both Class A and Class D received 100 Class Points. On top of that, Horikita's class had claimed the individual Special Reward, bringing their total to 200 Class Points. Class A's position, which had nearly been shaken, was now stabilized. In the published individual token rankings, Ryuuen-kun had placed 2nd.</p></div>\n<div><p>The gap between him and 1st place was only about 2 tokens. Had the positions been slightly different, the Special Reward would have gone to Class B—a bitter outcome. The sole consolation was that their group had placed 2nd, earning 50 Class Points.</p></div>\n<div><p>\"But Shinohara's expulsion can't be overlooked. Ike's mental state is pretty dangerous too. Shinohara got expelled, huh… Just what did you do, Ayanokouji?\"</p></div>\n<div><p>Hashimoto asked with a smug smile. I scanned the room. Ike was nowhere to be seen—probably lying down in the infirmary.</p></div>\n<div><p>The buffet-style dinner soon began, and the third-years were free to move about. Most clustered by class, but those with friendships across class lines found seats together and chatted easily.</p></div>\n<div><p>\"…Ayanokouji-kun, can you spare a little time?\" The one who had approached empty-handed was Horikita—I hadn't spoken with her directly at all on the uninhabited island.</p></div>\n<div><p>She probably wanted to sort through the events of the special exam before we started eating. The deck would do—we could talk there.</p></div>\n<div><p>\"Let's sort out this whole chain of events, including the matter with Shinohara.\"</p></div>\n<div><p>—I began to explain to Horikita, who stood beside me.</p></div>\n<div><p>—All the groundwork had been laid starting from the night of Day 3, even before I contacted Ichinose-san.</p></div>\n<div><p>—Specifically, it began with a conversation lasting less than five minutes with Katsuragi on the morning of Day 2.</p></div>\n<div><p>\"Sorry for bothering you so early.\"</p></div>\n<div><p>—I tossed an idea at the back of Katsuragi, who was about to leave.</p></div>\n<div><p>\"Since this seems like a good opportunity to bring it up—I intend to have Ibuki expelled in this special exam.\"</p></div>\n<div><p>—Katsuragi hadn't intended to turn around, but those words, once spoken, made it impossible for him to ignore them. He turned back.</p></div>\n<div><p>\"…I see. So that's a declaration of war?\"</p></div>\n<div><p>\"Considering this school's mechanisms, the expulsion of students who lack ability is a natural principle. Intentional selection and elimination isn't necessarily evil. But I cannot accept it. When Sakayanagi clashed with the class over the leader issue, Yahiko, who had sided with me, was arbitrarily selected and eliminated. Of course, that was because I lacked strength. But precisely because of that, I can understand the feelings of those who are cut down. I won't go so far as to say 'protect everyone,' but I also won't act on the premise of getting a classmate expelled from the very start. If I go any further, I'll be the one driven out of the class first.\"</p></div>\n<div><p>—Katsuragi's words carried heavy, solid weight.</p></div>\n<div><p>\"In order to protect your allies, you'll fight mercilessly—is that how I should understand it?\"</p></div>\n<div><p>\"That's exactly what I think.\"</p></div>\n<div><p>\"In that case, you and I can cooperate.\"</p></div>\n<div><p>\"…What?\"</p></div>\n<div><p>\"The Representative can hold a great many tokens in custody. In other words, the Representative wields significant discretionary power. Using that power, I want you to thoroughly give Ibuki the cold shoulder. Naturally, the tokens Ibuki will be able to receive will drop sharply.\"</p></div>\n<div><p>\"I can't understand what you're saying. Making Ibuki get expelled—\"</p></div>\n<div><p>\"Think about it objectively. What would happen if you did as I said. Ibuki will clearly be left behind in the token tally. The students in Group 3 will start thinking: 'As long as my tokens are higher than that student's, I'm safe.' Then, by anonymously sharing Ibuki's token count and adjusting as needed, anyone can escape being a candidate for expulsion.\"</p></div>\n<div><p>\"A foolish proposal. Would I do something so extremely disadvantageous to Class B?\"</p></div>\n<div><p>\"I'm proposing it precisely because it isn't disadvantageous.\"</p></div>\n<div><p>—When I answered that, Katsuragi perceived the truth behind my proposal.</p></div>\n<div><p>\"…Could it be… a decoy?\"</p></div>\n<div><p>\"Correct. Use Ibuki only as an indicator for 'being able to avoid expulsion.' The target to aim for is a Class A student.\"</p></div>\n<div><p>\"Are you serious?\"</p></div>\n<div><p>\"The ultimate goal of the students at this school is to graduate from Class A. If that's the highest priority, then reducing the fighting strength of Class A—who are currently leading—takes precedence. If Kushida or Wang were expelled, the class's combat power would drop enormously. If Ike or Shinohara were expelled, it wouldn't just be a couple breaking up—depending on the circumstances, the lover might follow and voluntarily drop out afterward, eliminating two in one go. For the three classes chasing them, they are ideal expulsion candidates.\"</p></div>\n<div><p>\"But can it really be done that simply? If I give Ibuki the cold shoulder, ordinary people won't easily believe a story like 'the class cut one of its own.' They'll suspect it's just temporary harshness before tokens are transferred later. They'll definitely confirm the number accurately before the finish line.\"</p></div>\n<div><p>\"It doesn't matter if she notices. Having her suspicious is actually better.\"</p></div>\n<div><p>—I envisioned the following developments and told Katsuragi about various schemes, including how the transfer sound could be eliminated.</p></div>\n<div><p>—The ship departed from the uninhabited island, sailing across the dark sea. The groundwork was laid upon the entire group: 'Ayanokouji is going to use Ibuki as a target' Katsuragi's cold treatment of Ibuki created a token gap. The genuine anger and impatience of Ibuki, who knew nothing—Shinohara and Ike watched all this up close, and they thought: As long as we have more than that person, we absolutely won't be expelled ourselves.</p></div>\n<div><p>—The crucial thing was a reliable indicator for definitely avoiding expulsion. The number held by the decoy Ibuki didn't matter; the real goal was informing the whole group of the token counts held by Shinohara and Ike.</p></div>\n<div><p>\"I had the feeling Ibuki-san had earned more than expected. There were also students whose actual token holdings didn't match the numbers I reported…\"</p></div>\n<div><p>—Shinohara and Ike's individual earnings were low-tier, but they had a stash pooled from what they'd siphoned off Kushida. Even if the two split it fifty-fifty, it still added up.</p></div>\n<div><p>\"Making the adjustments must have been tough.\"</p></div>\n<div><p>—While consoling her, I told Horikita about what happened in the endgame.</p></div>\n<div><p>On the final day, as the end drew near, Shinohara and the others began to think:</p></div>\n<div><p>Ayanokouji might have already done something.</p></div>\n<div><p>Until they could head to the finish line, they kept their eyes on Katsuragi and the others, preventing contact. But their suspicions would not go away.</p></div>\n<div><p>Was Ibuki's token count truly below theirs? They wanted to confirm her holdings. The wristwatch display couldn't be forged, and it was 100% certain that tokens couldn't be transferred before the critical point. So on Ibuki's side, if something happened, she would be the one expelled—they wanted to make contact too. The timing for Katsuragi to save Ibuki was also extremely tight.</p></div>\n<div><p>—The approaching finish line. I simulated it too. Shinohara's and the others' actions would also be affected.</p></div>\n<div><p>—The linchpin of that scenario was to have Yoshida stand before the finish line and give Ibuki trouble, preventing her from reaching it and wasting time. As a backup, I had also considered using Kushida. Unexpectedly, the incident where Ibuki tried to punch me occurred, so I had Sanada—whom I'd coordinated with beforehand—approach Kushida and quickly explain the situation, then add the portion Katsuragi had transferred for Ibuki, passing along the tokens needed to save her.</p></div>\n<div><p>\"You made that suggestion to Shinohara and the others with the resolve to bear my counterattack—so that's what you meant.\"</p></div>\n<div><p>\"Yeah… Ibuki-san being driven into a corner was Ayanokouji-kun proceeding according to plan. And then, depending on the circumstances, the spearhead might turn toward Shinohara-san and the others—\"</p></div>\n<div><p>\"You were right to contact Shinohara. You saw through the possibility that making Ibuki get expelled was a feint.\"</p></div>\n<div><p>\"It didn't feel right. Even if Katsuragi-kun said 'make Ibuki get expelled,' he wouldn't accept it unconditionally. And he wouldn't ignore Ryuuen-kun and proceed on his own authority. In that case, what they must have been told was 'make a student from another class get expelled.' Thinking that way, the target was our class. So I thoroughly emphasized to Shinohara and the others that they should pay attention to Ibuki's token count, to confirm it if possible—\"</p></div>\n<div><p>\"In practice, Shinohara, although forceful, accomplished that. The confirmation itself was done.\"</p></div>\n<div><p>\"But… as a result, I couldn't protect her. I didn't want anyone to be expelled, but… it didn't work out.\"</p></div>\n<div><p>\"It can't be helped. Ichinose-san was in the same group. A cooperative system was easy to establish, and with the group aligned on the goal of high ranking, unity came easily—those were advantages; the Leader's group winning the grand prize was also a multiplier effect. But this special exam required both reaching the finish line early to win and reaching it late to preserve lives—it had a duality in it's nature. It's not easy to achieve both.\"</p></div>\n<div><p>—The finish line was recognized when a majority arrived. Horikita could have held onto the phone and not reached the finish line. But there was a limit to what one person could handle. And besides, she didn't want to reduce her token count.</p></div>\n<div><p>\"If I had personally guided Shinohara and the others toward the finish line, the situation might have changed.\"</p></div>\n<div><p>\"Perhaps. But swapping out the expelled student isn't simple in terms of results. To save someone, another person, unseen, has to be pushed down. In that situation, protecting both Class A and Class D 100% was practically impossible.\"</p></div>\n<div><p>\"…Yes. There will definitely be a sacrifice… We won't know who from which class…\"</p></div>\n<div><p>—One fatal element was that Shiina from Class B had been drawn into the stage I had set. Physical distance became a major obstacle.</p></div>\n<div><p>\"Couldn't you have targeted Kushida-san or Wang-san? For our class, losing them would be a far greater loss in fighting strength. Why didn't you do that?\"</p></div>\n<div><p>\"The ones that topple easily topple first.\"</p></div>\n<div><p>—That was my answer. But that wasn't true. Kushida as an expulsion candidate was only a surface pretense; I had never intended to eliminate her from the start. She was far stronger than Shinohara or Ike. Mii-chan was also sufficient fighting strength. Moreover, she had other uses now.</p></div>\n<div><p>—What mattered to me was cultivating Class A as well. Side shoots that stretch out spread widely but bear small fruit. So for Class A, it was necessary to select which branches to cultivate.</p></div>\n<div><p>\"Blame me, don't blame yourself.\"</p></div>\n<div><p>—After saying that, I sensed a presence approaching from behind.</p></div>\n<div><p>\"Those words aren't quite right, are they? The one who decided who would be expelled wasn't Ayanokouji-kun.\"</p></div>\n<div><p>—Having seen us go out onto the deck, Kushida emerged from the shadows.</p></div>\n<div><p>—I had noticed her eavesdropping, so I wasn't surprised.</p></div>\n<div><p>\"With the tokens Sanada gave me, I could have reached the finish line on my own. In that case, the one expelled would have been Ibuki-san.\"</p></div>\n<div><p>—Having decided there was no need to put on an act anymore, Kushida also wanted to speak.</p></div>\n<div><p>\"It was you, wasn't it? The one who decided to have Shinohara-san expelled?\"</p></div>\n<div><p>—When Horikita asked that, Kushida ignored her and said what was on her own mind.</p></div>\n<div><p>\"Making me give tokens to Ibuki-san was like walking a tightrope, wasn't it? When I was heading toward the finish line, Katsuragi-kun was pretty flustered.\"</p></div>\n<div><p>\"Perhaps.\"</p></div>\n<div><p>—I answered like that, but it wasn't really the case.</p></div>\n<div><p>—Handing over the decisive core tokens—I had also judged that to be without issue.</p></div>\n<div><p>Kushida Kikyou bore the judgment of life and death.</p></div>\n<div><p>—All I had to do was make her desire Shinohara's or Ike's disappearance more strongly than Ibuki's disappearance.</p></div>\n<div><p>—A seed planted from the very moment the special exam began.</p></div>\n<div><p>—I had deliberately ignored the friction that arose between those two.</p></div>\n<div><p>—Their greetings ignored, their abilities questioned—Shinohara and the others accumulated rage.</p></div>\n<div><p>—At the same time, I valued Kushida and treated her as excellent. Such conduct made my classmates in the temporarily ranked Class D uncomfortable. \"Does he still have lingering attachment to Horikita's class? Or does he trust Horikita's class's students more?\" — that kind of thinking.</p></div>\n<div><p>—That unpleasant environment. The spear of anger naturally pointed toward the hated Kushida.</p></div>\n<div><p>Shinohara's intense enmity.</p></div>\n<div><p>—Wanting to make Kushida suffer by any means necessary.</p></div>\n<div><p>—Those emotions were guided out.</p></div>\n<div><p>Disrupting Class A's order, isolating Kushida within the group—this also became easy.</p></div>\n<div><p>—Everything went according to plan.</p></div>\n<div><p>—The environment I had created.</p></div>\n<div><p>\"Did you see Ike-kun's face when the results were announced? Wasn't it the best?\"</p></div>\n<div><p>—When the results had been announced just before, the two of them looked like they had been struck by lightning.</p></div>\n<div><p>—Even I couldn't completely determine which one would be expelled.</p></div>\n<div><p>\"I had originally hoped that Shinohara-san would remain, but it couldn't be helped.\"</p></div>\n<div><p>—Shinohara had no intention of giving Kushida the tokens she had promised her; she had long since split them up and transferred them to Ike. But that was the fatal wound. In the end, forced to give Kushida 10 tokens, Shinohara ended up below Ike.</p></div>\n<div><p>Shinohara Satsuki, at the very bottom, was pronounced expelled and fell into a panic.</p></div>\n<div><p>Ike, meanwhile, became deranged. His outburst was suppressed by Sudou and the others with great effort.</p></div>\n<div><img alt=\"Chapter Image\" width=\"600\" height=\"800\" src=\"/assets/y3v4_ch10.webp\"></div>\n<div><p>—Recalling that scene, Kushida smiled with pleasure.</p></div>\n<div><p>\"I don't think I did anything wrong. I was a hair's breadth away from being driven to expulsion by Shinohara-san. I was just striking back.\"</p></div>\n<div><p>—That was what she wanted to say. Satisfied, Kushida turned to walk away.</p></div>\n<div><p>\"And don't misunderstand—the reason I spared Ibuki-san is because I decided she doesn't pose a threat. No other reason.\"</p></div>\n<div><p>—Without waiting for a reply, she left.</p></div>\n<div><p>—Horikita's inner distrust may have deepened, but my impression was the opposite.</p></div>\n<div><p>—In this upheaval, Kushida had without a doubt shed a layer of skin. No, you could say she had undergone a great transformation.</p></div>\n<div><p>—By revealing her true nature in front of the other classes, Horikita would also discover it.</p></div>\n<div><p>\"There's still a lot I want to ask. I'm also curious about your exam results…\"</p></div>\n<div><p>\"Another time. If needed, we can set a time.\"</p></div>\n<div><p>\"Yeah… I'll head back to the venue. There are still several problems I can't leave unattended.\"</p></div>\n<div><p>—The class had won, but the fact that a classmate had been sacrificed would not disappear.</p></div>\n<div><p>—Beyond looking after Ike, other matters from here on would also need to be discussed.</p></div>\n<div><p>—If I went back together with her, I might get dragged into such troublesome matters. I'd return a little later.</p></div>\n<div><p>Left alone, I stopped on the deck.</p></div>\n<div><p>—In this special exam of tangled rhythms, what surfaced thickly in my mind was not the matter of Shinohara and the others.</p></div>\n<div><p>—It was only one person: Shiina Hiyori.</p></div>\n<div><p>Now, I was thinking only about her.</p></div>\n<div><p>—After confirming that Ibuki and Shinohara and the others had reached the finish line, I glanced at my wristwatch.</p></div>\n<div><p>—Extrapolating backwards from the already calculated time, there was hardly any leeway left.</p></div>\n<div><p>\"Yoshida. I'll leave the rest to you.\"</p></div>\n<div><p>\"What do you mean, leave the rest?\"</p></div>\n<div><p>—I briefly told him about Ryuuen-kun's message and that Shiina Hiyori was waiting for me.</p></div>\n<div><p>\"What the—!! If you do that, the tokens—\"</p></div>\n<div><p>\"I know. At the very least, the possibility of the Special Reward is completely gone.\"</p></div>\n<div><p>—The probability of reaching the finish line in 1st place from here was high. Abandoning that was equivalent to throwing 100 Class Points into the gutter.</p></div>\n<div><p>\"But I'm still going to go pick her up.\"</p></div>\n<div><p>\"If you can save her, of course you should, but Shiina is a Class B student, right? No matter how you think about it, you should leave her—\"</p></div>\n<div><p>\"She's special.\"</p></div>\n<div><p>\"Spe…\"</p></div>\n<div><p>\"Shiina Hiyori—is a special existence to me.\"</p></div>\n<div><p>\"Special—you…\"</p></div>\n<div><p>\"If Shiraishi were waiting in the same situation, could you abandon her?\"</p></div>\n<div><p>\"That… I couldn't…\"</p></div>\n<div><p>—With that one sentence, he clutched his head, no further explanation needed.</p></div>\n<div><p>\"Tch… When you put it like that, I can't stop you…\"</p></div>\n<div><p>\"That's exactly why I told you—because I knew you couldn't stop me.\"</p></div>\n<div><p>\"Jeez… Fine. But will you make it? The distance isn't short.\"</p></div>\n<div><p>\"It's no problem.\"</p></div>\n<div><p>\"Ah, but with Shiina's tokens divided and the 70% multiplier, is it really okay? She was only given 1 token, right?\"</p></div>\n<div><p>\"Whether it's 1 or more, even 2 would be difficult. If she was given 1 and both of us can't avoid expulsion, scraping together 20 million (2000) Private Points on this side would also be hard. All I can do is transfer as needed.\"</p></div>\n<div><p>\"Worst case, you'd be at the very bottom…?\"</p></div>\n<div><p>\"That might happen.\"</p></div>\n<div><p>\"One minute—no, 30 seconds, wait for me.\"</p></div>\n<div><p>—Yoshida immediately called Sanada and Morishita and brought them over.</p></div>\n<div><p>\"We have the portion exceeding the threshold tokens here. Take from us.\"</p></div>\n<div><p>\"Asking people to hand over tokens without giving a reason—what kind of person are you, Ayanokouji Kiyotaka?\"</p></div>\n<div><p>\"Anyway, I need them, Morishita. I'll explain later.\"</p></div>\n<div><p>—Sanada had already accepted. Watching Yoshida's words and actions, Morishita muttered, \"Can't be helped.\"</p></div>\n<div><p>\"I've done you a huge favor, you know. Pay it back ten million times over.\"</p></div>\n<div><p>—Morishita also extended her wristwatch, uttering a bizarre unit of measurement that even a child couldn't have come up with.</p></div>\n<div><p>Just before 7 p.m., as the special exam approached its end and the ship was about to sound its great horn—in that moment, a single girl was at that place.</p></div>\n<div><p>The sun, slanting westward, slowly sank toward the horizon; the sky shifted from blue to deep crimson. The sea's surface reflected like a mirror, the light endlessly deforming with the fine ripples of the waves. The tide-scented wind blew intermittently, brushing across the surface of the not-yet-dry sand.</p></div>\n<div><p>\"Hiyori.\"</p></div>\n<div><p>—Careful not to startle her, I quietly called her name.</p></div>\n<div><p>—My footsteps hadn't reached her; her awareness of my presence came a beat late.</p></div>\n<div><p>—Her shoulders reacted slightly, but she did not turn around immediately.</p></div>\n<div><p>\"You actually came… I didn't think you would.\"</p></div>\n<div><p>—A moment later, a voice controlled and steady in volume.</p></div>\n<div><p>—The sound of waves striking came rhythmically, back and forth.</p></div>\n<div><p>—A quiet sea. Listening carefully, the footsteps on the sand behind me—someone following me—stopped a little distance away.</p></div>\n<div><p>—I walked slowly forward and came beside her. About an arm's length away—an ambiguous distance, neither touching nor far.</p></div>\n<div><p>\"If you accepted Ryuuen-kun's strategy because you foresaw that I would come—wouldn't that be strange?\"</p></div>\n<div><p>\"It isn't. It couldn't even be called a strategy to begin with. In this special exam, Class B couldn't find a surefire way to win—that was a dead end with no hope.\"</p></div>\n<div><p>—Hiyori's gaze did not drop; as if tracing the horizon line, she kept watching it.</p></div>\n<div><p>—Her fingertips gently pinched the hem of her tracksuit.</p></div>\n<div><p>\"If you're enrolled in Class B, part of the responsibility lies with you, but that's something shared by the entire class. Or rather, as the Leader, Ryuuen-kun's responsibility is greater. There's no need for you to shoulder it alone, is there?\"</p></div>\n<div><p>—For the first time, I looked at her profile. The sinking light softly outlined her contours, the shadow of her eyelashes falling delicately on her cheek.</p></div>\n<div><p>—Through the gaps in her hair lifted by the wind, I intermittently caught her expression.</p></div>\n<div><p>—Facing me, who had come to pick her up, she showed no sign of joy.</p></div>\n<div><p>—She simply gazed at the sea, sorrowfully.</p></div>\n<div><p>\"…I felt I had to do something. Something only I could do—\"</p></div>\n<div><p>—The sand beneath her feet was shallowly clawed by her fingertips, in an irregular rhythm. That motion told of how long she had been waiting there.</p></div>\n<div><p>\"Something only you could do, huh.\"</p></div>\n<div><p>—Indeed, in that sense, the strategy could also be said to still be alive.</p></div>\n<div><p>—No one else would have come here.</p></div>\n<div><p>—In the distance, a seabird skimmed low across the water's surface and cried out.</p></div>\n<div><p>\"When Ryuuen-kun told me, initially I didn't intend to come. Or, to be precise, my intuition told me that coming was the wrong choice. If I came, it would absolutely be a net negative for the class. If I simply wanted the class to win, there was no benefit. Leaving Hiyori alone would chip away at Class B's fighting strength, and I could still obtain the Special Reward.\"</p></div>\n<div><img alt=\"Chapter Image\" width=\"600\" height=\"800\" src=\"/assets/y3v4_ch9.webp\"></div>\n<div><p>—I didn't know what the group totals would be, but it was an outcome that would affect the rankings.</p></div>\n<div><p>\"Then… why did you come…?\"</p></div>\n<div><p>—Here, Hiyori shifted her gaze slightly for the first time.</p></div>\n<div><p>—Not fully looking at me, it fell somewhere between her feet and the sea.</p></div>\n<div><p>\"Perhaps I wanted to surrender myself to the irrational, the non-rational. I was interested in what emotions I would feel after making a mistake that I normally wouldn't choose.\"</p></div>\n<div><p>—It wasn't a lie. I told her the answer that had first surfaced.</p></div>\n<div><p>—But after speaking it, an opposite answer arose.</p></div>\n<div><p>—What I had just said was a front. It wasn't the truth.</p></div>\n<div><p>\"No, I was wrong… The outcome, or whatever, doesn't matter. I simply don't want you to be expelled. I don't want to see a future where Ryuuen-kun didn't save you, where no one saved you. Even if just for one more second, I want to spend school life together with you—that is the reason I came here.\"</p></div>\n<div><p>\"I'm not a particularly interesting person. Am I worth those words? Ayanokouji-kun, you have many friends around you.\"</p></div>\n<div><p>—After answering that, without moving her gaze, she continued.</p></div>\n<div><p>\"Waiting here was underhanded—the more I think about it, the more underhanded it feels.\"</p></div>\n<div><p>\"Underhanded?\"</p></div>\n<div><p>\"Because… is it not? Using myself as bait. Do I have any value as bait… what type of delusion is that… There's no way Ayanokouji-kun would abandon the possibility of winning to come get me.\"</p></div>\n<div><p>—Slowly, calmly, Hiyori explained her current feelings.</p></div>\n<div><p>—Matching her words, her fingertips, which had been pinching the hem of her tracksuit, loosened slightly and let go.</p></div>\n<div><p>—Chasing the cloth fluttering in the wind, she lightly grasped it again.</p></div>\n<div><p>\"I'm underhanded. But I still faintly hoped—wondered whether Ayanokouji-kun would come to see me. Whether he would come to get me…\"</p></div>\n<div><p>—Two nearly opposite feelings intertwined.</p></div>\n<div><p>\"You really came… I'm happy. But I can't say I'm happy…\"</p></div>\n<div><p>—Where her words broke off, the sound of the waves filled the gap.</p></div>\n<div><p>—Only that regular sound quietly marked the passage of time.</p></div>\n<div><p>\"What… should I do.\"</p></div>\n<div><p>—To this question, I didn't know whether I could give a correct answer.</p></div>\n<div><p>—But I had one thing to say.</p></div>\n<div><p>\"Right now, I am clearly aware of it. I—am in love with Shiina Hiyori.\"</p></div>\n<div><p>—The words that should be said.</p></div>\n<div><p>—The words that must be said.</p></div>\n<div><p>—But at the same moment I spoke them, my throat became slightly dry.</p></div>\n<div><p>—It wasn't simply from the physical exertion of rushing here.</p></div>\n<div><p>—The weight of putting those words into voice. The reality that the other person's response was not 100% guaranteed.</p></div>\n<div><p>—Right now, I was being shaken by an emotion I was experiencing for the first time.</p></div>\n<div><p>—A gust of wind blew the hair flowing down, and with that motion, her gaze fixed on me.</p></div>\n<div><p>—A subtle freeze, and we were completely face-to-face.</p></div>\n<div><p>\"I'm sorry—\"</p></div>\n<div><p>—An apology.</p></div>\n<div><p>\"Truly, I'm sorry—\"</p></div>\n<div><p>—She apologized once more.</p></div>\n<div><p>\"I… I also… like Ayanokouji-kun. …I'm sorry—\"</p></div>\n<div><p>—An apology for having exploited my feelings toward her.</p></div>\n<div><p>—After she finished speaking, her gaze did not move away; she still looked at me, her chest subtly rising and falling as if adjusting her breath.</p></div>\n<div><p>—There was no need for further words.</p></div>\n<div><p>—I operated my wristwatch and transferred the tokens I had brought to Hiyori.</p></div>\n<div><p>—Then, with my right hand, I took hold of her left hand, and together we gazed out at the sea.</p></div>\n<div><p>—At the moment of contact, her fingertips faintly gripped back. They immediately relaxed, but the motion and sensation of that instant were unmistakably imprinted.</p></div>\n<div><p>—The ship's horn sounded.</p></div>\n<div><p>—That was not an ending, but the sound of a beginning.</p></div>\n<div><p>—Was thinking like this correct?</p></div>\n<div><p>—I, as an ordinary high school student, came to know love, and through that, to grow—would I change?</p></div>\n<div><p>—Something lurked at the bottom of dark, murky, invisible lake, raising its head.</p></div>\n<div><p>—When I fully digest this new emotion, I will probably release this hand without hesitation.</p></div>\n<div><p>—I am merely desiring.</p></div>\n<div><p>—To turn knowledge, experience, memory—all of it—into my own flesh and blood.</p></div>\n<div><p>—Everything, for my own sake.</p></div>\n<div><p>—I act solely for myself.</p></div>\n<div><p>Until now, and from here on—</p></div>\n<div><p>—That will certainly never change, until the day I die.</p></div>\n<div><p>After the exam ended, at 7:30 p.m. The results were announced outside; we disembarked from the large passenger ship and waited for that moment on the uninhabited island.</p></div>\n<div><p>—Positions were unrestricted; free activity was allowed.</p></div>\n<div><p>—Before long, a small boat carrying students who hadn't reached the finish line returned to the pier.</p></div>\n<div><p>—With a heart full overflowing with unease, I waited for him to come down.</p></div>\n<div><p>—Hiding in the nearby forest, I watched.</p></div>\n<div><p>—I could have gone to greet him openly and honorably. But I couldn't.</p></div>\n<div><p>Yoshida-kun had said something to Hashimoto-kun that I didn't want to believe.</p></div>\n<div><p>\"That guy, he was prepared to throw away his own chance of winning to save Shiina. I couldn't stop him.\"</p></div>\n<div><p>—It lingered in my mind, that sentence echoing over and over.</p></div>\n<div><p>Why?</p></div>\n<div><p>How?</p></div>\n<div><p>To save Shiina-san?</p></div>\n<div><p>Why would he do such a thing?</p></div>\n<div><p>I don't understand.</p></div>\n<div><p>—No. I don't want to understand.</p></div>\n<div><p>—Ayanokouji-kun and Shiina-san were reading companions who met in the library, this, I knew. But to me, it wasn't something worth paying attention to.</p></div>\n<div><p>—Just a friend.</p></div>\n<div><p>—No more, no less.</p></div>\n<div><p>But now, it was different.</p></div>\n<div><p>Even if only provisionally, as a Class Leader expected to produce results, achieving a major outcome in this special exam was a goal for Ayanokouji-kun.</p></div>\n<div><p>But he—to save Shiina-san, he threw all of that away.</p></div>\n<div><p>'He saved her because she's a friend'—putting it that way is simple.</p></div>\n<div><p>I, too, if a classmate fell into the same predicament, would save them without hesitation.</p></div>\n<div><p>But Ayanokouji-kun and I are different.</p></div>\n<div><p>What came to my mind, what I could possibly think of—</p></div>\n<div><p>…It's because she's excellent.</p></div>\n<div><p>—Ayanokouji-kun wants the 4 classes to maintain a balanced fight.</p></div>\n<div><p>That's why Shiina-san is necessary—</p></div>\n<div><p>I understand. That must be it.</p></div>\n<div><p>No.</p></div>\n<div><p>It's not.</p></div>\n<div><p>—Shiina-san isn't just a friend.</p></div>\n<div><p>I didn't want to believe it.</p></div>\n<div><p>But what my eyes took in was cruel reality.</p></div>\n<div><p>—Ayanokouji-kun stepped down first from the unsteady gangplank onto land, then turned around and took Shiina-san's hand.</p></div>\n<div><p>—And then, tenderly, he helped her off the ship.</p></div>\n<div><p>—Her expression was tinged with apology, but it was clearly happy.</p></div>\n<div><p>I thought it was Karuizawa.</p></div>\n<div><p>I thought that by pushing her away, I could stand beside Ayanokouji-kun.</p></div>\n<div><p>But it wasn't.</p></div>\n<div><p>—What I truly had to do was—</p></div>\n<div><p>It was you…</p></div>\n<div><p>\"Shiina Hiyori…-san.\"</p></div>\n<div><p>I murmured quietly.</p></div>\n<div><p>Heavy, dark, deep.</p></div>\n<div><p>—My heart, gouged as though something had been carved out of it, etched that name into itself as a scar.</p></div>\n<div><p>Surely, I won't be able to suppress this feeling—</p></div>",
    "12": "<div><p>It's been half a year since I last put pen to paper. Kinugasa here.</p></div>\n<div><p>I'm still taking care of my health as I write, but thanks to everyone's support, I've gradually been able to put in more hours at the desk again.</p></div>\n<div><p>That said, this volume is a bit lighter on main-story content than usual. For the previous two years, the standard pattern was to wrap up the first semester in Volume 4 and then continue into Volume 5, but this Year 3 arc will board the return ship and head straight into the story's climax. After that, I imagine the next installment will be a smaller tale woven together by the first- and second-year underclassmen. We're aiming for an October release — please look forward to it!</p></div>\n<div><p>As for who gets featured on each volume's cover — I agonized over that quite a bit during the Year 2 arc. There were even several times when it nearly ended up blank. But for this Year 3 arc, the covers were actually decided long ago. If you have any guesses about which nostalgic characters are slated to appear, please do give it some thought.</p></div>\n<div><p>Also, the anime adaptation is currently airing — I hope you'll all give it a watch.</p></div>\n<div><p>This has nothing to do with what drives me to write at the moment, but I do have a rare announcement to make:</p></div>\n<div><p>\"This September, a new work is set for release!\"</p></div>\n<div><p>Once again I've been able to partner with Tomose-san, and I'm deeply grateful for being given free rein to do as I please. After a good, long rest at the izakaya, I'll be putting my all into this one as well.</p></div>\n<div><p>Ah, that's right — looking at you, I get the feeling you're not in the best of health.</p></div>\n<div><p>Yes — the truth is, I've been chipping away at this one on and off for a very long time now. It really should have seen the light of day much earlier, but my health kept pushing it back again and again. If I'd been able to put those physical troubles aside and push through to today… well, looking back on it all, I imagine I'd have quite a lot of feelings about that, wouldn't I?</p></div>\n<div><p>This work holds a very deep, personal meaning for me.</p></div>\n<div><p>And regarding how things are going on the publisher's end — if you hear anything, do let me know when you get the chance.</p></div>\n<div><p>Thank you, truly.</p></div>\n<div><p>Let's meet again before the year is out. Everyone, take care of yourselves and stay healthy!</p></div>"
};
